export const alignedVoiceLines: Readonly<Record<string, GeneratedVoiceAlignment>> = {"prologue-003":{"text":"People like to begin a love story at the moment two lives finally meet. A glance across a room. A name remembered. The first small coincidence that later feels like fate.","voiceUrl":"voices/prologue/prologue-003.mp3","durationMs":13416,"cues":[[7,120],[12,480],[15,720],[21,820],[23,1140],[28,1280],[34,1560],[37,2180],[41,2300],[48,2420],[52,2840],[58,3060],[66,3720],[72,4220],[74,5420],[81,5520],[88,5940],[90,6240],[96,6340],[98,7240],[103,7360],[115,7680],[119,9240],[125,9360],[131,10180],[143,10500],[148,11600],[154,11740],[160,12040],[165,12380],[170,12660]]},"prologue-004":{"text":"My story with Nurul has a moment like that. But this is not that moment. Not yet.","voiceUrl":"voices/prologue/prologue-004.mp3","durationMs":8016,"cues":[[3,1060],[9,1320],[14,1620],[20,1840],[24,2520],[26,2680],[33,2780],[38,3100],[44,3340],[48,4580],[53,4760],[56,5180],[60,5340],[65,5780],[73,6000],[77,7240],[81,7480]]},"prologue-005":{"text":"Before I could recognise the love of my life, I had to become someone capable of meeting her. That becoming was untidy. It passed through school corridors, glowing phone screens, and choices I understood only years later.","voiceUrl":"voices/prologue/prologue-005.mp3","durationMs":16368,"cues":[[7,880],[9,1300],[15,1380],[25,1560],[29,2200],[34,2380],[37,2620],[40,2760],[46,2960],[48,4000],[52,4080],[55,4200],[62,4300],[70,4660],[78,4980],[81,5380],[89,5580],[94,5940],[99,7480],[108,7900],[112,8480],[120,8900],[123,10020],[130,10180],[138,10660],[145,10900],[156,11220],[164,12100],[170,12480],[179,12800],[183,13680],[191,13840],[193,14340],[204,14420],[209,14940],[215,15340],[221,15760]]},"prologue-006":{"text":"Memory is not a recording. It keeps the warmth of an afternoon and loses the date. It saves one sentence while whole months blur around it. So I will not pretend every word happened exactly this way.","voiceUrl":"voices/prologue/prologue-006.mp3","durationMs":15144,"cues":[[7,1240],[10,1920],[14,2080],[16,2260],[27,2320],[30,3500],[36,3640],[40,3900],[47,4059],[50,4440],[53,4520],[63,4680],[67,5720],[73,5900],[77,6340],[83,6500],[86,7420],[92,7580],[96,8080],[105,8360],[111,9060],[117,9260],[124,9560],[129,10000],[136,10420],[140,10800],[143,11580],[145,11840],[150,11900],[154,12020],[162,12180],[168,12840],[173,13120],[182,13420],[190,13720],[195,14320],[199,14560]]},"prologue-007":{"text":"What remains true is how those years shaped me: the excitement, the mistakes, the pride, and the shame. Even the parts I once wanted to hide belong to the road.","voiceUrl":"voices/prologue/prologue-007.mp3","durationMs":12744,"cues":[[5,780],[13,940],[18,1420],[21,2220],[25,2340],[31,2580],[37,2880],[44,3340],[48,3680],[52,4260],[64,4380],[68,5380],[78,5480],[82,6560],[89,6680],[93,7620],[97,7800],[104,7940],[109,9160],[113,9360],[119,9500],[121,9960],[126,10080],[133,10380],[136,10640],[141,10780],[148,11480],[151,11840],[155,11960],[160,12080]]},"prologue-008":{"text":"In 2009, I was a twelve-year-old Boyanese Malay boy: short, round, bespectacled, and trying very hard to look as though I knew what I was doing.","voiceUrl":"voices/prologue/prologue-008.mp3","durationMs":11496,"cues":[[3,1100],[9,1300],[11,2780],[15,2840],[17,2960],[33,3060],[42,3980],[48,4640],[53,5020],[60,5980],[67,6760],[81,7460],[85,8460],[92,8600],[97,8900],[102,9160],[105,9420],[110,9540],[113,9680],[120,9800],[122,10000],[127,10120],[132,10400],[134,10600],[138,10660],[144,10840]]},"prologue-009":{"text":"I did not. None of us did. That was the innocence of Primary Six. We borrowed the language of grown-up love while still worrying about spelling tests and whether the canteen queue would finish before recess did.","voiceUrl":"voices/prologue/prologue-009.mp3","durationMs":14280,"cues":[[2,780],[6,860],[11,1040],[16,2140],[19,2280],[22,2400],[27,2560],[32,3520],[36,4000],[40,4160],[50,4320],[53,4720],[61,4860],[66,5340],[69,6600],[78,6800],[82,7160],[91,7280],[94,7720],[103,7860],[108,8260],[114,8980],[120,9220],[129,9480],[135,9820],[144,10180],[150,10560],[154,11260],[162,11400],[166,11640],[174,11780],[180,12360],[186,12580],[193,12780],[200,13100],[207,13440],[211,13900]]},"prologue-010":{"text":"There was a girl named Alya. She had long braided hair, bright eyes that seemed to notice everything, and a laugh that could make an ordinary classroom feel briefly important.","voiceUrl":"voices/prologue/prologue-010.mp3","durationMs":12600,"cues":[[6,940],[10,1060],[12,1200],[17,1300],[23,1800],[29,2360],[33,3680],[37,3800],[42,4019],[50,4400],[56,4820],[63,5680],[68,6020],[73,6400],[80,6580],[83,6900],[90,7020],[102,7480],[106,8360],[108,8500],[114,8640],[119,9240],[125,9340],[130,9480],[133,9640],[142,9820],[152,10240],[157,10860],[165,11180],[175,11680]]},"prologue-011":{"text":"At twelve, I thought the beginning of a relationship meant the difficult part was over. All you had to do after that was keep liking each other.","voiceUrl":"voices/prologue/prologue-011.mp3","durationMs":8832,"cues":[[3,620],[11,860],[13,1820],[21,1900],[25,2120],[35,2200],[38,2600],[40,2720],[53,2780],[59,3780],[63,4019],[73,4140],[78,4580],[82,4840],[88,5020],[92,6020],[96,6160],[100,6300],[103,6400],[106,6520],[112,6700],[117,6940],[121,7300],[126,7520],[133,7760],[138,8119],[144,8340]]},"prologue-012":{"text":"I would learn that distance can enter quietly. I would learn that silence is also a kind of message. And first, I would learn how much damage one message sent to the wrong person could do.","voiceUrl":"voices/prologue/prologue-012.mp3","durationMs":13056,"cues":[[2,500],[8,580],[14,760],[19,1240],[28,1460],[32,2200],[38,2360],[47,2640],[49,3680],[55,3740],[61,3900],[66,4140],[74,4380],[77,5160],[82,5360],[84,5680],[89,5780],[92,6020],[101,6160],[105,7460],[112,7660],[114,8780],[120,8840],[126,9020],[130,9340],[135,9520],[142,9800],[146,10320],[154,10520],[159,11120],[162,11280],[166,11380],[172,11500],[179,11820],[185,12280],[188,12480]]},"ch1-001":{"text":"Our classroom wore the colours of the morning: pale walls, warm sun, and rows of light-blue uniforms. Ceiling fans pushed the same hot air in patient circles above us.","voiceUrl":"voices/chapter-1/ch1-001.mp3","durationMs":12312,"cues":[[4,140],[14,360],[19,980],[23,1140],[31,1280],[34,1560],[38,1660],[47,1800],[52,2980],[59,3340],[64,4120],[69,4500],[73,5340],[78,5500],[81,5800],[92,5960],[102,6520],[110,8240],[115,8600],[122,9100],[126,9520],[131,9700],[135,10040],[139,10380],[142,10640],[150,10840],[158,11240],[164,11680],[167,12000]]},"ch1-002":{"text":"Alya sat close enough that passing a worksheet could become an event. Sometimes our fingers touched. Sometimes they did not, and I spent the next ten minutes wondering whether I had moved too slowly.","voiceUrl":"voices/chapter-1/ch1-002.mp3","durationMs":12384,"cues":[[5,140],[9,520],[15,780],[22,1060],[27,1320],[35,1500],[37,1840],[47,1920],[53,2560],[60,2720],[63,2980],[70,3100],[80,4560],[84,5020],[92,5200],[101,5600],[111,6880],[116,7360],[120,7500],[125,7680],[129,8780],[131,8960],[137,9080],[141,9260],[146,9360],[150,9620],[158,9820],[168,10160],[176,10600],[178,10840],[182,10880],[188,11060],[192,11560],[199,11820]]},"ch1-003":{"text":"Aleem, you have been staring at question four for so long. Are you solving it or trying to scare it?","voiceUrl":"voices/chapter-1/ch1-003.mp3","durationMs":7512,"cues":[[7,140],[11,1120],[16,1220],[21,1380],[29,1620],[32,2000],[41,2160],[46,2660],[50,2980],[53,3320],[59,3640],[63,5220],[67,5340],[75,5500],[78,5920],[81,6240],[88,6520],[91,6820],[97,6980],[100,7240]]},"ch1-004":{"text":"I was thinking. Deeply.","voiceUrl":"voices/chapter-1/ch1-004.mp3","durationMs":2952,"cues":[[2,280],[6,360],[16,560],[23,1680]]},"ch1-005":{"text":"Deeply wrong, maybe. Your answer is on the next page.","voiceUrl":"voices/chapter-1/ch1-005.mp3","durationMs":5832,"cues":[[7,120],[14,980],[21,1720],[26,3840],[33,4019],[36,4540],[39,4680],[43,4780],[48,4900],[53,5180]]},"ch1-006":{"text":"That was Alya's way: a little playful, never cruel. Her eyes widened whenever she delivered a joke, as though she was surprised by her own courage.","voiceUrl":"voices/chapter-1/ch1-006.mp3","durationMs":10704,"cues":[[5,160],[9,420],[16,660],[21,1060],[23,2260],[30,2380],[39,2660],[45,3600],[52,4000],[56,5440],[61,5640],[69,5980],[78,6460],[82,6780],[92,6960],[94,7300],[100,7440],[103,8000],[110,8140],[114,8380],[118,8520],[128,8640],[131,9380],[135,9520],[139,9740],[147,10040]]},"ch1-007":{"text":"We did not have a dramatic confession. There was no rain, no music, no perfect speech. There were only friends who noticed us noticing each other and carried rumours up and down the corridor.","voiceUrl":"voices/chapter-1/ch1-007.mp3","durationMs":12720,"cues":[[3,100],[7,220],[11,400],[16,640],[18,860],[27,940],[39,1400],[45,2820],[49,2960],[52,3120],[58,3340],[61,4240],[68,4440],[71,5360],[79,5580],[87,6060],[93,7160],[98,7260],[103,7420],[111,7740],[115,8440],[123,8580],[126,9020],[135,9320],[140,9700],[146,9920],[150,10580],[158,10740],[166,11080],[169,11520],[173,11620],[178,11760],[182,11940],[191,12060]]},"ch1-008":{"text":"So... everyone says you like me.","voiceUrl":"voices/chapter-1/ch1-008.mp3","durationMs":6312,"cues":[[6,140],[15,2200],[20,2860],[24,3580],[29,3740],[32,4080]]},"ch1-009":{"text":"Everyone talks too much.","voiceUrl":"voices/chapter-1/ch1-009.mp3","durationMs":2112,"cues":[[9,140],[15,560],[19,920],[24,1080]]},"ch1-010":{"text":"That is not an answer.","voiceUrl":"voices/chapter-1/ch1-010.mp3","durationMs":2160,"cues":[[5,180],[8,520],[12,820],[15,1200],[22,1400]]},"ch1-011":{"text":"Okay. Yes. I like you.","voiceUrl":"voices/chapter-1/ch1-011.mp3","durationMs":2880,"cues":[[6,160],[11,840],[13,1640],[18,1720],[22,2020]]},"ch1-012":{"text":"Good. Because I like you too.","voiceUrl":"voices/chapter-1/ch1-012.mp3","durationMs":3984,"cues":[[6,160],[14,2420],[16,2880],[21,2980],[25,3320],[29,3540]]},"ch1-013":{"text":"From that day, we said we were together. The phrase felt enormous. In practice, it meant shared snacks, carefully timed walks after school, and messages sent from phones we were not supposed to use during homework.","voiceUrl":"voices/chapter-1/ch1-013.mp3","durationMs":14160,"cues":[[5,120],[10,360],[15,660],[18,1420],[23,1660],[26,2020],[31,2160],[41,2380],[45,3680],[52,3780],[57,4160],[67,4420],[70,5760],[80,5880],[83,6360],[89,6500],[96,6700],[104,7080],[114,8039],[120,8480],[126,8860],[132,9260],[140,9540],[144,10460],[153,10600],[158,11060],[163,11240],[170,11460],[173,11900],[178,11980],[182,12080],[191,12260],[194,12620],[198,12840],[205,13160],[214,13460]]},"ch1-014":{"text":"We spoke about secondary school as if it were a foreign country. New uniforms. New subjects. Older students who, in our imagination, all knew exactly where to go.","voiceUrl":"voices/chapter-1/ch1-014.mp3","durationMs":12240,"cues":[[3,300],[9,560],[15,880],[25,1180],[32,1720],[35,2020],[38,2160],[41,2260],[46,2380],[48,2540],[56,2680],[65,3080],[69,4640],[79,4960],[83,5980],[93,6220],[99,7440],[108,7740],[113,8160],[116,8820],[120,8920],[133,9060],[137,10300],[142,10460],[150,10640],[156,11500],[159,11680],[162,11800]]},"ch1-015":{"text":"What if you become very handsome in secondary school and forget me?","voiceUrl":"voices/chapter-1/ch1-015.mp3","durationMs":5832,"cues":[[5,180],[8,360],[12,520],[19,640],[24,1400],[33,1800],[36,2260],[46,2420],[53,3020],[57,3580],[64,3760],[67,4160]]},"ch1-016":{"text":"I am already handsome.","voiceUrl":"voices/chapter-1/ch1-016.mp3","durationMs":2280,"cues":[[2,320],[5,520],[13,700],[22,1060]]},"ch1-017":{"text":"Wah, confident. Then I should be the one worried.","voiceUrl":"voices/chapter-1/ch1-017.mp3","durationMs":4080,"cues":[[5,320],[16,760],[21,2260],[23,2760],[30,2860],[33,3060],[37,3200],[41,3300],[49,3520]]},"ch1-018":{"text":"I laughed because the future sounded harmless when Alya teased it. Neither of us knew how completely a timetable could rearrange a friendship, or how difficult affection became without daily proximity.","voiceUrl":"voices/chapter-1/ch1-018.mp3","durationMs":12312,"cues":[[2,220],[10,340],[18,1180],[22,1460],[29,1580],[37,1980],[46,2360],[51,2860],[56,3080],[63,3420],[67,3740],[75,4880],[78,5200],[81,5340],[86,5500],[90,5700],[101,5860],[103,6560],[113,6660],[119,7220],[129,7460],[131,8060],[143,8140],[146,9160],[150,9380],[160,9600],[170,10020],[177,10480],[185,10820],[191,11160],[201,11520]]},"ch1-019":{"text":"Graduation arrived dressed as celebration. Parents took photographs beneath the school gate. Teachers gave final reminders. Shirts gathered signatures in inks that bled whenever a hand grew sweaty.","voiceUrl":"voices/chapter-1/ch1-019.mp3","durationMs":12072,"cues":[[11,140],[19,800],[27,1320],[30,1760],[43,1900],[51,3360],[56,3800],[68,4000],[76,4660],[80,4920],[87,5060],[93,5400],[102,6080],[107,6500],[113,6720],[124,7020],[131,8160],[140,8580],[151,8900],[154,9480],[159,9720],[164,9980],[169,10180],[178,10500],[180,10860],[185,10960],[190,11300],[197,11560]]},"ch1-020":{"text":"Message me when you get home, okay?","voiceUrl":"voices/chapter-1/ch1-020.mp3","durationMs":2400,"cues":[[8,120],[11,540],[16,700],[20,860],[24,960],[30,1180],[35,1840]]},"ch1-021":{"text":"Of course. We will still talk every day.","voiceUrl":"voices/chapter-1/ch1-021.mp3","durationMs":2952,"cues":[[3,120],[11,300],[14,1120],[19,1240],[25,1460],[30,1720],[36,2260],[40,2560]]},"ch1-022":{"text":"Promise?","voiceUrl":"voices/chapter-1/ch1-022.mp3","durationMs":3192,"cues":[[8,140]]},"ch1-023":{"text":"Promise.","voiceUrl":"voices/chapter-1/ch1-023.mp3","durationMs":1440,"cues":[[8,140]]},"ch1-024":{"text":"We meant it. That is important. Young promises are not lies simply because the people making them do not yet understand what keeping them will require.","voiceUrl":"voices/chapter-1/ch1-024.mp3","durationMs":9840,"cues":[[3,140],[9,340],[13,640],[18,1900],[21,2060],[32,2200],[38,3840],[47,4080],[51,4560],[55,4680],[60,4960],[67,5640],[75,5980],[79,6260],[86,6380],[93,6700],[98,6980],[101,7160],[105,7280],[109,7480],[120,7660],[125,8240],[133,8480],[138,8780],[143,8920],[151,9100]]},"ch1-025":{"text":"The new year placed us on different routes. Different buses, different assemblies, different circles of names. At first we compensated with long messages about every detail.","voiceUrl":"voices/chapter-1/ch1-025.mp3","durationMs":12000,"cues":[[4,200],[8,360],[13,640],[20,960],[23,1340],[26,1580],[36,1800],[44,2160],[54,3220],[61,3580],[71,4360],[83,4640],[93,5860],[101,6260],[104,6720],[111,6880],[114,8180],[120,8340],[123,8720],[135,8880],[140,9600],[145,9800],[154,10100],[160,10620],[166,10980],[173,11340]]},"ch1-026":{"text":"My class monitor is so serious. He wrote down three names before first period even started.","voiceUrl":"voices/chapter-1/ch1-026.mp3","durationMs":5496,"cues":[[3,80],[9,260],[17,620],[20,1040],[23,1200],[32,1460],[35,2240],[41,2360],[46,2580],[52,2880],[58,3200],[65,3560],[71,3940],[78,4220],[83,4620],[91,5000]]},"ch1-027":{"text":"Mine keeps forgetting she is the monitor. Maybe they should swap.","voiceUrl":"voices/chapter-1/ch1-027.mp3","durationMs":7032,"cues":[[5,220],[11,580],[22,860],[26,1400],[29,1700],[33,2020],[42,2160],[48,3760],[53,4019],[60,4180],[65,4420]]},"ch1-028":{"text":"A vibration in my pocket could rescue an entire afternoon. Her name on the small screen meant some part of primary school had survived the crossing.","voiceUrl":"voices/chapter-1/ch1-028.mp3","durationMs":9120,"cues":[[2,100],[12,200],[15,820],[18,960],[25,1220],[31,1680],[38,1860],[41,2220],[48,2320],[59,3020],[63,4560],[68,4780],[71,5120],[75,5240],[81,5400],[88,5700],[94,6100],[99,6360],[104,6620],[107,6840],[115,6980],[122,7460],[126,7720],[135,7880],[139,8360],[148,8500]]},"ch1-029":{"text":"Then the gaps lengthened. Homework became heavier. New friendships demanded attention. One missed evening turned into two without either of us deciding that anything had changed.","voiceUrl":"voices/chapter-1/ch1-029.mp3","durationMs":11760,"cues":[[5,100],[9,340],[14,480],[26,820],[35,2080],[42,2580],[51,2940],[55,4220],[67,4420],[76,4960],[87,5420],[91,7020],[98,7220],[106,7520],[113,7900],[118,8280],[122,8560],[130,8820],[137,9240],[140,9480],[143,9620],[152,9800],[157,10280],[166,10520],[170,10880],[178,11080]]},"ch1-030":{"text":"We still called ourselves together, but the relationship lived mostly in the assumption that we would speak properly tomorrow.","voiceUrl":"voices/chapter-1/ch1-030.mp3","durationMs":6480,"cues":[[3,100],[9,280],[16,580],[26,900],[36,1500],[40,2500],[44,2620],[57,2720],[63,3300],[70,3600],[73,3960],[77,4040],[88,4160],[93,4740],[96,4880],[102,5000],[108,5200],[117,5460],[126,5900]]},"ch1-031":{"text":"One ordinary evening, while I sat near my bed with unfinished work beside me, the phone buzzed.","voiceUrl":"voices/chapter-1/ch1-031.mp3","durationMs":5664,"cues":[[4,120],[13,520],[22,960],[28,1660],[30,1920],[34,1960],[39,2180],[42,2340],[46,2520],[51,2740],[62,2960],[67,3500],[74,3740],[78,4140],[82,4760],[88,4860],[95,5200]]},"ch1-032":{"text":"I saw Alya's name and smiled before reading. The body can celebrate half a second faster than the mind understands.","voiceUrl":"voices/chapter-1/ch1-032.mp3","durationMs":8064,"cues":[[2,220],[6,340],[13,660],[18,1120],[22,1400],[29,1600],[36,2140],[45,2500],[49,4080],[54,4220],[58,4580],[68,4800],[73,5380],[75,5660],[82,5780],[89,6120],[94,6540],[98,6680],[103,6800],[115,7120]]},"ch1-033":{"text":"The first message asked whether a boy liked her. The second asked how she could approach him without making her interest obvious.","voiceUrl":"voices/chapter-1/ch1-033.mp3","durationMs":8304,"cues":[[4,120],[10,260],[18,660],[24,1380],[32,1660],[34,1920],[38,2040],[44,2420],[49,2700],[53,3840],[60,4019],[66,4440],[70,5100],[74,5260],[80,5380],[89,5500],[93,5920],[101,6220],[108,6520],[112,6800],[121,7040],[129,7620]]},"ch1-034":{"text":"I read both again. Perhaps there was context I had missed. Perhaps 'he' meant someone else on behalf of a friend. Perhaps the words would rearrange themselves if I stared long enough.","voiceUrl":"voices/chapter-1/ch1-034.mp3","durationMs":11904,"cues":[[2,120],[7,180],[12,380],[19,640],[27,1800],[33,2160],[37,2300],[45,2580],[47,3180],[51,3240],[59,3400],[68,4580],[72,5160],[78,5500],[86,5760],[91,6060],[94,6320],[101,6460],[104,6800],[106,6900],[114,7000],[122,8380],[126,8800],[132,8940],[138,9320],[148,9500],[159,10080],[162,10640],[164,10780],[171,10920],[176,11240],[183,11400]]},"ch1-sms-ask-001":{"text":"Alya... was that message meant for me?","voiceUrl":"voices/chapter-1/ch1-sms-ask-001.mp3","durationMs":3336,"cues":[[8,120],[12,1460],[17,1660],[25,1960],[31,2400],[35,2740],[38,2960]]},"ch1-sms-ask-002":{"text":"I chose the smallest question I could manage. Years later, I would remember how even that gentle sentence carried the answer I was afraid to name.","voiceUrl":"voices/chapter-1/ch1-sms-ask-002.mp3","durationMs":8952,"cues":[[2,120],[8,200],[12,540],[21,700],[30,1180],[32,1580],[38,1660],[46,1820],[52,3260],[59,3560],[61,4300],[67,4360],[76,4500],[80,4920],[85,5180],[90,5460],[97,5760],[106,6200],[114,6740],[118,6980],[125,7140],[127,7660],[131,7720],[138,7840],[141,8240],[146,8380]]},"ch1-sms-direct-001":{"text":"I thought we were still together. Who are you talking about?","voiceUrl":"voices/chapter-1/ch1-sms-direct-001.mp3","durationMs":3240,"cues":[[2,200],[10,300],[13,520],[18,640],[24,840],[34,1040],[38,1940],[42,2080],[46,2220],[54,2360],[60,2780]]},"ch1-sms-direct-002":{"text":"The words looked braver on the screen than I felt. Years later, I would remember that directness not as anger, but as a frightened request for reality to hold still.","voiceUrl":"voices/chapter-1/ch1-sms-direct-002.mp3","durationMs":11112,"cues":[[4,100],[10,220],[17,600],[24,880],[27,1260],[31,1400],[38,1540],[43,1880],[45,2080],[51,2220],[57,3800],[64,4120],[66,4920],[72,5000],[81,5120],[86,5520],[97,5680],[101,6540],[104,6720],[111,6980],[115,7860],[118,7980],[120,8100],[131,8240],[139,8680],[143,9160],[151,9300],[154,9800],[159,10000],[165,10500]]},"ch1-sms-wait-001":{"text":"I did not answer. The typing indicator appeared, vanished, then returned. Each flicker felt like a door opening and closing before I could reach it.","voiceUrl":"voices/chapter-1/ch1-sms-wait-001.mp3","durationMs":10224,"cues":[[2,180],[6,240],[10,420],[18,760],[22,2300],[29,2420],[39,2760],[49,3220],[59,4059],[64,4900],[74,5060],[79,6580],[87,6820],[92,7200],[97,7420],[99,7580],[104,7720],[112,8160],[116,8500],[124,8700],[131,9160],[133,9480],[139,9540],[145,9700],[148,9960]]},"ch1-sms-wait-002":{"text":"Years later, I would remember that silence as my first instinct under hurt: become still, hope the other person explains, and pretend waiting is the same as being protected.","voiceUrl":"voices/chapter-1/ch1-sms-wait-002.mp3","durationMs":11184,"cues":[[6,120],[13,440],[15,1260],[21,1320],[30,1460],[35,1860],[43,2080],[46,2480],[49,2620],[55,2800],[64,3220],[70,3740],[76,3980],[83,5180],[90,5620],[95,6600],[99,6860],[105,6980],[112,7160],[122,7480],[126,8660],[134,8780],[142,9160],[145,9680],[149,9820],[154,9960],[157,10180],[163,10320],[173,10560]]},"ch1-035":{"text":"Wait—Aleem? Oh no. I sent that to the wrong person. I am so sorry.","voiceUrl":"voices/chapter-1/ch1-035.mp3","durationMs":8880,"cues":[[5,180],[12,1540],[15,3700],[19,3900],[21,4960],[26,5080],[31,5320],[34,5500],[38,5620],[44,5720],[52,6080],[54,7200],[57,7280],[60,7580],[66,7920]]},"ch1-036":{"text":"There was no clever explanation. The message had been intended for somebody she trusted, somebody helping her understand a different boy.","voiceUrl":"voices/chapter-1/ch1-036.mp3","durationMs":7992,"cues":[[6,120],[10,280],[13,480],[20,720],[33,1080],[37,2460],[45,2560],[49,2900],[54,3040],[63,3220],[67,3680],[76,3820],[80,4160],[89,4340],[98,5360],[106,5700],[110,5980],[121,6140],[123,6800],[133,6940],[137,7500]]},"ch1-037":{"text":"I should have told you. I kept thinking I would find the right time, and then more time passed. That was not fair to you.","voiceUrl":"voices/chapter-1/ch1-037.mp3","durationMs":9432,"cues":[[2,220],[9,340],[14,500],[19,700],[24,1060],[26,3040],[31,3160],[40,3380],[42,3780],[48,3840],[53,4040],[57,4300],[63,4420],[69,4700],[73,5160],[78,5300],[83,5560],[88,5900],[96,6280],[101,7840],[105,8000],[109,8200],[114,8520],[117,8800],[121,8980]]},"ch1-038":{"text":"So... when did we stop being together?","voiceUrl":"voices/chapter-1/ch1-038.mp3","durationMs":3096,"cues":[[6,300],[11,1860],[15,2000],[18,2140],[23,2280],[29,2520],[38,2700]]},"ch1-039":{"text":"I do not know. I think I felt us becoming different, and I was scared to say it. I am sorry you found out like this.","voiceUrl":"voices/chapter-1/ch1-039.mp3","durationMs":11664,"cues":[[2,240],[5,380],[9,540],[15,760],[17,2820],[23,2940],[25,3260],[30,3420],[33,3780],[42,4120],[53,4860],[57,5680],[59,6160],[63,6240],[70,6540],[73,6940],[77,7140],[81,7400],[83,9500],[86,9620],[92,9840],[96,10200],[102,10360],[106,10660],[111,10820],[116,11080]]},"ch1-040":{"text":"At twelve, uncertainty felt more insulting than a clean ending. I wanted a date, a reason, a single mistake I could point to. She could only offer the messy truth: her feelings had changed before her words did.","voiceUrl":"voices/chapter-1/ch1-040.mp3","durationMs":16152,"cues":[[3,100],[11,300],[23,1100],[28,1760],[33,2000],[43,2180],[48,2840],[50,2980],[56,3080],[64,3420],[66,4720],[73,4820],[75,5300],[81,5580],[83,6220],[91,6400],[93,7420],[100,7560],[108,7900],[110,8720],[116,8800],[122,8980],[126,9320],[130,10680],[136,10880],[141,11040],[147,11320],[151,11540],[157,11660],[164,12020],[168,13320],[177,13500],[181,14180],[189,14360],[196,14900],[200,15200],[206,15400],[210,15780]]},"ch1-041":{"text":"Alya had handled it badly. She knew that. But she was not a villain with a secret plan. She was a young person avoiding a painful conversation until an accidental message forced it into the open.","voiceUrl":"voices/chapter-1/ch1-041.mp3","durationMs":13272,"cues":[[5,160],[9,460],[17,640],[20,1000],[27,1180],[31,1860],[36,2020],[42,2240],[46,3380],[50,3520],[54,3640],[58,3840],[60,4040],[68,4200],[73,4560],[75,4700],[82,4820],[88,5200],[92,6640],[96,6800],[98,6960],[104,7080],[111,7400],[120,8119],[122,8520],[130,8660],[143,9040],[149,10340],[152,10580],[163,10820],[171,11460],[178,11980],[181,12320],[186,12460],[190,12660],[195,12820]]},"ch1-042":{"text":"I wish you had just told me.","voiceUrl":"voices/chapter-1/ch1-042.mp3","durationMs":2424,"cues":[[2,320],[7,420],[11,640],[15,740],[20,880],[25,1120],[28,1460]]},"ch1-043":{"text":"I know. You deserved that.","voiceUrl":"voices/chapter-1/ch1-043.mp3","durationMs":3984,"cues":[[2,240],[8,340],[12,1960],[21,2080],[26,2620]]},"ch1-044":{"text":"The conversation ended without ceremony. No final meeting beneath the school gate. No shared audience to declare us finished. Just two small screens going dark in two different homes.","voiceUrl":"voices/chapter-1/ch1-044.mp3","durationMs":13680,"cues":[[4,160],[17,260],[23,940],[31,1280],[41,1660],[44,3260],[50,3500],[58,3840],[66,4200],[70,4500],[77,4640],[83,4920],[86,5960],[93,6160],[102,6540],[105,6960],[113,7060],[116,7420],[126,7620],[131,9140],[135,9440],[141,9820],[149,10180],[155,10960],[160,11240],[163,12400],[167,12540],[177,12720],[183,13020]]},"ch1-045":{"text":"For a while, I replayed the message as though repetition could reveal an alternate outcome. What if I had called more? What if distance had not made us strangers? What if I had noticed first?","voiceUrl":"voices/chapter-1/ch1-045.mp3","durationMs":13512,"cues":[[4,100],[6,240],[13,360],[15,1020],[24,1120],[28,1540],[36,1660],[39,2460],[46,2620],[57,2880],[63,3520],[70,3680],[73,4019],[83,4260],[92,4700],[97,6340],[100,6500],[102,6680],[106,6740],[113,6940],[119,7400],[124,8640],[127,8760],[136,8920],[140,9420],[144,9580],[149,9820],[152,10040],[163,10240],[168,11640],[171,11780],[173,12100],[177,12180],[185,12360],[191,12840]]},"ch1-046":{"text":"Those questions were too large for the relationship we had actually lived. We had cared for each other sincerely, then grown apart before we had the language to end things kindly.","voiceUrl":"voices/chapter-1/ch1-046.mp3","durationMs":9912,"cues":[[6,120],[16,420],[21,920],[25,1080],[31,1280],[35,1660],[39,1780],[52,1880],[55,2520],[59,2620],[68,2780],[75,3220],[78,4480],[82,4560],[88,4740],[92,4980],[97,5080],[103,5280],[114,5500],[119,6660],[125,6900],[131,7100],[138,7580],[141,7880],[145,7980],[149,8119],[158,8240],[161,8700],[165,8840],[172,9020],[179,9340]]},"ch1-047":{"text":"My first heartbreak taught me to fear the sentence that arrives late. It did not yet teach me how easily I could become the person delaying one.","voiceUrl":"voices/chapter-1/ch1-047.mp3","durationMs":8784,"cues":[[3,160],[9,420],[20,720],[27,1300],[30,1520],[33,1640],[38,1820],[42,2100],[51,2240],[56,2740],[64,2880],[70,3340],[73,4740],[77,4820],[81,4960],[85,5160],[91,5340],[94,5580],[98,5720],[105,6060],[107,6880],[113,6960],[120,7120],[124,7400],[131,7540],[140,7920],[144,8440]]},"ch1-048":{"text":"By 2011 I had changed shape, school, and confidence. I was taller, much thinner, still wearing glasses, and convinced that looking older must mean I had become wiser.","voiceUrl":"voices/chapter-1/ch1-048.mp3","durationMs":12144,"cues":[[3,120],[8,460],[10,1800],[14,1860],[22,2040],[29,2600],[37,3360],[41,3960],[53,4180],[55,5580],[59,5660],[67,5840],[72,6440],[81,6760],[87,7520],[95,7780],[104,8080],[108,8680],[118,8820],[123,9480],[131,9620],[137,10000],[142,10380],[147,10720],[149,11000],[153,11060],[160,11180],[166,11520]]},"ch2-001":{"text":"My secondary school was a boys' school. Every classroom, assembly, and crowded canteen table made that fact completely unremarkable. Girls belonged to other schools, other buses, and stories told by friends with suspicious confidence.","voiceUrl":"voices/chapter-2/ch2-001.mp3","durationMs":16080,"cues":[[3,140],[13,440],[20,860],[24,1200],[26,1360],[32,1500],[40,1800],[46,3020],[57,3340],[67,4140],[71,4740],[79,4960],[87,5400],[93,5860],[98,6480],[103,6680],[108,6900],[119,7360],[133,8080],[139,9660],[148,10040],[151,10520],[157,10640],[166,10860],[172,11600],[179,11840],[183,12780],[191,12960],[196,13480],[199,13680],[207,13900],[212,14460],[223,14740],[234,15360]]},"ch2-002":{"text":"Most days were a familiar rhythm of lessons, jokes, and trying not to be noticed when homework was incomplete. I had grown upward so quickly that my old self felt stored in somebody else's photographs.","voiceUrl":"voices/chapter-2/ch2-002.mp3","durationMs":12000,"cues":[[5,120],[10,500],[15,880],[17,1000],[26,1080],[33,1520],[36,1800],[45,1940],[52,2680],[56,3280],[63,3420],[67,3720],[70,3900],[73,4000],[81,4160],[86,4620],[95,4760],[99,5160],[111,5300],[113,6920],[117,6960],[123,7100],[130,7460],[133,7860],[141,8140],[146,8540],[149,8680],[153,8900],[158,9180],[163,9460],[170,9880],[173,10320],[182,10480],[189,10800],[201,11160]]},"ch2-003":{"text":"Then, once a week, I travelled to a mixed school for third-language class. We kept our own uniforms; the borrowed campus was only a meeting place for students arriving from different schools.","voiceUrl":"voices/chapter-2/ch2-003.mp3","durationMs":11280,"cues":[[6,120],[11,480],[13,740],[19,840],[21,1380],[31,1480],[34,1960],[36,2060],[42,2140],[49,2580],[53,2880],[68,3020],[75,3720],[78,5000],[83,5140],[87,5360],[91,5500],[101,5760],[105,6920],[114,7020],[121,7380],[125,7880],[130,8140],[132,8360],[140,8440],[146,8740],[150,9020],[159,9200],[168,9560],[173,10000],[183,10200],[191,10520]]},"ch2-004":{"text":"The room felt different before anyone spoke. Navy skirts and white shirts mixed with the plain white uniforms from my school. New voices filled the spaces where routine usually sat.","voiceUrl":"voices/chapter-2/ch2-004.mp3","durationMs":12072,"cues":[[4,80],[9,200],[14,500],[24,820],[31,1300],[38,1620],[45,2060],[50,3240],[57,3580],[61,4040],[67,4200],[74,4480],[80,5100],[85,5400],[89,5520],[95,5640],[101,6000],[110,6320],[115,6860],[118,7000],[126,7200],[130,8660],[137,8900],[144,9620],[148,9840],[155,10000],[161,10440],[169,10620],[177,11220],[181,11580]]},"ch2-005":{"text":"I became intensely aware of my arms, my glasses, and the possibility that I had forgotten how to sit naturally.","voiceUrl":"voices/chapter-2/ch2-005.mp3","durationMs":7104,"cues":[[2,140],[9,220],[19,500],[25,1120],[28,1580],[31,1740],[37,2020],[40,2840],[49,2980],[53,4140],[57,4240],[69,4360],[74,5020],[76,5180],[80,5200],[90,5320],[94,5740],[97,5860],[101,6040],[111,6480]]},"ch2-006":{"text":"Hana sat a few places away. She was tall, with long straight hair and glasses that she nudged upward whenever she concentrated. She listened before speaking, then asked questions that made the teacher pause.","voiceUrl":"voices/chapter-2/ch2-006.mp3","durationMs":14400,"cues":[[5,140],[9,520],[11,680],[15,780],[22,960],[28,1360],[32,2720],[36,2860],[42,3120],[47,3880],[52,4120],[61,4520],[66,4880],[70,5520],[78,5700],[83,6340],[87,6480],[94,6640],[101,7060],[110,7420],[114,7740],[128,7900],[132,9720],[141,9880],[148,10320],[158,10720],[163,11760],[169,12020],[179,12420],[184,12940],[189,13080],[193,13240],[201,13360],[207,13800]]},"ch2-007":{"text":"Do you know what page we are supposed to be on?","voiceUrl":"voices/chapter-2/ch2-007.mp3","durationMs":3120,"cues":[[3,160],[7,360],[12,620],[17,980],[22,1260],[25,1700],[29,1800],[38,1940],[41,2380],[44,2540],[47,2740]]},"ch2-008":{"text":"Page... forty-two. I think.","voiceUrl":"voices/chapter-2/ch2-008.mp3","durationMs":4008,"cues":[[8,120],[19,1320],[21,2960],[27,3040]]},"ch2-009":{"text":"The teacher wrote fifty-four on the board.","voiceUrl":"voices/chapter-2/ch2-009.mp3","durationMs":3024,"cues":[[4,120],[12,280],[18,760],[29,1160],[32,1960],[36,2120],[42,2260]]},"ch2-010":{"text":"Right. I was checking whether you were paying attention.","voiceUrl":"voices/chapter-2/ch2-010.mp3","durationMs":2880,"cues":[[7,120],[9,540],[13,620],[22,900],[30,1340],[34,1700],[39,1780],[46,1940],[56,2340]]},"ch2-011":{"text":"Very helpful. Terima kasih—thank you, page forty-two.","voiceUrl":"voices/chapter-2/ch2-011.mp3","durationMs":4800,"cues":[[5,160],[14,740],[21,1340],[27,1760],[33,2520],[38,3000],[43,3440],[53,3780]]},"ch2-012":{"text":"Her smile turned my embarrassment into a private joke. The next week she asked if I had finally found the correct page. The week after that, I saved her a seat.","voiceUrl":"voices/chapter-2/ch2-012.mp3","durationMs":8952,"cues":[[4,80],[10,240],[17,680],[20,980],[34,1120],[39,1820],[41,2000],[49,2100],[55,2500],[59,3680],[64,3780],[69,4059],[73,4280],[79,4480],[82,4820],[84,4940],[88,4980],[96,5120],[102,5460],[106,5640],[114,5740],[120,6080],[124,7080],[129,7160],[135,7380],[141,7640],[143,7940],[149,8039],[153,8260],[155,8380],[160,8520]]},"ch2-013":{"text":"Conversation arrived in pieces: complaints about vocabulary lists, comparisons of long commutes, recommendations for songs. She was observant without making a show of it.","voiceUrl":"voices/chapter-2/ch2-013.mp3","durationMs":12240,"cues":[[13,120],[21,840],[24,1280],[32,1460],[43,2660],[49,3240],[60,3520],[67,4260],[79,5020],[82,5740],[87,5900],[97,6180],[113,7180],[117,8039],[124,8200],[128,9820],[132,9980],[142,10120],[150,10880],[157,11200],[159,11520],[164,11600],[167,11800],[170,11920]]},"ch2-014":{"text":"You always draw boxes in the margins. Is that meant to be a building?","voiceUrl":"voices/chapter-2/ch2-014.mp3","durationMs":5520,"cues":[[4,240],[11,360],[16,720],[22,1240],[25,1840],[29,1960],[38,2060],[41,3740],[46,3900],[52,4140],[55,4420],[58,4560],[60,4700],[69,4800]]},"ch2-015":{"text":"A base. You build walls, add rooms, and make systems so everything works together.","voiceUrl":"voices/chapter-2/ch2-015.mp3","durationMs":5280,"cues":[[2,100],[8,220],[12,1220],[18,1320],[25,1580],[29,2300],[36,2500],[40,3060],[45,3160],[53,3380],[56,3940],[67,4120],[73,4540],[82,4820]]},"ch2-016":{"text":"You sound happier explaining that than anything in this textbook.","voiceUrl":"voices/chapter-2/ch2-016.mp3","durationMs":3912,"cues":[[4,200],[10,360],[18,740],[29,1240],[34,1900],[39,2180],[48,2380],[51,2780],[56,2920],[65,3140]]},"ch2-017":{"text":"She was right. I loved digital spaces where effort produced visible structure. You placed one block, then another, and the empty world became somewhere people wanted to stay.","voiceUrl":"voices/chapter-2/ch2-017.mp3","durationMs":12240,"cues":[[4,120],[8,280],[15,500],[17,1640],[23,1820],[31,2360],[38,2860],[44,3300],[51,3600],[60,4000],[68,4560],[79,5080],[83,6420],[90,6540],[94,6900],[101,7140],[106,7880],[115,8060],[119,8920],[123,9040],[129,9280],[135,9640],[142,10020],[152,10400],[159,10800],[166,11160],[169,11480],[174,11720]]},"ch2-018":{"text":"I also liked Hana, which was less orderly. Every good conversation made the next one feel more important. Every goodbye left me rehearsing what I should have said.","voiceUrl":"voices/chapter-2/ch2-018.mp3","durationMs":12144,"cues":[[2,160],[7,280],[13,620],[19,960],[25,1760],[29,2140],[34,2380],[43,2760],[49,4160],[54,4540],[67,4780],[72,5900],[76,6040],[81,6200],[85,6520],[90,6900],[95,7120],[106,7300],[112,8760],[120,9020],[125,10080],[128,10340],[139,10480],[144,11020],[146,11200],[153,11320],[158,11520],[163,11700]]},"ch2-019":{"text":"Faris noticed before I told him. He was short and round, with fluffy hair, glasses, and the relaxed confidence of someone who considered awkwardness a problem other people had.","voiceUrl":"voices/chapter-2/ch2-019.mp3","durationMs":11040,"cues":[[6,120],[14,520],[21,960],[23,1320],[28,1420],[33,1660],[36,2660],[40,2760],[46,2920],[50,3440],[57,3600],[62,4380],[69,4580],[75,4940],[84,5440],[88,6400],[92,6500],[100,6580],[111,7120],[114,7620],[122,7740],[126,8000],[137,8119],[149,8660],[151,9440],[159,9540],[165,9980],[172,10220],[176,10560]]},"ch2-020":{"text":"You wait until Hana leaves before you walk to the gate, then somehow reach the gate at the same time. Very subtle, bro.","voiceUrl":"voices/chapter-2/ch2-020.mp3","durationMs":9912,"cues":[[4,140],[9,340],[15,660],[20,1060],[27,1400],[34,1800],[38,2460],[43,2640],[46,2920],[50,3040],[56,3200],[61,4480],[69,5040],[75,5740],[79,6060],[84,6220],[87,6600],[91,6780],[96,7020],[102,7480],[107,8320],[115,9000],[119,9400]]},"ch2-021":{"text":"It is a public walkway.","voiceUrl":"voices/chapter-2/ch2-021.mp3","durationMs":1656,"cues":[[3,180],[6,320],[8,620],[15,680],[23,940]]},"ch2-022":{"text":"And your face is public evidence. You like her. Shall I help?","voiceUrl":"voices/chapter-2/ch2-022.mp3","durationMs":5112,"cues":[[4,120],[9,400],[14,760],[17,1180],[24,1460],[34,2080],[38,3040],[43,3320],[48,3600],[54,4160],[56,4480],[61,4580]]},"ch2-023":{"text":"Help how?","voiceUrl":"voices/chapter-2/ch2-023.mp3","durationMs":1512,"cues":[[5,320],[9,660]]},"ch2-024":{"text":"I can speak to her. Nothing dramatic. Just tell her you are interested and ask whether she would be comfortable talking to you about it.","voiceUrl":"voices/chapter-2/ch2-024.mp3","durationMs":8232,"cues":[[2,180],[6,300],[12,580],[15,840],[20,980],[28,1680],[38,2060],[43,3060],[48,3380],[52,3580],[56,3860],[60,3960],[71,4180],[75,4980],[79,5280],[87,5600],[91,5900],[97,6040],[100,6200],[112,6380],[120,6920],[123,7340],[127,7440],[133,7580],[136,7820]]},"ch2-wingman-simple-001":{"text":"Just say I like her. Simple. Before I overthink it and move to another country.","voiceUrl":"voices/chapter-2/ch2-wingman-simple-001.mp3","durationMs":4680,"cues":[[5,140],[9,480],[11,800],[16,980],[21,1180],[29,1680],[36,2320],[38,2780],[48,2840],[51,3220],[55,3440],[60,3740],[63,3900],[71,3980],[79,4180]]},"ch2-wingman-simple-002":{"text":"Direct and efficient. I knew there was hope for you.","voiceUrl":"voices/chapter-2/ch2-wingman-simple-002.mp3","durationMs":4080,"cues":[[7,140],[11,680],[22,920],[24,1820],[29,2060],[35,2320],[39,2500],[44,2720],[48,2980],[52,3200]]},"ch2-wingman-sincere-001":{"text":"Tell her I really value the time we spend together. And that I would like it to mean something, if she does too.","voiceUrl":"voices/chapter-2/ch2-wingman-sincere-001.mp3","durationMs":7176,"cues":[[5,100],[9,300],[11,620],[18,860],[24,1420],[28,1860],[33,2000],[36,2280],[42,2420],[52,2600],[56,3540],[61,3700],[63,4320],[69,4380],[74,4580],[77,4780],[80,4900],[85,5040],[96,5280],[99,6100],[103,6240],[108,6380],[112,6620]]},"ch2-wingman-sincere-002":{"text":"Wah. Very sincere. I will remove the part where your voice nearly disappeared.","voiceUrl":"voices/chapter-2/ch2-wingman-sincere-002.mp3","durationMs":6240,"cues":[[5,200],[10,1120],[19,1600],[21,3040],[26,3120],[33,3300],[37,3740],[42,3900],[48,4180],[53,4320],[59,4500],[66,4940],[78,5380]]},"ch2-wingman-pressure-001":{"text":"Make sure she knows there is no pressure. If she does not feel the same, I do not want class to become uncomfortable.","voiceUrl":"voices/chapter-2/ch2-wingman-pressure-001.mp3","durationMs":6264,"cues":[[5,140],[10,320],[14,500],[20,660],[26,1060],[29,1300],[32,1720],[42,1900],[45,2740],[49,2820],[54,2960],[58,3120],[63,3300],[67,3460],[73,3560],[75,4080],[78,4220],[82,4360],[87,4560],[93,4720],[96,5020],[103,5100],[117,5540]]},"ch2-wingman-pressure-002":{"text":"Good. I will ask, not corner her. Wingman service with ethics.","voiceUrl":"voices/chapter-2/ch2-wingman-pressure-002.mp3","durationMs":6072,"cues":[[6,160],[8,1140],[13,1220],[18,1580],[22,2200],[29,2520],[34,2900],[42,3900],[50,4380],[55,5020],[62,5420]]},"ch2-025":{"text":"Faris walked across the courtyard before my courage could object. He spoke to Hana briefly, without an audience. She looked surprised, glanced toward me, and asked him something I could not hear.","voiceUrl":"voices/chapter-2/ch2-025.mp3","durationMs":11424,"cues":[[6,100],[13,500],[20,720],[24,1080],[34,1200],[41,1740],[44,2020],[52,2200],[58,2600],[66,2740],[69,4000],[75,4140],[78,4360],[83,4480],[92,4780],[100,5220],[103,5560],[113,5680],[117,6800],[124,6960],[135,7380],[143,8280],[150,8860],[154,9180],[158,9360],[164,9760],[168,10000],[178,10200],[180,10560],[186,10640],[190,10800],[195,11020]]},"ch2-026":{"text":"She said you should tell her yourself. This is good news, by the way.","voiceUrl":"voices/chapter-2/ch2-026.mp3","durationMs":4560,"cues":[[4,180],[9,440],[13,720],[20,840],[25,1080],[29,1300],[39,1500],[44,2740],[47,2960],[52,3200],[58,3440],[61,3760],[65,3940],[69,4059]]},"ch2-027":{"text":"How is that good news? Your entire job was to prevent me from doing that.","voiceUrl":"voices/chapter-2/ch2-027.mp3","durationMs":3936,"cues":[[4,160],[7,320],[12,440],[17,700],[23,920],[28,1440],[35,1560],[39,2120],[43,2500],[46,2640],[54,2740],[57,3100],[62,3340],[68,3520],[73,3740]]},"ch2-028":{"text":"My job was to open the door. Walking through is your character development.","voiceUrl":"voices/chapter-2/ch2-028.mp3","durationMs":6312,"cues":[[3,180],[7,460],[11,820],[14,1040],[19,1360],[23,1680],[29,1840],[37,2880],[45,3380],[48,4100],[53,4380],[63,4880],[75,5400]]},"ch2-029":{"text":"Hi. I assume Faris gave a very calm and accurate presentation.","voiceUrl":"voices/chapter-2/ch2-029.mp3","durationMs":4752,"cues":[[4,160],[6,940],[13,1020],[19,1460],[24,1820],[26,2160],[31,2360],[36,2640],[40,3040],[49,3280],[62,3600]]},"ch2-030":{"text":"He used the phrase 'important diplomatic matter.'","voiceUrl":"voices/chapter-2/ch2-030.mp3","durationMs":3912,"cues":[[3,100],[8,340],[12,600],[20,780],[30,1580],[41,2360],[49,3140]]},"ch2-031":{"text":"That sounds like him. The accurate part is that I like you.","voiceUrl":"voices/chapter-2/ch2-031.mp3","durationMs":4296,"cues":[[5,100],[12,220],[17,400],[22,560],[26,1480],[35,1640],[40,1920],[43,2520],[48,2620],[50,3060],[55,3260],[59,3640]]},"ch2-032":{"text":"I like you too. I was not sure whether you were interested or just always lost after class.","voiceUrl":"voices/chapter-2/ch2-032.mp3","durationMs":7680,"cues":[[2,240],[7,360],[11,700],[16,960],[18,2780],[22,2900],[26,3120],[31,3420],[39,3740],[43,4059],[48,4140],[59,4360],[62,5140],[67,5340],[74,5680],[79,6060],[85,6620],[91,6960]]},"ch2-033":{"text":"Both can be true.","voiceUrl":"voices/chapter-2/ch2-033.mp3","durationMs":2040,"cues":[[5,620],[9,840],[12,960],[17,1100]]},"ch2-034":{"text":"We agreed to try. No grand declaration, only mutual relief and the shy happiness of discovering that hope had been shared.","voiceUrl":"voices/chapter-2/ch2-034.mp3","durationMs":8952,"cues":[[3,120],[10,240],[13,660],[18,820],[21,1940],[27,2160],[40,2540],[45,3440],[52,3740],[59,4260],[63,5080],[67,5180],[71,5300],[81,5640],[84,6160],[96,6260],[101,6820],[106,7020],[110,7840],[115,8000],[122,8280]]},"ch2-035":{"text":"For a while, the weekly class became the centre of my calendar. Hana and I exchanged messages between lessons and stretched the walk to the bus stop whenever time allowed.","voiceUrl":"voices/chapter-2/ch2-035.mp3","durationMs":10152,"cues":[[4,100],[6,240],[13,340],[17,1000],[24,1160],[30,1500],[37,1880],[41,2160],[48,2360],[51,2680],[54,2820],[64,3020],[69,4320],[73,4580],[75,4880],[85,5020],[94,5700],[102,6160],[110,6520],[114,7320],[124,7520],[128,8020],[133,8140],[136,8340],[140,8440],[144,8560],[149,8740],[158,9000],[163,9300],[171,9540]]},"ch2-036":{"text":"You know we could walk directly to the gate.","voiceUrl":"voices/chapter-2/ch2-036.mp3","durationMs":2952,"cues":[[4,200],[9,340],[12,600],[18,760],[23,960],[32,1400],[35,2020],[39,2160],[44,2300]]},"ch2-037":{"text":"This route has better... trees.","voiceUrl":"voices/chapter-2/ch2-037.mp3","durationMs":2640,"cues":[[5,160],[11,420],[15,720],[25,980],[31,2040]]},"ch2-038":{"text":"We have passed the same tree twice.","voiceUrl":"voices/chapter-2/ch2-038.mp3","durationMs":3024,"cues":[[3,180],[8,360],[15,580],[19,980],[24,1200],[29,1660],[35,2100]]},"ch2-039":{"text":"She knew what I was doing and walked the second circle anyway. It was an ordinary kindness. I wish I had understood then how relationships are built from attention to ordinary things.","voiceUrl":"voices/chapter-2/ch2-039.mp3","durationMs":12960,"cues":[[4,100],[9,260],[14,460],[16,700],[20,780],[26,940],[30,1700],[37,1860],[41,2280],[48,2420],[55,2720],[63,3060],[66,4640],[70,4760],[73,4920],[82,5220],[92,5780],[94,7560],[99,7640],[101,7880],[105,7920],[116,8060],[121,8560],[125,8940],[139,9080],[143,9780],[149,9960],[154,10220],[164,10400],[167,11440],[176,11740],[183,12300]]},"ch2-040":{"text":"At home, another world was taking shape. I had started running a Minecraft server: part community, part small business, part endlessly demanding machine.","voiceUrl":"voices/chapter-2/ch2-040.mp3","durationMs":11040,"cues":[[3,180],[9,320],[17,1240],[23,1580],[27,1980],[34,2160],[41,2500],[43,3700],[47,3780],[55,3920],[63,4280],[65,4600],[75,4740],[83,5420],[88,6260],[99,6480],[104,7160],[110,7420],[120,7700],[125,8700],[135,9220],[145,9800],[153,10320]]},"ch2-041":{"text":"I learned to configure systems, settle disputes, organise volunteers, and keep strangers returning. Every solved problem revealed two more, which felt less like failure than an invitation.","voiceUrl":"voices/chapter-2/ch2-041.mp3","durationMs":13344,"cues":[[2,160],[10,240],[13,500],[23,600],[32,1020],[39,2000],[49,2280],[58,3400],[70,3860],[74,5220],[79,5420],[89,5640],[100,6180],[106,7860],[113,8180],[121,8600],[130,9000],[134,9600],[140,9800],[146,10520],[151,10700],[156,11220],[161,11460],[169,11720],[174,12220],[177,12380],[188,12560]]},"ch2-042":{"text":"Players joined. A community formed. Support began arriving from people who valued the place enough to contribute. I was making real money from something I had built in my bedroom.","voiceUrl":"voices/chapter-2/ch2-042.mp3","durationMs":11520,"cues":[[8,100],[16,560],[18,1640],[28,1720],[36,2320],[44,3440],[50,3900],[59,4180],[64,4700],[71,4880],[75,5180],[82,5360],[86,5700],[92,5820],[99,6100],[102,6340],[114,6440],[116,7920],[120,7980],[127,8160],[132,8600],[138,8980],[143,9280],[153,9480],[155,9880],[159,9940],[165,10120],[168,10440],[171,10560],[179,10840]]},"ch2-043":{"text":"Hana, someone supported the server again. They said it is the first place online where their friends all enjoy playing together.","voiceUrl":"voices/chapter-2/ch2-043.mp3","durationMs":6720,"cues":[[6,140],[14,660],[24,980],[28,1320],[35,1460],[42,1760],[47,2400],[52,2540],[55,2740],[58,2840],[62,2980],[68,3160],[74,3520],[81,3880],[87,4380],[93,4500],[101,4660],[105,5120],[111,5360],[119,5680],[128,5940]]},"ch2-044":{"text":"That is actually amazing. You made a place people care about.","voiceUrl":"voices/chapter-2/ch2-044.mp3","durationMs":4632,"cues":[[5,180],[8,420],[17,740],[26,1180],[30,2240],[35,2380],[37,2600],[43,2720],[50,3080],[55,3500],[61,3820]]},"ch2-045":{"text":"Her pride mattered to me. The server was not merely a distraction. It taught me leadership, technical patience, and the thrilling fact that my ideas could have value beyond school.","voiceUrl":"voices/chapter-2/ch2-045.mp3","durationMs":12144,"cues":[[4,100],[10,320],[19,940],[22,1280],[26,1400],[30,3000],[37,3120],[41,3400],[45,3580],[52,3780],[54,4019],[67,4080],[70,5180],[77,5300],[80,5520],[92,5700],[102,6500],[112,7000],[116,7940],[120,8039],[130,8200],[135,8720],[140,9400],[143,9620],[149,9940],[155,10360],[160,10500],[166,10720],[173,11140],[180,11540]]},"ch2-046":{"text":"But achievement came with an alarm bell. The server did not care whether I had class the next morning. Problems arrived whenever players were awake, which seemed to be always.","voiceUrl":"voices/chapter-2/ch2-046.mp3","durationMs":11184,"cues":[[4,80],[16,260],[21,940],[26,1240],[29,1420],[35,1560],[41,2020],[45,3220],[52,3380],[56,3780],[60,3920],[65,4180],[73,4520],[75,4780],[79,4840],[85,5020],[89,5400],[94,5500],[103,5780],[112,6860],[120,7340],[129,7740],[137,8080],[142,8400],[149,8580],[155,9560],[162,10000],[165,10240],[168,10340],[175,10520]]},"ch2-047":{"text":"One night, three demands collided: Hana was waiting for a promised call, unfinished revision lay beside the keyboard, and the server began failing under a rush of activity.","voiceUrl":"voices/chapter-2/ch2-047.mp3","durationMs":10800,"cues":[[4,240],[11,420],[17,900],[25,1240],[35,1780],[40,3020],[44,3320],[52,3480],[56,3780],[58,3900],[67,3980],[73,4400],[84,5360],[93,5860],[97,6320],[104,6460],[108,6740],[118,6900],[122,7840],[126,7960],[133,8140],[139,8640],[147,9020],[153,9360],[155,9600],[160,9740],[163,10000],[172,10120]]},"ch2-priority-hana-001":{"text":"I called Hana. For ten minutes, I listened properly while warning messages multiplied behind the call window. She laughed once, and the sound made the choice feel simple.","voiceUrl":"voices/chapter-2/ch2-priority-hana-001.mp3","durationMs":11520,"cues":[[2,160],[9,260],[15,520],[19,1800],[23,1940],[32,2140],[34,2840],[43,2900],[52,3300],[58,4200],[66,4440],[75,4760],[86,5240],[93,5800],[97,6060],[102,6220],[110,6460],[114,8000],[122,8160],[128,8560],[132,9520],[136,9620],[142,9760],[147,10020],[151,10180],[158,10320],[163,10740],[170,11080]]},"ch2-priority-hana-002":{"text":"Then I rushed back to the server and worked far past midnight. Years later, I remembered that attention was possible—but without boundaries, I treated it as an exception I could not sustain.","voiceUrl":"voices/chapter-2/ch2-priority-hana-002.mp3","durationMs":12624,"cues":[[5,160],[7,440],[14,560],[19,920],[22,1160],[26,1300],[33,1420],[37,2000],[44,2180],[48,2540],[53,2860],[63,3220],[69,4940],[76,5220],[78,5600],[89,5680],[94,6160],[104,6300],[108,7100],[117,7280],[121,8460],[129,8600],[141,8980],[143,9940],[151,10060],[154,10380],[157,10640],[160,10760],[170,10840],[172,11520],[178,11560],[182,11720],[190,11940]]},"ch2-priority-server-001":{"text":"I told myself I needed only ten minutes to stabilise the server. Ten became forty. By the time I reached for my phone, Hana's message simply said she was going to sleep.","voiceUrl":"voices/chapter-2/ch2-priority-server-001.mp3","durationMs":11904,"cues":[[2,320],[7,420],[14,660],[16,1140],[23,1220],[28,1560],[32,1920],[40,2160],[43,2540],[53,2680],[57,3260],[65,3400],[69,5040],[76,5480],[83,5900],[86,6980],[90,7120],[95,7220],[97,7440],[105,7520],[109,7840],[112,7980],[119,8160],[126,8880],[134,9220],[141,9640],[146,9980],[150,10780],[154,10920],[160,11080],[163,11340],[169,11500]]},"ch2-priority-server-002":{"text":"Years later, I remembered how reasonable every delay sounded from inside it. I never chose to neglect her in one dramatic moment. I chose 'just a little longer' again and again.","voiceUrl":"voices/chapter-2/ch2-priority-server-002.mp3","durationMs":13752,"cues":[[6,160],[13,480],[15,1200],[26,1280],[30,1680],[41,1880],[47,2460],[53,2720],[61,3100],[66,3520],[73,3740],[77,4200],[79,5560],[85,5640],[91,5880],[94,6220],[102,6320],[106,6700],[109,6880],[113,7060],[122,7500],[130,7940],[132,9100],[139,9200],[144,10320],[146,10760],[153,10840],[161,11160],[167,12120],[171,12980],[177,13140]]},"ch2-priority-study-001":{"text":"I closed the dashboard and revised first. Yet my eyes kept moving between the textbook and two silent screens, absorbing little from the page and giving nothing fully to either person or server.","voiceUrl":"voices/chapter-2/ch2-priority-study-001.mp3","durationMs":13104,"cues":[[2,200],[9,280],[13,640],[23,780],[27,1360],[35,1480],[42,2080],[46,3300],[49,3460],[54,3700],[59,4000],[66,4240],[74,4560],[78,4840],[87,4980],[91,5880],[95,6060],[102,6360],[111,6820],[121,7920],[128,8500],[133,8760],[137,8920],[142,9060],[146,9920],[153,10080],[161,10380],[167,10880],[170,11220],[177,11400],[184,11720],[187,12300],[194,12560]]},"ch2-priority-study-002":{"text":"Years later, I remembered that choosing the responsible task was not enough if I had already built a life with no margin. The crisis was not that night; it was the pattern around it.","voiceUrl":"voices/chapter-2/ch2-priority-study-002.mp3","durationMs":11592,"cues":[[6,260],[13,580],[15,1360],[26,1460],[31,1900],[40,2100],[44,2480],[56,2560],[61,3180],[65,3620],[69,3820],[76,4000],[79,4740],[81,4880],[85,4940],[93,5140],[99,5520],[101,5740],[106,5840],[111,6140],[114,6360],[122,6600],[126,8240],[133,8360],[137,8800],[141,8960],[146,9220],[153,9420],[156,10260],[160,10360],[164,10540],[172,10680],[179,11100],[182,11440]]},"ch2-048":{"text":"The server recovered. The homework was eventually submitted. Hana and I spoke again. From the outside, nothing had broken. That made it easy to ignore what the night was showing me.","voiceUrl":"voices/chapter-2/ch2-048.mp3","durationMs":11664,"cues":[[4,120],[11,260],[22,660],[26,1860],[35,1960],[39,2440],[50,2580],[61,3000],[66,4500],[70,4840],[72,5080],[78,5220],[85,5440],[90,6840],[94,7000],[103,7120],[111,7680],[115,7920],[123,8039],[128,9100],[133,9280],[136,9420],[141,9600],[144,9880],[151,9960],[156,10400],[160,10560],[166,10680],[170,10880],[178,11040],[181,11360]]},"ch2-049":{"text":"Success made the pattern harder to challenge. More players meant more responsibility and more income. Every late night produced evidence that the late night had been worthwhile.","voiceUrl":"voices/chapter-2/ch2-049.mp3","durationMs":11664,"cues":[[8,120],[13,660],[17,840],[25,1000],[32,1420],[35,1780],[46,1940],[51,3200],[59,3400],[65,3840],[70,4080],[85,4260],[89,5460],[94,5780],[102,6040],[108,7640],[113,7920],[119,8180],[128,8560],[137,8980],[142,9520],[146,9640],[151,9760],[157,10020],[161,10380],[166,10560],[177,10840]]},"ch2-050":{"text":"Schoolwork was different. One neglected topic did not immediately collapse. A missed revision session created no flashing alert. The consequences waited quietly, gathering weight beyond the edge of the screen.","voiceUrl":"voices/chapter-2/ch2-050.mp3","durationMs":14640,"cues":[[11,180],[15,800],[26,1000],[30,2320],[40,2480],[46,2960],[50,3320],[54,3460],[66,3640],[76,4300],[78,5680],[85,5780],[94,6120],[102,6580],[110,7360],[113,7780],[122,8020],[129,8380],[133,9960],[146,10080],[153,10760],[162,11180],[172,12360],[179,12800],[186,13160],[190,13460],[195,13580],[198,13760],[202,13880],[209,14020]]},"ch2-051":{"text":"Hana waited quietly too, at first. I still arrived at language class. I still smiled when I saw her. I mistook continued affection for proof that affection required no maintenance.","voiceUrl":"voices/chapter-2/ch2-051.mp3","durationMs":12144,"cues":[[5,100],[12,480],[20,880],[25,1340],[28,1860],[35,2020],[37,3640],[43,3760],[51,3940],[54,4340],[63,4480],[70,4880],[72,5860],[78,6000],[85,6260],[90,6680],[92,6840],[96,6960],[101,7160],[103,8039],[111,8119],[121,8740],[131,9200],[135,9700],[141,9880],[146,10220],[156,10360],[165,10760],[168,11200],[180,11400]]},"ch2-052":{"text":"You disappeared last night. Everything okay?","voiceUrl":"voices/chapter-2/ch2-052.mp3","durationMs":3672,"cues":[[4,160],[16,300],[21,1060],[28,1440],[39,2440],[44,2940]]},"ch2-053":{"text":"Server issue. It was quite bad, but I fixed it.","voiceUrl":"voices/chapter-2/ch2-053.mp3","durationMs":2808,"cues":[[7,180],[14,480],[17,1060],[21,1220],[27,1580],[32,1780],[36,2140],[38,2260],[44,2340],[47,2580]]},"ch2-054":{"text":"I am glad you fixed it. I was worried because you said you would call.","voiceUrl":"voices/chapter-2/ch2-054.mp3","durationMs":5280,"cues":[[2,200],[5,300],[10,560],[14,900],[20,1080],[24,1580],[26,2600],[30,2680],[38,2920],[46,3380],[50,3720],[55,3900],[59,4160],[65,4260],[70,4480]]},"ch2-055":{"text":"Sorry. Next time I will message first.","voiceUrl":"voices/chapter-2/ch2-055.mp3","durationMs":2040,"cues":[[7,160],[12,660],[17,820],[19,1180],[24,1220],[32,1320],[38,1560]]},"ch2-056":{"text":"I meant the apology. I also meant the promise. Intentions were never the missing ingredient; I lacked the habit of turning them into action.","voiceUrl":"voices/chapter-2/ch2-056.mp3","durationMs":9672,"cues":[[2,160],[8,260],[12,460],[21,580],[23,2320],[28,2460],[34,2780],[38,2960],[47,3080],[58,4500],[63,5180],[69,5400],[73,5660],[81,5760],[93,6080],[95,7420],[102,7540],[106,7860],[112,8020],[115,8320],[123,8460],[128,8740],[133,8880],[140,9160]]},"ch2-057":{"text":"Next time, I remembered only after the crisis had started. The time after that, I sent a quick message so vague it asked her to wait without telling her for how long.","voiceUrl":"voices/chapter-2/ch2-057.mp3","durationMs":10704,"cues":[[5,120],[11,420],[13,1240],[24,1320],[29,1840],[35,2220],[39,2540],[46,2640],[50,3040],[59,3260],[63,4520],[68,4620],[74,4880],[80,5140],[82,6040],[87,6120],[89,6280],[95,6380],[103,6600],[106,7100],[112,7400],[115,8180],[121,8340],[125,8540],[128,8660],[133,8860],[141,9260],[149,9540],[153,9780],[157,9900],[161,10020],[166,10220]]},"ch2-058":{"text":"My days narrowed. At school, I thought about the server. At home, I managed it. When Hana spoke, part of me listened while another part counted unresolved tasks.","voiceUrl":"voices/chapter-2/ch2-058.mp3","durationMs":12000,"cues":[[3,140],[8,360],[18,840],[21,2180],[29,2400],[31,2800],[39,2880],[45,3100],[49,3300],[57,3440],[60,4580],[66,4720],[68,5480],[76,5620],[80,6060],[85,7120],[90,7240],[97,7540],[102,8440],[105,8620],[108,8720],[117,8880],[123,9300],[131,9480],[136,9820],[144,10120],[155,10540],[161,11340]]},"ch2-059":{"text":"You are here, but sometimes it feels like you are waiting to go back to your computer.","voiceUrl":"voices/chapter-2/ch2-059.mp3","durationMs":7344,"cues":[[4,220],[8,480],[14,720],[18,1840],[28,2160],[31,2900],[37,3100],[42,3520],[46,3880],[50,4140],[58,4440],[61,5280],[64,5420],[69,5620],[72,6000],[77,6140],[86,6340]]},"ch2-060":{"text":"That is not fair. I have a lot to manage right now.","voiceUrl":"voices/chapter-2/ch2-060.mp3","durationMs":2952,"cues":[[5,140],[8,280],[12,520],[18,920],[20,1560],[25,1600],[27,1720],[31,1840],[34,2060],[41,2180],[47,2480],[51,2640]]},"ch2-061":{"text":"I know you do. I am not asking you to stop caring about it. I am asking whether there is still room for me.","voiceUrl":"voices/chapter-2/ch2-061.mp3","durationMs":9840,"cues":[[2,180],[7,300],[11,580],[15,760],[17,2040],[20,2120],[24,2300],[31,2640],[35,3040],[38,3160],[43,3300],[50,3620],[56,4040],[60,4360],[62,6360],[65,6520],[72,6760],[80,7420],[86,7760],[89,7940],[95,8180],[100,8560],[104,8960],[107,9180]]},"ch2-062":{"text":"Her question reached the part of me that knew she was right. Another part heard criticism of the thing I was proudest of and raised its defences.","voiceUrl":"voices/chapter-2/ch2-062.mp3","durationMs":8952,"cues":[[4,140],[13,340],[21,860],[25,1340],[30,1460],[33,1680],[36,1800],[41,2000],[46,2160],[50,2500],[54,2640],[61,2840],[69,4080],[74,4420],[80,4680],[90,4920],[93,5520],[97,5620],[103,5740],[105,6060],[109,6140],[118,6340],[121,6840],[125,7420],[132,7600],[136,7980],[145,8160]]},"ch2-063":{"text":"There is room. This busy period will settle down. I just need you to be patient with me.","voiceUrl":"voices/chapter-2/ch2-063.mp3","durationMs":5352,"cues":[[6,260],[9,520],[15,740],[20,1460],[25,1640],[32,1900],[37,2320],[44,2580],[50,2820],[52,3480],[57,3680],[62,3940],[66,4100],[69,4160],[72,4240],[80,4360],[85,4660],[88,4800]]},"ch2-064":{"text":"I have been patient, Aleem.","voiceUrl":"voices/chapter-2/ch2-064.mp3","durationMs":3504,"cues":[[2,380],[7,580],[12,920],[21,1380],[27,2600]]},"ch2-065":{"text":"I carried those words home, placed them beside all my other unfinished obligations, and opened the server dashboard.","voiceUrl":"voices/chapter-2/ch2-065.mp3","durationMs":7272,"cues":[[2,340],[10,440],[16,740],[22,980],[28,1320],[35,2060],[40,2380],[47,2540],[51,3040],[54,3240],[60,3500],[71,3820],[84,4380],[88,5480],[95,5640],[99,6000],[106,6160],[116,6480]]},"ch2-066":{"text":"My school results began reflecting the same imbalance. Teachers marked gaps I promised to close. Notes accumulated. I understood each warning separately and failed to see the shape they formed together.","voiceUrl":"voices/chapter-2/ch2-066.mp3","durationMs":13680,"cues":[[3,200],[10,400],[18,720],[24,1200],[35,1520],[39,2060],[44,2220],[55,2480],[64,3780],[71,4240],[76,4640],[78,5060],[87,5200],[90,5560],[97,5660],[103,6660],[116,7240],[118,8800],[129,8880],[134,9440],[142,9700],[153,10140],[157,11020],[164,11200],[167,11500],[171,11620],[175,11780],[181,11920],[186,12460],[193,12660],[202,13100]]},"ch2-067":{"text":"I will catch up during the break.","voiceUrl":"voices/chapter-2/ch2-067.mp3","durationMs":2112,"cues":[[2,300],[7,340],[13,600],[16,880],[23,1100],[27,1360],[33,1440]]},"ch2-068":{"text":"The break arrived carrying server plans. Catching up moved to the following week, then the next month, always close enough to sound possible.","voiceUrl":"voices/chapter-2/ch2-068.mp3","durationMs":9120,"cues":[[4,120],[10,220],[18,480],[27,940],[34,1380],[41,1700],[50,2780],[53,3160],[59,3460],[62,3880],[66,4000],[76,4100],[82,4520],[87,5160],[91,5600],[96,5700],[103,6040],[110,6840],[116,7180],[123,7460],[126,7760],[132,7900],[141,8500]]},"ch2-069":{"text":"At language class, the easy rhythm between Hana and me faded. We still sat near each other, but conversation became practical. Page numbers. Assignment dates. Which bus was coming.","voiceUrl":"voices/chapter-2/ch2-069.mp3","durationMs":12072,"cues":[[3,80],[12,240],[19,680],[23,1420],[28,1580],[35,1920],[43,2200],[48,2560],[52,2840],[55,3000],[62,3280],[65,4580],[71,4720],[75,4960],[80,5180],[85,5360],[92,5580],[96,6320],[109,6460],[116,7100],[127,7440],[132,8520],[141,8840],[152,9680],[159,10240],[165,10900],[169,11140],[173,11460],[180,11640]]},"ch2-070":{"text":"Are you angry with me?","voiceUrl":"voices/chapter-2/ch2-070.mp3","durationMs":1656,"cues":[[4,140],[8,340],[14,980],[19,1260],[22,1420]]},"ch2-071":{"text":"I am tired of having the same conversation.","voiceUrl":"voices/chapter-2/ch2-071.mp3","durationMs":5040,"cues":[[2,240],[5,360],[11,640],[14,1600],[21,1760],[25,2380],[30,2640],[43,3420]]},"ch2-072":{"text":"Then tell me what you want me to do.","voiceUrl":"voices/chapter-2/ch2-072.mp3","durationMs":2184,"cues":[[5,120],[10,300],[13,520],[18,940],[22,1100],[27,1220],[30,1600],[33,1720],[36,1840]]},"ch2-073":{"text":"I wanted you to want to be present. I do not know how to turn that into instructions.","voiceUrl":"voices/chapter-2/ch2-073.mp3","durationMs":7992,"cues":[[2,200],[9,360],[13,820],[16,1020],[21,1300],[24,1720],[27,1840],[36,2020],[38,4920],[41,5060],[45,5260],[50,5520],[54,5680],[57,5800],[62,5960],[67,6240],[72,6500],[85,6800]]},"ch2-074":{"text":"I heard the sadness, but I also heard an impossible request. At sixteen, I believed effort counted only when it looked like solving. Presence did not feel measurable enough to manage.","voiceUrl":"voices/chapter-2/ch2-074.mp3","durationMs":12240,"cues":[[2,140],[8,240],[12,500],[21,680],[25,1720],[27,1920],[32,2020],[38,2400],[41,2640],[52,2760],[61,3400],[64,5060],[73,5240],[75,6220],[84,6280],[91,6680],[99,7000],[104,7380],[109,7640],[112,7760],[119,7920],[124,8160],[133,8420],[142,9600],[146,10240],[150,10340],[155,10540],[166,10800],[173,11260],[176,11520],[183,11660]]},"ch2-075":{"text":"After that, there was no single breakup conversation. There were shorter replies and seats left unsaved. We drifted into a silence I recognised from Alya, though this time I was helping create it.","voiceUrl":"voices/chapter-2/ch2-075.mp3","durationMs":13200,"cues":[[6,220],[12,500],[18,1220],[22,1340],[25,1500],[32,1760],[40,2120],[54,2480],[60,4080],[65,4180],[73,4340],[81,4680],[85,5520],[91,5700],[96,6100],[105,6340],[108,7900],[116,8039],[121,8460],[123,8640],[131,8760],[133,9260],[144,9360],[149,10000],[155,10240],[162,11100],[167,11280],[172,11480],[174,12000],[178,12100],[186,12260],[193,12600],[196,12960]]},"ch2-076":{"text":"Aleem, I thought you should hear it from someone. Hana has moved on.","voiceUrl":"voices/chapter-2/ch2-076.mp3","durationMs":6144,"cues":[[7,160],[9,1500],[17,1640],[21,1900],[28,2020],[33,2200],[36,2400],[41,2560],[50,2800],[55,3980],[59,4380],[65,4640],[68,4960]]},"ch2-077":{"text":"The words landed in an ordinary courtyard after an ordinary class. For a moment, even the sounds around us seemed badly timed.","voiceUrl":"voices/chapter-2/ch2-077.mp3","durationMs":8232,"cues":[[4,100],[10,240],[17,620],[20,1280],[23,1380],[32,1600],[42,2080],[48,2720],[51,2920],[60,3120],[67,3580],[71,4900],[73,5000],[81,5100],[86,5520],[90,5720],[97,5880],[104,6220],[107,6660],[114,6820],[120,7360],[126,7760]]},"ch2-friend-confirm-001":{"text":"Did Hana say that herself? I need to hear it from her, not through somebody else.","voiceUrl":"voices/chapter-2/ch2-friend-confirm-001.mp3","durationMs":4464,"cues":[[4,100],[9,280],[13,560],[18,740],[27,860],[29,2240],[34,2320],[37,2420],[42,2520],[45,2640],[50,2740],[55,2960],[59,3380],[67,3560],[76,3720],[81,4000]]},"ch2-friend-confirm-002":{"text":"That is fair. Please talk to her. I only told you because I thought nobody had.","voiceUrl":"voices/chapter-2/ch2-friend-confirm-002.mp3","durationMs":5760,"cues":[[5,120],[8,340],[14,580],[21,1500],[26,1820],[29,2060],[34,2180],[36,3020],[41,3100],[46,3380],[50,3640],[58,3760],[60,4280],[68,4360],[75,4620],[79,5040]]},"ch2-friend-defend-001":{"text":"You do not know our relationship. Things have been difficult, but that does not mean you can decide what happened.","voiceUrl":"voices/chapter-2/ch2-friend-defend-001.mp3","durationMs":5280,"cues":[[4,140],[7,240],[11,400],[16,620],[20,760],[34,860],[41,1820],[46,2000],[51,2100],[62,2220],[66,2820],[71,2920],[76,3040],[80,3280],[85,3520],[89,3960],[93,4059],[100,4160],[105,4680],[114,4820]]},"ch2-friend-defend-002":{"text":"I am not deciding. I am telling you because you deserve a direct conversation. Ask her.","voiceUrl":"voices/chapter-2/ch2-friend-defend-002.mp3","durationMs":7440,"cues":[[2,260],[5,400],[9,620],[19,920],[21,2300],[24,2400],[32,2600],[36,3060],[44,3380],[48,3840],[56,4019],[58,4480],[65,4580],[79,5020],[83,6560],[87,6900]]},"ch2-friend-silent-001":{"text":"I said nothing. My friend waited, then gently repeated that I should speak to Hana myself. Silence did not make the news less real.","voiceUrl":"voices/chapter-2/ch2-friend-silent-001.mp3","durationMs":8640,"cues":[[2,200],[7,300],[16,520],[19,1780],[26,1920],[34,2200],[39,2860],[46,3080],[55,3440],[60,3980],[62,4160],[69,4240],[75,4480],[78,4700],[83,4840],[91,5060],[99,6480],[103,6940],[107,7080],[112,7300],[116,7480],[121,7600],[126,7940],[131,8220]]},"ch2-friend-silent-002":{"text":"Years later, I would recognise the old reflex from Alya's message: freeze, wait, and hope somebody else carries the difficult words the rest of the way.","voiceUrl":"voices/chapter-2/ch2-friend-silent-002.mp3","durationMs":9744,"cues":[[6,140],[13,440],[15,820],[21,900],[31,1060],[35,1620],[39,1760],[46,1980],[51,2400],[58,2640],[67,2980],[75,4120],[81,5220],[85,5980],[90,6140],[99,6420],[104,6800],[112,7080],[116,7420],[126,7560],[132,8000],[136,8640],[141,8780],[144,9060],[148,9180],[152,9300]]},"ch2-078":{"text":"I asked Hana to stay after class. She agreed. For once, I closed every other task in my mind and gave the conversation my full attention.","voiceUrl":"voices/chapter-2/ch2-078.mp3","durationMs":8640,"cues":[[2,220],[8,340],[13,620],[16,960],[21,1080],[27,1360],[34,1600],[38,2720],[46,2820],[50,4040],[56,4240],[58,4540],[65,4620],[71,5040],[77,5300],[82,5520],[85,5840],[88,5960],[93,6140],[97,6460],[102,6600],[106,6800],[119,6900],[122,7540],[127,7780],[137,7940]]},"ch2-079":{"text":"Someone told me you have moved on. Is that true?","voiceUrl":"voices/chapter-2/ch2-079.mp3","durationMs":3552,"cues":[[8,80],[13,460],[16,760],[20,960],[25,1120],[31,1720],[35,2060],[38,2900],[43,3000],[48,3180]]},"ch2-080":{"text":"Yes. I should have told you directly. I kept waiting for us to feel like us again, and then I stopped believing that would happen.","voiceUrl":"voices/chapter-2/ch2-080.mp3","durationMs":10080,"cues":[[5,220],[7,1120],[14,1220],[19,1380],[24,1560],[28,1820],[38,1940],[40,3880],[45,4019],[53,4320],[57,4720],[60,4940],[63,5140],[68,5300],[73,5520],[76,5860],[83,6100],[87,7340],[92,7480],[94,7720],[102,7860],[112,8260],[117,8780],[123,8920],[130,9080]]},"ch2-081":{"text":"You could have said your feelings changed. Hearing it from somebody else makes me feel foolish.","voiceUrl":"voices/chapter-2/ch2-081.mp3","durationMs":4536,"cues":[[4,160],[10,320],[15,460],[20,620],[25,800],[34,960],[43,1360],[51,2160],[54,2380],[59,2460],[68,2620],[73,2940],[79,3300],[82,3500],[87,3640],[95,3960]]},"ch2-082":{"text":"You are right. I avoided the final conversation, and I am sorry. But I did tell you I was lonely in this relationship. More than once.","voiceUrl":"voices/chapter-2/ch2-082.mp3","durationMs":11592,"cues":[[4,160],[8,440],[15,680],[17,2040],[25,2140],[29,2600],[35,2780],[49,3140],[53,4140],[55,4440],[58,4680],[65,4980],[69,6680],[71,6900],[75,7080],[80,7380],[84,7660],[86,7860],[90,7940],[97,8180],[100,8640],[105,8760],[119,8940],[124,10160],[129,10480],[134,10720]]},"ch2-083":{"text":"Both truths occupied the same space. She should have told me clearly when it ended. I had also taught her, through repeated absence, that my promises to change were not reliable.","voiceUrl":"voices/chapter-2/ch2-083.mp3","durationMs":11904,"cues":[[5,80],[12,420],[21,1040],[25,1460],[30,1660],[37,2020],[41,3360],[48,3540],[53,3700],[58,3880],[61,4120],[69,4340],[74,4780],[77,4920],[84,5080],[86,6320],[90,6380],[95,6560],[102,6860],[107,7100],[115,7620],[124,7860],[133,8400],[138,9180],[141,9340],[150,9520],[153,10020],[160,10240],[165,10720],[169,10940],[178,11220]]},"ch2-084":{"text":"I was busy, but that is not the whole answer. I made you wait too often. I kept assuming there would be another chance to do better.","voiceUrl":"voices/chapter-2/ch2-084.mp3","durationMs":9360,"cues":[[2,220],[6,360],[12,540],[16,1580],[21,1740],[24,1880],[28,2000],[32,2400],[38,2520],[46,3000],[48,3980],[53,4080],[57,4300],[62,4460],[66,5000],[73,5440],[75,6400],[80,6480],[89,6680],[95,7140],[101,7240],[104,7360],[112,7520],[119,7960],[122,8380],[125,8520],[132,8860]]},"ch2-085":{"text":"I know the server matters to you. I never wanted you to fail at it. I just could not keep being the thing you returned to after everything urgent was finished.","voiceUrl":"voices/chapter-2/ch2-085.mp3","durationMs":13032,"cues":[[2,220],[7,360],[11,640],[18,820],[26,1300],[29,1860],[34,2080],[36,3580],[42,3740],[49,4100],[53,4440],[56,4560],[61,4760],[64,5120],[68,5360],[70,6760],[75,6880],[81,7240],[85,7560],[90,8000],[96,8320],[100,8740],[106,8900],[110,9220],[119,9380],[122,10000],[128,10420],[139,10820],[146,11500],[150,12020],[159,12260]]},"ch2-086":{"text":"I understand. Or I think I am starting to.","voiceUrl":"voices/chapter-2/ch2-086.mp3","durationMs":3096,"cues":[[2,180],[14,260],[17,1300],[19,1940],[25,2060],[27,2440],[30,2500],[39,2640],[42,2900]]},"ch2-087":{"text":"We parted without cruelty. That did not make it painless. Hana had been patient until patience began costing her too much; I had noticed the cost only after she stopped paying it.","voiceUrl":"voices/chapter-2/ch2-087.mp3","durationMs":12072,"cues":[[3,120],[10,440],[18,880],[27,1280],[32,2700],[36,2820],[40,3020],[45,3420],[48,3580],[58,3720],[63,5120],[67,5360],[72,5500],[80,5720],[86,6360],[95,6720],[101,7180],[109,7540],[113,7880],[117,8060],[123,8260],[125,9160],[129,9220],[137,9360],[141,9720],[146,9840],[151,10440],[157,10700],[161,10920],[169,11120],[176,11480],[179,11820]]},"ch2-088":{"text":"At home, the server welcomed me with familiar notifications. For the first time, every alert sounded like evidence in a case against me.","voiceUrl":"voices/chapter-2/ch2-088.mp3","durationMs":8472,"cues":[[3,160],[9,320],[13,900],[20,1020],[29,1360],[32,1800],[37,2020],[46,2200],[61,2600],[65,4220],[69,4340],[75,4480],[81,4840],[87,5420],[93,5740],[101,6160],[106,6480],[115,6740],[118,7280],[120,7400],[125,7540],[133,7800],[136,8200]]},"ch2-089":{"text":"That was unfair too. The server had not taken control of my hands. It was a creation, an achievement, and a responsibility. I had chosen to give it boundaries only after other parts of life were damaged.","voiceUrl":"voices/chapter-2/ch2-089.mp3","durationMs":13680,"cues":[[5,160],[9,360],[16,520],[21,1020],[25,1980],[32,2100],[36,2360],[40,2500],[46,2680],[54,2960],[57,3360],[60,3480],[67,3660],[70,4660],[74,4780],[76,4920],[86,5040],[89,6200],[102,6300],[106,7320],[108,7620],[124,7680],[126,9660],[130,9740],[137,9940],[140,10400],[145,10500],[148,10620],[159,10760],[164,11440],[170,11740],[176,12080],[182,12300],[185,12500],[190,12620],[195,12840],[203,13000]]},"ch2-090":{"text":"By 2013, the largest consequence was already waiting. O Levels were no longer a distant threat used by teachers to focus a noisy class. The examinations had dates.","voiceUrl":"voices/chapter-2/ch2-090.mp3","durationMs":12384,"cues":[[3,100],[9,380],[13,1460],[21,1600],[33,2100],[37,2780],[45,2960],[54,3380],[56,4740],[63,4900],[68,5260],[71,5380],[78,5520],[80,5840],[88,5980],[95,6320],[100,7140],[103,7420],[112,7620],[115,8020],[121,8160],[123,8460],[129,8580],[136,8920],[140,10340],[153,10440],[157,11500],[163,11760]]},"ch2-091":{"text":"I tried to compress years of inconsistent study into months. Topics I should have recognised looked newly introduced. Each revision session exposed how much foundation was missing beneath me.","voiceUrl":"voices/chapter-2/ch2-091.mp3","durationMs":12480,"cues":[[2,260],[8,300],[11,600],[20,700],[26,1320],[29,1680],[42,1880],[48,2680],[53,2980],[61,3300],[68,4320],[70,4780],[77,4840],[82,5000],[93,5120],[100,5800],[106,6160],[118,6460],[123,7980],[132,8220],[140,8700],[148,9020],[152,10080],[157,10240],[168,10480],[172,11160],[180,11380],[188,11760],[191,12180]]},"ch2-092":{"text":"I reduced my time online, but habits do not disappear when the timetable becomes frightening. Some nights I revised. Some nights I escaped into problems I still knew how to solve.","voiceUrl":"voices/chapter-2/ch2-092.mp3","durationMs":12144,"cues":[[2,140],[10,220],[13,640],[18,820],[26,1100],[30,2320],[37,2520],[40,3000],[44,3140],[54,3360],[59,3900],[63,4040],[73,4160],[81,4700],[94,5120],[99,6760],[106,6940],[108,7260],[117,7340],[122,8680],[129,8860],[131,9380],[139,9440],[144,9880],[153,10160],[155,10800],[161,10980],[166,11200],[170,11380],[173,11520],[179,11680]]},"ch2-093":{"text":"A server problem had a clear cause, tools, and grateful players when repaired. A page of questions could stare back without offering any clue where my understanding had first gone wrong.","voiceUrl":"voices/chapter-2/ch2-093.mp3","durationMs":11424,"cues":[[2,140],[9,300],[17,700],[21,1260],[23,1380],[29,1480],[36,1840],[43,2660],[47,3160],[56,3300],[64,3700],[69,4100],[79,4260],[81,5720],[86,5840],[89,6100],[99,6260],[105,6840],[111,7060],[116,7360],[124,7860],[133,8140],[137,8560],[142,8860],[148,9160],[151,9320],[165,9460],[169,10100],[175,10280],[180,10640],[186,10860]]},"ch2-094":{"text":"The examination hall smelled of paper and nervous stillness. Rows of desks faced the clock. When the papers turned over, the sound moved through the room like a single wave.","voiceUrl":"voices/chapter-2/ch2-094.mp3","durationMs":11592,"cues":[[4,140],[16,240],[21,980],[29,1240],[32,1520],[38,1700],[42,2200],[50,2400],[61,2860],[66,4240],[69,4520],[75,4680],[81,5220],[85,5520],[92,5660],[97,6940],[101,7060],[108,7180],[115,7600],[121,7880],[125,8720],[131,8860],[137,9240],[145,9600],[149,9780],[154,9920],[159,10200],[161,10380],[168,10520],[173,10940]]},"ch2-095":{"text":"Some questions opened. Others remained locked no matter how carefully I read them. I wrote what I could, crossed out what I could not defend, and watched minutes leave.","voiceUrl":"voices/chapter-2/ch2-095.mp3","durationMs":11592,"cues":[[5,160],[15,520],[23,1240],[30,2640],[39,2960],[46,3420],[49,3880],[56,4000],[60,4260],[70,4500],[72,4960],[77,5040],[83,5240],[85,6640],[91,6700],[96,6920],[98,7100],[105,7220],[113,7760],[117,8119],[122,8280],[124,8440],[130,8500],[134,8660],[142,8840],[146,9980],[154,10140],[162,10580],[168,11020]]},"ch2-096":{"text":"Just keep moving. One question, then the next.","voiceUrl":"voices/chapter-2/ch2-096.mp3","durationMs":3624,"cues":[[5,140],[10,560],[18,1080],[22,1860],[32,2060],[37,2940],[41,3080],[46,3180]]},"ch2-097":{"text":"There is dignity in continuing even when preparation has failed you. There is also no magic in it. Effort made during the paper could not replace all the effort deferred before it.","voiceUrl":"voices/chapter-2/ch2-097.mp3","durationMs":11184,"cues":[[6,120],[9,300],[17,560],[20,1020],[31,1180],[36,2140],[41,2360],[53,2540],[57,3140],[64,3320],[69,3680],[75,4940],[78,5080],[83,5260],[86,5600],[92,5800],[95,6160],[99,6280],[106,7100],[111,7460],[118,7720],[122,7980],[128,8119],[134,8620],[138,8740],[146,8920],[150,9480],[154,9640],[161,9780],[170,10060],[177,10420],[180,10840]]},"ch2-098":{"text":"Results day arrived beneath fluorescent lights. Around me, people compared expressions before they compared slips. Celebration and disappointment tried to occupy the same hall without looking at each other.","voiceUrl":"voices/chapter-2/ch2-098.mp3","durationMs":12864,"cues":[[8,160],[12,640],[20,840],[28,1340],[40,1660],[48,2180],[55,3160],[59,3580],[66,3900],[75,4200],[87,4620],[94,5640],[99,5940],[108,6080],[115,6600],[127,7800],[131,8660],[146,8920],[152,9780],[155,10000],[162,10140],[166,10620],[171,10780],[176,11120],[184,11520],[192,11900],[195,12200],[200,12320],[206,12540]]},"ch2-099":{"text":"I held the folded paper for a moment. Part of me still expected a rescue: some kinder arithmetic, some proof that worry had exaggerated everything.","voiceUrl":"voices/chapter-2/ch2-099.mp3","durationMs":9360,"cues":[[2,160],[7,200],[11,380],[18,500],[24,880],[28,1220],[30,1320],[38,1420],[43,2560],[46,2760],[49,2860],[55,3060],[64,3220],[66,3700],[74,3800],[79,5020],[86,5300],[98,5760],[103,6820],[109,7060],[114,7380],[120,7600],[124,7880],[136,8020],[147,8720]]},"ch2-100":{"text":"The results were bad. Not one disappointing number, but an outcome that narrowed the paths I had imagined. I will not display the grades here. Their emotional weight mattered more than their digits.","voiceUrl":"voices/chapter-2/ch2-100.mp3","durationMs":12384,"cues":[[4,160],[12,280],[17,1000],[22,1180],[26,2200],[30,2480],[44,2740],[52,3360],[56,4160],[59,4300],[67,4520],[72,4960],[81,5180],[85,5520],[91,5660],[93,6100],[97,6180],[107,6300],[109,7480],[114,7540],[118,7680],[126,7880],[130,8320],[137,8420],[143,8840],[149,9620],[159,9780],[166,10300],[175,10760],[180,11100],[185,11400],[191,11560],[198,11800]]},"ch2-results-condemn-001":{"text":"I ruined everything. Everyone else gets to move forward, and I did this to myself.","voiceUrl":"voices/chapter-2/ch2-results-condemn-001.mp3","durationMs":4920,"cues":[[2,140],[9,240],[21,580],[30,1520],[35,1900],[40,2120],[43,2300],[48,2400],[57,2580],[61,3160],[63,3620],[67,3740],[72,3900],[75,4100],[82,4240]]},"ch2-results-condemn-002":{"text":"That thought followed me home because it was absolute, and absolutes can feel simpler than uncertainty. Years later, I would learn that responsibility and permanent condemnation are not the same thing.","voiceUrl":"voices/chapter-2/ch2-results-condemn-002.mp3","durationMs":13440,"cues":[[5,120],[13,320],[22,620],[25,940],[30,1100],[38,1360],[41,1620],[45,1760],[55,2080],[59,3360],[69,3660],[73,4180],[78,4340],[86,4660],[91,5060],[104,5220],[110,7480],[117,7780],[119,8720],[125,8780],[131,8920],[136,9140],[151,9260],[155,10220],[165,10400],[178,10840],[182,11760],[186,11980],[190,12500],[195,12640],[201,12960]]},"ch2-results-honest-001":{"text":"This is the consequence of my choices. I cannot pretend the warnings were not there.","voiceUrl":"voices/chapter-2/ch2-results-honest-001.mp3","durationMs":4680,"cues":[[5,160],[8,300],[12,400],[24,520],[27,1200],[30,1340],[39,1500],[41,2620],[48,2700],[56,3020],[60,3400],[69,3500],[74,3940],[78,4100],[84,4340]]},"ch2-results-honest-002":{"text":"The thought was honest but incomplete. Years later, I would learn that owning a mistake should guide the next action, not become a weight carried forever as proof of unworthiness.","voiceUrl":"voices/chapter-2/ch2-results-honest-002.mp3","durationMs":11904,"cues":[[4,140],[12,280],[16,820],[23,1080],[27,1580],[39,2000],[45,3600],[52,3920],[54,4720],[60,4760],[66,4920],[71,5120],[78,5320],[80,5540],[88,5600],[95,6120],[101,6340],[105,6600],[110,6720],[118,7040],[122,8080],[129,8320],[131,8600],[138,8700],[146,9080],[154,9380],[157,10280],[163,10500],[166,10800],[179,10920]]},"ch2-results-continue-001":{"text":"I do not know what the next path is. I cannot see it from here. But there must be one.","voiceUrl":"voices/chapter-2/ch2-results-continue-001.mp3","durationMs":4920,"cues":[[2,180],[5,300],[9,420],[14,600],[19,760],[23,860],[28,960],[33,1180],[37,1420],[39,2240],[46,2340],[50,2640],[53,2740],[58,2820],[64,2980],[68,3840],[74,3940],[79,4140],[82,4480],[86,4660]]},"ch2-results-continue-002":{"text":"It was more hope than I could consistently feel, but the sentence survived. Years later, I would understand that a path can exist before you are strong enough to see its shape.","voiceUrl":"voices/chapter-2/ch2-results-continue-002.mp3","durationMs":11112,"cues":[[3,160],[7,300],[12,500],[17,740],[22,1240],[24,1440],[30,1520],[43,1680],[49,2380],[53,3480],[57,3620],[66,3740],[76,4440],[82,6060],[89,6400],[91,7000],[97,7060],[108,7200],[113,7680],[115,7800],[120,7920],[124,8320],[130,8460],[137,9160],[141,9480],[145,9560],[152,9720],[159,9960],[162,10200],[166,10340],[170,10460],[176,10640]]},"ch2-101":{"text":"The period after results was dark in a quiet way. I withdrew. I avoided questions about what came next because every answer seemed to expose the same failure.","voiceUrl":"voices/chapter-2/ch2-101.mp3","durationMs":10464,"cues":[[4,140],[11,280],[17,760],[25,1020],[29,1540],[34,1760],[37,2120],[39,2220],[45,2320],[50,2660],[52,3920],[62,4000],[64,5320],[72,5380],[82,5840],[88,6320],[93,6580],[98,6780],[103,7000],[111,7560],[117,7840],[124,8100],[131,8440],[134,8780],[141,8880],[145,9460],[150,9600],[158,9880]]},"ch2-102":{"text":"My room, once alive with plans and player chatter, became a place where time passed without direction. Even the server's success felt difficult to hold beside the damage I associated with it.","voiceUrl":"voices/chapter-2/ch2-102.mp3","durationMs":11760,"cues":[[3,120],[9,280],[14,1080],[20,1460],[25,1900],[31,2100],[35,2500],[42,2680],[51,3000],[58,3740],[60,4000],[66,4100],[72,4400],[77,4620],[84,4980],[92,5420],[103,5720],[108,6900],[112,7100],[121,7260],[129,7600],[134,8180],[144,8440],[147,8820],[152,8940],[159,9340],[163,9660],[170,9840],[172,10520],[183,10580],[188,11260],[191,11420]]},"ch2-103":{"text":"I had lost Hana, disappointed myself academically, and reached the end of a road without the future I expected waiting there. Shame tried to combine those facts into one identity.","voiceUrl":"voices/chapter-2/ch2-103.mp3","durationMs":11904,"cues":[[2,160],[6,220],[11,400],[17,740],[30,1560],[37,2180],[51,2740],[55,3880],[63,4040],[67,4480],[71,4660],[74,4820],[76,4940],[81,5060],[89,5360],[93,5680],[100,5820],[102,6360],[111,6460],[119,7040],[126,7420],[132,8660],[138,9380],[141,9640],[149,9740],[155,10100],[161,10360],[166,10740],[170,11020],[179,11180]]},"ch2-104":{"text":"But I was not only the boy who neglected his studies. I was also the boy who had built something from nothing, earned trust from a community, and learned skills no examination measured.","voiceUrl":"voices/chapter-2/ch2-104.mp3","durationMs":11352,"cues":[[4,80],[6,280],[10,360],[14,560],[19,780],[23,1060],[27,1200],[31,1520],[41,1640],[45,2120],[54,2320],[56,3720],[60,3800],[65,4040],[69,4380],[73,4500],[77,4720],[81,4820],[87,4960],[97,5220],[102,5580],[111,5800],[118,6840],[124,7160],[129,7620],[131,7780],[142,7860],[146,9100],[154,9240],[161,9600],[164,10000],[176,10120],[185,10800]]},"ch2-105":{"text":"And I was not only the boyfriend who became absent. I was a young person learning, painfully, that caring about someone is different from making room for them.","voiceUrl":"voices/chapter-2/ch2-105.mp3","durationMs":10320,"cues":[[4,120],[6,420],[10,520],[14,720],[19,960],[23,1280],[33,1380],[37,1880],[44,1960],[52,2360],[54,3660],[58,3740],[60,3900],[66,3980],[73,4280],[83,4740],[94,5340],[99,6220],[106,6500],[112,6960],[120,7280],[123,7960],[133,8200],[138,8760],[145,8920],[150,9320],[154,9640],[159,9880]]},"ch2-106":{"text":"Those kinder truths did not arrive all at once. First came smaller things: waking up, opening the curtains, answering one message, considering one route I had not planned.","voiceUrl":"voices/chapter-2/ch2-106.mp3","durationMs":12312,"cues":[[6,120],[13,460],[20,920],[24,1420],[28,1560],[35,1740],[39,2120],[42,2240],[48,2460],[54,3720],[59,4080],[67,4380],[75,4740],[82,5720],[86,6100],[94,7040],[98,7320],[108,7440],[118,8420],[122,8860],[131,9080],[143,10140],[147,10740],[153,11000],[155,11280],[159,11340],[163,11440],[171,11660]]},"ch2-107":{"text":"A bad result can close doors. It can change the route, cost time, and demand humility. What it cannot do is issue a final judgement on the life standing before it.","voiceUrl":"voices/chapter-2/ch2-107.mp3","durationMs":12312,"cues":[[2,120],[6,260],[13,560],[17,1120],[23,1340],[30,1780],[33,2720],[37,2820],[44,2980],[48,3360],[55,3480],[60,4100],[66,4520],[70,5300],[77,5420],[87,5900],[92,7360],[95,7500],[102,7720],[105,8140],[108,8760],[114,8900],[116,9160],[122,9340],[132,9840],[135,10600],[139,10720],[144,10860],[153,11220],[160,11620],[163,12020]]},"ch2-108":{"text":"I did not know that yet. I only knew morning kept arriving, annoyingly faithful, whether I felt ready for it or not.","voiceUrl":"voices/chapter-2/ch2-108.mp3","durationMs":7680,"cues":[[2,120],[6,200],[10,340],[15,540],[20,780],[25,1000],[27,2180],[32,2300],[37,2580],[45,2900],[50,3260],[60,3480],[71,4200],[81,4860],[89,5860],[91,6100],[96,6180],[102,6460],[106,6760],[109,6920],[112,7040],[116,7220]]},"ch3-001":{"text":"The morning after disappointment is rarely dramatic. The sun still reaches the dining table. Cups still clink. Then somebody asks what comes next, and the question makes the whole room feel smaller.","voiceUrl":"voices/chapter-3/ch3-001.mp3","durationMs":14544,"cues":[[4,140],[12,260],[18,660],[33,960],[36,1760],[43,2000],[53,2380],[57,3860],[61,3980],[67,4260],[75,4560],[79,4980],[86,5100],[93,5440],[98,6360],[104,7040],[111,7340],[116,9040],[125,9300],[130,9700],[135,10260],[141,10480],[147,10780],[151,12000],[155,12100],[164,12220],[170,12640],[174,12900],[180,13040],[185,13340],[190,13700],[198,13980]]},"ch3-002":{"text":"My family wanted reassurance that one poor result had not closed every respectable route. Their concern arrived as comparisons, repeated suggestions, and questions from relatives whose voices I could hear even when they were not there.","voiceUrl":"voices/chapter-3/ch3-002.mp3","durationMs":13584,"cues":[[3,120],[10,320],[17,740],[29,1080],[34,1840],[38,2040],[43,2340],[50,2560],[54,2940],[58,3040],[65,3260],[71,3700],[83,3980],[90,4620],[96,5860],[104,6020],[112,6460],[115,6900],[128,7020],[137,8080],[150,8500],[154,9780],[164,9980],[169,10500],[179,10680],[185,11140],[192,11360],[194,11740],[200,11800],[205,11960],[210,12300],[215,12520],[220,12660],[225,12780],[229,12900],[235,13140]]},"ch3-003":{"text":"Which school would take me? Would I cope? Had I finally understood what was at stake? Nobody needed to say I had disappointed them. I supplied that sentence myself and placed it underneath everything they did say.","voiceUrl":"voices/chapter-3/ch3-003.mp3","durationMs":15432,"cues":[[6,160],[13,480],[19,800],[24,1040],[28,1300],[34,2500],[36,2700],[42,2860],[46,4160],[48,4360],[56,4500],[67,5000],[72,5660],[76,5900],[79,6080],[86,6300],[93,7860],[100,8260],[103,8520],[107,8660],[109,8900],[113,8960],[126,9100],[132,9680],[134,10840],[143,10940],[148,11320],[157,11500],[164,11900],[168,12960],[175,13080],[178,13360],[189,13540],[200,14040],[205,14500],[209,14740],[213,15000]]},"ch3-004":{"text":"I know I messed up. I do not need everyone to keep translating the results for me.","voiceUrl":"voices/chapter-3/ch3-004.mp3","durationMs":4608,"cues":[[2,240],[7,300],[9,500],[16,560],[20,840],[22,1260],[25,1360],[29,1620],[34,1980],[43,2200],[46,2620],[51,2840],[63,3220],[67,3820],[75,3920],[79,4280],[82,4380]]},"ch3-005":{"text":"I said that mostly inside my room. Outside it, I nodded and answered as little as possible. Shame made even ordinary advice sound like a verdict, and silence felt safer than admitting how frightened I was.","voiceUrl":"voices/chapter-3/ch3-005.mp3","durationMs":13584,"cues":[[2,220],[7,320],[12,500],[19,700],[26,1060],[29,1400],[35,1600],[43,2700],[47,3160],[49,3720],[56,3820],[60,4500],[69,4660],[72,4980],[79,5160],[82,5400],[92,5560],[98,6980],[103,7560],[108,7740],[117,8060],[124,8500],[130,9100],[135,9300],[137,9460],[146,9600],[150,10600],[158,10800],[163,11280],[169,11520],[174,11780],[184,11940],[188,12320],[199,12540],[201,12980],[205,13100]]},"ch3-006":{"text":"Still, I did not give up. The route available to me led to a junior college people around me casually called weak. I repeated the word before anyone could use it against me.","voiceUrl":"voices/chapter-3/ch3-006.mp3","durationMs":11592,"cues":[[7,140],[9,860],[13,960],[17,1120],[22,1340],[26,1560],[30,2680],[36,2800],[46,3020],[49,3520],[52,3680],[56,4140],[59,4300],[61,4420],[68,4560],[76,4960],[83,5580],[90,5820],[93,6200],[102,6440],[109,6960],[115,7540],[117,8840],[126,8920],[130,9320],[135,9440],[142,9680],[149,10040],[155,10400],[159,10600],[162,10760],[170,10880],[173,11280]]},"ch3-007":{"text":"A school is not weak. It is rooms, teachers, ambitions, tired students, second chances, and hundreds of lives moving at different speeds. But at sixteen, prestige felt like a measurement of the person wearing the uniform.","voiceUrl":"voices/chapter-3/ch3-007.mp3","durationMs":15120,"cues":[[2,140],[9,240],[12,800],[16,1000],[22,1300],[25,2220],[28,2340],[35,2560],[45,3340],[56,3920],[62,4940],[72,5320],[79,6140],[88,6560],[92,7480],[101,7660],[104,8039],[110,8180],[117,8640],[120,8900],[130,9040],[138,9440],[142,10620],[145,10760],[154,10920],[163,11840],[168,12360],[173,12640],[175,12800],[187,12880],[190,13260],[194,13360],[201,13480],[209,13880],[213,14300],[221,14460]]},"ch3-008":{"text":"On the first day of 2014, I entered in a new white, charcoal, and muted-teal uniform, taller than most people around me and determined to look as though this had always been the plan.","voiceUrl":"voices/chapter-3/ch3-008.mp3","durationMs":11832,"cues":[[3,100],[7,220],[13,360],[17,700],[20,900],[26,1100],[28,2520],[36,2580],[39,2860],[41,3000],[45,3120],[52,3500],[62,4040],[66,4660],[77,4840],[86,5640],[93,6720],[98,7120],[103,7280],[110,7500],[117,7780],[120,8200],[124,8900],[135,9020],[138,9520],[143,9620],[146,9780],[153,9900],[158,10100],[162,10240],[169,10560],[174,11040],[178,11180],[183,11300]]},"ch3-009":{"text":"Orientation turned the campus into a tide of unfamiliar faces. I checked classroom signs twice, followed whichever crowd looked confident, and hoped nobody would ask why I had chosen the school.","voiceUrl":"voices/chapter-3/ch3-009.mp3","durationMs":12480,"cues":[[12,140],[19,1020],[23,1400],[30,1540],[35,2100],[37,2300],[42,2440],[45,2820],[56,3020],[63,3640],[65,4800],[73,4900],[83,5200],[89,5700],[96,6100],[105,6880],[115,7180],[121,7580],[128,8000],[139,8280],[143,9220],[149,9340],[156,9880],[162,10260],[166,10460],[170,10780],[172,11220],[176,11260],[183,11400],[187,11720],[194,11860]]},"ch3-010":{"text":"Aleem? From Chinese class? You still look lost in every school, ah?","voiceUrl":"voices/chapter-3/ch3-010.mp3","durationMs":5592,"cues":[[7,100],[12,1080],[20,1280],[27,1660],[31,2960],[37,3240],[42,3540],[47,3820],[50,4180],[56,4380],[64,4700],[67,5100]]},"ch3-011":{"text":"Syafiqa stood beside the noticeboard, tall, with long hair tied back and the expression of someone pleased to have found one familiar person. She had attended the same external Chinese class as Hana and me, though we had never been close then.","voiceUrl":"voices/chapter-3/ch3-011.mp3","durationMs":14472,"cues":[[8,100],[14,600],[21,880],[25,1220],[38,1340],[44,2340],[49,2860],[54,3080],[59,3380],[64,3720],[69,3980],[73,4840],[77,4920],[88,5020],[91,5520],[99,5660],[107,6020],[110,6420],[115,6500],[121,6620],[125,7020],[134,7340],[142,7780],[146,9380],[150,9460],[159,9560],[163,9960],[168,10100],[177,10380],[185,10900],[191,11360],[194,11660],[199,11780],[203,12020],[207,12160],[214,13020],[217,13220],[221,13300],[227,13400],[232,13600],[238,13800],[243,14120]]},"ch3-012":{"text":"I am not lost. I am checking whether the signs are accurate.","voiceUrl":"voices/chapter-3/ch3-012.mp3","durationMs":3624,"cues":[[2,260],[5,380],[9,540],[15,740],[17,1460],[20,1520],[29,1640],[37,1920],[41,2100],[47,2220],[51,2620],[60,2800]]},"ch3-013":{"text":"Of course. Very responsible. Come, our class is this way.","voiceUrl":"voices/chapter-3/ch3-013.mp3","durationMs":5592,"cues":[[3,220],[11,460],[16,1560],[29,1900],[35,3400],[39,4160],[45,4340],[48,4660],[53,4800],[57,5020]]},"ch3-014":{"text":"Recognition did what confidence could not. For a few minutes we were back in the borrowed classroom, complaining about characters that looked almost identical and pretending our pronunciation was better than it was.","voiceUrl":"voices/chapter-3/ch3-014.mp3","durationMs":12552,"cues":[[12,160],[16,940],[21,1200],[32,1420],[38,1960],[43,2120],[47,3520],[49,3640],[53,3740],[61,3980],[64,4740],[69,4840],[74,5020],[77,5220],[81,5320],[90,5420],[101,5800],[113,6620],[119,7080],[130,7340],[135,7900],[142,8039],[149,8360],[159,8740],[163,9840],[174,9940],[178,10360],[192,10520],[196,11280],[203,11500],[208,11720],[211,11880],[215,12040]]},"ch3-015":{"text":"Then the coincidence widened. We were classmates. We lived along the same direction home. Our mornings began at the same interchange, which gave us an easy reason to meet again the next day.","voiceUrl":"voices/chapter-3/ch3-015.mp3","durationMs":12312,"cues":[[5,100],[9,380],[21,520],[30,1260],[33,2760],[38,2860],[50,3020],[53,4380],[59,4480],[65,4700],[69,4980],[74,5120],[84,5320],[90,5800],[94,6980],[103,7140],[109,7640],[112,7960],[116,8080],[121,8200],[134,8400],[140,9420],[145,9700],[148,9880],[151,10000],[156,10200],[163,10520],[166,10840],[171,10940],[177,11100],[181,11400],[186,11500],[190,11780]]},"ch3-016":{"text":"If you are late tomorrow, I am leaving without you.","voiceUrl":"voices/chapter-3/ch3-016.mp3","durationMs":3360,"cues":[[3,240],[7,480],[11,580],[16,800],[26,1080],[28,1920],[31,2000],[39,2180],[47,2560],[51,3000]]},"ch3-017":{"text":"Fair. If you are late, I will wait and complain the whole way.","voiceUrl":"voices/chapter-3/ch3-017.mp3","durationMs":3240,"cues":[[6,200],[9,680],[13,800],[17,900],[23,1040],[25,1560],[30,1580],[35,1760],[39,2000],[48,2120],[52,2660],[58,2760],[62,2980]]},"ch3-018":{"text":"The arrangement became routine before either of us named it. A message before leaving home. A familiar figure near the queue. Two seats if the bus was kind, or two handholds near each other if it was not.","voiceUrl":"voices/chapter-3/ch3-018.mp3","durationMs":12480,"cues":[[4,80],[16,180],[23,800],[31,1140],[38,1720],[45,2120],[48,2360],[51,2480],[57,2680],[61,2980],[63,4180],[71,4300],[78,4740],[86,5020],[92,5320],[94,6080],[103,6160],[110,6600],[115,6940],[119,7100],[126,7260],[130,8160],[136,8360],[139,8660],[143,8780],[147,8880],[151,9100],[157,9260],[160,10100],[164,10280],[174,10500],[179,11060],[184,11220],[190,11380],[193,11580],[196,11680],[200,11820],[204,11980]]},"ch3-019":{"text":"We spoke about tutorials, teachers, family rules, and the peculiar exhaustion of beginning again. Syafiqa could make a complaint sound like a story. By the time we reached school, I usually felt less like an admission mistake.","voiceUrl":"voices/chapter-3/ch3-019.mp3","durationMs":15120,"cues":[[3,120],[9,320],[15,540],[26,820],[36,1880],[43,2720],[50,3100],[54,4100],[58,4200],[67,4300],[78,4960],[81,5560],[91,5680],[98,6040],[106,7440],[112,8080],[117,8240],[119,8420],[129,8500],[135,9240],[140,9440],[142,9600],[149,9760],[152,10960],[156,11120],[161,11220],[164,11440],[172,11600],[180,12000],[182,12820],[190,12960],[195,13240],[200,13500],[205,13840],[208,14000],[218,14080],[226,14520]]},"ch3-020":{"text":"Some mornings one bus arrived before she did. I let it leave. Then another came with space, but her message said she was close, so I let that one leave too.","voiceUrl":"voices/chapter-3/ch3-020.mp3","durationMs":10392,"cues":[[5,160],[14,360],[18,840],[22,1080],[30,1320],[37,1800],[41,2160],[46,2360],[48,3420],[52,3500],[55,3680],[62,3820],[67,4940],[75,5100],[80,5480],[85,5680],[92,5920],[96,6660],[100,6780],[108,6940],[113,7480],[117,7660],[121,7780],[128,7980],[131,8880],[133,9000],[137,9060],[142,9260],[146,9460],[152,9660],[156,9920]]},"ch3-021":{"text":"You skipped two buses? Aleem, you could have gone first.","voiceUrl":"voices/chapter-3/ch3-021.mp3","durationMs":4632,"cues":[[4,320],[12,600],[16,1020],[23,1320],[30,2520],[34,3240],[40,3400],[45,3520],[50,3640],[56,3920]]},"ch3-022":{"text":"And listen to you blame traffic for being late by myself? Cannot. I need the full performance.","voiceUrl":"voices/chapter-3/ch3-022.mp3","durationMs":5664,"cues":[[4,140],[11,260],[14,500],[18,660],[24,860],[32,1080],[36,1440],[42,1560],[47,1740],[50,1900],[58,2000],[66,2880],[68,3860],[73,3960],[77,4340],[82,4540],[94,4740]]},"ch3-023":{"text":"She laughed, and the wasted minutes felt transformed into something chosen. Soon she waited for me too. We never called it a promise. We simply began expecting the other person to appear.","voiceUrl":"voices/chapter-3/ch3-023.mp3","durationMs":13272,"cues":[[4,160],[13,360],[17,1320],[21,1420],[28,1500],[36,1920],[41,2300],[53,2500],[58,3300],[68,3500],[76,4040],[81,5700],[85,6000],[92,6160],[96,6440],[99,6600],[104,6920],[107,8100],[113,8220],[120,8540],[123,8840],[125,9180],[134,9280],[137,10660],[144,10780],[150,11060],[160,11360],[164,11820],[170,11940],[177,12180],[180,12540],[187,12660]]},"ch3-024":{"text":"On quieter rides, one of us offered an earpiece. The wire crossed the small distance between our shoulders. We never needed the same favourite song; sharing the silence around it seemed to be enough.","voiceUrl":"voices/chapter-3/ch3-024.mp3","durationMs":11904,"cues":[[3,180],[11,380],[18,800],[22,1580],[25,1700],[28,1800],[36,2060],[39,2320],[49,2480],[53,3660],[58,3760],[66,4120],[70,4480],[76,4620],[85,4920],[93,5360],[97,5680],[108,5840],[111,7000],[117,7100],[124,7340],[128,7640],[133,7780],[143,8080],[149,8480],[157,9520],[161,9880],[169,10000],[176,10420],[179,10740],[186,10900],[189,11100],[192,11200],[199,11300]]},"ch3-bus-proof-001":{"text":"People do not keep choosing the same bus, the same seat, and the same pair of earphones for no reason. Surely this is her way of saying it.","voiceUrl":"voices/chapter-3/ch3-bus-proof-001.mp3","durationMs":8304,"cues":[[7,80],[10,380],[14,520],[19,880],[28,1140],[32,1740],[37,1920],[42,2180],[46,2720],[51,2920],[57,3200],[61,3700],[65,3800],[70,4000],[75,4400],[78,4600],[88,4760],[92,5500],[95,5660],[103,5860],[110,6800],[115,7160],[118,7280],[122,7380],[126,7540],[129,7660],[136,7760],[139,8039]]},"ch3-bus-proof-002":{"text":"I treated repetition as proof because certainty was comforting. But intimacy can be real without being romantic, and another person's comfort is not consent to the meaning you privately assign it.","voiceUrl":"voices/chapter-3/ch3-bus-proof-002.mp3","durationMs":12624,"cues":[[2,320],[10,360],[21,820],[24,1400],[30,1600],[38,1980],[48,2320],[52,2860],[64,3060],[68,4480],[77,4660],[81,5180],[84,5320],[89,5500],[97,5860],[103,6200],[113,6420],[117,7740],[125,7880],[134,8220],[142,8640],[145,9440],[149,9580],[157,9800],[160,10520],[164,10640],[172,10760],[176,11120],[186,11300],[193,11840],[196,12260]]},"ch3-bus-possibility-001":{"text":"Maybe she feels something. Maybe she simply trusts me. Guessing harder will not turn either possibility into an answer.","voiceUrl":"voices/chapter-3/ch3-bus-possibility-001.mp3","durationMs":6576,"cues":[[6,100],[10,340],[16,480],[27,720],[33,1600],[37,1880],[44,2040],[51,2340],[55,2640],[64,3480],[71,3760],[76,4120],[80,4280],[85,4520],[92,4920],[104,5140],[109,5920],[112,6100],[119,6220]]},"ch3-bus-possibility-002":{"text":"That was the fairest thought available to me. Closeness created a question, not a claim. Clarity would require risking an answer that did not match the hope behind it.","voiceUrl":"voices/chapter-3/ch3-bus-possibility-002.mp3","durationMs":10872,"cues":[[5,140],[9,400],[13,760],[21,920],[29,1420],[39,1700],[42,2180],[46,2300],[56,3580],[64,4120],[66,4580],[76,4680],[80,5440],[82,5600],[89,5680],[97,6760],[103,7280],[111,7420],[119,7940],[122,8300],[129,8520],[134,8860],[138,8980],[142,9120],[148,9340],[152,9680],[157,9820],[164,10240],[167,10620]]},"ch3-bus-friendship-001":{"text":"She is my friend. I should be grateful for that instead of measuring every kind thing for a hidden message.","voiceUrl":"voices/chapter-3/ch3-bus-friendship-001.mp3","durationMs":4608,"cues":[[4,160],[7,300],[10,400],[18,520],[20,1200],[27,1240],[30,1360],[39,1460],[43,1800],[48,1920],[56,2100],[59,2320],[69,2440],[75,2840],[80,3100],[86,3380],[90,3640],[92,3760],[99,3820],[107,4080]]},"ch3-bus-friendship-002":{"text":"Restraint protected the friendship from entitlement, but it could not erase my feelings. Pretending the question did not exist would eventually make the ordinary moments heavier, not simpler.","voiceUrl":"voices/chapter-3/ch3-bus-friendship-002.mp3","durationMs":11832,"cues":[[10,100],[20,840],[24,1360],[35,1500],[40,1960],[53,2120],[57,3480],[60,3620],[66,3760],[70,3920],[76,4080],[79,4500],[89,4680],[100,5880],[104,6380],[113,6480],[117,6900],[121,7060],[127,7240],[133,8080],[144,8200],[149,8760],[153,8980],[162,9220],[170,9620],[179,10060],[183,11000],[191,11280]]},"ch3-bus-join":{"text":"There were afternoons when tiredness ended the conversation before either of us chose to. Our heads tipped toward the glass, the shared earpieces remained in place, and we woke near our stop with the embarrassed alertness of people caught being comfortable.","voiceUrl":"voices/chapter-3/ch3-bus-join.mp3","durationMs":15504,"cues":[[6,100],[11,240],[22,440],[27,1180],[37,1420],[43,2100],[47,2340],[60,2460],[67,3180],[74,3700],[77,3980],[80,4100],[86,4320],[90,4660],[94,5740],[100,5880],[107,6460],[114,6740],[118,6940],[125,7040],[129,8060],[136,8180],[146,8600],[155,9220],[158,9560],[165,9700],[169,10700],[172,10840],[177,10960],[182,11240],[186,11420],[191,11620],[196,12220],[200,12340],[212,12420],[222,12940],[225,13440],[232,13560],[239,13920],[245,14460],[257,14820]]},"ch3-025":{"text":"We fell asleep again. Next time you are responsible for not missing the stop.","voiceUrl":"voices/chapter-3/ch3-025.mp3","durationMs":6000,"cues":[[3,180],[8,400],[15,620],[22,1140],[27,2480],[32,2800],[36,3380],[40,3660],[52,3760],[56,4480],[60,4680],[68,4920],[72,5220],[77,5380]]},"ch3-026":{"text":"You say that every time, then you sleep first.","voiceUrl":"voices/chapter-3/ch3-026.mp3","durationMs":3096,"cues":[[4,240],[8,400],[13,580],[19,880],[25,1180],[30,2000],[34,2240],[40,2380],[46,2620]]},"ch3-027":{"text":"I liked the version of myself beside her: less defensive, less defined by results, able to make somebody laugh before eight in the morning. Wanting that feeling to have a name was not unreasonable.","voiceUrl":"voices/chapter-3/ch3-027.mp3","durationMs":13272,"cues":[[2,180],[8,220],[12,600],[20,760],[23,1100],[30,1240],[37,1700],[42,2100],[47,3200],[58,3460],[63,4660],[71,5000],[74,5560],[83,5720],[88,7100],[91,7280],[96,7380],[105,7560],[111,7940],[118,8380],[124,8720],[127,8880],[131,8960],[140,9080],[148,10540],[153,10920],[161,11140],[164,11420],[169,11500],[171,11640],[176,11780],[180,12120],[184,12300],[197,12480]]},"ch3-028":{"text":"What confused me was the space between our routines and our words. We could arrange whole days around each other, yet neither of us spoke about whether the closeness pointed anywhere beyond friendship.","voiceUrl":"voices/chapter-3/ch3-028.mp3","durationMs":13272,"cues":[[5,300],[14,560],[17,1220],[21,1460],[25,1820],[31,2020],[39,2420],[43,3040],[52,3240],[56,4120],[60,4260],[67,4540],[70,5940],[76,6140],[84,6320],[90,6740],[95,7020],[102,7340],[107,7640],[114,7840],[118,8580],[126,8860],[129,9220],[132,9320],[138,9560],[144,9860],[152,10140],[156,10420],[166,10560],[174,11140],[183,11700],[190,12140],[201,12520]]},"ch3-029":{"text":"Eventually, uncertainty became harder to carry than rejection. I asked Syafiqa to stay behind near a quieter stretch of campus after the last lesson.","voiceUrl":"voices/chapter-3/ch3-029.mp3","durationMs":9672,"cues":[[12,180],[24,1360],[31,2080],[38,2420],[41,2740],[47,2860],[52,3180],[63,3340],[65,4980],[71,5120],[79,5340],[82,5760],[87,5920],[94,6120],[99,6980],[101,7140],[109,7280],[117,7660],[120,7860],[127,8000],[133,8520],[137,8740],[142,8840],[149,9220]]},"ch3-confession-direct-001":{"text":"I like you, Syafiqa. Not only as the person I travel with. Do you feel the same way?","voiceUrl":"voices/chapter-3/ch3-confession-direct-001.mp3","durationMs":4152,"cues":[[2,200],[7,260],[12,440],[21,540],[25,1260],[30,1480],[33,1740],[37,1840],[44,1940],[46,2220],[53,2300],[59,2580],[62,3260],[66,3340],[71,3440],[75,3580],[80,3680],[84,3840]]},"ch3-confession-direct-002":{"text":"Directness gave her a clear question and gave me nowhere to hide from the answer. It was frightening, but it did not make her responsible for rewarding the courage it required.","voiceUrl":"voices/chapter-3/ch3-confession-direct-002.mp3","durationMs":10320,"cues":[[11,160],[16,760],[20,940],[22,1060],[28,1160],[37,1460],[41,2280],[46,2420],[49,2680],[57,2940],[60,3220],[65,3340],[70,3560],[74,3740],[82,3880],[85,5320],[89,5440],[102,5620],[106,6800],[109,6920],[113,7000],[117,7140],[122,7360],[126,7540],[138,7720],[142,8320],[152,8460],[156,8920],[164,9080],[167,9420],[176,9540]]},"ch3-confession-gentle-001":{"text":"The mornings and rides with you have become important to me. I was wondering whether you could ever see us as more than friends.","voiceUrl":"voices/chapter-3/ch3-confession-gentle-001.mp3","durationMs":6648,"cues":[[4,180],[13,300],[17,640],[23,760],[28,1040],[32,1200],[37,1500],[44,1640],[54,2180],[57,2600],[61,2700],[63,3520],[67,3600],[77,3740],[85,4280],[89,4540],[95,4620],[100,4880],[104,5160],[107,5320],[110,5580],[115,5740],[120,5940],[128,6140]]},"ch3-confession-gentle-002":{"text":"I tried to leave room around the question. Gentle wording could reduce pressure, but it could not guarantee a gentle outcome. Some truths hurt however carefully they are invited in.","voiceUrl":"voices/chapter-3/ch3-confession-gentle-002.mp3","durationMs":11664,"cues":[[2,200],[8,280],[11,560],[17,640],[22,880],[29,1160],[33,1520],[43,1640],[50,2940],[58,3260],[64,3640],[71,3800],[81,4200],[85,5260],[88,5380],[94,5480],[98,5660],[108,5900],[110,6280],[117,6420],[126,6760],[131,8300],[138,8560],[143,8920],[151,9820],[161,10220],[166,10640],[170,10740],[178,10840],[181,11360]]},"ch3-confession-defensive-001":{"text":"Maybe I understood everything wrongly. If I did, just tell me. But I like you, and I need to know what all this means to you.","voiceUrl":"voices/chapter-3/ch3-confession-defensive-001.mp3","durationMs":7848,"cues":[[6,120],[8,520],[19,560],[30,1140],[39,1480],[42,2360],[44,2520],[49,2560],[54,2900],[59,3260],[63,3460],[67,4080],[69,4500],[74,4540],[79,4820],[83,5260],[85,5620],[90,5680],[93,5840],[98,5960],[103,6160],[107,6360],[112,6520],[118,6700],[121,7220],[125,7440]]},"ch3-confession-defensive-002":{"text":"The defence arrived before the rejection. I wanted honesty while already bracing for humiliation, which made the question carry more accumulated fear than Syafiqa had created.","voiceUrl":"voices/chapter-3/ch3-confession-defensive-002.mp3","durationMs":11520,"cues":[[4,120],[12,220],[20,780],[27,1320],[31,1780],[42,1880],[44,3480],[51,3560],[59,3980],[65,4800],[73,4960],[81,5400],[85,5800],[98,5920],[104,7260],[109,7460],[113,7620],[122,7740],[128,8200],[133,8500],[145,8840],[150,9660],[155,10100],[163,10260],[167,10660],[175,10840]]},"ch3-confession-join":{"text":"Syafiqa went quiet. She did not laugh, look disgusted, or punish me for asking. She chose her words slowly, aware that friendship would not make them painless.","voiceUrl":"voices/chapter-3/ch3-confession-join.mp3","durationMs":11424,"cues":[[8,100],[13,540],[20,780],[24,2140],[28,2300],[32,2460],[39,2740],[44,3480],[55,3680],[58,4400],[65,4620],[68,4960],[72,5100],[80,5280],[84,6620],[90,6780],[94,7100],[100,7280],[108,7960],[114,8960],[119,9280],[130,9480],[136,9940],[140,10100],[145,10320],[150,10500],[159,10700]]},"ch3-030":{"text":"I care about you, but I do not want a relationship. I really need to focus on my studies now. I hope we can still be friends.","voiceUrl":"voices/chapter-3/ch3-030.mp3","durationMs":9600,"cues":[[2,300],[7,380],[13,680],[18,1020],[22,1740],[24,2120],[27,2160],[31,2340],[36,2660],[38,2900],[52,2980],[54,4740],[61,4880],[66,5180],[69,5340],[75,5460],[78,5820],[81,5960],[89,6160],[94,6520],[96,7640],[101,7760],[104,8000],[108,8119],[114,8320],[117,8520],[125,8680]]},"ch3-031":{"text":"Okay. Thank you for telling me. I will not make things difficult for you.","voiceUrl":"voices/chapter-3/ch3-031.mp3","durationMs":4536,"cues":[[6,100],[12,860],[16,1020],[20,1120],[28,1240],[32,1460],[34,1940],[39,2020],[43,2180],[48,2600],[55,2780],[65,3240],[69,3740],[73,3900]]},"ch3-032":{"text":"I had asked for clarity and received a no. The reason hurt, but it was believable. Junior college moved quickly; all of us had been warned how easily one neglected week could become a lost term.","voiceUrl":"voices/chapter-3/ch3-032.mp3","durationMs":13440,"cues":[[2,160],[6,220],[12,400],[16,780],[24,940],[28,1760],[37,1900],[39,2320],[43,2460],[47,3780],[54,3900],[60,4280],[64,4760],[67,5240],[71,5380],[83,5640],[90,6960],[98,7320],[104,7780],[113,8119],[117,9020],[120,9160],[123,9280],[127,9420],[132,9540],[139,9760],[143,10100],[150,10400],[154,10860],[164,11100],[169,11640],[175,11980],[182,12140],[184,12380],[189,12500],[194,12940]]},"ch3-033":{"text":"For several days, I worked at accepting the answer exactly as given. We travelled separately. I told myself distance was respectful, not punishment, though some mornings I still watched the usual bus leave.","voiceUrl":"voices/chapter-3/ch3-033.mp3","durationMs":13512,"cues":[[4,120],[12,260],[18,620],[20,1180],[27,1300],[30,1600],[40,1720],[44,2200],[51,2360],[59,2700],[62,3180],[69,3340],[72,4720],[82,4860],[94,5240],[96,6380],[101,6460],[108,6680],[117,7140],[121,7620],[133,7800],[137,8740],[149,9000],[156,10340],[161,10560],[170,10760],[172,11220],[178,11340],[186,11600],[190,12060],[196,12220],[200,12580],[206,12960]]},"ch3-034":{"text":"A week after the confession, I saw Syafiqa elsewhere on campus, walking closely beside another boy. They looked at ease in the way people do when a conversation began long before you entered the scene.","voiceUrl":"voices/chapter-3/ch3-034.mp3","durationMs":12480,"cues":[[2,160],[7,280],[13,620],[17,900],[29,1000],[31,2220],[35,2340],[43,2600],[53,3200],[56,3600],[64,3800],[72,4640],[80,4940],[87,5340],[95,5700],[100,6020],[105,7260],[112,7380],[115,7560],[120,7780],[123,8540],[127,8620],[131,8700],[138,8900],[141,9200],[146,9420],[148,9540],[161,9640],[167,10240],[172,10640],[179,10920],[183,11360],[191,11580],[195,11800],[201,11940]]},"ch3-035":{"text":"Seeing them did not prove they were together. It did not rewrite her no into a debt she owed me. But hurt is impatient with careful distinctions, and mine supplied a conclusion immediately.","voiceUrl":"voices/chapter-3/ch3-035.mp3","durationMs":12720,"cues":[[7,180],[12,500],[16,780],[20,920],[26,1180],[31,1580],[36,1720],[46,1860],[49,3080],[53,3160],[57,3300],[65,3600],[69,4059],[72,4320],[77,5120],[79,5320],[84,5500],[88,5880],[93,6120],[97,6360],[101,7180],[106,7440],[109,7780],[119,7900],[124,8540],[132,8780],[146,9200],[150,10380],[155,10540],[164,10960],[166,11280],[177,11340],[189,11880]]},"ch3-036":{"text":"So studying was not the real reason. There was already somebody else.","voiceUrl":"voices/chapter-3/ch3-036.mp3","durationMs":4464,"cues":[[3,120],[12,400],[16,740],[20,900],[24,1340],[29,1440],[37,1640],[43,2580],[47,2700],[55,2920],[64,3560],[69,3920]]},"ch3-037":{"text":"Later, through a separate conversation, I learned that she had liked him before I confessed. That information was firmer than what I had seen, and it struck the same bruise Alya's wrong message had left years earlier.","voiceUrl":"voices/chapter-3/ch3-037.mp3","durationMs":13344,"cues":[[7,120],[15,640],[17,800],[26,920],[40,1220],[42,2440],[50,2520],[55,2760],[59,2900],[63,3000],[69,3140],[73,3420],[80,3640],[82,4140],[93,4240],[98,5800],[110,6000],[114,6540],[121,6780],[126,7360],[131,7540],[133,7720],[137,7780],[143,7960],[147,8900],[150,9020],[157,9200],[161,9500],[166,9660],[173,10020],[180,10920],[186,11280],[194,11640],[198,12020],[203,12200],[209,12500],[217,12820]]},"ch3-038":{"text":"Again, I believed the important truth had existed behind me while I behaved according to a softer explanation. Again, I wondered why someone could not simply trust me with the answer they seemed to give everyone else.","voiceUrl":"voices/chapter-3/ch3-038.mp3","durationMs":13200,"cues":[[7,160],[9,940],[18,1040],[22,1540],[32,1680],[38,2200],[42,2520],[50,2660],[57,3180],[60,3620],[66,4200],[68,4500],[76,4540],[86,4880],[89,5320],[91,5420],[98,5540],[111,5960],[118,7540],[120,8060],[129,8160],[133,8480],[141,8780],[147,9100],[151,9240],[158,9500],[164,9900],[167,10320],[172,10880],[176,10980],[183,11160],[188,11480],[195,11660],[198,11860],[203,11980],[212,12260],[217,12700]]},"ch3-belief-generalise-001":{"text":"Alya, Hana, now Syafiqa. Maybe Malay girls simply will not tell me the truth until I discover it somewhere else.","voiceUrl":"voices/chapter-3/ch3-belief-generalise-001.mp3","durationMs":7944,"cues":[[6,140],[12,780],[16,1500],[25,1660],[31,2940],[37,3140],[43,3400],[50,3760],[55,4180],[59,4460],[64,4860],[67,4980],[71,5080],[77,5180],[83,5960],[85,6180],[94,6260],[97,6620],[107,7060],[112,7480]]},"ch3-belief-generalise-002":{"text":"I turned three different people and three different endings into a rule about Malay girls. The pattern felt protective because it made pain predictable. It was also unfair, shaped by selective memory and large enough to erase every individual person inside it.","voiceUrl":"voices/chapter-3/ch3-belief-generalise-002.mp3","durationMs":16800,"cues":[[2,160],[9,260],[15,560],[25,920],[32,1280],[36,1740],[42,1920],[52,2220],[60,2600],[65,3200],[67,3420],[72,3580],[78,3940],[84,4200],[91,4560],[95,5900],[103,6020],[108,6360],[119,6840],[127,7700],[130,7940],[135,8080],[140,8340],[153,8680],[156,9960],[160,10080],[165,10260],[173,10560],[180,11360],[183,11700],[193,11980],[200,12480],[204,13120],[210,13320],[217,13640],[220,13900],[226,14020],[232,14520],[243,14960],[250,15540],[257,16040],[260,16520]]},"ch3-belief-protect-001":{"text":"People say the kindest reason, not the truest one. From now on, I need to watch what they do and find the answer myself.","voiceUrl":"voices/chapter-3/ch3-belief-protect-001.mp3","durationMs":8688,"cues":[[7,80],[11,380],[15,860],[23,1000],[31,1560],[35,2360],[39,2740],[46,2880],[51,3300],[56,4140],[60,4300],[64,4540],[66,5200],[71,5260],[74,5400],[80,5520],[85,5840],[90,6080],[93,6320],[97,6860],[102,7060],[106,7280],[113,7380],[120,7820]]},"ch3-belief-protect-002":{"text":"That rule sounded cautious and mature. In practice, it trained me to treat ambiguity as evidence and inference as certainty. Suspicion could prevent surprise, but it could also manufacture betrayal where a boundary or private feeling was enough.","voiceUrl":"voices/chapter-3/ch3-belief-protect-002.mp3","durationMs":18000,"cues":[[5,260],[10,500],[18,840],[27,1320],[31,1880],[39,2060],[42,3560],[52,3700],[55,4700],[63,4820],[66,5180],[69,5380],[75,5500],[85,5820],[88,6500],[97,6740],[101,7580],[111,7820],[114,8700],[125,8880],[135,10380],[141,11040],[149,11200],[159,11540],[163,12880],[166,13000],[172,13120],[177,13400],[189,13720],[198,14420],[204,15500],[206,15640],[215,15760],[218,16340],[226,16500],[234,16900],[238,17220],[245,17380]]},"ch3-belief-question-001":{"text":"I wish she had told me about him. But Syafiqa is one person, and rejection is still rejection whatever explanation comes with it.","voiceUrl":"voices/chapter-3/ch3-belief-question-001.mp3","durationMs":7776,"cues":[[2,120],[7,220],[11,400],[15,500],[20,640],[23,960],[29,1080],[34,1300],[38,2320],[46,2480],[49,2980],[53,3220],[61,3460],[65,4140],[75,4260],[78,4820],[84,5080],[94,5360],[103,6120],[115,6540],[121,7100],[126,7360],[129,7520]]},"ch3-belief-question-002":{"text":"It was the thought I needed, though not always the one I could sustain. A wish for direct communication was reasonable. Turning that wish into entitlement to somebody's private feelings—or a judgement on an entire group—was not.","voiceUrl":"voices/chapter-3/ch3-belief-question-002.mp3","durationMs":15120,"cues":[[3,120],[7,260],[11,600],[19,740],[21,1080],[29,1180],[36,2220],[40,2440],[47,2620],[51,2980],[55,3120],[57,3280],[63,3360],[72,3560],[74,5140],[79,5260],[83,5500],[90,5620],[104,5980],[108,6700],[120,6920],[128,8260],[133,8560],[138,8800],[143,9240],[155,9420],[158,10180],[169,10300],[177,10740],[186,11160],[189,12020],[191,12260],[201,12420],[204,12960],[207,13080],[214,13220],[220,13720],[224,14400],[228,14660]]},"ch3-belief-join":{"text":"Syafiqa had every right to reject me and no obligation to disclose a crush. I could also honestly say that the softened explanation made later knowledge harder to absorb. Both truths fit, even when teenage me wanted only one guilty side.","voiceUrl":"voices/chapter-3/ch3-belief-join.mp3","durationMs":17664,"cues":[[8,140],[12,640],[18,940],[24,1280],[27,1640],[34,1720],[37,2160],[41,2860],[44,3040],[55,3180],[58,3760],[67,3860],[69,4300],[76,4400],[78,5820],[84,5880],[89,6040],[98,6420],[102,6940],[107,7260],[111,7400],[120,7540],[132,7920],[137,8560],[143,8800],[153,9060],[160,10000],[163,10420],[171,10520],[176,12160],[183,12580],[188,13100],[193,13980],[198,14200],[206,14500],[209,14960],[216,15520],[221,15800],[225,16180],[232,16720],[237,17100]]},"ch3-039":{"text":"The rides did not recover their old ease. We remained civil, then less present in each other's routines. The queue where I had once waited through two buses became only a place to get home.","voiceUrl":"voices/chapter-3/ch3-039.mp3","durationMs":13440,"cues":[[4,140],[10,280],[14,800],[18,980],[26,1200],[32,1680],[36,1900],[42,2200],[45,3500],[54,3620],[61,4059],[66,4960],[71,5540],[79,5820],[82,6220],[87,6320],[95,6520],[105,6820],[109,8300],[115,8460],[121,9080],[123,9280],[127,9320],[132,9520],[139,9780],[147,10060],[151,10360],[157,10620],[164,11580],[169,11920],[171,12180],[177,12280],[180,12600],[184,12700],[189,12920]]},"ch3-040":{"text":"I told myself the lesson was about other people: ask sooner, trust less, look beneath every answer. I was slower to notice the more urgent question underneath—why one rejection had become a referendum on whether I was worth choosing at all.","voiceUrl":"voices/chapter-3/ch3-040.mp3","durationMs":17280,"cues":[[2,140],[7,240],[14,480],[18,960],[25,1080],[29,1380],[35,1540],[41,1960],[49,2220],[53,3220],[61,3540],[67,4160],[73,4600],[78,5400],[86,5620],[92,6300],[100,6600],[102,8140],[106,8240],[113,8440],[116,8800],[123,8920],[127,9320],[132,9460],[139,9860],[148,10380],[159,10940],[163,12440],[167,12840],[177,13020],[181,13580],[188,13720],[190,14020],[201,14120],[204,15120],[212,15260],[214,15620],[218,15720],[224,15940],[233,16320],[236,16660],[240,16880]]},"ch4-001":{"text":"After Syafiqa, I did not become cautious in the way I imagined. I became restless. Rejection had left a question about my worth, and instead of sitting with it, I began asking new people to answer it for me.","voiceUrl":"voices/chapter-4/ch4-001.mp3","durationMs":15024,"cues":[[6,320],[15,740],[17,2200],[21,2280],[25,2440],[32,2620],[41,2980],[44,3420],[48,3520],[52,3620],[54,3900],[64,3980],[66,5240],[73,5320],[83,6060],[93,7600],[97,8119],[102,8260],[104,8460],[113,8560],[119,8980],[122,9240],[129,9460],[133,10360],[141,10520],[144,10880],[152,11020],[157,11320],[161,11460],[163,12260],[169,12320],[176,12680],[180,13100],[187,13320],[190,13660],[197,13820],[200,14140],[204,14420],[207,14680]]},"ch4-002":{"text":"A crush could form from a few friendly conversations. A moment of attention became possibility. Once possibility appeared, I wanted a verdict quickly, as though enough courage repeated often enough would eventually produce the answer I preferred.","voiceUrl":"voices/chapter-4/ch4-002.mp3","durationMs":16560,"cues":[[2,100],[8,240],[14,680],[19,900],[24,1280],[26,1480],[30,1580],[39,1880],[54,2240],[56,3920],[63,4019],[66,4340],[76,4440],[83,5400],[96,5900],[101,7840],[113,8180],[123,8760],[125,9640],[132,9720],[134,10020],[142,10100],[151,10600],[154,11440],[161,11580],[168,11740],[176,12120],[185,12500],[191,13020],[198,13240],[204,14060],[215,14180],[223,14660],[227,15020],[234,15240],[236,15720],[246,15820]]},"ch4-003":{"text":"Maybe I have been waiting too long every time. Maybe the confident guys simply ask, accept the answer, and move on.","voiceUrl":"voices/chapter-4/ch4-003.mp3","durationMs":7176,"cues":[[6,120],[8,480],[13,660],[18,1000],[26,1140],[30,1480],[35,1640],[41,1880],[47,2060],[53,3040],[57,3240],[67,3360],[72,3760],[79,4380],[84,4740],[91,5260],[95,5600],[103,5740],[107,6280],[112,6400],[115,6600]]},"ch4-004":{"text":"That explanation contained one useful idea: a clear, respectful question can be healthier than months of private assumptions. It also concealed my desperation to make the next yes cancel every earlier no.","voiceUrl":"voices/chapter-4/ch4-004.mp3","durationMs":14712,"cues":[[5,200],[17,400],[27,1100],[31,1560],[38,1920],[44,2340],[46,3440],[53,3560],[64,4080],[73,4720],[77,5580],[80,5720],[90,5880],[95,6280],[102,6540],[105,6900],[113,7080],[126,7420],[129,8920],[134,9040],[144,9340],[147,9820],[159,10020],[162,11140],[167,11220],[171,11400],[176,11520],[180,11900],[187,12660],[193,13200],[201,13660],[204,14140]]},"ch4-search-love-001":{"text":"I am not trying to replace anyone. I just want to meet someone who sees me clearly and still wants to stay.","voiceUrl":"voices/chapter-4/ch4-search-love-001.mp3","durationMs":7920,"cues":[[2,160],[5,220],[9,360],[16,680],[19,980],[27,1060],[35,1440],[37,2440],[42,2520],[47,2700],[50,2780],[55,2860],[63,3040],[67,3320],[72,3480],[75,3720],[83,3860],[87,4360],[93,4600],[99,4880],[102,5140],[107,5280]]},"ch4-search-love-002":{"text":"The longing was sincere. The problem was the speed at which I assigned that hope to people I barely knew. Wanting love did not make every new attraction capable of carrying it.","voiceUrl":"voices/chapter-4/ch4-search-love-002.mp3","durationMs":10944,"cues":[[4,100],[12,260],[16,940],[25,1160],[29,2520],[37,2640],[41,3000],[45,3200],[51,3400],[54,3720],[60,3840],[62,4059],[71,4140],[76,4540],[81,4760],[84,4980],[91,5080],[93,5360],[100,5500],[106,5880],[114,7160],[119,7520],[123,7840],[127,7980],[132,8160],[138,8460],[142,8800],[153,8960],[161,9600],[164,9960],[173,10160],[176,10620]]},"ch4-search-proof-001":{"text":"One person saying yes would prove I am not the problem everyone eventually discovers. I need to know I can be chosen.","voiceUrl":"voices/chapter-4/ch4-search-proof-001.mp3","durationMs":7848,"cues":[[4,280],[11,500],[18,900],[22,1180],[28,1860],[34,2040],[36,2740],[39,2780],[43,2920],[47,3120],[55,3240],[64,3840],[75,4220],[86,4620],[88,5740],[93,5900],[96,6200],[101,6380],[103,6860],[107,6940],[110,7080],[117,7240]]},"ch4-search-proof-002":{"text":"No person could safely provide that proof. A yes would have soothed me for a while, then become something I feared losing. Self-worth borrowed from another person's answer always arrives with a repayment date.","voiceUrl":"voices/chapter-4/ch4-search-proof-002.mp3","durationMs":14544,"cues":[[3,160],[10,380],[16,800],[23,1020],[31,1400],[36,1820],[43,2140],[45,3460],[49,3600],[55,4160],[60,4260],[68,4460],[71,4880],[75,5060],[77,5220],[84,5300],[89,6300],[96,6560],[106,6940],[108,7300],[115,7400],[123,7700],[134,9100],[143,9980],[148,10300],[156,10440],[165,10800],[172,11260],[179,12280],[187,12720],[192,13180],[194,13320],[204,13400],[209,14100]]},"ch4-search-control-001":{"text":"If I ask early, there is no hidden story to discover later. Yes or no, at least I control when the truth arrives.","voiceUrl":"voices/chapter-4/ch4-search-control-001.mp3","durationMs":7776,"cues":[[3,180],[5,320],[9,480],[16,760],[22,1440],[25,1580],[28,1840],[35,2200],[41,2540],[44,2860],[53,2960],[60,3460],[64,4220],[67,4420],[71,4520],[74,5080],[80,5220],[82,5700],[90,5780],[95,6380],[99,6520],[105,6640],[113,7020]]},"ch4-search-control-002":{"text":"Early questions reduced uncertainty but did not create control. Other people still had private histories, changing feelings, and the right to choose what they shared. Clarity was a conversation, not an interrogation timed for my comfort.","voiceUrl":"voices/chapter-4/ch4-search-control-002.mp3","durationMs":15840,"cues":[[6,100],[16,400],[24,940],[36,1500],[40,2320],[44,2440],[48,2600],[55,2880],[64,3220],[70,4520],[77,4740],[83,5140],[87,5420],[95,5760],[106,6100],[115,6960],[125,7420],[129,8100],[133,8200],[139,8320],[142,8760],[149,8940],[154,9320],[159,9480],[167,9660],[175,11160],[179,11700],[181,11840],[195,11940],[199,13000],[202,13380],[216,13480],[222,14300],[226,14720],[229,14900],[237,15220]]},"ch4-search-join":{"text":"There were three confessions in that restless stretch: to an Indian girl, a Chinese girl, and another Malay girl. I identify them that way because teenage me was already sorting experience into categories, searching for a pattern large enough to explain me.","voiceUrl":"voices/chapter-4/ch4-search-join.mp3","durationMs":16800,"cues":[[6,100],[11,220],[17,400],[29,860],[32,1500],[37,1620],[46,1840],[55,2300],[58,3400],[61,3500],[68,3620],[74,4040],[76,4780],[84,4880],[90,5400],[94,6320],[102,6520],[108,6840],[114,7200],[116,8220],[125,8360],[130,8900],[135,9080],[139,9280],[147,9520],[155,10120],[158,10600],[162,10860],[170,11020],[178,11480],[189,11820],[194,12420],[206,12620],[216,13860],[220,14280],[222,14400],[230,14520],[236,14920],[243,15240],[246,15520],[254,15620],[257,16239]]},"ch4-005":{"text":"They were not a sequence of conquests or failed auditions. Each was a person with a life outside my question. Their names and private reasons are not needed here; none chose a relationship with me, and their answers were enough.","voiceUrl":"voices/chapter-4/ch4-005.mp3","durationMs":15024,"cues":[[5,100],[10,220],[14,400],[16,820],[25,960],[28,1360],[38,1540],[41,2520],[48,2680],[59,3060],[64,4660],[68,4920],[70,5080],[77,5200],[82,5580],[84,5720],[89,5820],[97,6200],[100,6880],[110,7100],[116,8140],[122,8300],[126,8740],[134,8900],[142,9260],[146,9640],[150,9740],[157,9960],[163,10280],[168,11260],[174,11780],[176,12000],[189,12060],[194,12680],[198,12880],[202,13540],[208,13680],[216,13920],[221,14340],[228,14500]]},"ch4-006":{"text":"I did not argue or continue pursuing them. I accepted the boundary in front of me. Respecting a no was important, even while the frequency of my asking revealed that I was not truly ready for a yes.","voiceUrl":"voices/chapter-4/ch4-006.mp3","durationMs":12864,"cues":[[2,200],[6,300],[10,460],[16,720],[19,1260],[28,1360],[37,1780],[43,2220],[45,3320],[54,3400],[58,3920],[67,4040],[70,4420],[76,4560],[79,4780],[83,4900],[94,5960],[96,6480],[99,6620],[103,6940],[114,7080],[119,8340],[125,8580],[129,8800],[139,8920],[142,9400],[145,9500],[152,9780],[161,10200],[166,10560],[168,10740],[172,10820],[176,10960],[182,11340],[188,11800],[192,12140],[194,12280],[198,12380]]},"ch4-007":{"text":"After each attempt, I performed recovery: never mind, all good, no worries. Then I carried the rejection home and stacked it beside the others until individual disappointments became a theory about myself.","voiceUrl":"voices/chapter-4/ch4-007.mp3","durationMs":14400,"cues":[[6,140],[11,400],[20,600],[22,1440],[32,1520],[42,1940],[48,3260],[54,3500],[58,4280],[64,4460],[67,5280],[76,5480],[81,7320],[83,7500],[91,7600],[95,7840],[105,7940],[110,8480],[114,9180],[122,9360],[125,9640],[132,9760],[136,10120],[143,10260],[149,11080],[160,11440],[176,11980],[183,12720],[185,13020],[192,13160],[198,13520],[205,13780]]},"ch4-008":{"text":"Desperation is not always loud. Mine looked organised. Ask clearly. Receive answer. Withdraw politely. Try again elsewhere. The motion kept me from noticing I was treating connection like a locked door that enough keys might open.","voiceUrl":"voices/chapter-4/ch4-008.mp3","durationMs":17184,"cues":[[12,140],[15,1080],[19,1240],[26,1580],[32,2040],[37,3460],[44,3720],[55,3960],[59,5480],[68,5980],[76,6720],[84,7120],[93,7760],[103,8180],[107,9280],[113,9500],[124,9860],[128,11700],[135,11820],[140,12220],[143,12420],[148,12540],[157,12720],[159,13700],[163,13760],[172,13900],[183,14180],[188,14620],[190,14780],[197,14900],[202,15300],[207,15680],[214,15840],[219,16180],[225,16500],[230,16720]]},"ch4-009":{"text":"By J2, the pace of school left less room for that cycle. The calendar filled with timed practices, consultations, and teachers reminding us how quickly A Levels would stop being a distant phrase.","voiceUrl":"voices/chapter-4/ch4-009.mp3","durationMs":12864,"cues":[[3,120],[7,380],[11,1360],[16,1500],[19,1740],[26,1900],[31,2300],[36,2600],[41,2920],[45,3200],[50,3340],[57,3560],[61,4920],[70,5080],[77,5560],[82,5920],[88,6140],[99,6520],[114,7380],[118,8720],[127,8900],[137,9280],[140,9700],[144,9820],[152,10040],[154,10500],[161,10640],[167,11000],[172,11180],[178,11400],[180,11600],[188,11760],[195,12180]]},"ch4-010":{"text":"I had spent a year beside classmates without knowing them deeply. Pressure changed that. People who once exchanged jokes began exchanging notes, food, and the small encouragements that help somebody survive a bad test.","voiceUrl":"voices/chapter-4/ch4-010.mp3","durationMs":14640,"cues":[[2,160],[6,220],[12,380],[14,640],[19,780],[26,1060],[37,1420],[45,2000],[53,2300],[58,2580],[66,2780],[75,4200],[83,4800],[89,5260],[96,6440],[100,6740],[105,6940],[115,7180],[121,7880],[127,8420],[138,8720],[145,9260],[151,9960],[155,10900],[159,11020],[165,11220],[180,11540],[185,12320],[190,12460],[199,12720],[207,13080],[209,13560],[213,13660],[218,14020]]},"ch4-011":{"text":"Mei Lin had been in my class from the beginning. She was Chinese, wore glasses, and was so much shorter than me that our conversations looked as though one of us had chosen the wrong camera angle.","voiceUrl":"voices/chapter-4/ch4-011.mp3","durationMs":11424,"cues":[[4,140],[8,320],[12,700],[17,900],[20,1100],[23,1240],[29,1440],[34,1880],[38,2060],[49,2180],[53,3460],[57,3580],[66,3720],[71,4620],[80,4780],[84,5940],[88,6060],[91,6280],[96,6560],[104,6860],[109,7200],[112,7360],[117,7960],[121,8060],[135,8220],[142,8960],[145,9180],[152,9280],[156,9480],[159,9600],[162,9680],[166,9800],[173,9960],[177,10260],[183,10360],[190,10660],[196,11040]]},"ch4-012":{"text":"Could you stop standing directly in front of the board? Some of us are educationally disadvantaged by your height.","voiceUrl":"voices/chapter-4/ch4-012.mp3","durationMs":8232,"cues":[[6,120],[10,340],[15,660],[24,980],[33,1440],[36,1960],[42,2140],[45,2400],[49,2540],[56,2680],[61,3520],[64,3760],[67,3940],[71,4220],[85,4480],[99,5300],[102,6240],[107,6420],[114,6600]]},"ch4-013":{"text":"I am contributing shade and perspective. Both are valuable classroom services.","voiceUrl":"voices/chapter-4/ch4-013.mp3","durationMs":4536,"cues":[[2,180],[5,240],[18,360],[24,900],[28,1460],[41,1580],[46,2460],[50,2900],[59,3060],[69,3380],[78,3760]]},"ch4-014":{"text":"Your perspective is blocking the entire question.","voiceUrl":"voices/chapter-4/ch4-014.mp3","durationMs":3432,"cues":[[5,260],[17,460],[20,1200],[29,1440],[33,2000],[40,2120],[49,2720]]},"ch4-015":{"text":"At first, her height and cuteness caught my attention. What kept it was her steadiness. Mei Lin was diligent without advertising it and funny in a quiet way that sometimes reached me several seconds late.","voiceUrl":"voices/chapter-4/ch4-015.mp3","durationMs":13200,"cues":[[3,120],[10,300],[14,680],[21,900],[25,1180],[34,1380],[41,1940],[44,2160],[55,2300],[60,3780],[65,3980],[68,4240],[72,4760],[76,4900],[88,5100],[92,6600],[96,6800],[100,7120],[109,7340],[117,7860],[129,8200],[132,8780],[136,9160],[142,9360],[145,9740],[147,9840],[153,9960],[157,10320],[162,10580],[172,10780],[180,11300],[183,11680],[191,11900],[199,12340],[204,12760]]},"ch4-016":{"text":"We began studying at the same table after lessons. She organised papers into neat sections. I brought explanations from whichever topic had finally made sense to me and snacks selected with no academic discipline at all.","voiceUrl":"voices/chapter-4/ch4-016.mp3","durationMs":12720,"cues":[[3,100],[9,200],[18,640],[21,1040],[25,1140],[30,1260],[36,1500],[42,1840],[51,2080],[55,3340],[65,3480],[72,4040],[77,4400],[82,4640],[92,4860],[94,6060],[102,6160],[115,6420],[120,7140],[130,7260],[136,7600],[140,7860],[148,8000],[153,8320],[159,8540],[162,8780],[165,8880],[169,9500],[176,9680],[185,10360],[190,10780],[193,10980],[202,11240],[213,11680],[216,12060],[220,12260]]},"ch4-017":{"text":"You solved the difficult part correctly, then lost a mark because your final line looks like it escaped during an emergency.","voiceUrl":"voices/chapter-4/ch4-017.mp3","durationMs":8472,"cues":[[4,140],[11,360],[15,860],[25,1080],[30,1580],[41,1920],[46,2900],[51,3140],[53,3460],[58,3580],[66,4019],[71,4400],[77,4640],[82,5140],[88,5620],[93,5980],[96,6220],[104,6360],[111,7020],[114,7380],[124,7520]]},"ch4-018":{"text":"The examiner should reward creativity under pressure.","voiceUrl":"voices/chapter-4/ch4-018.mp3","durationMs":2880,"cues":[[4,200],[13,300],[20,780],[27,960],[38,1440],[44,1980],[53,2180]]},"ch4-019":{"text":"The examiner would reward legible working. Start there.","voiceUrl":"voices/chapter-4/ch4-019.mp3","durationMs":5352,"cues":[[4,120],[13,240],[19,980],[26,1200],[34,1720],[43,2260],[49,3120],[55,3480]]},"ch4-020":{"text":"She noticed when frustration made me rush. I noticed when one poor practice paper made her unusually quiet. Support moved in both directions, practical and unannounced.","voiceUrl":"voices/chapter-4/ch4-020.mp3","durationMs":13272,"cues":[[4,140],[12,360],[17,920],[29,1080],[34,1800],[37,1980],[43,2200],[45,3560],[53,3660],[58,4240],[62,4480],[67,4780],[76,5020],[82,5460],[87,5980],[91,6140],[101,6360],[108,7200],[116,8740],[122,9220],[125,9560],[130,9720],[142,10000],[152,11180],[156,11980],[168,12440]]},"ch4-021":{"text":"One paper does not cancel all the work you have done. You told me that last week, so unfortunately it applies to you too.","voiceUrl":"voices/chapter-4/ch4-021.mp3","durationMs":6960,"cues":[[4,160],[10,360],[15,840],[19,1120],[26,1400],[30,1900],[34,2040],[39,2120],[43,2320],[48,2380],[54,2500],[58,3160],[63,3260],[66,3400],[71,3520],[76,3660],[82,3940],[85,4400],[99,4800],[102,5800],[110,5880],[113,6360],[117,6500],[121,6640]]},"ch4-022":{"text":"I regret giving you reusable advice.","voiceUrl":"voices/chapter-4/ch4-022.mp3","durationMs":4152,"cues":[[2,200],[9,340],[16,960],[20,1280],[29,1480],[36,2120]]},"ch4-023":{"text":"For the first time since the server years, discipline began to feel like something I could build rather than something other people possessed. A completed topic led to the next. Questions became less threatening when I returned to them daily.","voiceUrl":"voices/chapter-4/ch4-023.mp3","durationMs":15024,"cues":[[4,100],[8,220],[14,360],[19,700],[25,1080],[29,1360],[36,1520],[43,1900],[54,2880],[60,3940],[63,4220],[68,4340],[73,4520],[83,4740],[85,5160],[91,5220],[97,5460],[104,6260],[109,6560],[119,6740],[125,7160],[132,7380],[143,7720],[145,9540],[155,9620],[161,10080],[165,10440],[168,10620],[172,10720],[178,10820],[188,12020],[195,12560],[200,12900],[212,13160],[217,13640],[219,13780],[228,13860],[231,14220],[236,14320],[242,14500]]},"ch4-024":{"text":"Family expectations did not disappear. School prestige did not stop mattering to people. What changed was the evidence I could offer myself: I was no longer waiting for shame to become motivation. I was practising different choices.","voiceUrl":"voices/chapter-4/ch4-024.mp3","durationMs":16224,"cues":[[7,140],[20,460],[24,1240],[28,1420],[39,1700],[46,3240],[55,3540],[59,4180],[63,4340],[68,4560],[78,4840],[81,5220],[89,5340],[94,6660],[102,6840],[106,7760],[110,7900],[119,8119],[121,8580],[127,8640],[133,8840],[141,9080],[143,10560],[147,10640],[150,10780],[157,10940],[165,11300],[169,11660],[175,11860],[178,12240],[185,12320],[197,12620],[199,14000],[203,14080],[214,14280],[224,15160],[232,15560]]},"ch4-025":{"text":"My feelings for Mei Lin grew inside that ordinary partnership. They were less frantic than the confession spree and therefore, in some ways, more frightening. I knew her well enough for losing the friendship to mean something real.","voiceUrl":"voices/chapter-4/ch4-025.mp3","durationMs":14160,"cues":[[3,200],[12,380],[16,800],[20,940],[24,1120],[29,1460],[36,2000],[41,2360],[50,2620],[63,3080],[68,4660],[73,4760],[78,4900],[86,5200],[91,5660],[95,5820],[106,5920],[112,6500],[116,7120],[127,7240],[130,7980],[135,8140],[141,8340],[146,9240],[159,9440],[161,11020],[166,11120],[170,11280],[175,11460],[182,11620],[186,11920],[193,12080],[197,12380],[208,12500],[211,12900],[216,13020],[226,13280],[231,13700]]},"ch4-026":{"text":"I also knew there was a barrier neither cuteness nor good study sessions could responsibly ignore. I was Muslim. Mei Lin was Christian. Faith was not a decorative difference that affection could politely place to one side.","voiceUrl":"voices/chapter-4/ch4-026.mp3","durationMs":14640,"cues":[[2,160],[7,260],[12,560],[18,800],[22,940],[24,1080],[32,1180],[40,1820],[49,2180],[53,2860],[58,3160],[64,3440],[73,3780],[79,4220],[91,4380],[99,5060],[101,6740],[105,6920],[113,7120],[117,7960],[121,8140],[125,8620],[136,8780],[142,10100],[146,10600],[150,10800],[152,11000],[163,11140],[174,11660],[179,12100],[189,12200],[195,12720],[204,12880],[210,13360],[213,13640],[217,13760],[222,14040]]},"ch4-027":{"text":"It touched family, marriage, community, and the shape each of us imagined for an adult life. We never negotiated those questions because I never confessed. I could not see a future I was prepared to ask her to enter.","voiceUrl":"voices/chapter-4/ch4-027.mp3","durationMs":15024,"cues":[[3,220],[11,360],[19,760],[29,1560],[40,2320],[44,3560],[48,3680],[54,3800],[59,4180],[62,4340],[65,4460],[74,4600],[78,5140],[81,5240],[87,5360],[93,5780],[96,6940],[102,7100],[113,7320],[119,8020],[129,8260],[137,9240],[139,9560],[145,9680],[156,9920],[158,11760],[164,11840],[168,11980],[172,12160],[174,12280],[181,12380],[183,12880],[187,12960],[196,13120],[199,13660],[203,13880],[207,14120],[210,14320],[216,14500]]},"ch4-028":{"text":"She has been good to me. That does not mean I should hand her a problem just because keeping it private is difficult.","voiceUrl":"voices/chapter-4/ch4-028.mp3","durationMs":6120,"cues":[[4,120],[8,340],[13,700],[18,860],[21,1020],[25,1100],[30,1880],[35,2000],[39,2180],[44,2420],[46,2740],[53,2780],[58,2960],[62,3160],[64,3280],[72,3360],[77,3960],[85,4120],[93,4580],[96,4800],[104,4900],[107,5440],[117,5560]]},"ch4-029":{"text":"There was care in that restraint and fear inside it too. I stayed beside her without asking for more, telling myself the friendship was enough and trying not to inspect the word enough too closely.","voiceUrl":"voices/chapter-4/ch4-029.mp3","durationMs":12312,"cues":[[6,100],[10,280],[15,560],[18,1120],[23,1240],[33,1420],[37,2040],[42,2300],[49,2620],[52,3020],[57,3180],[59,4560],[66,4680],[73,4920],[77,5320],[85,5460],[92,5780],[96,6120],[102,6280],[110,7100],[117,7340],[121,7720],[132,7820],[136,8220],[143,8360],[147,8960],[154,9100],[158,9380],[161,9600],[169,9700],[173,10100],[178,10220],[185,10780],[189,11480],[197,11660]]},"ch4-030":{"text":"The weeks tightened around us. We reviewed until closing time, compared mistakes, and learned when to abandon one impossible question before it consumed an entire evening.","voiceUrl":"voices/chapter-4/ch4-030.mp3","durationMs":10320,"cues":[[4,180],[10,320],[20,740],[27,1120],[31,1500],[34,2440],[43,2620],[49,3040],[57,3360],[63,3760],[72,4280],[82,4660],[86,5560],[94,5740],[99,6040],[102,6180],[110,6300],[114,6860],[125,7040],[134,7720],[141,8200],[144,8460],[153,8580],[156,9160],[163,9280],[171,9880]]},"ch4-031":{"text":"After exams, I am going to sleep for a week. If anyone asks, I have left the country.","voiceUrl":"voices/chapter-4/ch4-031.mp3","durationMs":6960,"cues":[[6,180],[13,580],[15,1360],[18,1420],[24,1620],[27,1940],[33,2140],[37,2620],[39,2800],[45,2980],[48,3880],[55,4120],[61,4700],[63,5180],[68,5240],[73,5520],[77,5980],[85,6120]]},"ch4-032":{"text":"You need a more convincing plan. I will tell them you joined a travelling mathematics society.","voiceUrl":"voices/chapter-4/ch4-032.mp3","durationMs":4224,"cues":[[4,180],[9,280],[11,420],[16,480],[27,660],[33,1120],[35,1840],[40,1920],[45,2060],[50,2220],[54,2500],[61,2620],[63,2860],[74,2960],[86,3320],[94,3740]]},"ch4-033":{"text":"Then A Levels arrived. The exam hall resembled the one I remembered from 2013, but I did not. I was still afraid. This time, fear sat beside months of completed work instead of an empty space where preparation should have been.","voiceUrl":"voices/chapter-4/ch4-033.mp3","durationMs":15840,"cues":[[5,180],[7,560],[14,720],[23,1100],[27,2680],[32,2800],[37,3160],[47,3340],[51,3720],[55,3860],[57,4019],[68,4100],[73,4500],[79,4740],[83,5960],[85,6380],[89,6480],[94,6680],[96,8200],[100,8280],[106,8420],[114,8600],[119,10280],[125,10500],[130,11000],[134,11240],[141,11420],[148,11820],[151,12060],[161,12180],[166,12660],[174,13020],[177,13320],[180,13400],[186,13600],[192,14000],[198,14340],[210,14520],[217,15140],[222,15280],[227,15420]]},"ch4-034":{"text":"No paper felt perfect. Some questions opened cleanly; others resisted until time forced me onward. I wrote the final line, placed my pen down, and understood that uncertainty after effort feels different from uncertainty after avoidance.","voiceUrl":"voices/chapter-4/ch4-034.mp3","durationMs":17184,"cues":[[3,140],[9,340],[14,680],[23,1020],[28,2460],[38,2700],[45,3180],[54,3540],[61,4660],[70,4960],[76,5460],[81,5780],[88,6180],[91,6500],[99,6640],[101,8220],[107,8280],[111,8500],[117,8640],[123,8980],[130,9740],[133,10040],[137,10220],[143,10460],[147,11280],[158,11460],[163,11960],[175,12160],[181,13120],[188,13440],[194,14400],[204,14740],[209,15120],[221,15300],[227,16160],[237,16420]]},"ch4-035":{"text":"The long wait for results began. Without tutorials to organise our days, classmates scattered into temporary jobs, obligations, and plans they discussed with varying confidence. Mei Lin and I messaged less often but did not disappear entirely.","voiceUrl":"voices/chapter-4/ch4-035.mp3","durationMs":16632,"cues":[[4,120],[9,260],[14,580],[18,820],[26,940],[33,1700],[41,3240],[51,3540],[54,4160],[63,4300],[67,4700],[73,4860],[84,5620],[94,6280],[99,6680],[109,6920],[115,7440],[128,8220],[132,9360],[138,9520],[143,9920],[153,10040],[158,10540],[166,10780],[178,11260],[182,12960],[186,13120],[190,13300],[192,13500],[201,13680],[206,14260],[212,14520],[216,14980],[220,15180],[224,15340],[234,15520],[243,15960]]},"ch4-036":{"text":"I did not know whether the outcome would redeem anything. I only knew I had kept going after O Levels, entered the school I once dismissed, and allowed it to become a place where I learned how to work again.","voiceUrl":"voices/chapter-4/ch4-036.mp3","durationMs":12312,"cues":[[2,180],[6,240],[10,400],[15,580],[23,820],[27,1080],[35,1220],[41,1600],[48,1740],[58,2220],[60,3800],[65,3880],[70,4100],[72,4340],[76,4460],[81,4600],[87,4820],[93,5260],[95,5540],[103,5660],[111,6680],[115,6920],[122,7060],[124,7520],[129,7620],[140,7880],[144,9260],[152,9400],[155,9700],[158,9820],[165,9900],[167,10160],[173,10260],[179,10600],[181,10780],[189,10880],[193,11260],[196,11380],[201,11540],[207,11860]]},"ch5-001":{"text":"Results day in 2016 returned us to school in clothes that no longer matched the timetable. We occupied our old gathering places without belonging to the routine around them, carrying envelopes and trying to read one another's faces.","voiceUrl":"voices/chapter-5/ch5-001.mp3","durationMs":16080,"cues":[[8,120],[12,600],[15,1020],[20,1280],[29,2080],[32,2540],[35,2780],[42,2920],[45,3520],[53,3740],[58,4360],[61,4620],[68,4800],[76,5160],[80,5680],[91,5820],[94,7580],[103,7740],[107,8300],[111,8620],[121,8940],[128,9400],[136,9880],[146,10200],[149,10760],[153,10860],[161,10980],[168,11440],[174,11840],[183,12440],[193,13040],[197,13680],[204,14020],[207,14380],[212,14540],[216,14900],[226,15040],[232,15500]]},"ch5-002":{"text":"When I saw my outcome, I checked it more than once. The exact grades remain private. What matters is that I had done well—well enough to feel a future opening where I once believed every useful door had closed.","voiceUrl":"voices/chapter-5/ch5-002.mp3","durationMs":13200,"cues":[[5,80],[7,300],[11,420],[14,660],[23,860],[25,1500],[33,1640],[36,1880],[41,2080],[46,2300],[52,2500],[56,3740],[62,3840],[69,4280],[76,4660],[85,5040],[90,5800],[98,6000],[101,6420],[106,6580],[108,6940],[112,7000],[117,7180],[122,7440],[127,8119],[134,8340],[137,8700],[142,8860],[144,9060],[151,9180],[159,9660],[165,10100],[167,10340],[172,10500],[181,10740],[187,11260],[194,11700],[199,12140],[203,12400],[210,12580]]},"ch5-003":{"text":"I did it. I actually did it.","voiceUrl":"voices/chapter-5/ch5-003.mp3","durationMs":2496,"cues":[[2,140],[6,260],[10,420],[12,980],[21,1280],[25,1760],[28,1920]]},"ch5-004":{"text":"Pride arrived carefully, as though it expected somebody to challenge its right to be there. I thought of the dark room after O Levels, the school label I had repeated with embarrassment, and every evening spent rebuilding habits one page at a time.","voiceUrl":"voices/chapter-5/ch5-004.mp3","durationMs":15912,"cues":[[6,160],[14,520],[25,1020],[28,1940],[35,2080],[38,2260],[47,2380],[56,2960],[59,3460],[69,3660],[73,4100],[79,4340],[82,4600],[85,4740],[92,4940],[94,6200],[102,6280],[105,6540],[109,6680],[114,6800],[119,7140],[125,7460],[127,7780],[135,7960],[139,8660],[146,8800],[152,9120],[154,9580],[158,9660],[167,9800],[172,10400],[187,10540],[191,11660],[197,11940],[205,12440],[211,12900],[222,13200],[229,13800],[233,14560],[238,14820],[241,15200],[243,15340],[248,15440]]},"ch5-005":{"text":"Then I found Mei Lin. Her paper rested in both hands. She was not crying, but the stillness around her was different from concentration. Her results had fallen below what she had worked and hoped for.","voiceUrl":"voices/chapter-5/ch5-005.mp3","durationMs":13104,"cues":[[5,120],[7,400],[13,540],[17,920],[22,1120],[26,2300],[32,2480],[39,2880],[42,3340],[47,3500],[54,3740],[58,4660],[62,4800],[66,4960],[74,5200],[78,6140],[82,6280],[92,6460],[99,7080],[103,7440],[107,7640],[117,7860],[122,8420],[137,8640],[141,9960],[149,10120],[153,10560],[160,10720],[166,11060],[171,11420],[175,11620],[179,11740],[186,11940],[190,12260],[196,12460],[200,12800]]},"ch5-006":{"text":"I know this is not the end of everything. Please do not give me the speech yet. I just need a while before I can believe it.","voiceUrl":"voices/chapter-5/ch5-006.mp3","durationMs":8544,"cues":[[2,180],[7,340],[12,600],[15,780],[19,1000],[23,1240],[27,1440],[30,1640],[42,1820],[49,3260],[52,3680],[56,3800],[61,4019],[64,4240],[68,4380],[75,4680],[80,5080],[82,5940],[87,6100],[92,6420],[94,6740],[100,6880],[107,7200],[109,7520],[113,7640],[121,7840],[124,8220]]},"ch5-007":{"text":"No speech. I can sit here and be quiet. I have at least some experience with results feeling heavier than paper.","voiceUrl":"voices/chapter-5/ch5-007.mp3","durationMs":6864,"cues":[[3,60],[11,260],[13,1360],[17,1420],[21,1560],[26,1700],[30,1800],[33,1880],[40,2000],[42,3260],[47,3360],[50,3560],[56,3660],[61,4040],[72,4220],[77,4740],[85,4860],[93,5240],[101,5620],[106,6060],[112,6200]]},"ch5-008":{"text":"My good news and her disappointment occupied the same afternoon. Supporting her did not require me to apologise for succeeding. Celebrating myself did not require me to hurry her out of grief.","voiceUrl":"voices/chapter-5/ch5-008.mp3","durationMs":12072,"cues":[[3,120],[8,340],[13,540],[17,1220],[21,1420],[36,1620],[45,2400],[49,2840],[54,2960],[65,3240],[76,4620],[80,5080],[84,5260],[88,5420],[96,5620],[99,6040],[102,6200],[112,6340],[116,7080],[128,7240],[140,8460],[147,9000],[151,9480],[155,9620],[163,9820],[166,10260],[169,10420],[175,10620],[179,10960],[183,11280],[186,11420],[192,11560]]},"ch5-009":{"text":"In the days afterward, our class exchanged plans and consolation. Mei Lin answered messages politely but sounded compressed, as if every conversation might become another demand to explain what had gone wrong.","voiceUrl":"voices/chapter-5/ch5-009.mp3","durationMs":13440,"cues":[[3,120],[7,240],[12,340],[23,660],[27,1220],[33,1460],[43,1800],[49,2480],[53,2960],[66,3240],[70,4620],[74,4780],[83,5180],[92,5560],[101,6040],[105,6560],[113,6840],[125,7500],[128,8660],[131,8800],[137,9080],[150,9420],[156,10100],[163,10280],[171,10540],[178,10880],[181,11440],[189,11580],[194,12220],[198,12360],[203,12520],[209,12780]]},"ch5-010":{"text":"I remembered how my room had narrowed after O Levels. Advice had reached me as pressure because everyone wanted movement before I could imagine direction. I wanted to offer her something that did not resemble another plan.","voiceUrl":"voices/chapter-5/ch5-010.mp3","durationMs":13200,"cues":[[2,120],[13,200],[17,600],[20,740],[25,960],[29,1160],[38,1400],[44,1860],[46,2160],[54,2300],[61,3280],[65,3700],[73,3860],[76,4240],[79,4640],[88,4860],[96,5500],[105,5900],[112,6300],[121,6680],[128,7200],[130,7520],[136,7600],[144,7720],[155,8119],[157,9740],[164,9820],[167,10080],[173,10240],[177,10500],[187,10680],[192,11020],[196,11160],[200,11300],[209,11560],[217,12180],[222,12640]]},"ch5-011":{"text":"Would you like to go to the zoo one day? No results talk unless you start it. We can just walk around and let animals have more organised lives than us.","voiceUrl":"voices/chapter-5/ch5-011.mp3","durationMs":7848,"cues":[[6,100],[10,240],[15,360],[18,580],[21,680],[24,820],[28,920],[32,1060],[36,1260],[41,1420],[44,2400],[52,2560],[57,2960],[64,3260],[68,3520],[74,3660],[78,3840],[81,4440],[85,4520],[90,4640],[95,4860],[102,5060],[106,5380],[110,5620],[118,5820],[123,6120],[128,6340],[138,6580],[144,6940],[149,7180],[152,7320]]},"ch5-012":{"text":"That is a strange sales pitch. But yes. I think getting out would be good.","voiceUrl":"voices/chapter-5/ch5-012.mp3","durationMs":5760,"cues":[[5,120],[8,300],[10,500],[18,760],[24,1320],[31,1760],[35,2800],[40,3000],[42,3900],[48,4040],[56,4400],[60,4760],[66,4920],[69,5120],[74,5300]]},"ch5-013":{"text":"The invitation was goodwill, not a bargain disguised as kindness. I had feelings I had never declared, but she had agreed to a day out with a friend. Anything beyond that existed only in my private hopes.","voiceUrl":"voices/chapter-5/ch5-013.mp3","durationMs":13512,"cues":[[4,100],[15,200],[19,860],[29,1020],[33,2000],[35,2160],[43,2300],[53,2760],[56,3260],[66,3420],[68,4760],[72,4820],[81,5080],[83,5760],[87,5820],[93,5980],[103,6200],[107,7200],[111,7440],[115,7660],[122,7800],[125,8180],[127,8320],[131,8420],[135,8660],[140,8840],[142,8940],[150,9060],[159,9960],[166,10360],[171,10840],[179,11060],[184,11620],[187,12040],[190,12180],[198,12480],[204,12960]]},"ch5-014":{"text":"The morning was warm before we reached the entrance. Families moved around us with bags, folded maps, and children already negotiating for snacks. Mei Lin arrived carrying enough water for a minor expedition.","voiceUrl":"voices/chapter-5/ch5-014.mp3","durationMs":13272,"cues":[[4,120],[12,240],[16,580],[21,780],[28,1100],[31,1440],[39,1600],[43,1920],[53,2040],[62,3180],[68,3640],[75,3880],[78,4260],[83,4440],[89,4640],[96,5280],[102,5660],[106,6080],[115,6420],[123,6880],[135,7280],[139,7920],[147,8100],[151,9500],[155,9720],[163,10120],[172,10580],[179,10900],[185,11180],[189,11580],[191,11740],[197,11940],[208,12440]]},"ch5-015":{"text":"You know they sell drinks inside, right? We are not crossing a desert.","voiceUrl":"voices/chapter-5/ch5-015.mp3","durationMs":3408,"cues":[[4,140],[9,200],[14,320],[19,460],[26,700],[34,960],[41,1360],[44,1960],[48,2060],[52,2240],[61,2560],[63,2900],[70,2960]]},"ch5-016":{"text":"And pay attraction prices? My disappointing results did not remove my common sense.","voiceUrl":"voices/chapter-5/ch5-016.mp3","durationMs":6720,"cues":[[4,140],[8,420],[19,760],[27,1420],[30,3020],[44,3220],[52,3940],[56,4580],[60,4820],[67,5180],[70,5620],[77,5780],[83,6120]]},"ch5-017":{"text":"For the first part of the day, she remained careful, smiling half a second after the moment asked for it. Then an animal ignored a perfectly placed meal, and her commentary became so indignant that the old Mei Lin emerged mid-sentence.","voiceUrl":"voices/chapter-5/ch5-017.mp3","durationMs":15360,"cues":[[4,120],[8,240],[14,360],[19,700],[22,860],[26,980],[31,1080],[35,1400],[44,1560],[53,2040],[61,2940],[66,3480],[68,3700],[75,3820],[81,4200],[85,4480],[92,4580],[98,5040],[102,5360],[106,5560],[111,6440],[114,6820],[121,7120],[129,7700],[131,8119],[141,8280],[148,8840],[154,9280],[158,10120],[162,10280],[173,10460],[180,11140],[183,11580],[193,11800],[198,12500],[202,12640],[206,12900],[210,13220],[214,13440],[222,13840],[235,14520]]},"ch5-018":{"text":"That is excellent food being wasted. Do you know how many hours of studying I could have survived with that snack?","voiceUrl":"voices/chapter-5/ch5-018.mp3","durationMs":7752,"cues":[[5,140],[8,320],[18,640],[23,1340],[29,1700],[37,2040],[40,3200],[44,3380],[49,3620],[53,3980],[58,4140],[64,4440],[67,4880],[76,5080],[78,5720],[84,5760],[89,5900],[98,6100],[103,6680],[108,6840],[114,7100]]},"ch5-019":{"text":"We moved without a timetable. She stopped for whatever caught her interest. I took photographs when asked and accepted several lectures about composition from somebody whose own thumb appeared in two pictures.","voiceUrl":"voices/chapter-5/ch5-019.mp3","durationMs":12792,"cues":[[3,140],[9,300],[17,740],[19,1040],[30,1140],[34,2360],[42,2600],[46,3020],[55,3240],[62,3620],[66,3820],[76,4019],[78,5140],[83,5240],[95,5420],[100,6020],[106,6300],[110,6960],[119,7100],[127,7640],[136,7980],[142,8500],[154,8780],[159,9460],[168,9680],[174,10060],[178,10420],[184,10800],[193,11360],[196,11780],[200,11980],[209,12180]]},"ch5-020":{"text":"By lunch, her shoulders looked less guarded. She spoke about small future possibilities without attaching each one to what her results had removed. That was what I had hoped the day might offer.","voiceUrl":"voices/chapter-5/ch5-020.mp3","durationMs":12480,"cues":[[3,140],[10,340],[14,980],[24,1140],[31,1640],[36,1960],[45,2240],[49,3440],[55,3680],[61,4019],[67,4440],[74,4840],[88,5200],[96,6000],[106,6320],[111,6860],[115,7200],[118,7480],[123,7600],[127,7740],[135,7920],[139,8380],[148,8560],[153,10020],[157,10240],[162,10620],[164,10840],[168,10880],[174,11040],[178,11420],[182,11560],[188,11760],[194,12020]]},"ch5-021":{"text":"Thank you for asking me out today. I was going to stay home and avoid everybody, which is probably not a complete recovery strategy.","voiceUrl":"voices/chapter-5/ch5-021.mp3","durationMs":8952,"cues":[[6,160],[10,460],[14,660],[21,860],[24,1240],[28,1460],[35,1660],[37,2620],[41,2700],[47,2880],[50,3160],[55,3340],[60,3660],[64,4000],[70,4160],[81,4640],[87,5560],[90,5740],[99,5980],[103,6640],[105,6900],[114,7020],[123,7540],[132,8119]]},"ch5-022":{"text":"Avoiding everybody works for about one day. After that, your room starts winning arguments you never agreed to have.","voiceUrl":"voices/chapter-5/ch5-022.mp3","durationMs":7104,"cues":[[9,120],[19,740],[25,1400],[29,1660],[35,1800],[39,2200],[44,2640],[50,3300],[56,3540],[61,3940],[66,4160],[73,4420],[81,4680],[91,4920],[95,5540],[101,5780],[108,6120],[111,6400],[116,6520]]},"ch5-023":{"text":"Somewhere across those hours, another name kept returning: Daniel—the pseudonym I use here for a guy she knew through church. I remember the pattern more clearly than the sentences, so I will not invent exact comparisons memory did not preserve.","voiceUrl":"voices/chapter-5/ch5-023.mp3","durationMs":15984,"cues":[[10,140],[17,600],[23,1080],[30,1440],[38,1820],[43,2200],[48,2500],[59,2740],[66,4100],[70,5260],[80,5400],[82,6000],[86,6140],[91,6320],[95,6540],[97,6660],[101,6760],[105,7100],[110,7280],[118,7500],[126,7800],[128,9080],[137,9160],[141,9560],[149,9720],[154,10160],[162,10400],[167,10840],[171,11020],[182,11160],[185,11920],[187,12320],[192,12380],[196,12560],[203,12780],[209,13300],[221,13840],[228,14600],[232,15000],[236,15180],[245,15420]]},"ch5-024":{"text":"A place we passed reminded her of something Daniel had mentioned. A choice I made invited a comparison with how he approached things. Later, his name entered again through another association that felt effortless to her and increasingly pointed to me.","voiceUrl":"voices/chapter-5/ch5-024.mp3","durationMs":15984,"cues":[[2,140],[8,240],[11,660],[18,840],[27,1360],[31,1880],[34,2060],[44,2200],[51,2580],[55,3080],[66,3260],[68,4580],[75,4720],[77,5260],[82,5360],[90,5640],[92,6160],[103,6220],[108,6920],[112,7100],[115,7360],[126,7520],[134,8080],[141,9280],[145,9640],[150,9820],[158,10140],[164,10420],[172,10800],[180,11200],[192,11580],[197,12340],[202,12520],[213,12900],[216,13460],[220,13580],[224,13860],[237,14100],[245,14840],[248,15360],[251,15580]]},"ch5-025":{"text":"The first mention was ordinary. The next caught my attention. By the time I perceived a pattern, irritation sat underneath every new subject, waiting to hear his name before I heard what Mei Lin was actually saying.","voiceUrl":"voices/chapter-5/ch5-025.mp3","durationMs":14952,"cues":[[4,120],[10,260],[18,640],[22,1180],[32,1680],[36,2980],[41,3120],[48,3820],[51,4059],[62,4200],[65,5580],[69,5700],[74,5840],[76,6180],[86,6280],[88,6680],[97,6820],[108,7360],[112,8140],[123,8380],[129,8980],[133,9500],[142,9840],[150,10760],[153,11200],[158,11340],[162,11600],[167,11880],[174,12240],[176,12580],[182,12660],[187,12940],[191,13140],[195,13380],[199,13680],[208,13960],[215,14480]]},"ch5-026":{"text":"Why does everything I do need to be placed beside this guy? I invited her here to help, not to spend the day being measured against someone who is not even present.","voiceUrl":"voices/chapter-5/ch5-026.mp3","durationMs":8232,"cues":[[4,260],[9,480],[20,720],[22,1140],[25,1240],[30,1640],[33,1740],[36,1820],[43,1960],[50,2260],[55,2800],[60,2980],[62,3820],[70,3880],[74,4220],[79,4340],[82,4480],[88,4580],[92,5100],[95,5240],[101,5380],[105,5540],[109,5640],[115,5820],[124,6060],[132,6400],[140,6640],[144,6940],[147,7060],[151,7220],[156,7500],[164,7760]]},"ch5-027":{"text":"That reaction contained jealousy, wounded pride, and a genuine dislike of repeated comparison. It also ignored an important fact: I had never told Mei Lin how I felt, so she could not knowingly manage feelings I had chosen to hide.","voiceUrl":"voices/chapter-5/ch5-027.mp3","durationMs":16704,"cues":[[5,240],[14,460],[24,980],[34,1560],[42,2540],[49,2920],[53,3840],[55,3980],[63,4160],[71,4660],[74,5160],[83,5280],[95,5860],[98,7380],[103,7540],[111,7820],[114,8300],[124,8420],[130,8880],[132,10060],[136,10120],[142,10260],[147,10580],[151,10980],[155,11180],[159,11480],[161,11700],[167,11840],[170,12840],[174,13100],[180,13260],[184,13440],[194,13720],[201,14260],[210,14740],[212,15460],[216,15540],[223,15740],[226,16100],[231,16219]]},"ch5-zoo-mask-001":{"text":"Come on. We still have half the place left, and you have not criticised my photography enough to meet today's quota.","voiceUrl":"voices/chapter-5/ch5-zoo-mask-001.mp3","durationMs":4824,"cues":[[5,120],[9,340],[12,740],[18,840],[23,1000],[28,1160],[32,1360],[38,1460],[44,1700],[48,2060],[52,2200],[57,2300],[61,2560],[72,2840],[75,3260],[87,3360],[94,3800],[97,4019],[102,4100],[110,4240],[116,4480]]},"ch5-zoo-mask-002":{"text":"Humour kept my irritation from becoming her burden on an already difficult week. It also helped me perform a comfort I did not feel, leaving her no opportunity to understand why I would soon become distant.","voiceUrl":"voices/chapter-5/ch5-zoo-mask-002.mp3","durationMs":13272,"cues":[[7,140],[12,640],[15,940],[26,1180],[31,1820],[40,2000],[44,2480],[51,2800],[54,3420],[57,3540],[65,3760],[75,4220],[81,4700],[84,5520],[89,5660],[96,6020],[99,6340],[107,6500],[109,6880],[117,6980],[119,7480],[123,7560],[127,7720],[133,7960],[141,8740],[145,9060],[148,9280],[160,9500],[163,10200],[174,10300],[178,10940],[180,11580],[186,11640],[191,11880],[198,12160],[206,12580]]},"ch5-zoo-signal-001":{"text":"She is telling me where her interest is without having to reject a question I never asked. I should listen and finish the day as her friend.","voiceUrl":"voices/chapter-5/ch5-zoo-signal-001.mp3","durationMs":7776,"cues":[[4,160],[7,360],[15,520],[18,840],[24,1100],[28,1220],[37,1400],[40,1740],[48,2160],[55,2440],[58,2680],[65,2740],[67,3080],[76,3160],[78,3800],[84,3920],[91,4220],[93,5100],[100,5160],[107,5340],[111,5980],[118,6140],[122,6380],[126,6500],[129,7080],[133,7200],[140,7360]]},"ch5-zoo-signal-002":{"text":"Interpreting the name as a boundary helped me behave respectfully. But Mei Lin never confirmed that intention. A compassionate inference was still an inference, and I would later treat it as settled fact.","voiceUrl":"voices/chapter-5/ch5-zoo-signal-002.mp3","durationMs":13824,"cues":[[13,120],[17,660],[22,820],[25,1160],[27,1300],[36,1420],[43,2040],[46,2380],[53,2560],[67,2920],[71,4320],[75,4460],[79,4680],[85,5020],[95,5240],[100,5840],[111,6020],[113,7380],[127,7460],[137,8240],[141,8940],[147,9220],[150,9800],[161,10020],[165,11180],[167,11400],[173,11500],[179,11680],[185,12060],[188,12320],[191,12540],[199,12960],[204,13380]]},"ch5-zoo-name-feeling-001":{"text":"I am jealous. That is mine to manage, especially today. I can decide what to do with it after I am no longer angry.","voiceUrl":"voices/chapter-5/ch5-zoo-name-feeling-001.mp3","durationMs":6864,"cues":[[2,460],[5,560],[14,760],[19,1420],[22,1540],[27,1780],[30,2080],[38,2200],[49,2640],[56,3140],[58,3940],[62,4019],[69,4140],[74,4520],[77,4680],[80,4760],[85,4880],[88,5000],[94,5300],[96,5720],[99,5780],[102,5940],[109,6140],[115,6460]]},"ch5-zoo-name-feeling-002":{"text":"Naming the feeling prevented it from disguising itself as certainty. Waiting was wise. The missing step came afterward, when waiting quietly became withdrawing without ever returning to the conversation.","voiceUrl":"voices/chapter-5/ch5-zoo-name-feeling-002.mp3","durationMs":13752,"cues":[[7,140],[11,520],[19,680],[29,1100],[32,1620],[37,1780],[48,1980],[55,2540],[58,2980],[69,3180],[77,4720],[81,5160],[87,5400],[91,6600],[99,6680],[104,7080],[109,7460],[120,7920],[125,8900],[133,9100],[141,9460],[148,10000],[160,10740],[168,11600],[173,11940],[183,12180],[186,12700],[190,12800],[203,12900]]},"ch5-zoo-join":{"text":"I held the frustration in. We continued along shaded paths, stopped when something interested her, and let the afternoon soften toward evening. Mei Lin did not know there was a private argument taking place beside her.","voiceUrl":"voices/chapter-5/ch5-zoo-join.mp3","durationMs":14712,"cues":[[2,180],[7,240],[11,460],[23,580],[27,1400],[30,2560],[40,2660],[46,3200],[53,3540],[60,3920],[68,4660],[73,5040],[83,5260],[94,5680],[99,6260],[103,6940],[107,7060],[111,7240],[121,7380],[128,8100],[135,8580],[144,8940],[148,10280],[152,10500],[156,10860],[160,11040],[165,11300],[171,11580],[175,11740],[177,11880],[185,12000],[194,12540],[201,13220],[207,13560],[214,13880],[218,14300]]},"ch5-028":{"text":"Today helped. Not in a magical everything-is-fixed way. I just remembered I can have one good day while the larger problem is still there.","voiceUrl":"voices/chapter-5/ch5-028.mp3","durationMs":10224,"cues":[[6,160],[14,660],[18,1940],[21,2120],[23,2240],[31,2360],[51,3080],[56,4059],[58,5160],[63,5300],[74,5500],[76,6200],[80,6300],[85,6500],[89,6880],[94,7120],[98,7400],[104,8160],[108,8340],[115,8500],[123,8880],[126,9320],[132,9500],[138,9780]]},"ch5-029":{"text":"One good day is enough for today.","voiceUrl":"voices/chapter-5/ch5-029.mp3","durationMs":2496,"cues":[[4,340],[9,540],[13,720],[16,1260],[23,1360],[27,1920],[33,2060]]},"ch5-030":{"text":"When we parted, I was relieved. Partly because she seemed lighter. Partly because I no longer had to keep smiling through comparisons that had made me feel unnecessary in my own act of kindness.","voiceUrl":"voices/chapter-5/ch5-030.mp3","durationMs":13200,"cues":[[5,200],[8,420],[16,600],[18,1520],[22,1620],[32,1820],[39,3240],[47,3640],[51,3980],[58,4160],[67,4520],[74,5600],[82,6040],[84,6540],[87,6620],[94,6800],[98,7140],[101,7280],[106,7380],[114,7720],[122,8240],[134,8440],[139,9260],[143,9380],[148,9520],[151,9780],[156,10060],[168,10420],[171,11360],[174,11480],[178,11740],[182,12080],[185,12260],[194,12420]]},"ch5-031":{"text":"On the journey home, I constructed an explanation: Mei Lin had sensed that I might want more, so she had raised Daniel's name repeatedly to put her walls up. It was plausible. Plausibility made it easy to stop asking questions.","voiceUrl":"voices/chapter-5/ch5-031.mp3","durationMs":16080,"cues":[[3,140],[7,260],[15,420],[21,760],[23,1120],[35,1220],[38,1980],[51,2100],[55,3660],[59,3860],[63,4059],[70,4260],[75,4840],[77,5020],[83,5140],[88,5440],[94,5720],[97,6540],[101,6680],[105,6780],[112,6920],[121,7340],[126,7740],[137,7940],[140,8740],[144,8840],[148,8980],[154,9140],[158,9520],[161,10800],[165,10940],[176,11340],[189,12740],[194,13720],[197,13900],[202,14120],[205,14460],[210,14600],[217,14860],[227,15260]]},"ch5-032":{"text":"Perhaps Daniel mattered romantically. Perhaps he was simply present in her recent life. Perhaps comparison was her way of making conversation, or perhaps I heard more comparison than she intended because jealousy had sharpened my attention.","voiceUrl":"voices/chapter-5/ch5-032.mp3","durationMs":15984,"cues":[[8,140],[15,660],[24,1060],[38,1440],[46,3120],[49,3480],[53,3580],[60,3720],[68,4080],[71,4640],[75,4780],[82,4940],[88,5300],[96,6420],[107,6780],[111,7500],[115,7700],[119,7920],[122,8119],[129,8260],[143,8620],[146,10320],[154,10480],[156,11160],[162,11280],[167,11700],[178,11900],[183,12520],[187,12720],[196,12860],[204,13440],[213,13840],[217,14480],[227,14680],[230,15220],[240,15380]]},"ch5-033":{"text":"I cannot honestly select one of those possibilities now and call it memory. Mei Lin never told me that the day was a warning, and I never gave her the chance to confirm or correct what I believed.","voiceUrl":"voices/chapter-5/ch5-033.mp3","durationMs":11904,"cues":[[2,120],[9,200],[18,520],[25,1060],[29,1520],[32,1680],[38,1800],[52,2020],[56,2800],[60,3020],[65,3240],[68,3420],[76,3620],[80,4900],[84,5120],[90,5400],[95,5740],[98,5960],[103,6140],[107,6300],[111,6420],[115,6660],[117,6860],[126,6980],[130,7980],[132,8240],[138,8360],[143,8640],[147,8840],[151,9040],[158,9160],[161,9480],[169,9600],[172,10240],[180,10440],[185,10920],[187,11180],[196,11260]]},"ch5-034":{"text":"So I gradually pulled away. Replies took longer. Invitations stopped. The friendship did not end in an argument; it thinned through absences small enough to deny individually and obvious when placed together.","voiceUrl":"voices/chapter-5/ch5-034.mp3","durationMs":15264,"cues":[[3,140],[5,340],[15,440],[22,1020],[28,1260],[36,2500],[41,3040],[49,3240],[61,4019],[70,5060],[74,6320],[85,6420],[89,6860],[93,7000],[97,7320],[100,7640],[103,7760],[113,8000],[116,9120],[124,9380],[132,10000],[141,10400],[147,11140],[154,11420],[157,11740],[162,11860],[175,12300],[179,13460],[187,13740],[192,14220],[199,14420],[208,14720]]},"ch5-035":{"text":"At the time, leaving felt respectful. If she wanted distance, I would provide it before she needed to ask. That story protected me from another explicit rejection and allowed me to call retreat consideration.","voiceUrl":"voices/chapter-5/ch5-035.mp3","durationMs":13824,"cues":[[3,100],[7,240],[13,360],[21,1100],[26,1480],[38,1700],[41,3120],[45,3240],[52,3400],[62,3720],[64,4520],[70,4600],[78,4760],[81,5180],[88,5360],[92,5660],[99,5820],[102,6100],[107,6340],[112,7560],[118,7840],[128,8180],[131,8640],[136,8800],[144,8940],[153,9440],[163,9960],[167,11080],[175,11220],[178,11520],[181,11660],[186,11800],[194,12080],[208,12840]]},"ch5-036":{"text":"Years later, I could see the irony. I had been wounded when difficult truths reached me indirectly, yet I now expected Mei Lin to understand my withdrawal without the direct words I wished others had given me.","voiceUrl":"voices/chapter-5/ch5-036.mp3","durationMs":13440,"cues":[[6,260],[13,540],[15,1140],[21,1220],[25,1420],[29,1620],[36,1780],[38,3080],[42,3140],[47,3280],[55,3500],[60,3920],[70,4120],[77,4580],[85,5140],[88,5540],[100,5780],[104,7180],[106,7400],[110,7500],[119,7720],[123,8240],[127,8460],[130,8720],[141,8860],[144,9500],[155,9700],[163,10300],[167,10760],[174,10880],[180,11300],[182,11720],[189,11820],[196,12240],[200,12520],[206,12700],[209,13000]]},"ch5-037":{"text":"The zoo day was not a betrayal. It was a kind gesture mixed with unspoken hope, an uncomfortable pattern of comparison, and an interpretation neither person tested. Silence filled the remaining space and hardened into an answer.","voiceUrl":"voices/chapter-5/ch5-037.mp3","durationMs":17184,"cues":[[4,180],[8,340],[12,600],[16,920],[20,1140],[22,1480],[32,1560],[35,2940],[39,3020],[41,3140],[46,3260],[54,3860],[60,4680],[65,5060],[74,5320],[80,6000],[83,6980],[97,7100],[105,7900],[108,8280],[120,8420],[124,9520],[127,9960],[142,10120],[150,11040],[157,11420],[165,11800],[173,13280],[180,13860],[184,14080],[194,14200],[200,14700],[204,15320],[213,15540],[218,16260],[221,16540],[228,16700]]},"ch5-038":{"text":"By then I had academic evidence that a bad result did not define me. Emotionally, I was still building rules from incomplete endings. Those rules would follow me into the relationship that came next.","voiceUrl":"voices/chapter-5/ch5-038.mp3","durationMs":13344,"cues":[[3,120],[8,320],[10,940],[14,1080],[23,1420],[32,1920],[37,2480],[39,2600],[43,2700],[50,2980],[54,3660],[58,3820],[65,4040],[69,4440],[82,5160],[84,6360],[88,6440],[94,6600],[103,6860],[109,7300],[114,7780],[125,8140],[134,8860],[140,9940],[146,10260],[152,10640],[159,10840],[162,11140],[167,11280],[171,11480],[184,11580],[189,12300],[194,12520],[199,12780]]},"ns-001":{"text":"National Service began before the relief of my A-Level results had settled into confidence. The uniform gave every hour a purpose: wake, train, wait, move, clean, repeat. It was difficult, but difficulty with instructions felt safer than uncertainty without them.","voiceUrl":"voices/chapter-ns/ns-001.mp3","durationMs":17520,"cues":[[9,120],[17,620],[23,1120],[30,1460],[34,1860],[41,1960],[44,2300],[47,2440],[55,2720],[63,3160],[67,3620],[75,3800],[80,4160],[92,4420],[96,5840],[104,6000],[109,6480],[115,6820],[120,7200],[122,7420],[131,7540],[137,8420],[144,8940],[150,9480],[156,9960],[163,10520],[171,11160],[174,12240],[178,12380],[189,12600],[193,13600],[204,13800],[209,14340],[222,14540],[227,15360],[233,15620],[238,15940],[250,16120],[258,16800],[263,17200]]},"ns-002":{"text":"By 2016, I could point to evidence that I was disciplined and capable. I could endure exhaustion, learn quickly, and be useful to the people beside me. None of that automatically repaired the private rules I had built around affection.","voiceUrl":"voices/chapter-ns/ns-002.mp3","durationMs":15504,"cues":[[3,120],[9,360],[11,1820],[17,1880],[23,2080],[26,2300],[35,2440],[40,2960],[42,3200],[46,3280],[58,3480],[62,4180],[71,4440],[73,5620],[79,5640],[86,5820],[98,6240],[104,7360],[113,7760],[117,8500],[120,8740],[127,8960],[130,9440],[134,9560],[141,9680],[148,9980],[152,10400],[157,11280],[160,11440],[165,11560],[179,11900],[188,12540],[192,12980],[200,13140],[206,13600],[208,14060],[212,14120],[218,14280],[225,14540],[235,14840]]},"ns-003":{"text":"Do the work in front of you. Do not expect too much from anyone. That is how you avoid being surprised.","voiceUrl":"voices/chapter-ns/ns-003.mp3","durationMs":7200,"cues":[[3,280],[7,480],[12,600],[15,800],[21,920],[24,1080],[29,1180],[32,1860],[36,2040],[43,2400],[47,2840],[52,3080],[57,3520],[65,3800],[70,4840],[73,5160],[77,5280],[81,5420],[87,5520],[93,5860],[103,6100]]},"ns-004":{"text":"I called that rule maturity. Much of it was fear dressed in practical language. Earlier rejection had already encouraged an unfair suspicion of Malay girls; I had challenged the thought sometimes, but I had not removed its roots.","voiceUrl":"voices/chapter-ns/ns-004.mp3","durationMs":16632,"cues":[[2,300],[9,480],[14,800],[19,1080],[29,1960],[34,3600],[37,3860],[40,4000],[44,4200],[49,4620],[57,5160],[60,5540],[70,5740],[80,6300],[88,7340],[98,7740],[102,8320],[110,8520],[121,8860],[124,9440],[131,9640],[141,10060],[144,10680],[150,10840],[157,11200],[159,12260],[163,12340],[174,12540],[178,13200],[186,13340],[197,13660],[201,14280],[203,14960],[207,15020],[211,15160],[219,15400],[223,15860],[229,16120]]},"ns-005":{"text":"Camp compressed the world. Inside, rank, routine, and the next book-out mattered. Outside, family meals and ordinary messages acquired the brightness of another country. A weekend could feel enormous because it belonged to me for only a little while.","voiceUrl":"voices/chapter-ns/ns-005.mp3","durationMs":19200,"cues":[[5,160],[16,720],[20,1420],[27,1580],[35,2780],[41,3620],[50,4180],[54,5060],[58,5320],[63,5480],[72,5860],[82,6360],[91,7420],[98,8460],[104,8880],[108,9540],[117,9940],[126,10460],[135,10960],[139,11380],[150,11520],[153,12180],[161,12300],[170,12740],[172,14140],[180,14260],[186,14740],[191,14960],[200,15340],[208,16100],[211,16360],[220,16480],[223,16960],[226,17100],[230,17380],[235,17620],[237,18220],[244,18400],[250,18740]]},"ns-006":{"text":"During Hari Raya, my family visited one of my father's good friends. Nadiah was connected through that family's wider circle—the niece of his friend's brother—a relationship distant enough that we had never properly met.","voiceUrl":"voices/chapter-ns/ns-006.mp3","durationMs":12240,"cues":[[7,100],[12,480],[18,760],[21,1420],[28,1580],[36,1900],[40,2380],[43,2500],[46,2620],[55,2800],[60,3180],[69,3360],[76,4560],[80,4960],[90,5120],[98,5540],[103,5740],[112,5920],[118,6340],[125,6660],[129,7540],[135,7660],[138,7880],[142,7960],[151,8119],[159,8480],[161,9320],[174,9380],[182,10000],[189,10380],[194,10800],[197,10960],[201,11060],[207,11180],[216,11420],[220,11800]]},"ns-007":{"text":"The house carried the familiar movement of visiting: greetings crossing in the doorway, plates being replenished before they were empty, children migrating between rooms, adults rebuilding conversations from the previous year.","voiceUrl":"voices/chapter-ns/ns-007.mp3","durationMs":14304,"cues":[[4,100],[10,220],[18,580],[22,880],[31,1040],[40,1640],[43,2220],[53,2380],[63,3580],[72,4160],[75,4600],[79,4700],[88,4820],[95,5620],[101,6080],[113,6340],[120,7040],[125,7420],[130,7540],[137,7720],[146,8580],[156,9220],[164,9800],[171,10280],[178,11180],[189,11680],[203,12200],[208,13100],[212,13280],[221,13400],[226,13920]]},"ns-008":{"text":"Salam. Sorry—where should I put these? The table is already losing the battle.","voiceUrl":"voices/chapter-ns/ns-008.mp3","durationMs":4872,"cues":[[7,140],[13,980],[19,1360],[26,1500],[28,1640],[32,1720],[39,1880],[43,2560],[49,2660],[52,3000],[60,3220],[67,3580],[71,3840],[78,3940]]},"ns-009":{"text":"Then I looked across the room and saw Nadiah. She wore a hijab that framed her face softly, and for one suspended instant every other detail seemed to move behind her. She looked up at almost the same moment.","voiceUrl":"voices/chapter-ns/ns-009.mp3","durationMs":15432,"cues":[[5,100],[7,300],[14,380],[21,600],[25,980],[30,1120],[34,1660],[38,1980],[46,2440],[50,3780],[55,3920],[57,4100],[63,4160],[68,4900],[75,5140],[79,5420],[84,5600],[92,5880],[96,7120],[100,7260],[104,7580],[114,7880],[122,8760],[128,9700],[134,10160],[141,10400],[148,10860],[151,11280],[156,11440],[163,11820],[168,12220],[172,13500],[179,13660],[182,13920],[185,14080],[192,14200],[196,14560],[201,14700],[208,14960]]},"ns-010":{"text":"We held each other's gaze long enough for me to feel noticed and briefly embarrassed by how completely I had stopped listening. I knew almost nothing about her. Attraction rushed ahead and offered to fill every empty space.","voiceUrl":"voices/chapter-ns/ns-010.mp3","durationMs":15120,"cues":[[3,100],[8,200],[13,400],[21,580],[26,880],[31,1240],[38,1500],[42,1740],[45,1860],[48,1980],[53,2120],[61,2340],[65,3300],[73,3560],[85,3960],[88,4560],[92,4840],[103,5080],[105,6000],[109,6060],[117,6240],[128,6620],[130,8240],[135,8320],[142,8660],[150,9060],[156,9580],[161,9880],[172,11000],[179,11660],[185,11980],[189,12360],[197,12700],[200,13000],[205,13160],[211,13520],[217,14160],[223,14580]]},"ns-011":{"text":"She is beautiful. Not just beautiful—there is something peaceful about her. The hijab suits her so perfectly.","voiceUrl":"voices/chapter-ns/ns-011.mp3","durationMs":8232,"cues":[[4,160],[7,560],[18,1200],[22,2480],[27,2660],[37,2840],[43,3680],[46,3780],[56,3880],[65,4480],[71,5140],[76,5380],[80,6180],[86,6280],[92,6820],[96,7040],[99,7320],[109,7560]]},"ns-012":{"text":"That was the first image I made of Nadiah: beauty, modesty, calm, certainty. Her hijab was part of her appearance that day, not evidence about the whole of her character. I did not yet understand how much meaning I had assigned without permission.","voiceUrl":"voices/chapter-ns/ns-012.mp3","durationMs":18792,"cues":[[5,160],[9,360],[13,580],[19,720],[25,1060],[27,1360],[32,1460],[35,1660],[43,1820],[51,2860],[60,3840],[66,4960],[77,6000],[81,7400],[87,7540],[91,8060],[96,8260],[99,8540],[103,8640],[114,8820],[119,9360],[124,9560],[128,10180],[137,10540],[143,11060],[147,11300],[153,11440],[156,11960],[160,12060],[171,12220],[173,14000],[177,14080],[181,14240],[185,14480],[196,14820],[200,15460],[205,15660],[213,15960],[215,16600],[219,16680],[228,16860],[236,17660],[247,18060]]},"ns-013":{"text":"You look like somebody just asked you a question and you missed all of it.","voiceUrl":"voices/chapter-ns/ns-013.mp3","durationMs":6000,"cues":[[4,240],[9,400],[14,680],[23,1000],[28,1560],[34,2000],[38,2340],[40,2480],[49,2620],[53,3660],[57,3920],[64,4140],[68,4960],[71,5220],[74,5400]]},"ns-014":{"text":"That is possible. I have been in camp too long. Civilian conversations move very fast.","voiceUrl":"voices/chapter-ns/ns-014.mp3","durationMs":4800,"cues":[[5,140],[8,260],[18,420],[20,1120],[25,1200],[30,1380],[33,1480],[38,1620],[42,1820],[48,1960],[57,2680],[71,3020],[76,3720],[81,4100],[86,4360]]},"ns-015":{"text":"We spoke only briefly, surrounded by relatives and interrupted by the needs of the room. She was warm and amused, and I carried those few minutes away as though they contained a promise neither of us had made.","voiceUrl":"voices/chapter-ns/ns-015.mp3","durationMs":13824,"cues":[[3,140],[9,380],[14,880],[23,1220],[34,2080],[37,2600],[47,2820],[51,3480],[63,3800],[66,4400],[70,4540],[76,4660],[79,4980],[83,5100],[89,5240],[93,6440],[97,6580],[102,6780],[106,7580],[114,7720],[118,8660],[120,8840],[128,8980],[134,9320],[138,9640],[146,9900],[151,10220],[154,10820],[161,11000],[166,11200],[176,11320],[178,11700],[186,11820],[194,12600],[197,12920],[200,13060],[204,13200],[209,13380]]},"ns-016":{"text":"Back in camp, her face returned during the quiet edges of routine. I wondered whether she remembered me, then criticised myself for wondering. Wanting to reach out felt hopeful and dangerous in equal measure.","voiceUrl":"voices/chapter-ns/ns-016.mp3","durationMs":14400,"cues":[[5,80],[8,320],[14,520],[18,860],[23,1040],[32,1320],[39,1940],[43,2200],[49,2320],[55,2740],[58,3220],[67,3360],[69,4860],[78,4940],[86,5360],[90,5680],[101,5860],[105,6440],[110,7160],[121,7700],[128,8320],[132,8920],[143,9080],[151,10380],[154,10660],[160,10800],[164,11120],[169,11380],[177,11800],[181,12480],[191,12900],[194,13440],[200,13580],[208,13880]]},"ns-017":{"text":"Wait until Passing Out Parade. Finish this first. If the feeling survives all these weeks, maybe it deserves a real conversation.","voiceUrl":"voices/chapter-ns/ns-017.mp3","durationMs":7200,"cues":[[5,140],[11,300],[19,600],[23,920],[31,1080],[38,1620],[43,1880],[50,2080],[53,3080],[57,3200],[65,3320],[74,3620],[78,4260],[84,4440],[91,4620],[97,5220],[100,5420],[109,5520],[111,6000],[116,6080],[129,6260]]},"ns-018":{"text":"Passing Out Parade arrived in heat, rehearsed movement, and the sight of families searching formations for one familiar face. Completion did not transform me, but it made the future feel briefly negotiable.","voiceUrl":"voices/chapter-ns/ns-018.mp3","durationMs":13920,"cues":[[8,120],[12,460],[19,620],[27,1020],[30,1440],[36,1640],[46,2220],[56,2740],[60,3420],[64,3540],[70,3660],[73,3860],[82,4019],[92,4620],[103,5020],[107,5680],[111,5940],[120,6220],[126,6760],[137,7960],[141,8640],[145,8820],[155,9120],[159,9840],[163,10160],[166,10880],[171,11020],[175,11240],[182,11400],[187,11860],[195,12400],[206,13040]]},"ns-019":{"text":"Afterward, Nadiah and I began talking properly. The first messages were cautious, then surprisingly easy. We moved from polite updates to conversations that followed me through bus rides and the final minutes before sleep.","voiceUrl":"voices/chapter-ns/ns-019.mp3","durationMs":15840,"cues":[[11,200],[18,980],[22,1320],[24,1660],[30,1760],[38,2100],[48,2500],[52,3980],[58,4080],[67,4420],[72,4980],[82,5160],[87,6000],[100,6820],[106,7660],[109,8860],[115,9020],[120,9500],[127,9780],[135,10220],[138,10940],[152,11160],[157,12020],[166,12220],[169,12640],[177,12800],[181,13060],[187,13360],[191,13820],[195,14120],[201,14280],[209,14620],[216,15000],[222,15400]]},"ns-020":{"text":"So now that you have passed out, are you finally allowed to have a personality again?","voiceUrl":"voices/chapter-ns/ns-020.mp3","durationMs":4872,"cues":[[3,120],[7,340],[12,540],[16,680],[21,780],[28,1000],[33,1440],[37,2000],[41,2140],[49,2340],[57,2820],[60,3160],[65,3240],[67,3380],[79,3500],[85,4300]]},"ns-021":{"text":"Limited issue only. I need to return it before every book-in.","voiceUrl":"voices/chapter-ns/ns-021.mp3","durationMs":3432,"cues":[[8,140],[14,480],[20,780],[22,1360],[27,1420],[30,1560],[37,1640],[40,1940],[47,2060],[53,2460],[61,2720]]},"ns-022":{"text":"The dialogue here is reconstructed from memory, and the moments that follow are composites of many ordinary exchanges. I remember their emotional shape more reliably than exact wording: mutual attention, anticipation, and the comfort of being expected.","voiceUrl":"voices/chapter-ns/ns-022.mp3","durationMs":15912,"cues":[[4,240],[13,360],[18,880],[21,1340],[35,1520],[40,2260],[48,2460],[52,3220],[56,3320],[64,3420],[69,3840],[76,4000],[80,4300],[91,4480],[94,5040],[99,5200],[108,5760],[119,6180],[121,7540],[130,7620],[136,7980],[146,8119],[152,8680],[157,9100],[166,9260],[171,9800],[177,9940],[186,10400],[193,11420],[204,11820],[218,12720],[222,14100],[226,14180],[234,14300],[237,14700],[243,14840],[252,15100]]},"ns-023":{"text":"Message when you reach camp. I know you will be busy; I just want to know the journey was okay.","voiceUrl":"voices/chapter-ns/ns-023.mp3","durationMs":7344,"cues":[[8,220],[13,720],[17,940],[23,1060],[29,1400],[31,2720],[36,2840],[40,3080],[45,3200],[48,3360],[54,3540],[56,4960],[61,5060],[66,5260],[69,5460],[74,5600],[78,5780],[86,5960],[90,6340],[95,6580]]},"ns-024":{"text":"Reached. The bunk is exactly as glamorous as I left it. I already miss talking without checking the time.","voiceUrl":"voices/chapter-ns/ns-024.mp3","durationMs":7032,"cues":[[9,220],[13,1100],[18,1260],[21,1760],[29,1900],[32,2660],[42,2820],[45,3460],[47,3600],[52,3660],[56,3900],[58,4760],[66,4940],[71,5260],[79,5520],[87,5920],[96,6180],[100,6480],[105,6600]]},"ns-025":{"text":"We called ourselves a couple. We behaved like one: affectionate messages, planned meetings, reassurance across book-ins, small claims on each other's days. The warmth was real. So was a gap we failed to examine.","voiceUrl":"voices/chapter-ns/ns-025.mp3","durationMs":16704,"cues":[[3,100],[10,260],[20,560],[22,1020],[30,1100],[33,2040],[41,2180],[46,2580],[51,2840],[64,3780],[74,4300],[82,5240],[92,5620],[104,6640],[111,7240],[121,7600],[127,8600],[134,8900],[137,9360],[142,9480],[150,9660],[156,9920],[160,11340],[167,11520],[171,12280],[177,12520],[180,14200],[184,14420],[186,14560],[190,14680],[193,15160],[200,15360],[203,15920],[211,16040]]},"ns-026":{"text":"We never had one reliable conversation defining exclusivity, unfinished attachments, or what being together required from each of us. I assumed the word couple had completed that work. Assumption felt romantic while everything seemed secure.","voiceUrl":"voices/chapter-ns/ns-026.mp3","durationMs":17352,"cues":[[3,240],[9,380],[13,620],[17,940],[26,1240],[39,1900],[48,2720],[61,3420],[72,4720],[85,5260],[88,6260],[93,6600],[99,7000],[108,7280],[117,7660],[122,8160],[127,8340],[130,8520],[134,8640],[136,9900],[144,9980],[148,10540],[153,10640],[160,11020],[164,11500],[174,11700],[179,12140],[185,12380],[196,13540],[201,14280],[210,14580],[216,15780],[227,15960],[234,16420],[241,16700]]},"ns-027":{"text":"Our relationship lived mostly in modest pieces: a call before lights-out, her message waiting after training, a public meal where neither of us wanted to be first to say the evening should end.","voiceUrl":"voices/chapter-ns/ns-027.mp3","durationMs":12240,"cues":[[4,160],[17,440],[23,1240],[30,1560],[33,2060],[40,2220],[48,2720],[50,3800],[55,3920],[62,4280],[74,4600],[78,5680],[86,5840],[94,6260],[100,6620],[110,6900],[112,7980],[119,8080],[124,8480],[130,8960],[138,9180],[141,9520],[144,9660],[151,9860],[154,10120],[157,10200],[163,10380],[166,10720],[170,10840],[174,11000],[182,11160],[189,11560],[193,11820]]},"ns-028":{"text":"You always sound surprised when I remember something you told me.","voiceUrl":"voices/chapter-ns/ns-028.mp3","durationMs":3912,"cues":[[4,240],[11,540],[17,860],[27,1120],[32,1760],[34,1940],[43,2020],[53,2560],[57,2980],[62,3120],[65,3440]]},"ns-029":{"text":"I am adjusting to being important enough for somebody to remember the small things.","voiceUrl":"voices/chapter-ns/ns-029.mp3","durationMs":4464,"cues":[[2,140],[5,180],[15,280],[18,980],[24,1080],[34,1380],[41,1760],[45,2240],[54,2420],[57,2920],[66,3020],[70,3560],[76,3700],[83,4000]]},"ns-030":{"text":"She did remember. She made space for me, and I made space for her. Whatever remained unresolved elsewhere in her life does not make every tender moment counterfeit. Memory becomes less honest when pain is allowed to erase all preceding care.","voiceUrl":"voices/chapter-ns/ns-030.mp3","durationMs":19680,"cues":[[4,200],[8,420],[18,660],[22,2500],[27,2640],[33,2920],[37,3260],[41,3420],[45,4180],[47,4540],[52,4680],[58,4940],[62,5260],[67,5400],[76,6660],[85,7080],[96,7700],[106,8540],[109,8980],[113,9100],[118,9300],[123,9920],[127,10140],[132,10440],[138,10880],[145,11340],[152,11760],[165,12240],[172,13840],[180,14240],[185,14720],[192,15000],[197,15580],[202,15960],[205,16580],[213,16740],[216,17100],[222,17280],[226,18200],[236,18500],[241,19100]]},"ns-031":{"text":"Months passed. I began treating the relationship as an answer to older fears: here was a Malay woman who seemed to contradict every suspicious rule I had built. Instead of releasing the category, I made Nadiah its exception.","voiceUrl":"voices/chapter-ns/ns-031.mp3","durationMs":16464,"cues":[[7,200],[15,880],[17,2060],[23,2120],[32,2480],[36,2880],[49,2980],[52,3660],[55,3780],[62,4019],[65,4400],[71,4640],[78,5060],[83,6280],[87,6560],[89,6720],[95,6820],[101,7260],[105,7600],[112,7780],[115,8140],[126,8260],[132,8980],[143,9380],[148,10080],[150,10540],[154,10600],[161,10780],[169,11920],[172,12280],[182,12400],[186,13040],[196,13180],[198,14420],[203,14540],[210,14820],[214,15520],[224,15700]]},"ns-032":{"text":"That distinction mattered later. If one person carries the burden of disproving a prejudice, her mistake can appear to prove it again. I had placed Nadiah inside an argument she did not know I was conducting.","voiceUrl":"voices/chapter-ns/ns-032.mp3","durationMs":14880,"cues":[[5,240],[17,440],[26,1060],[33,1500],[36,2820],[40,3040],[47,3320],[55,3820],[59,4200],[66,4340],[69,4740],[80,4860],[82,5500],[93,5620],[97,6780],[105,6980],[109,7740],[116,7900],[119,8360],[125,8560],[128,8820],[135,8940],[137,10300],[141,10340],[148,10480],[155,11020],[162,11500],[165,11920],[174,12140],[178,12800],[182,13000],[186,13200],[191,13480],[193,13920],[197,14020],[208,14180]]},"ns-033":{"text":"One day in camp, Aisyah—a pseudonym for Nadiah's friend—sent me a message. It began with a question that seemed small enough to answer casually: had I seen Nadiah's Instagram story from Universal Studios Singapore?","voiceUrl":"voices/chapter-ns/ns-033.mp3","durationMs":14400,"cues":[[4,80],[8,260],[11,440],[17,640],[24,1260],[26,2060],[36,2260],[40,2940],[49,3100],[56,3620],[61,4340],[64,4520],[66,4620],[75,4720],[78,5900],[84,5980],[89,6380],[91,6500],[100,6620],[105,7160],[112,7400],[118,7980],[125,8240],[128,8480],[135,8640],[145,9000],[149,10040],[151,10320],[156,10460],[165,10800],[175,11300],[181,11920],[186,12280],[196,12520],[204,13040],[214,13760]]},"ns-034":{"text":"USS? No. She didn't tell me she was going. There is nothing on her story.","voiceUrl":"voices/chapter-ns/ns-034.mp3","durationMs":5760,"cues":[[5,120],[9,1200],[13,2220],[20,2320],[25,2500],[28,2620],[32,2720],[36,2840],[43,3020],[49,3940],[52,4080],[60,4400],[63,5000],[67,5100],[73,5280]]},"ns-035":{"text":"It was posted to Close Friends. I thought you would be included. I'll send what I saw, but I don't want to pretend I know the whole situation.","voiceUrl":"voices/chapter-ns/ns-035.mp3","durationMs":7992,"cues":[[3,260],[7,400],[14,600],[17,1020],[23,1180],[32,1560],[34,2440],[42,2520],[46,2740],[52,2820],[55,2960],[65,3080],[70,4100],[75,4260],[80,4500],[82,4660],[87,4760],[91,5240],[93,5540],[99,5660],[104,5880],[107,5980],[115,6080],[117,6560],[122,6660],[126,6860],[132,6960],[142,7180]]},"ns-036":{"text":"The screenshot arrived inside our chat. It showed Nadiah at USS beside another man. Aisyah identified him as Chinese and as someone from Nadiah's past. Nadiah was not wearing hijab in the image.","voiceUrl":"voices/chapter-ns/ns-036.mp3","durationMs":14472,"cues":[[4,100],[15,240],[23,900],[30,1580],[34,1980],[40,2240],[43,3220],[50,3360],[57,3640],[60,4120],[64,4300],[71,4880],[79,5300],[84,5700],[91,6740],[102,7000],[106,7580],[109,7740],[117,7920],[121,8940],[124,9140],[132,9320],[137,9660],[146,9880],[152,10360],[159,11720],[163,12260],[167,12460],[175,12720],[181,13040],[184,13780],[188,13880],[194,14020]]},"ns-037":{"text":"She hid this from me. She even took off her hijab for him. What else could this mean?","voiceUrl":"voices/chapter-ns/ns-037.mp3","durationMs":6072,"cues":[[4,160],[8,380],[13,580],[18,760],[22,960],[26,1820],[31,2080],[36,2380],[40,2560],[44,2700],[50,2820],[54,3380],[59,3520],[64,4540],[69,4740],[75,5100],[80,5260],[85,5520]]},"ns-038":{"text":"I did not know why Nadiah was not wearing hijab that day, and the screenshot could not tell me. Connecting that choice to the man beside her was my immediate inference, not an explanation she gave.","voiceUrl":"voices/chapter-ns/ns-038.mp3","durationMs":12000,"cues":[[2,180],[6,280],[10,440],[15,660],[19,900],[26,1160],[30,1580],[34,1720],[42,1920],[48,2200],[53,2620],[58,2820],[62,3580],[66,3680],[77,3820],[83,4380],[87,4540],[92,4740],[96,4960],[107,5920],[112,6360],[119,6600],[122,6960],[126,7060],[130,7200],[137,7480],[141,7940],[145,8160],[148,8500],[158,8680],[169,9220],[173,10020],[176,10500],[188,10640],[192,11400],[197,11580]]},"ns-discovery-ask-001":{"text":"Did she tell you she was going with him? Do you know whether they are together, or only what is in this picture?","voiceUrl":"voices/chapter-ns/ns-discovery-ask-001.mp3","durationMs":5112,"cues":[[4,120],[8,240],[13,440],[17,720],[21,860],[25,980],[31,1100],[36,1340],[41,1460],[44,2280],[48,2340],[53,2480],[61,2700],[66,2920],[70,3020],[80,3120],[83,3660],[88,3960],[93,4200],[96,4300],[99,4460],[104,4560],[112,4700]]},"ns-discovery-ask-002":{"text":"I know they have history, and I saw the story. I don't know what they agreed today. You need to ask Nadiah, not let me answer for her.","voiceUrl":"voices/chapter-ns/ns-discovery-ask-002.mp3","durationMs":9840,"cues":[[2,240],[7,360],[12,620],[17,840],[26,1060],[30,2020],[32,2460],[36,2600],[40,2840],[47,3000],[49,4180],[55,4240],[60,4460],[65,4680],[70,4880],[77,5020],[84,5400],[88,6460],[93,6600],[96,6800],[100,6980],[108,7260],[112,8160],[116,8420],[119,8620],[126,8840],[130,9200],[134,9440]]},"ns-discovery-inspect-001":{"text":"I enlarged the screenshot, returned it to normal size, then enlarged it again. Every gesture and inch of distance became evidence in a trial whose witnesses could not speak.","voiceUrl":"voices/chapter-ns/ns-discovery-inspect-001.mp3","durationMs":11112,"cues":[[2,140],[11,220],[15,960],[27,1120],[36,2080],[39,2460],[42,2580],[49,2720],[55,3060],[60,3480],[69,3840],[72,4380],[79,4500],[85,5700],[93,6060],[97,6620],[102,6940],[105,7160],[114,7300],[121,7760],[130,8200],[133,8620],[135,8740],[141,8860],[147,9260],[157,9520],[163,10120],[167,10300],[173,10600]]},"ns-discovery-inspect-002":{"text":"Repeated inspection created familiarity, not knowledge. The image never changed. My interpretation became more certain simply because I had rehearsed it so many times.","voiceUrl":"voices/chapter-ns/ns-discovery-inspect-002.mp3","durationMs":11832,"cues":[[9,120],[20,620],[28,1360],[41,1820],[45,3020],[56,3260],[60,4360],[66,4480],[72,4940],[81,5240],[84,6360],[99,6520],[106,7440],[111,7860],[119,8180],[126,8720],[134,9080],[136,9620],[140,9660],[150,9840],[153,10360],[156,10680],[161,10920],[167,11220]]},"ns-discovery-verdict-001":{"text":"I am not stupid. People hide things because the truth would expose them. Asking will only give her time to make the story sound harmless.","voiceUrl":"voices/chapter-ns/ns-discovery-verdict-001.mp3","durationMs":7584,"cues":[[2,220],[5,300],[9,480],[17,840],[24,1520],[29,1800],[36,2020],[44,2320],[48,2540],[54,2700],[60,3160],[67,3280],[73,3800],[80,4480],[85,4860],[90,5140],[95,5420],[99,5560],[104,5720],[107,6000],[112,6100],[116,6260],[122,6380],[128,6740],[137,7020]]},"ns-discovery-verdict-002":{"text":"A verdict offered relief from not knowing. It also ensured that every answer would arrive already classified as confession, excuse, or lie. Certainty protected the wound by closing the door to information.","voiceUrl":"voices/chapter-ns/ns-discovery-verdict-002.mp3","durationMs":13920,"cues":[[2,100],[10,240],[18,880],[25,1200],[30,1860],[34,2040],[43,2240],[46,3340],[51,3480],[59,3720],[64,4059],[70,4300],[77,4660],[83,4960],[90,5100],[98,5600],[109,6040],[112,6680],[124,6820],[132,7820],[135,8940],[140,9140],[150,10540],[160,11040],[164,11520],[170,11640],[173,11980],[181,12180],[185,12580],[190,12720],[193,13000],[205,13120]]},"ns-discovery-join":{"text":"However I held the phone, three facts remained: Nadiah had gone to USS, the private story did not include me, and she appeared beside a man with whom Aisyah said she had history. Everything else still required a conversation.","voiceUrl":"voices/chapter-ns/ns-discovery-join.mp3","durationMs":15984,"cues":[[8,120],[10,660],[15,760],[19,980],[26,1100],[32,1860],[38,2180],[48,2680],[55,3860],[59,4320],[64,4480],[67,4660],[72,4820],[76,6080],[84,6180],[90,6620],[94,7040],[98,7240],[106,7600],[110,8080],[114,8940],[118,9100],[127,9240],[134,9620],[136,9960],[140,10060],[145,10360],[150,10520],[157,10840],[162,11240],[166,11840],[170,12000],[179,12180],[190,13600],[195,13980],[201,14260],[210,14500],[212,14960],[225,15040]]},"ns-039":{"text":"Shock moved through my body before thought could organise it. My throat tightened. Heat climbed beneath my uniform. I wanted to cry in front of everyone and wanted even more fiercely not to be seen crying.","voiceUrl":"voices/chapter-ns/ns-039.mp3","durationMs":13992,"cues":[[6,160],[12,660],[20,1080],[23,1300],[28,1480],[35,1740],[43,2100],[49,2500],[58,2680],[62,3140],[65,4160],[72,4320],[83,4860],[88,6020],[96,6520],[104,7000],[107,7300],[116,7500],[118,8680],[125,8780],[128,9120],[132,9280],[135,9600],[141,9740],[144,9920],[153,10120],[157,10560],[164,10760],[169,11180],[174,11420],[183,11680],[187,12320],[190,12780],[193,12900],[198,13080],[205,13380]]},"ns-040":{"text":"Not here. Breathe. Put the phone down. Finish what you need to finish, then talk when you can form a sentence.","voiceUrl":"voices/chapter-ns/ns-040.mp3","durationMs":7824,"cues":[[4,120],[10,360],[19,1480],[23,2560],[27,2740],[33,2840],[39,3120],[46,3860],[51,4120],[55,4280],[60,4360],[63,4500],[71,4620],[76,5300],[81,5520],[86,5840],[90,5960],[94,6040],[99,6280],[101,6720],[110,6880]]},"ns-041":{"text":"I waited a few hours. Calming down did not make me neutral; it only gave my hurt a quieter voice. When I finally messaged Nadiah, restraint and accusation travelled together in every line.","voiceUrl":"voices/chapter-ns/ns-041.mp3","durationMs":14712,"cues":[[2,140],[9,240],[11,620],[15,740],[22,980],[30,2120],[35,2500],[39,2840],[43,3020],[48,3300],[51,3500],[60,3700],[63,4640],[68,4780],[73,5040],[76,5280],[81,5580],[83,6220],[91,6320],[98,6840],[103,8220],[105,8400],[113,8540],[122,8980],[130,9720],[140,10580],[144,11460],[155,11820],[165,12560],[174,12960],[177,13620],[183,13900],[188,14260]]},"ns-042":{"text":"Aisyah sent me your Close Friends story. I didn't know you were at USS, and I saw who you were with. I need you to tell me what is happening.","voiceUrl":"voices/chapter-ns/ns-042.mp3","durationMs":10392,"cues":[[7,140],[12,440],[15,640],[20,840],[26,1300],[34,1860],[41,2560],[43,3620],[50,3660],[55,3860],[59,4019],[64,4100],[67,4180],[72,4340],[76,5420],[78,5600],[82,5740],[86,6160],[90,6340],[95,6440],[101,6620],[103,7680],[108,7860],[112,8140],[115,8220],[120,8340],[123,8560],[128,9040],[131,9420],[141,9600]]},"ns-043":{"text":"I should have told you I was going, and I should have spoken about him before you had to see anything through somebody else. I understand why this hurt you.","voiceUrl":"voices/chapter-ns/ns-043.mp3","durationMs":12792,"cues":[[2,1460],[9,1580],[14,1760],[19,2000],[23,2400],[25,2620],[29,2700],[36,2980],[40,4380],[42,4600],[49,4720],[54,4880],[61,5140],[67,5580],[71,5920],[78,6200],[82,6640],[86,6780],[89,7000],[93,7160],[102,7460],[110,8000],[119,8260],[125,8760],[127,10700],[138,10820],[142,11520],[147,11740],[152,11960],[156,12280]]},"ns-confrontation-couple-001":{"text":"When we called ourselves a couple, did that mean the same thing to you? Was I the only one treating this as exclusive?","voiceUrl":"voices/chapter-ns/ns-confrontation-couple-001.mp3","durationMs":6552,"cues":[[5,120],[8,300],[15,460],[25,660],[27,1040],[35,1120],[39,1840],[44,1980],[49,2180],[53,2360],[58,2500],[64,2740],[67,2940],[72,3080],[76,3800],[78,4200],[82,4240],[87,4380],[91,4640],[100,4780],[105,5080],[108,5320],[118,5540]]},"ns-confrontation-couple-002":{"text":"I cared about us and I called us a couple too. We should have defined what that meant instead of assuming. My feelings elsewhere were unresolved, and I was not clear with you.","voiceUrl":"voices/chapter-ns/ns-confrontation-couple-002.mp3","durationMs":11904,"cues":[[2,300],[8,360],[14,640],[17,960],[21,1920],[23,2160],[30,2200],[33,2440],[35,2600],[42,2720],[47,3180],[50,4019],[57,4180],[62,4340],[70,4500],[75,4960],[80,5120],[86,5340],[94,5780],[97,6200],[107,6320],[110,7560],[119,7740],[129,8280],[134,8760],[146,8960],[150,9880],[152,10120],[156,10200],[160,10440],[166,10780],[171,11080],[175,11320]]},"ns-confrontation-waiting-001":{"text":"Were you waiting for him to decide while I stayed beside you? Was I here only because he had not confirmed what he felt?","voiceUrl":"voices/chapter-ns/ns-confrontation-waiting-001.mp3","durationMs":7344,"cues":[[5,120],[9,320],[17,600],[21,1000],[25,1140],[28,1300],[35,1420],[41,1840],[43,2080],[50,2260],[57,2480],[62,2940],[66,3780],[68,4019],[73,4180],[78,4760],[86,5060],[89,5480],[93,5700],[97,5880],[107,6060],[112,6540],[115,6700],[120,6920]]},"ns-confrontation-waiting-002":{"text":"I did not begin this with a plan to use you. But he was my first love, and I had not resolved those feelings. I should have told you before we became this close.","voiceUrl":"voices/chapter-ns/ns-confrontation-waiting-002.mp3","durationMs":13344,"cues":[[2,240],[6,360],[10,540],[16,780],[21,1160],[26,1400],[28,1560],[33,1680],[36,2040],[40,2260],[45,2600],[49,3880],[52,4320],[56,4480],[59,4720],[65,4960],[71,5340],[75,6460],[77,6680],[81,6780],[85,7000],[94,7280],[100,7760],[110,8039],[112,9960],[119,10080],[124,10300],[129,10500],[133,10880],[140,11380],[143,11800],[150,11960],[155,12400],[161,12680]]},"ns-confrontation-disclosure-001":{"text":"Why did Aisyah have to show me? Why wasn't I trusted with something that directly affected what I thought our relationship was?","voiceUrl":"voices/chapter-ns/ns-confrontation-disclosure-001.mp3","durationMs":6384,"cues":[[4,100],[8,300],[15,500],[20,800],[23,980],[28,1140],[32,1400],[36,2140],[43,2320],[45,2780],[53,2800],[58,3120],[68,3260],[73,3580],[82,3720],[91,4160],[96,4640],[98,4820],[106,4960],[110,5400],[123,5500],[127,6020]]},"ns-confrontation-disclosure-002":{"text":"You should have heard it from me. I avoided a difficult conversation until the silence became more hurtful than the truth. I am sorry for making you discover it this way.","voiceUrl":"voices/chapter-ns/ns-confrontation-disclosure-002.mp3","durationMs":14400,"cues":[[4,180],[11,340],[16,500],[22,660],[25,880],[30,1060],[34,1300],[36,3440],[44,3560],[46,4059],[56,4180],[69,4800],[75,5680],[79,6100],[87,6300],[94,6920],[99,7340],[107,7620],[112,8320],[116,8520],[123,8700],[125,10840],[128,10940],[134,11200],[138,11700],[145,11900],[149,12340],[158,12480],[161,13140],[166,13560],[170,13880]]},"ns-confrontation-join":{"text":"Across the conversation, Nadiah acknowledged the central history: the other man was her first love. When she and I started talking, his feelings had not been confirmed, while her own attachment to him remained unresolved.","voiceUrl":"voices/chapter-ns/ns-confrontation-join.mp3","durationMs":14160,"cues":[[7,180],[11,580],[25,700],[32,1500],[45,1960],[49,2800],[57,3000],[66,3440],[70,4540],[76,4660],[80,4880],[84,5220],[88,5460],[94,5680],[100,6000],[105,7040],[109,7240],[113,7380],[115,7600],[123,7720],[132,8060],[136,8460],[145,8680],[149,9080],[153,9220],[158,9440],[169,9640],[175,10740],[179,11020],[183,11260],[194,11460],[197,12040],[201,12160],[210,12440],[221,13320]]},"ns-044":{"text":"She did not give me the exact sentence, You were my backup. That was the meaning I made from the order of events: he was the person she wanted first, his uncertainty created space, and I had occupied it temporarily.","voiceUrl":"voices/chapter-ns/ns-044.mp3","durationMs":15504,"cues":[[4,260],[8,440],[12,600],[17,860],[20,1040],[24,1200],[30,1320],[40,1840],[44,3120],[49,3320],[52,3600],[60,3840],[65,5080],[69,5300],[73,5500],[81,5620],[83,6040],[88,6140],[93,6380],[97,6560],[103,6760],[106,7040],[114,7180],[117,8320],[121,8480],[125,8660],[132,8780],[136,9260],[143,9460],[150,9840],[154,10660],[166,11000],[174,11780],[181,12300],[185,13140],[187,13560],[191,13640],[200,13900],[203,14420],[215,14580]]},"ns-045":{"text":"So I was never the main choice. I was the safe answer while you waited for the answer you actually wanted.","voiceUrl":"voices/chapter-ns/ns-045.mp3","durationMs":6864,"cues":[[3,200],[5,880],[9,960],[15,1100],[19,1300],[24,1400],[32,1600],[34,2620],[38,2720],[42,3180],[47,3320],[54,3600],[60,4280],[64,4540],[71,4660],[75,4940],[79,5060],[86,5200],[90,5760],[99,5980],[106,6400]]},"ns-046":{"text":"I understand why it feels that way. I did care for you. I also handled my uncertainty badly, and saying I cared does not undo what that cost you.","voiceUrl":"voices/chapter-ns/ns-046.mp3","durationMs":13344,"cues":[[2,280],[13,380],[17,1000],[20,1160],[26,1320],[31,1640],[36,1880],[38,3180],[42,3360],[47,3660],[51,3940],[56,4160],[58,6100],[63,6260],[71,6680],[74,7180],[86,7360],[93,8100],[97,9380],[104,9720],[106,10100],[112,10280],[117,10900],[121,11220],[126,11580],[131,12020],[136,12220],[141,12480],[145,13000]]},"ns-047":{"text":"Her answer did not fit the clean categories I needed. Care and harm could exist in the same history. A person could be confused rather than calculating and still make choices that left somebody else devastated.","voiceUrl":"voices/chapter-ns/ns-047.mp3","durationMs":14640,"cues":[[4,140],[11,360],[15,860],[19,1020],[23,1300],[27,1520],[33,1660],[44,2120],[46,2860],[54,2980],[59,4380],[63,4900],[68,5240],[74,5860],[80,6020],[83,6520],[87,6620],[92,6740],[101,7020],[103,8360],[110,8440],[116,8880],[119,9080],[128,9300],[135,10060],[140,10380],[152,10660],[156,11400],[162,11640],[167,11880],[175,12120],[180,12620],[185,12800],[194,13100],[199,13500],[210,13840]]},"ns-048":{"text":"But that night, nuance felt like an attempt to reduce the injury. The image of the woman I believed I knew collapsed, and I treated the collapse as proof that the image had been deliberately constructed for me.","voiceUrl":"voices/chapter-ns/ns-048.mp3","durationMs":14064,"cues":[[4,100],[9,260],[16,520],[23,1460],[28,2320],[33,2540],[36,2760],[44,2880],[47,3400],[54,3520],[58,4019],[66,4160],[70,5200],[76,5360],[79,5740],[83,5860],[89,6020],[91,6480],[100,6580],[102,7180],[107,7320],[118,7800],[122,8820],[124,9040],[132,9160],[136,9480],[145,9640],[148,10280],[154,10540],[159,11040],[163,11180],[169,11400],[173,11940],[178,12100],[191,12320],[203,12960],[207,13620],[210,13820]]},"ns-049":{"text":"All Malay girls will turn out like this. Different face, same ending. I was stupid to believe she was different.","voiceUrl":"voices/chapter-ns/ns-049.mp3","durationMs":7200,"cues":[[4,180],[10,440],[16,800],[21,1100],[26,1240],[30,1440],[35,1600],[41,1820],[51,2640],[57,2980],[62,3860],[70,4160],[72,5160],[76,5240],[83,5460],[86,5740],[94,5860],[98,6200],[102,6320],[112,6480]]},"ns-050":{"text":"That thought was prejudice, not revelation. Nadiah's choices belonged to Nadiah. My pain deepened an unfair generalisation that had begun years earlier; it did not transform the generalisation into evidence about Malay women.","voiceUrl":"voices/chapter-ns/ns-050.mp3","durationMs":16464,"cues":[[5,200],[13,380],[17,660],[28,900],[32,1820],[44,2120],[53,3580],[61,4140],[70,4600],[73,5160],[81,5340],[84,6480],[89,6800],[98,7220],[101,8060],[108,8360],[123,9020],[128,9940],[132,10060],[138,10200],[144,10680],[153,11140],[156,12260],[160,12360],[164,12520],[174,12760],[178,13320],[193,13480],[198,14400],[207,14760],[213,15300],[219,15600],[225,16020]]},"ns-051":{"text":"I cried for days—sometimes openly, more often when the room was dark enough to hide the effort of holding myself together. Sleep arrived late and released me early. Ordinary notifications could pull my stomach tight.","voiceUrl":"voices/chapter-ns/ns-051.mp3","durationMs":14160,"cues":[[2,180],[8,280],[12,580],[17,720],[27,1620],[35,2220],[40,3260],[46,3480],[51,3800],[55,3940],[60,4059],[64,4280],[69,4440],[76,4720],[79,4980],[84,5080],[88,5280],[95,5420],[98,5680],[106,5800],[113,6120],[123,6500],[129,7500],[137,8039],[142,8660],[146,9220],[155,9400],[158,9860],[165,10100],[174,11360],[188,11820],[194,12580],[199,12760],[202,12980],[210,13220],[216,13680]]},"ns-052":{"text":"My family supported me without having a solution. Food appeared near me. Somebody stayed at the table when conversation was impossible. Their concern could not shorten grief, but it kept grief from becoming the only presence in the house.","voiceUrl":"voices/chapter-ns/ns-052.mp3","durationMs":15192,"cues":[[3,120],[10,300],[20,680],[23,1180],[31,1340],[38,1780],[40,2020],[50,2120],[55,3400],[64,3940],[69,4300],[73,4500],[82,5460],[89,5960],[92,6220],[96,6320],[102,6460],[107,6860],[120,7120],[124,7840],[136,8080],[142,9360],[150,9560],[156,10160],[160,10320],[168,10600],[175,11060],[179,11740],[182,11880],[187,12060],[193,12340],[198,12640],[207,12800],[211,13220],[216,13460],[225,13840],[228,14480],[232,14580],[238,14700]]},"ns-053":{"text":"I know everyone is trying. I just cannot switch this off because the day has moved on. Everything I believed about us keeps replaying with a different meaning.","voiceUrl":"voices/chapter-ns/ns-053.mp3","durationMs":9432,"cues":[[2,220],[7,340],[16,660],[19,980],[27,1120],[29,1900],[34,2000],[41,2280],[48,2680],[53,2920],[57,3100],[65,3340],[69,3660],[73,3820],[77,4280],[83,4540],[87,4880],[98,5640],[100,6060],[109,6160],[115,6520],[118,6780],[124,7240],[134,7580],[139,8220],[141,8360],[151,8480],[159,8820]]},"ns-054":{"text":"Service continued. Timetables did not pause to recognise heartbreak. I returned to camp, completed tasks, answered when called, and discovered that a person can function reliably while feeling absent from his own life.","voiceUrl":"voices/chapter-ns/ns-054.mp3","durationMs":13824,"cues":[[8,120],[19,500],[30,1520],[34,2240],[38,2380],[44,2620],[47,3040],[57,3160],[69,3800],[71,5520],[80,5600],[83,6160],[89,6320],[99,6920],[106,7400],[115,8240],[120,8540],[128,8760],[132,9580],[143,9680],[148,10100],[150,10220],[157,10320],[161,10680],[170,10860],[179,11260],[185,11900],[193,12100],[200,12480],[205,12880],[209,13020],[213,13160],[218,13360]]},"ns-055":{"text":"The practical lesson should have been about clarity: define a relationship, ask about unresolved attachments, and leave when trust cannot be rebuilt. Instead, I wrote a broader and more damaging rule.","voiceUrl":"voices/chapter-ns/ns-055.mp3","durationMs":15024,"cues":[[4,80],[14,200],[21,740],[28,1240],[33,1400],[38,1500],[44,1700],[53,2060],[60,3340],[62,3900],[76,3980],[80,5240],[86,5700],[97,6000],[110,6520],[114,7600],[120,7800],[125,8480],[131,8700],[138,9140],[141,9480],[150,9640],[159,11020],[161,12120],[167,12200],[169,12500],[177,12640],[181,13380],[186,13640],[195,13940],[200,14560]]},"ns-056":{"text":"No more. I cannot trust Malay girls. If I never let another one close, this cannot happen to me again.","voiceUrl":"voices/chapter-ns/ns-056.mp3","durationMs":5904,"cues":[[3,240],[9,420],[11,1120],[18,1260],[24,1760],[30,2140],[37,2420],[40,3160],[42,3280],[48,3420],[52,3640],[60,3800],[64,4040],[71,4180],[76,4520],[83,4740],[90,5080],[93,5340],[96,5420],[102,5540]]},"ns-057":{"text":"Avoidance promised safety by turning ethnicity into a warning label. It also prevented any future person from being encountered as herself. I did not recognise the cost because withdrawal felt like the first decision I controlled.","voiceUrl":"voices/chapter-ns/ns-057.mp3","durationMs":15672,"cues":[[10,120],[19,1020],[26,1540],[29,2300],[37,2480],[47,2900],[52,3640],[54,3880],[62,4000],[69,4420],[72,5440],[77,5580],[87,5920],[91,6440],[98,6700],[105,7100],[110,7520],[116,7680],[128,7880],[131,8580],[140,8720],[142,10200],[146,10220],[150,10360],[160,10580],[164,11080],[169,11260],[177,12160],[188,12460],[193,13360],[198,13540],[202,13740],[208,13920],[217,14240],[219,14820],[230,14920]]},"ns-058":{"text":"Eventually, Operationally Ready Date arrived. I returned what belonged to the Army, carried out the familiar final procedures, and stepped beyond the gate with civilian time opening in front of me.","voiceUrl":"voices/chapter-ns/ns-058.mp3","durationMs":12552,"cues":[[12,180],[26,1020],[32,1860],[37,2160],[46,2600],[48,3960],[57,4040],[62,4460],[71,4600],[74,5140],[78,5260],[84,5400],[92,5980],[96,6320],[100,6500],[109,6620],[115,7180],[127,7520],[131,8500],[139,8700],[146,9060],[150,9400],[155,9540],[160,10020],[169,10260],[174,10820],[182,11300],[185,11620],[191,11760],[194,11960],[197,12100]]},"ns-059":{"text":"I had served, endured, and completed something demanding. I also left as a single man who believed heartbreak had exposed a truth about an entire community. Strength in one part of life had not corrected fear in another.","voiceUrl":"voices/chapter-ns/ns-059.mp3","durationMs":15600,"cues":[[2,280],[6,360],[14,620],[23,1300],[27,2040],[37,2240],[47,2840],[58,3200],[60,4860],[65,4960],[70,5260],[73,5540],[75,5680],[82,5780],[86,6080],[90,6340],[99,6460],[110,6840],[114,7360],[122,7500],[124,8020],[130,8180],[136,8820],[139,9020],[146,9160],[157,9600],[166,11180],[169,11620],[173,11840],[178,12060],[181,12260],[186,12420],[190,13220],[194,13380],[204,13660],[209,14280],[212,14860],[220,15020]]},"ns-060":{"text":"University waited next. I imagined new subjects, new friends, and a future large enough to leave the relationship behind. I did not yet know that what I carried would announce itself before the first week was over.","voiceUrl":"voices/chapter-ns/ns-060.mp3","durationMs":14064,"cues":[[11,160],[18,860],[24,1220],[26,2300],[35,2360],[39,3060],[49,3320],[53,4200],[62,4400],[66,5320],[68,5440],[75,5540],[81,5980],[88,6280],[91,6540],[97,6640],[101,6900],[114,7020],[122,7680],[124,8860],[128,8940],[132,9100],[136,9340],[141,9580],[146,9940],[151,10080],[153,10400],[161,10460],[167,11020],[176,11180],[183,11560],[190,12040],[194,12320],[200,12460],[205,12840],[209,13420],[214,13640]]},"uni-arrival-001":{"text":"University began in 2018 with orientation names I was still learning and routes I pretended to understand. The campus promised reinvention, as though a new timetable could separate me from everything that had happened before it.","voiceUrl":"voices/chapter-ns/uni-arrival-001.mp3","durationMs":13440,"cues":[[11,160],[17,700],[20,1020],[25,1280],[30,1980],[42,2220],[48,2860],[50,3260],[54,3300],[60,3460],[69,3720],[73,4460],[80,4640],[82,5140],[92,5260],[95,5800],[107,5920],[111,7180],[118,7320],[127,7800],[140,8240],[143,9320],[150,9440],[152,9560],[156,9700],[166,9960],[172,10580],[181,10780],[184,11180],[189,11340],[200,11620],[205,12160],[209,12260],[218,12400],[225,12760],[228,13140]]},"uni-arrival-002":{"text":"Hakim—a pseudonym for a friend I made during orientation—had the easy confidence of somebody who could enter an unfamiliar room and assume he was welcome. During the first club recruitment week, he asked me to visit the Muslim Society.","voiceUrl":"voices/chapter-ns/uni-arrival-002.mp3","durationMs":15264,"cues":[[6,120],[8,1060],[18,1200],[22,1740],[24,1880],[31,1980],[33,2340],[38,2440],[45,2700],[57,3100],[61,4440],[65,4580],[70,4800],[81,5140],[84,5740],[93,5880],[97,6300],[103,6460],[109,6700],[112,6960],[123,7160],[128,7900],[132,8560],[139,8700],[142,9220],[146,9380],[155,9560],[162,10860],[166,11100],[172,11240],[177,11580],[189,11840],[195,12380],[198,12940],[204,13100],[207,13420],[210,13580],[216,13720],[220,14020],[227,14140],[235,14600]]},"uni-arrival-003":{"text":"Come and look around. You don't have to join today. There are seniors, activities, and probably food if we arrive before everybody discovers it.","voiceUrl":"voices/chapter-ns/uni-arrival-003.mp3","durationMs":9120,"cues":[[5,100],[9,240],[14,380],[22,580],[26,1480],[32,1620],[37,1880],[40,2100],[45,2240],[52,2540],[58,3260],[62,3460],[71,3720],[83,4500],[87,5580],[96,5860],[101,6440],[104,6720],[107,6880],[114,7020],[121,7420],[131,7760],[141,8260],[144,8840]]},"uni-arrival-004":{"text":"I don't know. Muslim Society sounds like a room where someone will make me volunteer for three committees before I find the exit.","voiceUrl":"voices/chapter-ns/uni-arrival-004.mp3","durationMs":5760,"cues":[[2,200],[8,260],[14,380],[21,1040],[29,1340],[36,1800],[41,1980],[43,2100],[48,2180],[54,2400],[62,2620],[67,2860],[72,2980],[75,3160],[85,3280],[89,3780],[95,4000],[106,4340],[113,4760],[115,4980],[120,5060],[124,5240],[129,5360]]},"uni-arrival-005":{"text":"I sighed, then followed because I did not want to disappoint a new friend over one brief visit. A lecture theatre had been reserved for the club. Voices and ordinary laughter reached us through the open door.","voiceUrl":"voices/chapter-ns/uni-arrival-005.mp3","durationMs":13344,"cues":[[2,160],[10,280],[15,1120],[24,1420],[32,1820],[34,2280],[38,2380],[42,2540],[47,2800],[50,3020],[61,3140],[63,3680],[67,3780],[74,4000],[79,4360],[83,4700],[89,5000],[96,5520],[98,6860],[106,6960],[114,7320],[118,7660],[123,7820],[132,7980],[136,8520],[140,8640],[146,8760],[153,9720],[157,10300],[166,10600],[175,11100],[183,11600],[186,11980],[194,12220],[198,12440],[203,12580],[208,12900]]},"uni-arrival-006":{"text":"See? No ambush. We walk in, say hello, and leave whenever you want.","voiceUrl":"voices/chapter-ns/uni-arrival-006.mp3","durationMs":5424,"cues":[[5,300],[8,780],[16,1040],[19,1840],[24,2040],[28,2400],[32,2740],[39,2940],[43,3420],[49,3580],[58,3840],[62,4220],[67,4360]]},"uni-arrival-007":{"text":"Inside, volunteers arranged sign-up sheets and shifted chairs. Freshmen stood in uncertain clusters. Several Malay women, some wearing hijab and some not, talked with friends or waited for the programme to begin.","voiceUrl":"voices/chapter-ns/uni-arrival-007.mp3","durationMs":13920,"cues":[[8,140],[19,680],[28,1280],[36,1840],[43,2260],[47,2600],[55,2800],[63,3240],[72,4160],[78,4780],[81,5120],[91,5420],[101,6020],[109,7180],[115,7620],[122,8020],[127,8600],[135,8860],[141,9160],[145,9720],[150,9980],[155,10220],[162,10880],[167,11180],[175,11360],[178,11880],[185,12260],[189,12620],[193,12740],[203,12860],[206,13320],[212,13420]]},"uni-arrival-008":{"text":"Nothing in the room was directed at me. Nobody had accused, cornered, or even approached me. Still, as I crossed the threshold, my body stopped with such force that Hakim took another step before noticing I was behind him.","voiceUrl":"voices/chapter-ns/uni-arrival-008.mp3","durationMs":14640,"cues":[[8,80],[11,440],[15,560],[20,680],[24,920],[33,1100],[36,1520],[40,1660],[47,2820],[51,3180],[60,3320],[70,4260],[73,4780],[78,5000],[89,5360],[93,5980],[100,7220],[103,7640],[105,7820],[113,7960],[117,8500],[128,8640],[131,9860],[136,10020],[144,10360],[149,10700],[154,10940],[160,11240],[165,11600],[171,11720],[176,12200],[184,12340],[189,12680],[196,12920],[205,13220],[207,13700],[211,13780],[218,13920],[222,14280]]},"uni-arrival-009":{"text":"My eyes moved rapidly from face to face. In my perception, red markers seemed to appear above the women, converting strangers into warnings before any of them had spoken.","voiceUrl":"voices/chapter-ns/uni-arrival-009.mp3","durationMs":10800,"cues":[[3,160],[8,400],[14,780],[22,1100],[27,1620],[32,1840],[35,2120],[41,2260],[44,3260],[47,3400],[59,3620],[63,4280],[71,4560],[78,5060],[81,5460],[88,5580],[94,5960],[98,6260],[105,6380],[116,7140],[126,7780],[131,8320],[140,8600],[147,9140],[151,9500],[154,9680],[159,9800],[163,9960],[170,10200]]},"uni-arrival-010":{"text":"She will turn out the same. That one looks suspicious. Don't be fooled because she seems kind. You know how this ends.","voiceUrl":"voices/chapter-ns/uni-arrival-010.mp3","durationMs":8232,"cues":[[4,160],[9,400],[14,600],[18,920],[22,1120],[28,1340],[33,2520],[37,2780],[43,2980],[55,3220],[61,4340],[64,4520],[71,4700],[79,5020],[83,5300],[89,5500],[95,5800],[99,6660],[104,6860],[108,7140],[113,7320],[118,7520]]},"uni-arrival-011":{"text":"Those thoughts were the old prejudice moving at the speed of alarm. They revealed what heartbreak had trained me to expect; they revealed nothing about the women whose faces I was judging.","voiceUrl":"voices/chapter-ns/uni-arrival-011.mp3","durationMs":11664,"cues":[[6,180],[15,540],[20,1000],[24,1160],[28,1300],[38,1580],[45,2180],[48,2520],[52,2620],[58,2800],[61,3040],[68,3140],[73,4320],[82,4500],[87,5020],[98,5260],[102,5840],[110,6060],[113,6480],[116,6720],[124,6860],[129,8160],[138,8320],[146,8820],[152,9440],[156,9640],[162,9780],[168,10100],[174,10360],[176,10820],[180,10900],[188,11100]]},"uni-arrival-threat-scan-details-001":{"text":"Blue chairs. Two doors. Three ceiling lights in this row. One table near the aisle. Keep counting what is actually here.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-details-001.mp3","durationMs":8712,"cues":[[5,200],[13,420],[17,1480],[24,1660],[30,2680],[38,3000],[45,3300],[48,3540],[53,3640],[58,3820],[62,4640],[68,4880],[73,5260],[77,5420],[84,5560],[89,6440],[98,6680],[103,7160],[106,7300],[115,7580],[120,8100]]},"uni-arrival-threat-scan-details-002":{"text":"Concrete details briefly competed with the imagined markers. They did not make me comfortable, but they gave my attention a path that did not pass through somebody else's identity.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-details-002.mp3","durationMs":10704,"cues":[[9,120],[17,600],[25,1120],[34,1560],[39,2120],[43,2240],[52,2340],[61,2840],[66,4140],[70,4240],[74,4400],[79,4600],[82,4780],[95,4960],[99,6100],[104,6200],[109,6320],[112,6540],[122,6660],[124,7060],[129,7180],[134,7720],[138,7880],[142,8020],[147,8280],[155,8620],[164,8880],[171,9360],[180,10040]]},"uni-arrival-threat-scan-exit-001":{"text":"Look at the door. Not at them. Find the corridor, move your feet, and deal with everything else outside.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-exit-001.mp3","durationMs":5832,"cues":[[5,220],[8,340],[12,420],[18,540],[22,1160],[25,1300],[31,1440],[36,2100],[40,2280],[50,2380],[55,3020],[60,3200],[66,3340],[70,3900],[75,4040],[80,4220],[91,4460],[96,4800],[104,5200]]},"uni-arrival-threat-scan-exit-002":{"text":"The exit became a fixed point in a room my attention had made unstable. Looking away interrupted the judgements, though it also made immediate escape feel like the only available answer.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-exit-002.mp3","durationMs":12792,"cues":[[4,100],[9,300],[16,900],[18,1240],[24,1400],[30,1820],[33,2360],[35,2480],[40,2640],[43,3140],[53,3340],[57,3980],[62,4180],[72,4540],[80,6080],[85,6400],[97,6820],[101,7400],[113,7580],[120,8320],[123,8740],[128,8980],[133,9360],[143,9620],[150,10140],[155,10680],[160,10900],[164,11120],[169,11340],[179,11760],[186,12320]]},"uni-arrival-threat-scan-air-001":{"text":"Hakim, sorry. I need some air. I thought I could stay, but I need to step outside now.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-air-001.mp3","durationMs":6792,"cues":[[7,60],[14,1160],[16,2040],[21,2100],[26,2240],[31,2400],[33,3380],[41,3440],[43,3560],[49,3620],[55,3780],[59,4040],[61,4660],[66,4740],[69,4840],[74,4940],[82,5120],[86,6120]]},"uni-arrival-threat-scan-air-002":{"text":"Okay. No problem. I'll come with you, or I can give you space—just tell me what you need.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-air-002.mp3","durationMs":7344,"cues":[[6,200],[9,740],[18,940],[23,1660],[28,1820],[33,2020],[38,2260],[41,2820],[43,3060],[47,3160],[52,3340],[56,3500],[62,3700],[67,4420],[72,4700],[75,4880],[80,5000],[84,5160],[89,5300]]},"uni-arrival-threat-scan-join":{"text":"With effort, I broke my gaze from the crowd. I told Hakim I had something else to do and moved toward the door, concentrating on each step until the lecture theatre released me.","voiceUrl":"voices/chapter-ns/uni-arrival-threat-scan-join.mp3","durationMs":11184,"cues":[[5,100],[13,360],[15,1220],[21,1340],[24,1600],[29,1800],[34,2160],[38,2320],[45,2420],[47,3800],[52,3900],[58,4120],[60,4720],[64,4780],[74,4940],[79,5220],[82,5480],[85,5600],[89,6140],[95,6260],[102,6640],[106,6840],[112,6960],[126,7740],[129,8360],[134,8560],[139,8860],[145,9420],[149,9680],[157,9800],[165,10160],[174,10440],[177,10860]]},"uni-arrival-012":{"text":"In the corridor, I breathed hard. Sweat gathered across my face and beneath my shirt. I leaned away from the doorway, confused by the distance between the ordinary room I had entered and the danger my body had announced.","voiceUrl":"voices/chapter-ns/uni-arrival-012.mp3","durationMs":15192,"cues":[[3,140],[7,220],[17,360],[19,1240],[28,1380],[34,1880],[40,2900],[49,3500],[56,3900],[59,4280],[64,4520],[68,4900],[76,5200],[79,5600],[86,5820],[88,6960],[95,7040],[100,7320],[105,7600],[109,7740],[118,7880],[127,8420],[130,9040],[134,9240],[143,9400],[151,9980],[155,10500],[164,10840],[169,11440],[171,11780],[175,11820],[183,12060],[187,12980],[191,13080],[198,13240],[201,13840],[206,14040],[210,14360],[220,14520]]},"uni-arrival-013":{"text":"Slow down. You are outside. Nobody followed you. Just breathe until your hands stop feeling like this.","voiceUrl":"voices/chapter-ns/uni-arrival-013.mp3","durationMs":8400,"cues":[[5,340],[11,580],[15,1440],[19,1560],[28,1720],[35,3120],[44,3480],[49,3840],[54,5020],[62,5300],[68,5800],[73,6020],[79,6180],[84,6820],[92,7160],[97,7480],[102,7700]]},"uni-arrival-014":{"text":"The physical response was real: the heat, the frozen attention, the urgent need to leave. I will not invent a diagnosis for my younger self from a remembered scene.","voiceUrl":"voices/chapter-ns/uni-arrival-014.mp3","durationMs":11832,"cues":[[4,80],[13,200],[22,700],[26,1300],[32,1520],[36,2160],[42,2340],[46,3040],[53,3220],[64,3740],[68,4560],[75,4780],[80,5320],[83,5720],[90,5880],[92,7280],[97,7340],[101,7500],[108,7920],[110,8300],[120,8400],[124,9180],[127,9320],[135,9520],[140,9900],[145,10460],[147,10680],[158,10780],[164,11360]]},"uni-arrival-015":{"text":"What I can say is that none of those women had harmed me. Nadiah's choices were not theirs. A room of Malay and hijabi women was not evidence that betrayal had gathered in one place.","voiceUrl":"voices/chapter-ns/uni-arrival-015.mp3","durationMs":12552,"cues":[[5,140],[7,340],[11,460],[15,820],[18,1480],[23,1640],[28,1880],[31,2080],[37,2220],[43,2480],[47,2780],[54,2940],[58,3340],[67,4460],[75,4940],[80,5460],[84,5620],[92,5880],[94,7180],[99,7280],[102,7520],[108,7680],[112,8220],[119,8360],[125,8900],[129,9520],[133,9720],[142,10000],[147,10420],[156,10540],[160,11040],[169,11240],[172,11580],[176,11740],[182,11980]]},"uni-arrival-016":{"text":"My alarm deserved attention because I was suffering. Its verdict did not deserve obedience because it accused strangers. Learning to hold both truths would become part of the wild ride ahead.","voiceUrl":"voices/chapter-ns/uni-arrival-016.mp3","durationMs":14472,"cues":[[3,120],[9,320],[18,700],[28,1100],[36,1620],[38,2340],[42,2460],[53,2640],[57,3940],[65,4180],[69,4940],[73,5120],[81,5320],[91,5700],[99,6860],[102,7300],[110,7420],[121,8080],[130,9580],[133,9920],[138,10040],[143,10380],[150,10820],[156,11500],[163,11680],[168,12140],[171,12360],[175,12500],[180,12680],[185,13220],[191,13940]]},"uni-arrival-017":{"text":"What was that?","voiceUrl":"voices/chapter-ns/uni-arrival-017.mp3","durationMs":1512,"cues":[[5,400],[9,640],[14,820]]},"uni-arrival-end":{"text":"University had barely begun. I kept moving through it, carrying that unanswered question with me. By my second year, I knew the routes well enough to show somebody else the way.","voiceUrl":"voices/chapter-ns/uni-arrival-end.mp3","durationMs":11040,"cues":[[11,160],[15,780],[22,960],[29,1280],[31,2680],[36,2760],[43,3040],[51,3460],[55,3700],[64,4260],[69,4720],[80,5060],[89,5600],[94,6040],[98,6200],[101,7160],[104,7320],[111,7500],[117,7820],[119,8300],[124,8400],[128,8620],[135,8720],[140,9020],[147,9180],[150,9420],[155,9540],[164,9760],[169,10100],[173,10380],[177,10480]]},"ch6-001":{"text":"By my second year at university, I could stand in front of an orientation group and sound as if I knew what I was doing. I had a list of names, an overworked voice, and responsibility for people who still looked at every building as though it might be the wrong one.","voiceUrl":"voices/chapter-6/ch6-001.mp3","durationMs":15192,"cues":[[3,300],[6,460],[13,620],[18,920],[21,1080],[33,1280],[35,2220],[41,2260],[47,2440],[50,2680],[56,2840],[59,3020],[62,3100],[74,3300],[80,3940],[84,4740],[90,4920],[93,5260],[96,5380],[98,5540],[103,5620],[108,5740],[110,5920],[114,6000],[121,6160],[123,7400],[127,7440],[129,7580],[134,7660],[137,7880],[144,8020],[147,8720],[158,8940],[165,9600],[169,10160],[184,10280],[188,11140],[195,11280],[199,11620],[205,11840],[212,12100],[215,12360],[221,12580],[230,12940],[233,13600],[240,13760],[243,13880],[249,14000],[252,14200],[256,14360],[262,14460],[266,14800]]},"ch6-002":{"text":"I had also brought my old rules with me. With Malay girls, I kept conversations safely practical. Directions, group work, nothing that might become a crush. I called it knowing my type. Really, I was still arranging my life around the fear of being hurt in a familiar way.","voiceUrl":"voices/chapter-6/ch6-002.mp3","durationMs":19512,"cues":[[2,200],[6,280],[11,500],[19,860],[22,1220],[26,1520],[32,1880],[37,2300],[41,2500],[46,3520],[52,3800],[59,4200],[61,4840],[66,4960],[80,5200],[87,6060],[98,6540],[110,7540],[116,8360],[122,8660],[130,9020],[135,9440],[141,9620],[148,9960],[150,10280],[157,10400],[159,11620],[166,11740],[169,12040],[177,12600],[180,13120],[186,13440],[194,14620],[196,15120],[200,15220],[206,15440],[216,15680],[219,16120],[224,16320],[231,16640],[235,16880],[240,17060],[243,17280],[249,17440],[254,17800],[257,18260],[259,18440],[268,18620],[272,19140]]},"ch6-003":{"text":"Jia Wen stood near the front of my group, a Chinese freshie with a small backpack and a face I kept accidentally checking for a smile. She was short enough that somebody behind her could read my clipboard over her head. Very cute, I thought, then reminded myself to take attendance.","voiceUrl":"voices/chapter-6/ch6-003.mp3","durationMs":17280,"cues":[[4,220],[8,540],[14,1020],[19,1240],[23,1380],[29,1500],[32,1700],[35,1800],[42,2000],[44,2760],[52,2860],[60,3340],[65,3760],[67,3900],[73,4000],[82,4280],[86,4820],[88,4920],[93,5040],[95,5400],[100,5520],[113,5900],[122,6520],[126,6940],[128,7060],[135,7200],[139,8480],[143,8580],[149,8740],[156,8980],[161,9280],[170,9500],[177,9880],[181,10320],[187,10520],[192,10740],[195,10980],[205,11180],[210,11720],[214,11920],[220,12080],[225,13100],[231,13420],[233,14080],[242,14180],[247,15040],[256,15340],[263,15840],[266,16260],[271,16400],[282,16580]]},"ch6-004":{"text":"You already called my name. Twice. Am I supposed to attend twice also?","voiceUrl":"voices/chapter-6/ch6-004.mp3","durationMs":5760,"cues":[[4,300],[12,520],[19,1020],[22,1300],[28,1500],[35,2300],[38,3240],[40,3440],[49,3540],[52,3960],[59,4100],[65,4540],[70,5020]]},"ch6-005":{"text":"Just making sure the group is complete. Very thorough leadership.","voiceUrl":"voices/chapter-6/ch6-005.mp3","durationMs":3264,"cues":[[5,100],[12,320],[17,560],[21,700],[27,800],[30,980],[40,1080],[45,1960],[54,2420],[65,2760]]},"ch6-006":{"text":"Wah. Then later you better count us properly. I don't want to get left at the wrong faculty.","voiceUrl":"voices/chapter-6/ch6-006.mp3","durationMs":7920,"cues":[[5,160],[10,860],[16,1060],[20,1540],[27,1700],[33,2060],[36,2400],[46,2660],[48,3760],[54,3840],[59,4040],[62,4220],[66,4360],[71,4620],[74,5000],[78,5160],[84,5320],[92,5720]]},"ch6-007":{"text":"She said it without the careful politeness of somebody meeting a senior. I laughed, and after that talking to her felt strangely easy. She asked actual questions instead of nodding at my explanations, and caught me when I pointed confidently in a direction I then had to correct.","voiceUrl":"voices/chapter-6/ch6-007.mp3","durationMs":18000,"cues":[[4,340],[9,540],[12,740],[20,860],[24,1300],[32,1420],[43,1780],[46,2280],[55,2420],[63,2800],[65,3100],[73,3240],[75,4460],[84,4580],[88,5620],[94,5820],[99,6080],[107,6380],[110,6780],[114,6900],[119,7140],[129,7620],[135,8380],[139,9540],[145,9760],[152,10200],[162,10620],[170,11280],[173,11660],[181,11840],[184,12220],[187,12340],[201,12540],[205,13320],[212,13880],[215,14160],[220,14360],[222,14560],[230,14700],[242,15100],[245,15780],[247,15900],[257,16000],[259,16600],[264,16740],[268,17060],[271,17260],[279,17380]]},"ch6-008":{"text":"When orientation ended, the group chat grew quieter. Ours did the opposite. A question about where to find a tutorial room became a complaint about lunch, then a photograph of a queue, then a conversation that wandered past midnight without either of us announcing that we were staying.","voiceUrl":"voices/chapter-6/ch6-008.mp3","durationMs":17520,"cues":[[5,180],[17,380],[24,1040],[28,1680],[34,1820],[39,2080],[44,2420],[53,2720],[58,4120],[62,4740],[66,4860],[76,4980],[78,6340],[87,6440],[93,6920],[99,7180],[102,7340],[107,7460],[109,7680],[118,7760],[123,8320],[130,8740],[132,9000],[142,9080],[148,9480],[155,9760],[160,10700],[162,10860],[173,10920],[176,11460],[178,11560],[185,11700],[190,12580],[192,12880],[205,12980],[210,13600],[219,13800],[224,14200],[233,14540],[241,15160],[248,15540],[251,15780],[254,15900],[265,16059],[270,16500],[273,16660],[278,16780],[286,16940]]},"ch6-chat":{"text":"I would say I was going to sleep, put the phone down, and reach for it when it lit up again. She did the same. Our goodnights became negotiations neither of us was particularly determined to finish. The next morning, I could be tired in a lecture and still smile when she sent a complaint about hers.","voiceUrl":"voices/chapter-6/ch6-chat.mp3","durationMs":18312,"cues":[[2,140],[8,200],[12,380],[14,560],[18,640],[24,800],[27,1000],[34,1180],[38,1780],[42,1920],[48,2020],[54,2320],[58,2680],[64,2880],[68,3180],[71,3380],[76,3540],[79,3700],[83,3840],[86,4040],[93,4180],[97,5300],[101,5500],[105,5680],[111,5820],[115,6920],[126,7140],[133,7640],[146,7960],[154,8900],[157,9300],[160,9480],[164,9740],[177,9960],[188,10720],[191,11280],[199,11440],[203,13020],[208,13100],[217,13400],[219,13880],[225,13960],[228,14120],[234,14320],[237,14720],[239,14860],[247,14960],[251,15340],[257,15580],[263,15900],[268,16360],[272,16600],[277,16840],[279,17040],[289,17120],[295,17580],[300,17820]]},"ch6-009":{"text":"What time you finish tomorrow? I have this horrible gap between classes. Too short to go back, too long to pretend I'm being productive.","voiceUrl":"voices/chapter-6/ch6-009.mp3","durationMs":8952,"cues":[[5,80],[10,260],[14,480],[21,620],[31,1020],[33,1940],[38,2020],[43,2220],[52,2540],[56,3180],[64,3440],[73,3840],[77,4820],[83,5100],[86,5420],[89,5520],[95,5720],[99,6340],[104,6640],[107,6980],[115,7100],[119,7680],[125,7860],[136,8100]]},"ch6-010":{"text":"Send me your timetable. We can compare suffering.","voiceUrl":"voices/chapter-6/ch6-010.mp3","durationMs":2232,"cues":[[5,120],[8,280],[13,380],[24,520],[27,1160],[31,1260],[39,1400],[49,1740]]},"ch6-011":{"text":"Soon I knew her free afternoons better than my own assignment deadlines. We compared timetables before committing to other plans, chose lunch around whichever of us finished later, and found study spaces near the other's next class. It was never only me adjusting. She waited for me too, and those small decisions mattered enormously.","voiceUrl":"voices/chapter-6/ch6-011.mp3","durationMs":21504,"cues":[[5,180],[7,960],[12,1040],[16,1200],[21,1360],[32,1600],[39,2200],[44,2440],[47,2580],[51,2760],[62,2900],[73,3440],[76,4980],[85,5080],[96,5500],[103,6180],[114,6500],[117,6860],[123,6980],[130,7180],[136,8039],[142,8320],[149,8600],[159,8920],[162,9320],[165,9460],[174,9660],[181,10060],[185,10860],[191,10980],[197,11300],[204,11600],[209,12100],[213,12280],[221,12400],[226,12700],[233,13040],[236,14460],[240,14580],[246,14760],[251,15120],[254,15460],[265,15660],[269,16920],[276,17060],[280,17380],[283,17500],[288,17720],[292,18740],[298,18860],[304,19140],[314,19480],[323,20120],[334,20600]]},"ch6-012":{"text":"I saved you the seat with the plug. Please appreciate this. People were eyeing it.","voiceUrl":"voices/chapter-6/ch6-012.mp3","durationMs":5592,"cues":[[2,140],[8,300],[12,600],[16,740],[21,940],[26,1200],[30,1420],[36,1540],[43,2340],[54,2740],[60,3380],[67,4000],[72,4500],[79,4760],[82,5160]]},"ch6-013":{"text":"She pushed a drink towards me without stopping her typing. I put my bag down beside hers and felt the day's noise settle. We could work quietly for an hour, then lose another twenty minutes to something neither of us would remember the next morning. I began looking forward to nothing in particular, as long as it involved her.","voiceUrl":"voices/chapter-6/ch6-013.mp3","durationMs":19272,"cues":[[4,120],[11,260],[13,560],[19,640],[27,960],[30,1320],[38,1440],[47,1780],[51,2080],[59,2220],[61,3400],[65,3500],[68,3660],[72,3800],[77,4059],[84,4260],[89,4620],[93,5200],[98,5320],[102,5500],[108,5620],[114,5940],[122,6580],[125,7880],[131,7960],[136,8119],[144,8380],[148,8880],[151,9000],[157,9160],[162,10060],[167,10300],[175,10540],[182,10880],[190,11180],[193,11540],[203,11640],[211,12000],[214,12340],[217,12460],[223,12620],[232,12780],[236,13180],[241,13280],[250,13560],[252,14960],[258,15020],[266,15380],[274,15680],[277,16020],[285,16120],[288,16400],[300,16500],[303,17740],[308,17880],[311,18040],[314,18160],[323,18280],[327,18780]]},"ch6-study-break":{"text":"Once, I arrived annoyed with myself after a class and opened my laptop much harder than necessary. She waited until I had finished pretending to work, then nudged my drink closer. I told her what had happened. She listened, asked one useful question, and stayed until I could laugh about the way I had slammed the lid.","voiceUrl":"voices/chapter-6/ch6-study-break.mp3","durationMs":22872,"cues":[[6,180],[8,940],[16,1040],[24,1420],[29,1800],[36,1980],[42,2440],[44,2660],[50,2780],[54,3540],[61,3800],[64,4180],[71,4380],[76,4920],[83,5200],[88,5760],[99,5940],[103,7600],[110,7780],[116,8160],[118,8540],[122,8600],[131,8800],[142,9260],[145,9900],[151,10060],[156,10860],[163,11100],[166,11560],[172,11780],[180,12160],[182,13820],[187,13920],[191,14100],[196,14200],[200,14320],[210,14460],[214,15660],[224,15860],[230,16660],[234,17280],[241,17660],[251,18020],[255,19220],[262,19440],[268,19820],[270,20160],[276,20240],[282,20440],[288,20740],[292,21000],[296,21120],[298,21360],[302,21420],[310,21680],[314,22220],[318,22380]]},"ch6-014":{"text":"People noticed. Somebody would ask where my girlfriend was when I arrived alone; somebody else would tell Jia Wen to ask her boyfriend for help. The joke travelled beyond our original orientation group. Every time we appeared together, another person seemed to nod as if a rumour had just been confirmed.","voiceUrl":"voices/chapter-6/ch6-014.mp3","durationMs":18960,"cues":[[7,100],[16,440],[25,1540],[31,1880],[35,2060],[41,2280],[44,2480],[55,2660],[59,3200],[64,3500],[66,3740],[74,3780],[81,4200],[90,5100],[95,5460],[101,5800],[106,5980],[110,6260],[114,6520],[117,6860],[121,7020],[125,7220],[135,7400],[139,7920],[145,8060],[149,9020],[154,9180],[164,9520],[171,9920],[175,10340],[184,10700],[196,11300],[203,12040],[209,13040],[214,13260],[217,13480],[226,13600],[236,13940],[244,14800],[251,15160],[258,15540],[261,15900],[265,16059],[268,16740],[271,16880],[273,17000],[280,17120],[284,17500],[289,17680],[294,17960],[304,18160]]},"ch6-015":{"text":"We're friends lah. You all see two people eating lunch and immediately start planning a wedding.","voiceUrl":"voices/chapter-6/ch6-015.mp3","durationMs":6624,"cues":[[6,160],[14,400],[19,820],[23,1700],[27,1800],[31,2040],[35,2320],[42,2580],[49,3020],[55,3380],[59,4000],[71,4200],[77,4940],[86,5220],[88,5680],[96,5780]]},"ch6-016":{"text":"I laughed along. The word friends should have registered more clearly than the teasing around it. Instead, I carried the teasing home. If everybody could see something between us, surely there was something to see. I told myself she was simply embarrassed to admit it in front of everyone.","voiceUrl":"voices/chapter-6/ch6-016.mp3","durationMs":18792,"cues":[[2,300],[10,380],[17,680],[21,1780],[26,1900],[34,2280],[41,3340],[46,3500],[57,3660],[62,4180],[70,4440],[75,4920],[79,5100],[87,5300],[94,5760],[98,6120],[107,7080],[109,7540],[117,7640],[121,7920],[129,8060],[135,8440],[138,9700],[148,9840],[154,10380],[158,10620],[168,10880],[176,11300],[180,11740],[187,12200],[193,12720],[197,12940],[207,13140],[210,13520],[215,13700],[217,15020],[222,15100],[229,15320],[233,15760],[237,15920],[244,16059],[256,16379],[259,17120],[265,17280],[268,17600],[271,17740],[277,17880],[280,18060],[289,18200]]},"ch6-silence-time":{"text":"Maybe this was what I had rushed before: the ordinary hours that made somebody indispensable. I wanted to give us those hours. I could imagine a day when she looked at me differently, and the friendship changed without either of us having to risk an awkward beginning.","voiceUrl":"voices/chapter-6/ch6-silence-time.mp3","durationMs":18240,"cues":[[6,140],[11,460],[15,940],[20,1140],[22,1380],[26,1460],[33,1640],[41,2000],[45,3280],[54,3520],[60,4180],[65,4560],[70,4740],[79,5080],[94,5840],[96,7840],[103,7960],[106,8300],[111,8520],[114,8760],[120,9140],[127,9480],[129,10880],[135,10960],[143,11080],[145,11540],[149,11660],[154,11960],[158,12360],[165,12540],[168,12720],[171,12840],[184,13020],[188,14000],[192,14120],[203,14240],[211,14760],[219,15240],[226,15720],[229,15980],[232,16100],[239,16260],[242,16520],[247,16660],[250,16940],[258,17180],[268,17620]]},"ch6-silence-fear":{"text":"I could survive not knowing while there was still a place saved beside her. A no might change every comfortable thing we had. I held on to tomorrow's lunch, next week's study session, any small certainty I could keep by postponing the one question that frightened me.","voiceUrl":"voices/chapter-6/ch6-silence-fear.mp3","durationMs":18720,"cues":[[2,160],[8,260],[16,440],[20,1060],[28,1380],[34,1940],[40,2120],[44,2240],[50,2440],[52,2660],[58,2780],[64,3120],[71,3500],[76,3920],[78,4820],[81,5000],[87,5620],[94,5920],[100,6440],[112,6840],[118,7380],[121,7740],[126,7940],[128,9360],[133,9420],[136,9680],[139,9860],[150,9980],[157,10460],[162,11200],[169,11560],[175,12060],[184,12400],[188,13060],[194,13420],[204,13780],[206,14280],[212,14360],[217,14560],[220,15380],[231,15580],[235,16260],[239,16520],[248,17080],[253,17800],[264,17980],[267,18420]]},"ch6-silence-obvious":{"text":"Who else knew her timetable this well? Who else stayed up answering messages about a bad day? I thought my feelings must be visible in the time I gave her. Saying them aloud felt almost unnecessary, like explaining a joke everybody in the room already understood.","voiceUrl":"voices/chapter-6/ch6-silence-obvious.mp3","durationMs":17592,"cues":[[4,100],[9,340],[14,700],[18,900],[28,1080],[33,1640],[39,1880],[43,2840],[48,3080],[55,3560],[58,3800],[68,4000],[77,4420],[83,4920],[85,5160],[89,5380],[94,5760],[96,7180],[104,7260],[107,7480],[116,7660],[121,8119],[124,8360],[132,8560],[135,8960],[139,9060],[144,9180],[146,9460],[151,9560],[156,9800],[163,10940],[168,11160],[174,11320],[179,11760],[186,12040],[199,12580],[204,13920],[215,14340],[217,14840],[222,14960],[232,15340],[235,15860],[239,15960],[244,16059],[252,16440],[263,16880]]},"ch6-silence-join":{"text":"So I tried a different approach. No sudden declaration, no demand for an answer before we were close. Just stay nearby until she liked me. Hover, if I was being honest. I made it sound patient in my head, though I was quietly expecting that patience to lead somewhere specific.","voiceUrl":"voices/chapter-6/ch6-silence-join.mp3","durationMs":19512,"cues":[[3,140],[5,420],[11,520],[13,780],[23,880],[33,1220],[36,2340],[43,2660],[56,3020],[59,4140],[66,4320],[70,4860],[73,4980],[80,5200],[87,5600],[90,5980],[95,6100],[102,6280],[107,7460],[112,8240],[119,8460],[125,8940],[129,9260],[135,9440],[139,9780],[146,10500],[149,11140],[151,11380],[155,11460],[161,11620],[169,11860],[171,13160],[176,13260],[179,13460],[185,13620],[193,13940],[196,14380],[199,14500],[205,14700],[212,15600],[214,16000],[218,16079],[226,16280],[236,16680],[241,17180],[250,17420],[253,17920],[258,18020],[268,18300],[277,18780]]},"ch6-017":{"text":"And I began keeping watch. If a guy asked whether she was joining something, I listened for more than the question. Did he ask anyone else? Was he finding excuses to message? A friendly conversation could become a threat in the few seconds it took me to decide he liked her.","voiceUrl":"voices/chapter-6/ch6-017.mp3","durationMs":17832,"cues":[[4,100],[6,320],[12,420],[20,840],[27,1220],[30,2320],[32,2420],[36,2520],[42,2960],[50,3440],[54,3720],[58,3860],[66,4059],[77,4460],[79,5340],[88,5440],[92,5960],[97,6180],[102,6480],[106,6640],[116,6760],[120,8080],[123,8220],[127,8420],[134,8660],[140,9000],[144,9800],[147,9920],[155,10080],[163,10520],[166,11220],[175,11340],[177,12520],[186,12620],[199,13020],[205,13820],[212,14060],[214,14340],[221,14460],[224,15060],[228,15160],[232,15280],[240,15520],[243,15880],[248,16020],[251,16239],[254,16500],[261,16620],[264,17080],[270,17260],[274,17540]]},"ch6-018":{"text":"She has plans already. We're studying later. Maybe ask the group another time.","voiceUrl":"voices/chapter-6/ch6-018.mp3","durationMs":4704,"cues":[[4,240],[8,360],[14,580],[23,940],[29,1820],[38,1980],[45,2300],[51,3120],[55,3400],[59,3600],[65,3700],[73,3880],[78,4180]]},"ch6-019":{"text":"Eh, I haven't even answered him yet.","voiceUrl":"voices/chapter-6/ch6-019.mp3","durationMs":2784,"cues":[[4,160],[6,760],[14,860],[19,1180],[28,1560],[32,2000],[36,2260]]},"ch6-020":{"text":"Thought you said you had work to finish. I was helping you escape.","voiceUrl":"voices/chapter-6/ch6-020.mp3","durationMs":3840,"cues":[[8,240],[12,420],[17,520],[21,660],[25,760],[30,880],[33,1060],[41,1160],[43,2080],[47,2160],[55,2320],[59,2720],[66,2900]]},"ch6-021":{"text":"The excuse passed easily enough. Sometimes I discouraged a guy before she heard about his interest at all. I would mention how busy she was, turn an invitation into a group outing, or stay planted beside her until he left. I felt useful afterwards. That should have troubled me more than it did.","voiceUrl":"voices/chapter-6/ch6-021.mp3","durationMs":20640,"cues":[[4,180],[11,280],[18,1020],[25,1420],[33,1800],[43,2980],[45,3860],[57,4000],[59,4680],[63,4780],[70,5080],[74,5580],[80,5820],[86,6040],[90,6300],[99,6480],[102,6900],[107,7060],[109,7940],[115,8000],[123,8180],[127,8520],[132,8700],[136,9060],[141,9240],[146,9820],[149,10060],[160,10220],[165,10860],[167,11140],[173,11260],[181,11620],[184,12060],[189,12640],[197,12900],[204,13340],[208,13780],[214,13920],[217,14220],[223,14400],[225,15620],[230,15720],[237,16040],[249,16860],[254,18420],[261,18740],[266,18900],[275,19060],[278,19440],[283,19620],[288,19880],[291,20040],[295,20200]]},"ch6-keeping-watch":{"text":"I watched him put his phone away and felt myself relax. Then Jia Wen asked what I thought about something she had just said. I had to ask her to repeat it. I was sitting beside the person I wanted to know better, missing her actual conversation because I was busy deciding who else could have one with her.","voiceUrl":"voices/chapter-6/ch6-keeping-watch.mp3","durationMs":19104,"cues":[[2,140],[10,200],[14,520],[18,680],[22,820],[28,1000],[33,1240],[37,1480],[42,1640],[49,1840],[56,2220],[61,3360],[65,3880],[69,4140],[75,4640],[80,4980],[82,5160],[90,5260],[96,5460],[106,5740],[110,6200],[114,6320],[119,6460],[125,6780],[127,7780],[131,7820],[134,7920],[138,8080],[142,8280],[145,8400],[152,8520],[156,8920],[158,9980],[162,10040],[170,10240],[177,10600],[181,11080],[188,11220],[190,11800],[197,11960],[200,12320],[205,12460],[213,12720],[221,13560],[225,14020],[232,14320],[245,14740],[253,15420],[255,15760],[259,15840],[264,16059],[273,16440],[277,17100],[282,17400],[288,17840],[293,18040],[297,18340],[302,18580],[306,18760]]},"ch6-022":{"text":"In her dorm, I took the chair while she sat with her laptop on the bed, surrounded by notes she insisted were in a system. A desk fan clicked each time it turned. She would ask me to read a sentence, then argue with my suggestion until we both forgot why she had asked.","voiceUrl":"voices/chapter-6/ch6-022.mp3","durationMs":17592,"cues":[[3,120],[7,220],[13,360],[15,1160],[20,1300],[24,1480],[30,1600],[36,2300],[40,2520],[44,2740],[49,2980],[53,3100],[60,3240],[63,3660],[67,3760],[72,3880],[83,4620],[86,5020],[92,5220],[96,5660],[105,5780],[110,6480],[113,6640],[115,6760],[123,6880],[125,8220],[130,8320],[134,8600],[142,8900],[147,9400],[152,9640],[155,9820],[163,9960],[167,11260],[173,11360],[177,11560],[180,11800],[183,11940],[188,12040],[190,12220],[200,12320],[205,13220],[211,13520],[216,13880],[219,14020],[230,14200],[236,15300],[239,15540],[244,15720],[251,15980],[255,16500],[259,16820],[263,16960],[269,17160]]},"ch6-023":{"text":"You're making it sound like a government announcement. I just need it to sound like me, but more intelligent.","voiceUrl":"voices/chapter-6/ch6-023.mp3","durationMs":7344,"cues":[[7,160],[14,380],[17,780],[23,1000],[28,1340],[30,1540],[41,1740],[55,2280],[57,3600],[62,3780],[67,4040],[70,4240],[73,4400],[79,4580],[84,4840],[88,5100],[92,5640],[97,6140],[109,6320]]},"ch6-024":{"text":"That one a bit difficult. Need a bigger editing budget.","voiceUrl":"voices/chapter-6/ch6-024.mp3","durationMs":2784,"cues":[[5,240],[9,420],[11,500],[15,560],[26,720],[31,1400],[33,1540],[40,1600],[48,1860],[55,2140]]},"ch6-025":{"text":"She threatened to take back the snack she had given me. I surrendered immediately. Later, while she worked, I watched the fan stir a loose page and felt so comfortable that I could almost believe comfort was an agreement. Nobody had invited me to imagine a shared future. I was already furnishing one.","voiceUrl":"voices/chapter-6/ch6-025.mp3","durationMs":21840,"cues":[[4,160],[15,440],[18,920],[23,1060],[28,1280],[32,1520],[38,1780],[42,2140],[46,2260],[52,2440],[56,2700],[58,3600],[70,3720],[83,4240],[90,5880],[96,6360],[100,6580],[108,6780],[110,7260],[118,7360],[122,7900],[126,8080],[131,8700],[133,8960],[139,9080],[144,9400],[148,10240],[153,10380],[156,10720],[168,11140],[173,11860],[175,12040],[181,12120],[188,12380],[196,12900],[204,13420],[208,14420],[211,14600],[222,14720],[229,16379],[233,16760],[241,16920],[244,17420],[247,17640],[255,17780],[257,18340],[264,18480],[272,18900],[274,20220],[278,20320],[286,20540],[297,20980],[301,21540]]},"ch6-dorm-evening":{"text":"Sometimes she got tired of the assignment before I did. She would close the laptop and tell me about her day, shifting the pile of notes so she could sit properly. I knew which stories needed advice and which needed somebody to agree that people could be very irritating. It pleased me that she trusted me with both.","voiceUrl":"voices/chapter-6/ch6-dorm-evening.mp3","durationMs":20400,"cues":[[10,160],[14,800],[18,940],[24,1160],[27,1440],[31,1540],[42,1640],[49,2120],[51,2500],[56,2620],[60,3720],[66,3840],[72,4019],[76,4400],[83,4520],[87,5060],[92,5260],[95,5420],[101,5560],[105,5780],[110,5960],[119,6760],[123,7220],[128,7360],[131,7640],[137,7800],[140,8340],[144,8560],[150,8680],[154,8860],[164,9080],[166,10660],[171,10760],[177,11040],[185,11320],[192,11780],[199,12140],[203,12740],[209,13080],[216,13420],[225,13800],[228,14260],[234,14420],[239,14800],[246,15020],[252,15360],[255,15560],[260,15780],[272,16280],[275,17980],[283,18100],[286,18500],[291,18840],[295,19020],[303,19220],[306,19660],[311,19800],[316,19980]]},"ch6-026":{"text":"When she went home, I sometimes sent her back. Our conversation stretched across the journey, grew quieter near her stop, then found one last thing to say. At the drop-off, she would turn round because she had remembered something small, and I would get another minute before goodbye.","voiceUrl":"voices/chapter-6/ch6-026.mp3","durationMs":17760,"cues":[[5,120],[9,240],[14,380],[20,620],[22,1520],[32,1620],[37,2060],[41,2220],[47,2360],[51,3300],[64,3500],[74,4360],[81,4780],[85,5180],[94,5360],[99,6160],[107,6400],[112,6980],[116,7160],[122,7380],[127,8020],[133,8260],[137,8620],[142,8840],[148,9200],[151,9460],[156,9620],[159,10800],[163,10920],[173,11040],[177,12000],[183,12120],[188,12280],[194,12540],[202,12900],[206,13180],[210,13300],[221,13460],[231,13940],[238,14280],[242,15380],[244,15600],[250,15660],[254,15840],[262,16040],[269,16379],[276,16760],[284,17080]]},"ch6-027":{"text":"Message when you reach, okay? And don't forget to eat. You were so busy complaining you never finished dinner.","voiceUrl":"voices/chapter-6/ch6-027.mp3","durationMs":7992,"cues":[[8,180],[13,740],[17,960],[24,1120],[30,1580],[34,2420],[40,2660],[47,2900],[50,3280],[55,3520],[59,4280],[64,4400],[67,4700],[72,5000],[84,5400],[88,6220],[94,6400],[103,6800],[110,7320]]},"ch6-028":{"text":"Those were the lines I replayed. Her checking that I got home, her saving a seat, her asking whether I was free before making plans. They were real kindnesses. I stacked them carefully in my mind, each one evidence for a conclusion we had never spoken about together.","voiceUrl":"voices/chapter-6/ch6-028.mp3","durationMs":19680,"cues":[[6,320],[11,740],[15,880],[21,1000],[23,1420],[33,1520],[37,3220],[46,3400],[51,3800],[53,3980],[57,4059],[63,4260],[67,4980],[74,5180],[76,5460],[82,5600],[86,6700],[93,6900],[101,7280],[103,7600],[107,7680],[112,7900],[119,8220],[126,8580],[133,8940],[138,10620],[143,10820],[148,11120],[160,11780],[162,13380],[170,13540],[175,13940],[185,14200],[188,14640],[191,14760],[197,15000],[202,15800],[206,16160],[215,16500],[219,16980],[221,17100],[232,17200],[235,17880],[239,17980],[245,18160],[252,18540],[258,18900],[267,19160]]},"ch6-home-message":{"text":"Back in my own room, I would send the promised message and wait for her reply before putting the phone to charge. She usually had one more thing to add. I began to expect that small exchange at the end of a day. Without ever discussing it, I had made her part of how I knew the day was over.","voiceUrl":"voices/chapter-6/ch6-home-message.mp3","durationMs":17184,"cues":[[5,160],[8,360],[11,460],[15,640],[21,860],[23,1500],[29,1560],[34,1720],[38,1900],[47,2000],[55,2420],[59,3240],[64,3380],[68,3600],[72,3720],[78,3860],[85,4300],[93,4580],[97,4820],[103,4920],[106,5180],[114,5320],[118,6540],[126,6760],[130,7100],[134,7340],[139,7540],[145,7780],[148,8020],[153,8180],[155,9300],[161,9400],[164,9680],[171,9780],[176,10220],[182,10500],[191,10820],[194,11380],[198,11480],[202,11560],[205,11700],[207,11780],[212,11880],[220,13040],[225,13340],[236,13520],[240,14040],[242,14700],[246,14760],[251,14880],[255,15060],[260,15260],[263,15540],[267,15660],[269,15840],[274,15960],[278,16239],[282,16360],[286,16560],[291,16760]]},"ch6-029":{"text":"By fourth year, graduation had begun to appear in conversations. People discussed the world beyond campus as if we were all ready to leave. I looked at our matching gaps in the timetable and realised there would soon be no timetable holding us near each other. I needed to say something before that happened.","voiceUrl":"voices/chapter-6/ch6-029.mp3","durationMs":19104,"cues":[[3,100],[10,320],[16,620],[27,1160],[31,1900],[37,2040],[40,2340],[47,2480],[50,2800],[65,2960],[72,4340],[82,4640],[86,5200],[92,5340],[99,5680],[106,6240],[109,6820],[112,6980],[115,7200],[120,7360],[124,7580],[130,7780],[133,8100],[140,8240],[142,9700],[149,9780],[152,9980],[156,10100],[165,10260],[170,10700],[173,11080],[177,11180],[187,11320],[191,11900],[200,12060],[206,12880],[212,13080],[217,13300],[220,13580],[223,13800],[233,14040],[241,14640],[244,14960],[249,15120],[254,15300],[261,15520],[263,16880],[270,16980],[273,17280],[277,17420],[287,17660],[294,18040],[299,18380],[308,18560]]},"ch6-030":{"text":"I chose Universal Studios Singapore. December 2021, at the end of the year. We could have a full day together, something larger than lunch between classes, and I would find a quiet moment to tell her. I planned the outing until the planning itself began to feel like courage.","voiceUrl":"voices/chapter-6/ch6-030.mp3","durationMs":17760,"cues":[[2,120],[8,220],[18,560],[26,1140],[37,1600],[46,3040],[52,3660],[55,4820],[59,4920],[63,5000],[66,5120],[70,5220],[76,5340],[79,6260],[85,6360],[90,6500],[92,6660],[97,6840],[101,7200],[111,7440],[121,8380],[128,8720],[133,9100],[139,9320],[147,9680],[156,10040],[160,11140],[162,11280],[168,11340],[173,11480],[175,11680],[181,11820],[188,12160],[191,12600],[196,12720],[201,12940],[203,14180],[211,14280],[215,14640],[222,14820],[228,15280],[232,15480],[241,15580],[248,15880],[254,16400],[257,16660],[262,16760],[267,16940],[275,17180]]},"ch6-031":{"text":"Jia Wen, I like you. More than a friend. I've liked you for a long time.","voiceUrl":"voices/chapter-6/ch6-031.mp3","durationMs":5520,"cues":[[4,140],[9,320],[11,1240],[16,1300],[21,1540],[26,2260],[31,2420],[33,2520],[41,2600],[46,3440],[52,3580],[56,3840],[60,4100],[62,4400],[67,4540],[72,4880]]},"ch6-032":{"text":"Alone in my room, I kept adjusting that opening. Too serious. Too sudden. Too much like I had rehearsed it in my room, which was exactly what I was doing. I checked the plans again, imagined her expression, and let myself picture the journey home with everything finally understood.","voiceUrl":"voices/chapter-6/ch6-032.mp3","durationMs":19824,"cues":[[6,180],[9,520],[12,660],[18,840],[20,1140],[25,1240],[35,1440],[40,2100],[49,2360],[53,3340],[62,3620],[66,4320],[74,4820],[78,5860],[83,6020],[88,6300],[90,6540],[94,6640],[104,6780],[107,7260],[110,7400],[113,7540],[119,7800],[125,8680],[129,9100],[137,9420],[142,10040],[144,10220],[148,10300],[155,10500],[157,11840],[165,11960],[169,12300],[175,12440],[182,12800],[191,13680],[195,14360],[207,14520],[211,15360],[215,15580],[222,15760],[230,16239],[234,16680],[242,16840],[247,17240],[252,17560],[263,17900],[271,18660],[282,19140]]},"ch6-preparing":{"text":"I asked whether the date still worked for her and read her yes with ridiculous relief. I was careful to make the outing sound casual when we talked about it. Afterwards, I went back to planning a moment she had no reason to expect. Even now, with a confession ahead, secrecy felt easier than letting her see me nervous.","voiceUrl":"voices/chapter-6/ch6-preparing.mp3","durationMs":21360,"cues":[[2,180],[8,300],[16,720],[20,1040],[25,1180],[31,1520],[38,1780],[42,2060],[46,2200],[50,2940],[55,3120],[59,3340],[63,3620],[68,4320],[79,4600],[87,5400],[89,6820],[93,6880],[101,7040],[104,7340],[109,7440],[113,7600],[120,7760],[126,8100],[133,8560],[138,9300],[141,9500],[148,9660],[154,9940],[158,10200],[170,11120],[172,11660],[177,11720],[182,11920],[185,12100],[194,12240],[196,12560],[203,12660],[207,13140],[211,13340],[214,13640],[221,13920],[224,14360],[232,14500],[237,15880],[242,16219],[247,16660],[249,16900],[260,16980],[267,17560],[275,18340],[280,18920],[287,19240],[292,19640],[300,19840],[304,20100],[308,20300],[311,20460],[319,20720]]},"ch6-033":{"text":"Then the week before the outing arrived. I overheard her name in a conversation nearby, followed by boyfriend. Nothing dramatic in the way it was said. Just ordinary news moving between people who did not know they were pulling the floor out from under somebody within earshot.","voiceUrl":"voices/chapter-6/ch6-033.mp3","durationMs":17112,"cues":[[5,140],[9,400],[14,540],[21,760],[25,1140],[32,1280],[41,1560],[43,2940],[53,3060],[57,3480],[62,3680],[65,3960],[67,4059],[80,4140],[88,4760],[97,5760],[100,6060],[111,6620],[119,8140],[128,8480],[131,8920],[135,9000],[139,9100],[142,9240],[146,9340],[152,9520],[157,10300],[166,10880],[171,11400],[178,11780],[186,12100],[193,12460],[197,12900],[201,13020],[205,13200],[210,13480],[215,14000],[220,14100],[228,14300],[232,14580],[238,14740],[242,15060],[247,15240],[253,15400],[262,15660],[269,16059],[277,16440]]},"ch6-034":{"text":"I went still, then tried to look as if I hadn't. Maybe I had misheard. Maybe they meant someone else. I checked my phone without reading anything, giving my hands a task while my mind went through every name I knew around her. None of them fitted.","voiceUrl":"voices/chapter-6/ch6-034.mp3","durationMs":18144,"cues":[[2,140],[7,220],[14,540],[19,1440],[25,1720],[28,1960],[33,2080],[36,2280],[39,2420],[41,2580],[49,2660],[55,4040],[57,4380],[61,4500],[71,4780],[77,5920],[82,6260],[88,6440],[96,6740],[102,7080],[104,8420],[112,8520],[115,8780],[121,8960],[129,9280],[137,9640],[147,9980],[154,10840],[157,11100],[163,11320],[165,11640],[170,11760],[176,12160],[179,12340],[184,12540],[189,12900],[197,13120],[203,13460],[208,13780],[210,14100],[215,14220],[222,14460],[227,14840],[232,15980],[235,16160],[240,16300],[247,16540]]},"ch6-dread":{"text":"Her chat was still there, full of ordinary things. Nothing on the screen announced that my place in her life was different from what I had imagined. I scrolled up, looking for some warning I had missed, then stopped. I had years of messages and could not find the question whose answer I suddenly needed.","voiceUrl":"voices/chapter-6/ch6-dread.mp3","durationMs":20952,"cues":[[4,120],[9,380],[13,980],[19,1160],[26,1420],[31,2400],[34,2700],[43,3280],[51,3880],[59,5000],[62,5360],[66,5460],[73,5620],[83,5940],[88,6360],[91,6520],[97,6780],[100,7100],[104,7220],[109,7400],[113,7700],[123,7920],[128,8460],[133,8720],[135,9060],[139,9140],[149,9280],[151,10760],[160,10880],[164,11280],[172,11600],[176,11940],[181,12100],[189,12600],[191,13140],[195,13200],[203,13400],[208,13900],[217,14300],[219,15720],[223,15800],[229,16180],[232,16640],[241,16800],[245,17440],[251,17720],[255,17920],[260,18180],[264,18460],[273,18580],[279,19100],[286,19380],[288,19820],[297,20020],[304,20500]]},"ch6-035":{"text":"Then I saw them together. She reached for his hand with an ease that needed no explanation. He leaned closer to hear her, and she smiled the way people smile when they are continuing a conversation that belongs to them. There was nothing uncertain about what I was seeing.","voiceUrl":"voices/chapter-6/ch6-035.mp3","durationMs":17040,"cues":[[5,80],[7,260],[11,360],[16,540],[26,740],[30,2100],[38,2280],[42,2720],[46,2880],[51,3080],[56,3440],[59,3580],[64,3840],[69,4200],[76,4380],[79,4780],[92,5000],[95,6540],[102,6700],[109,7020],[112,7400],[117,7540],[122,7760],[126,8520],[130,8660],[137,8880],[141,9380],[145,9480],[152,9720],[158,10080],[163,10540],[168,10700],[172,10820],[183,10940],[185,11620],[198,11720],[203,12420],[211,12560],[214,13120],[220,13300],[226,14700],[230,14820],[238,15000],[248,15320],[254,15820],[259,16079],[261,16320],[265,16400],[272,16580]]},"ch6-036":{"text":"I did not recognise him. After all the attention I had paid, all the approaches I thought I had intercepted, the person beside her had appeared from outside my carefully maintained radar. For a few stunned seconds, that felt like the most impossible part: how had something so important happened without me knowing?","voiceUrl":"voices/chapter-6/ch6-036.mp3","durationMs":20640,"cues":[[2,140],[6,220],[10,380],[20,560],[25,1060],[31,2040],[35,2380],[39,2540],[49,2660],[51,3100],[55,3140],[61,3300],[65,3940],[69,4059],[80,4160],[82,4860],[90,4900],[92,5220],[96,5260],[109,5480],[113,6880],[120,7020],[127,7420],[131,7860],[135,8140],[144,8280],[149,8580],[157,8840],[160,9400],[170,9680],[181,10100],[188,10620],[192,12120],[194,12240],[198,12320],[206,12680],[215,13300],[220,14580],[225,14820],[230,15140],[234,15300],[239,15380],[250,15700],[256,16379],[260,17720],[264,17860],[274,18060],[277,18460],[287,18620],[296,19240],[304,19600],[307,19920],[315,20120]]},"ch6-037":{"text":"At home, I put the outing plans away, then opened them again. I had spent too long preparing to cancel. That was the reason I gave myself. Underneath it was another one: if I cancelled, these words might stay inside me forever, and I was tired of being the only person who heard them.","voiceUrl":"voices/chapter-6/ch6-037.mp3","durationMs":19032,"cues":[[3,100],[9,240],[11,1000],[15,1100],[19,1240],[26,1380],[32,1660],[38,2000],[43,2800],[50,3060],[55,3300],[62,3460],[64,4700],[68,4740],[74,4900],[78,5200],[83,5480],[93,5840],[96,6180],[104,6340],[109,7040],[113,7180],[117,7340],[124,7440],[126,7740],[131,7840],[139,8060],[150,9300],[153,9800],[157,10000],[165,10160],[170,10560],[173,11440],[175,11780],[186,11960],[192,12900],[198,13260],[204,13660],[209,13920],[216,14120],[219,14620],[228,14900],[232,16140],[234,16300],[238,16360],[244,16540],[247,16920],[253,17040],[257,17260],[262,17460],[269,17840],[273,18220],[279,18380],[284,18660]]},"ch6-038":{"text":"We still went. December lights brightened the park, and music followed us past shopfronts and families stopping for pictures. She arrived as the friend who had agreed to spend the day with me. I arrived carrying a confession that already knew it could not have the ending I had rehearsed.","voiceUrl":"voices/chapter-6/ch6-038.mp3","durationMs":18792,"cues":[[3,140],[9,380],[15,660],[24,2380],[31,2880],[42,3240],[46,3720],[52,3860],[56,4560],[62,4700],[71,5180],[74,5500],[79,5700],[90,6060],[94,6740],[103,6960],[112,7440],[116,7840],[126,8000],[130,9460],[138,9640],[141,10240],[145,10440],[152,10600],[156,11000],[160,11120],[167,11260],[170,11560],[176,11700],[180,11940],[184,12080],[189,12280],[193,12480],[195,13420],[203,13560],[212,14120],[214,14580],[225,14660],[230,15300],[238,15640],[243,16059],[246,16300],[252,16480],[256,16660],[261,16920],[265,17100],[272,17280],[274,17840],[278,17920],[288,18120]]},"ch6-039":{"text":"You okay? You're very quiet today. Usually by now you have complained about at least three things.","voiceUrl":"voices/chapter-6/ch6-039.mp3","durationMs":7824,"cues":[[4,240],[10,400],[17,1540],[22,1760],[28,2160],[35,2620],[43,3620],[46,4059],[50,4260],[54,4600],[59,4700],[70,4880],[76,5400],[79,5720],[85,6000],[91,6480],[98,6900]]},"ch6-040":{"text":"Saving my energy. Long day ahead. The complaints need to last.","voiceUrl":"voices/chapter-6/ch6-040.mp3","durationMs":4560,"cues":[[7,160],[10,520],[18,660],[23,1360],[27,1620],[34,1800],[38,2420],[49,2520],[54,3160],[57,3560],[62,3720]]},"ch6-041":{"text":"For stretches of the afternoon, we were almost ourselves. We argued about where to go next, laughed at a photograph, stood in a queue with nothing to do except talk. Then she looked away and the knowledge returned. I had become good at keeping things from her. Now I had to keep this too, until I didn't.","voiceUrl":"voices/chapter-6/ch6-041.mp3","durationMs":21744,"cues":[[4,120],[14,360],[17,920],[21,1040],[32,1180],[35,1840],[40,1980],[47,2320],[58,2900],[61,4480],[68,4680],[74,5120],[80,5400],[83,5580],[86,5680],[92,5860],[100,6700],[103,7040],[105,7140],[117,7220],[123,8180],[126,8440],[128,8560],[134,8680],[139,8980],[147,9200],[150,9500],[153,9620],[160,9760],[166,10120],[171,11340],[175,11620],[182,11760],[187,11980],[191,12320],[195,12440],[205,12580],[215,13260],[217,14960],[221,15020],[228,15180],[233,15580],[236,16180],[244,16340],[251,16680],[256,16980],[261,17220],[265,18400],[267,18700],[271,18760],[274,18900],[279,19040],[284,19320],[289,19740],[295,20740],[297,21120],[304,21200]]},"ch6-uss-waiting":{"text":"She asked whether I wanted something to drink. I nodded and followed her, absurdly grateful for a decision that required so little of me. There were still minutes I wanted to keep: her making room for someone to pass, then turning straight back to finish her story. I listened harder because I knew I might miss this soon.","voiceUrl":"voices/chapter-6/ch6-uss-waiting.mp3","durationMs":20304,"cues":[[4,80],[10,260],[18,560],[20,860],[27,940],[37,1320],[40,1700],[47,1880],[49,3240],[56,3340],[60,4000],[69,4200],[74,4500],[83,5200],[92,5760],[96,6280],[98,6460],[107,6560],[112,7000],[121,7120],[124,7620],[131,7820],[134,8060],[138,8220],[144,9340],[149,9440],[155,9580],[163,9860],[165,10260],[172,10320],[175,10620],[181,10780],[185,11860],[192,12180],[197,12600],[201,12960],[209,13100],[212,13340],[218,13480],[223,14460],[231,14660],[240,14980],[245,15240],[248,15540],[255,15640],[259,15880],[266,16059],[268,17480],[277,17560],[284,17940],[292,18400],[294,18700],[299,18780],[301,19020],[307,19120],[312,19380],[317,19660],[322,19920]]},"ch6-042":{"text":"When we found a quieter place beneath the lights, I stopped pretending to study the view. My prepared sentences had deserted me. She noticed my hands, then my face, and waited. After years of conversation, the space before this one felt longer than anything we had ever said.","voiceUrl":"voices/chapter-6/ch6-042.mp3","durationMs":19440,"cues":[[5,120],[8,340],[14,500],[16,760],[24,840],[30,1260],[38,1600],[42,1920],[50,2040],[52,3140],[60,3280],[71,3620],[74,4080],[80,4240],[84,4520],[90,4640],[93,5720],[102,5920],[112,6340],[116,7100],[125,7300],[129,7800],[133,8960],[141,9100],[144,9600],[151,9780],[156,10600],[159,10800],[165,11020],[169,11760],[177,11920],[183,13460],[189,13760],[192,14040],[206,14160],[210,15540],[216,15720],[223,16040],[228,16420],[232,16700],[237,16980],[244,17300],[249,17680],[258,18000],[261,18420],[265,18500],[270,18740],[275,19000]]},"ch6-043":{"text":"I know you're seeing someone. I'm not asking you to do anything about that. But I need to tell you. I like you, Jia Wen. I've liked you for a long time.","voiceUrl":"voices/chapter-6/ch6-043.mp3","durationMs":10080,"cues":[[2,160],[7,280],[14,700],[21,860],[30,1160],[34,2140],[38,2240],[45,2460],[49,2740],[52,2840],[55,2960],[64,3140],[70,3480],[76,3740],[80,4700],[82,5000],[87,5080],[90,5200],[95,5320],[100,5560],[102,6720],[107,6800],[112,7040],[116,7180],[121,7380],[126,8460],[132,8580],[136,8820],[140,8980],[142,9100],[147,9180],[152,9460]]},"ch6-044":{"text":"She looked at me without speaking. Somewhere behind us, somebody called for their family to stand closer for a picture. I could hear every little sound that should have disappeared for a moment like this. The world continued at exactly its usual volume.","voiceUrl":"voices/chapter-6/ch6-044.mp3","durationMs":15912,"cues":[[4,140],[11,320],[14,500],[17,640],[25,780],[35,1200],[45,2500],[52,2800],[56,3220],[65,3620],[72,3980],[76,4260],[82,4380],[89,4580],[92,4940],[98,5080],[105,5420],[109,5900],[111,6020],[120,6120],[122,7420],[128,7500],[133,7680],[139,7980],[146,8380],[152,8700],[157,9220],[164,9460],[169,9620],[181,9760],[185,10400],[187,10520],[194,10600],[199,10900],[205,11140],[209,12260],[215,12380],[225,12780],[228,13640],[236,13860],[240,14640],[246,14900],[253,15300]]},"ch6-045":{"text":"Why didn’t you tell me earlier?","voiceUrl":"voices/chapter-6/ch6-045.mp3","durationMs":2472,"cues":[[4,220],[11,480],[15,800],[20,1020],[23,1280],[31,1500]]},"ch6-046":{"text":"That sentence stayed. Not just that evening, not just on the way home. It found me afterwards while I was eating, working, trying to sleep. Earlier. The word suggested a door I might have reached before it closed, without telling me whether that door had ever actually been open.","voiceUrl":"voices/chapter-6/ch6-046.mp3","durationMs":18000,"cues":[[5,100],[14,340],[22,820],[26,1740],[31,1940],[36,2160],[45,2400],[49,2800],[54,3040],[57,3420],[61,3540],[65,3640],[71,3840],[74,4880],[80,5060],[83,5460],[94,5700],[100,6340],[102,6540],[106,6620],[114,6880],[123,7420],[130,7960],[133,8260],[140,8440],[149,9420],[153,10420],[158,10560],[168,11080],[170,11780],[175,11960],[177,12400],[183,12540],[188,12760],[196,12960],[203,13360],[206,13680],[214,13820],[222,14420],[230,14840],[233,15160],[241,15340],[246,15660],[251,15880],[255,16160],[260,16500],[269,16920],[274,17340],[279,17540]]},"ch6-question-chance":{"text":"My mind ran backwards through every evening I could have spoken. The seat she saved. Her dorm. The minute before she went home. In each memory I replaced my silence with a confession and imagined her saying yes. It hurt like losing a life I had almost lived.","voiceUrl":"voices/chapter-6/ch6-question-chance.mp3","durationMs":18720,"cues":[[3,140],[8,340],[12,720],[22,1020],[30,1640],[36,1960],[44,2380],[46,2740],[52,2840],[57,2980],[65,3180],[69,4340],[74,4500],[78,5040],[85,5240],[89,5880],[95,6060],[99,6960],[106,7100],[113,7500],[117,7820],[122,7960],[128,8180],[131,9380],[136,9580],[143,9860],[145,10300],[154,10380],[157,10900],[165,11100],[170,11520],[172,11640],[183,11720],[187,12900],[196,13040],[200,13480],[207,13700],[212,14000],[215,15400],[220,15600],[225,16260],[232,16460],[234,16800],[239,16920],[241,17400],[245,17460],[252,17620],[258,18080]]},"ch6-question-surprise":{"text":"I looked at the surprise on her face and wondered whether all my careful signals had simply looked like friendship. Had she spent these years beside somebody she trusted, while I kept waiting for her to understand a conversation we were not having? The possibility made my rehearsed certainty falter.","voiceUrl":"voices/chapter-6/ch6-question-surprise.mp3","durationMs":16872,"cues":[[2,160],[9,240],[12,440],[16,540],[25,640],[28,1120],[32,1240],[37,1420],[41,1660],[50,1840],[58,2200],[62,2540],[65,2720],[73,2920],[81,3320],[85,3720],[92,3900],[99,4340],[104,4720],[116,4980],[120,6360],[124,6540],[130,6780],[136,7060],[142,7300],[149,7560],[158,8000],[162,8380],[171,8600],[177,9360],[179,9620],[184,9740],[192,10000],[196,10320],[200,10440],[203,10560],[214,10680],[216,11160],[229,11240],[232,11980],[237,12120],[241,12280],[249,12500],[253,13800],[265,13920],[270,14640],[273,14920],[283,15180],[293,15800],[300,16360]]},"ch6-question-unknown":{"text":"I wanted to ask her to explain every word. Instead, I stood there with the terrible possibility that even an explanation would not give me the past back. Her question was real. The answer I kept hearing beneath it might still be something I was supplying myself.","voiceUrl":"voices/chapter-6/ch6-question-unknown.mp3","durationMs":17904,"cues":[[2,200],[9,300],[12,620],[16,800],[20,1020],[23,1200],[31,1340],[37,2100],[43,2540],[52,3840],[54,4880],[60,5020],[66,5260],[71,5540],[75,5740],[84,5900],[96,6300],[101,6960],[106,7200],[109,7580],[121,7740],[127,8560],[131,8720],[136,8940],[139,9100],[143,9220],[148,9360],[154,9720],[158,11080],[167,11260],[171,11740],[177,12000],[181,13240],[188,13400],[190,13860],[195,13980],[203,14180],[211,14480],[214,14820],[220,15220],[226,15520],[229,15740],[239,15920],[241,16620],[245,16720],[255,16860],[262,17280]]},"ch6-question-join":{"text":"I thought... I thought you knew. We spent so much time together. Everyone thought we were together already.","voiceUrl":"voices/chapter-6/ch6-question-join.mp3","durationMs":6312,"cues":[[2,160],[13,260],[15,1240],[23,1320],[27,1540],[33,1680],[36,2720],[42,2840],[45,3240],[50,3440],[55,3680],[65,3940],[74,4700],[82,5100],[85,5320],[90,5400],[99,5540],[107,5900]]},"ch6-047":{"text":"I knew we were close. You're important to me. But we never said we were a couple, Aleem.","voiceUrl":"voices/chapter-6/ch6-047.mp3","durationMs":7440,"cues":[[2,160],[7,300],[10,560],[15,680],[22,880],[29,2280],[39,2460],[42,3080],[46,3220],[50,4640],[53,4820],[59,5040],[64,5480],[67,5780],[72,5900],[74,6060],[82,6200],[88,6640]]},"ch6-048":{"text":"I wanted to lay out everything I had done. Every journey, every late reply I had stayed awake for, every afternoon arranged around her. It felt like more than friendship, so much more that I had allowed myself to treat us as already together. Hearing the missing agreement spoken aloud made my face burn.","voiceUrl":"voices/chapter-6/ch6-048.mp3","durationMs":23832,"cues":[[2,280],[9,380],[12,760],[16,920],[20,1220],[31,1640],[33,2520],[37,2600],[43,2840],[49,4019],[58,4400],[64,4880],[69,5680],[75,6020],[77,6800],[81,6840],[88,7080],[94,7320],[99,7740],[105,8740],[115,9120],[124,9880],[131,10620],[136,11040],[139,12340],[144,12500],[149,12760],[154,13080],[159,13380],[171,13600],[174,14940],[179,15200],[184,15560],[189,15860],[191,16219],[195,16260],[203,16420],[210,16760],[213,17200],[219,17340],[222,17640],[225,17840],[233,18500],[243,18960],[251,20320],[255,20680],[263,20780],[273,21100],[280,21640],[286,22000],[291,22440],[294,22640],[299,22900],[304,23300]]},"ch6-049":{"text":"The feelings were real. So were those afternoons. But no amount of remembering them could produce a moment when she had agreed to be my girlfriend. I had taken the meaning those things held for me and quietly written her name beneath it too.","voiceUrl":"voices/chapter-6/ch6-049.mp3","durationMs":14640,"cues":[[4,120],[13,280],[18,860],[24,1100],[27,2460],[32,2600],[38,2740],[50,3000],[54,4360],[57,4600],[64,4780],[67,5240],[79,5360],[84,5940],[90,6200],[98,6340],[100,6700],[107,6800],[112,7220],[116,7400],[120,7500],[127,7600],[130,7940],[133,8039],[136,8200],[148,8380],[150,9880],[154,9940],[160,10100],[164,10360],[172,10500],[178,10920],[185,11180],[190,11460],[194,11720],[197,11880],[201,12080],[209,12380],[217,12900],[221,13260],[226,13480],[234,13760],[237,14080],[241,14260]]},"ch6-050":{"text":"What happens to us now? Can we still be friends?","voiceUrl":"voices/chapter-6/ch6-050.mp3","durationMs":4224,"cues":[[5,140],[13,540],[16,1040],[19,1280],[24,1560],[28,2740],[31,2920],[37,3140],[40,3360],[48,3560]]},"ch6-farewell-ready":{"text":"I'm not ready. I know friends is what we've been, but in my head I kept waiting for something else. I can't just switch that off and come for lunch like nothing happened. I need to be away for a while.","voiceUrl":"voices/chapter-6/ch6-farewell-ready.mp3","durationMs":9840,"cues":[[4,240],[8,340],[15,500],[17,1540],[22,1600],[30,1840],[33,2080],[38,2180],[44,2300],[50,2460],[54,2940],[57,3100],[60,3200],[65,3380],[67,3740],[72,3780],[80,4080],[84,4360],[94,4480],[100,4800],[102,5580],[108,5680],[113,5860],[120,6040],[125,6260],[129,6400],[133,6540],[138,6660],[142,6820],[148,6920],[153,7140],[161,7280],[171,7520],[173,8320],[178,8400],[181,8560],[184,8660],[189,8780],[193,9040],[195,9140],[201,9220]]},"ch6-farewell-hurt":{"text":"I don't think I can face you right now. Every normal thing would hurt, even you asking about my day. I don't want you to have to watch everything you say around me. I need some distance because I don't know how to do this yet.","voiceUrl":"voices/chapter-6/ch6-farewell-hurt.mp3","durationMs":11424,"cues":[[2,200],[8,240],[14,360],[16,520],[20,580],[25,760],[29,960],[35,1060],[40,1240],[46,2080],[53,2420],[59,2740],[65,2900],[71,3080],[76,3780],[80,4059],[87,4240],[93,4520],[96,4700],[101,4860],[103,5760],[109,5780],[114,5980],[118,6180],[121,6260],[126,6400],[129,6520],[135,6640],[146,6880],[150,7200],[154,7340],[161,7520],[165,7780],[167,8460],[172,8540],[177,8680],[186,8860],[194,9380],[196,10080],[202,10100],[207,10280],[211,10460],[214,10560],[217,10660],[222,10800],[226,11000]]},"ch6-farewell-honest":{"text":"If I say yes now, I'll still be hoping. You'd think we were okay and I'd still be waiting for your feelings to change. I can't promise a friendship I don't know how to give you. I'm sorry. I need to step back.","voiceUrl":"voices/chapter-6/ch6-farewell-honest.mp3","durationMs":12384,"cues":[[3,100],[5,240],[9,320],[13,500],[18,780],[23,1520],[29,1660],[32,1840],[40,1960],[46,3140],[52,3320],[55,3560],[60,3660],[65,3800],[69,4400],[73,4500],[79,4680],[82,4860],[90,4980],[94,5240],[99,5340],[108,5500],[111,5880],[119,6000],[121,7200],[127,7300],[135,7540],[137,7860],[148,7940],[150,8420],[156,8540],[161,8740],[165,8880],[168,8980],[173,9100],[178,9300],[182,10120],[189,10300],[191,11320],[196,11420],[199,11560],[204,11680],[209,11900]]},"ch6-farewell-join":{"text":"She grew quiet. I had imagined relief after finally speaking, but it was awful watching my words reach her. She was losing a close friend in the same place where I was grieving a relationship we had never had. Neither of us could make the other person's loss smaller.","voiceUrl":"voices/chapter-6/ch6-farewell-join.mp3","durationMs":19104,"cues":[[4,200],[9,400],[16,660],[18,2240],[22,2300],[31,2440],[38,3160],[44,3860],[52,4140],[62,4560],[66,5780],[69,5900],[73,6000],[79,6280],[88,6900],[91,7300],[97,7540],[103,8000],[108,8220],[112,9380],[116,9540],[123,9740],[125,10140],[131,10260],[138,10640],[141,11020],[145,11120],[150,11280],[156,11580],[162,11960],[164,12340],[168,12460],[177,12680],[179,13120],[192,13200],[195,14000],[199,14100],[205,14280],[210,14600],[218,15880],[221,16280],[224,16440],[230,16700],[235,16900],[239,17100],[245,17240],[254,17480],[259,17960],[267,18700]]},"ch6-051":{"text":"Okay. I won't push you. Take care of yourself, can?","voiceUrl":"voices/chapter-6/ch6-051.mp3","durationMs":4464,"cues":[[6,240],[8,1360],[14,1440],[19,1620],[24,1940],[29,2820],[34,3020],[37,3220],[47,3340],[51,3800]]},"ch6-052":{"text":"Afterwards, my hand still moved towards her chat whenever something funny happened. I would compose half a message before remembering. The gap was in lunch, in the hours after class, in reaching home without anybody expecting an update. There was no official anniversary to mourn. My days noticed anyway.","voiceUrl":"voices/chapter-6/ch6-052.mp3","durationMs":21744,"cues":[[12,140],[15,800],[20,980],[26,1400],[32,1720],[40,1980],[44,2300],[49,2480],[58,2800],[68,3140],[74,3520],[84,3780],[86,5120],[92,5200],[100,5400],[105,6060],[107,6280],[115,6380],[122,7040],[135,7320],[139,8800],[143,8900],[147,9380],[150,9540],[157,9700],[160,10520],[164,10620],[170,10780],[176,11200],[183,11440],[186,12520],[195,12620],[200,12980],[208,13240],[216,13620],[226,14020],[229,14520],[237,14660],[243,16160],[247,16260],[250,16400],[259,16660],[271,17140],[274,17700],[281,17860],[284,19080],[289,19260],[297,19680],[304,20100]]},"ch6-053":{"text":"Would earlier have changed anything? Would we have been a couple? I kept returning to those questions as though persistence might make them answerable. Meanwhile, the simplest fact waited without changing: I was single. I had been single beside her too. Now I had to learn how to be alone.","voiceUrl":"voices/chapter-6/ch6-053.mp3","durationMs":21264,"cues":[[6,100],[14,360],[19,840],[27,1060],[37,1640],[43,2920],[46,3120],[51,3240],[56,3420],[58,3700],[66,3820],[68,5380],[73,5460],[83,5660],[86,6140],[92,6240],[102,6500],[105,7260],[112,7400],[124,7640],[130,8360],[135,8580],[140,8740],[152,8920],[163,10460],[167,11240],[176,11380],[181,11840],[188,12220],[196,12560],[206,12900],[208,14520],[212,14600],[220,14760],[222,16620],[226,16680],[231,16860],[238,17160],[245,17480],[249,17860],[254,18060],[258,19340],[260,19680],[264,19760],[267,19940],[273,20040],[277,20300],[280,20420],[283,20540],[289,20660]]},"ch7-001":{"text":"Working life gave my days a different shape. There were names to learn, tasks whose urgency I could not yet judge, and mornings when I arrived early because being lost seemed less embarrassing without an audience. I tried to look settled while checking the same instructions for the third time.","voiceUrl":"voices/chapter-7/ch7-001.mp3","durationMs":18000,"cues":[[8,140],[13,520],[18,1020],[21,1260],[26,1460],[28,1720],[38,1820],[45,2200],[51,3220],[56,3340],[62,3500],[65,3860],[72,3980],[78,4620],[84,5400],[92,5800],[94,6380],[100,6460],[104,6620],[108,6820],[115,7040],[119,7980],[128,8200],[133,8580],[135,8780],[143,8860],[149,9360],[157,9660],[163,9980],[168,10280],[175,11140],[180,11520],[193,11720],[201,12300],[204,12580],[214,12740],[216,14180],[222,14260],[225,14500],[230,14580],[238,14780],[244,15360],[253,15620],[257,15940],[262,16079],[275,16280],[279,16880],[283,17020],[289,17180],[294,17500]]},"ch7-002":{"text":"Claire found me in the pantry studying the drinks as if there might be a correct first-week choice. She was Chinese, easy to talk to, and had joined six months before me. That made her recent enough to remember being new and experienced enough to know which cupboard held the decent mugs.","voiceUrl":"voices/chapter-7/ch7-002.mp3","durationMs":17832,"cues":[[7,100],[13,400],[16,700],[19,800],[23,900],[30,1020],[39,1700],[43,2080],[50,2180],[53,3040],[56,3200],[62,3320],[68,3480],[71,3680],[73,3780],[81,3880],[92,4400],[100,5000],[104,6280],[108,6400],[117,6580],[122,7620],[125,7920],[130,8039],[134,8280],[138,8900],[142,9000],[149,9160],[153,9600],[160,9820],[167,10080],[171,10400],[176,11400],[181,11600],[185,11780],[192,12020],[199,12380],[202,12940],[211,13040],[217,13420],[221,13680],[225,14360],[237,14480],[244,15140],[247,15600],[252,15700],[258,15880],[267,16140],[272,16560],[276,16840],[283,16960],[288,17300]]},"ch7-003":{"text":"That one leaks. Unless you want coffee on your shirt before your first meeting, take the blue one.","voiceUrl":"voices/chapter-7/ch7-003.mp3","durationMs":6240,"cues":[[5,180],[9,420],[16,660],[23,1600],[27,1960],[32,2060],[39,2320],[42,2660],[47,2820],[53,3040],[60,3420],[65,3760],[71,3960],[80,4300],[85,5080],[89,5340],[94,5480],[98,5800]]},"ch7-004":{"text":"Very useful onboarding. They should have put you in charge.","voiceUrl":"voices/chapter-7/ch7-004.mp3","durationMs":3264,"cues":[[5,300],[12,580],[24,940],[29,1760],[36,1860],[41,1980],[45,2060],[49,2220],[52,2320],[59,2420]]},"ch7-005":{"text":"Six months of experience. Cannot waste it.","voiceUrl":"voices/chapter-7/ch7-005.mp3","durationMs":3744,"cues":[[4,160],[11,540],[14,1080],[26,1200],[33,2540],[39,3040],[42,3400]]},"ch7-006":{"text":"She showed me where people usually ate and which questions could safely wait until after lunch. When I looked overwhelmed, she checked in without making a performance of helping. Soon I had things to offer back: a second pair of eyes, a remembered drink order, company when a difficult day ran late.","voiceUrl":"voices/chapter-7/ch7-006.mp3","durationMs":19440,"cues":[[4,160],[11,300],[14,520],[20,660],[27,880],[35,1280],[39,1800],[43,2320],[49,2460],[59,2680],[65,3220],[72,3420],[77,3760],[83,4280],[89,4600],[96,4860],[101,6000],[103,6160],[110,6240],[123,6680],[127,7780],[135,7960],[138,8260],[146,8440],[153,8760],[155,9060],[167,9140],[170,9720],[179,9820],[184,11300],[186,11740],[190,11800],[197,11960],[200,12220],[206,12360],[212,12600],[214,13600],[221,13700],[226,14020],[229,14200],[235,14360],[237,15080],[248,15160],[254,15760],[261,16079],[269,16980],[274,17720],[276,17860],[286,17940],[290,18380],[294,18680],[299,18960]]},"ch7-007":{"text":"Do you have five minutes? I need someone to tell me whether this makes sense or I've been looking at it too long.","voiceUrl":"voices/chapter-7/ch7-007.mp3","durationMs":7584,"cues":[[3,140],[7,280],[12,460],[17,700],[26,980],[28,2160],[33,2280],[41,2540],[44,2940],[49,3100],[52,3380],[60,3600],[65,3920],[71,4160],[77,4460],[80,5720],[85,5900],[90,6060],[98,6260],[101,6600],[104,6780],[108,6960],[113,7180]]},"ch7-008":{"text":"Those can both be true. Let me see.","voiceUrl":"voices/chapter-7/ch7-008.mp3","durationMs":2472,"cues":[[6,140],[10,480],[15,640],[18,900],[24,1040],[28,1920],[31,2020],[35,2160]]},"ch7-009":{"text":"Five minutes became a conversation over lunch. Lunch became a message on the way home. She sent me a picture of something ridiculous she had passed; I saved a story from my day because I wanted to hear her laugh at it. Friendship slipped beyond the office without either of us needing to announce it.","voiceUrl":"voices/chapter-7/ch7-009.mp3","durationMs":18864,"cues":[[5,180],[13,460],[20,820],[22,1080],[35,1160],[40,1740],[47,1940],[53,3100],[60,3520],[62,3840],[70,3940],[73,4340],[77,4440],[81,4520],[87,4720],[91,5900],[96,6060],[99,6260],[101,6380],[109,6480],[112,6780],[122,6900],[133,7400],[137,8440],[141,8540],[149,8680],[151,9840],[157,9960],[159,10200],[165,10280],[170,10660],[173,10840],[177,11080],[185,11320],[187,11800],[194,11900],[197,12220],[202,12340],[206,12560],[212,12780],[215,13100],[219,13280],[230,14260],[238,14920],[245,15340],[249,15800],[256,15980],[264,16680],[271,17100],[274,17380],[277,17520],[285,17740],[288,18040],[297,18160],[300,18560]]},"ch7-pantry-routine":{"text":"I learned to recognise her footsteps when she came into the pantry. Some afternoons she only had time to refill her cup, but we could fit a surprising amount of conversation around the kettle. If one of us had been quiet all morning, the other noticed. Being noticed made the unfamiliar parts of working life feel less lonely.","voiceUrl":"voices/chapter-7/ch7-pantry-routine.mp3","durationMs":19104,"cues":[[2,220],[10,320],[13,620],[23,720],[27,1220],[37,1380],[42,1940],[46,2080],[51,2220],[56,2420],[60,2620],[68,2720],[73,3920],[84,4140],[88,4940],[93,5120],[97,5340],[102,5520],[105,5760],[112,5860],[116,6240],[121,6420],[125,7340],[128,7460],[134,7580],[138,7720],[140,7880],[151,7960],[158,8440],[161,8680],[174,8800],[181,9440],[185,9700],[193,9820],[196,10980],[200,11120],[203,11240],[206,11340],[210,11480],[215,11620],[221,11840],[225,12360],[234,12600],[238,13420],[244,13580],[253,13820],[259,15040],[267,15300],[272,16100],[276,16239],[287,16400],[293,17000],[296,17280],[304,17400],[309,17740],[314,18060],[319,18280],[326,18560]]},"ch7-010":{"text":"Outside work, Claire talked more slowly. She would turn her cup round while deciding how to describe something, then say exactly what she meant. I liked that. After all the meanings I had once hunted between somebody else's words, her plainness felt restful. I began wanting to be the person she chose for these conversations.","voiceUrl":"voices/chapter-7/ch7-010.mp3","durationMs":22704,"cues":[[8,140],[14,620],[21,1180],[28,1520],[33,1860],[41,2100],[45,3380],[51,3520],[56,3700],[60,3960],[64,4140],[70,4420],[76,4920],[85,5100],[89,5660],[92,5800],[101,5920],[112,6440],[117,7180],[121,7760],[129,8060],[134,8600],[138,8780],[145,8940],[147,10200],[153,10280],[159,10600],[165,11840],[169,12080],[173,12200],[182,12360],[184,12960],[188,13020],[193,13220],[200,13500],[208,13920],[217,14380],[224,14740],[231,15180],[235,16200],[245,16420],[250,17180],[259,17620],[261,19040],[267,19120],[275,19460],[278,19760],[281,19860],[285,20000],[292,20120],[296,20600],[302,20860],[306,21320],[312,21480],[326,21680]]},"ch7-011":{"text":"You know you can stop doing the polite work voice. We're not in a meeting.","voiceUrl":"voices/chapter-7/ch7-011.mp3","durationMs":4944,"cues":[[4,160],[9,260],[13,460],[17,580],[22,880],[28,1160],[32,1460],[39,1620],[44,2460],[51,2780],[57,3720],[61,3880],[64,4080],[66,4200],[74,4280]]},"ch7-012":{"text":"This is my normal voice. Very professional person, me.","voiceUrl":"voices/chapter-7/ch7-012.mp3","durationMs":3120,"cues":[[5,240],[8,380],[11,500],[18,680],[25,980],[30,1560],[43,1820],[51,2320],[54,2820]]},"ch7-013":{"text":"She laughed into her drink. I watched her try to recover her dignity and felt that familiar warmth spread through an ordinary evening. This time I recognised what I was hoping for. I also knew our religions were different. The difference sat among things we knew about each other, waiting for a conversation I couldn't keep avoiding.","voiceUrl":"voices/chapter-7/ch7-013.mp3","durationMs":21600,"cues":[[4,140],[12,340],[17,740],[21,900],[28,1080],[30,2300],[38,2380],[42,2740],[46,3000],[49,3240],[57,3340],[61,3720],[69,3940],[73,4440],[78,4740],[83,5020],[92,5300],[99,5940],[106,6700],[114,7000],[117,7280],[126,7600],[135,8140],[140,9500],[145,9700],[147,10060],[158,10200],[163,10940],[165,11120],[169,11200],[176,11340],[181,11720],[183,13140],[188,13220],[193,13500],[197,13720],[207,13860],[212,14420],[223,14580],[227,15560],[238,15680],[242,16280],[248,16500],[255,16840],[258,17360],[263,17580],[269,17880],[274,18140],[281,18380],[289,18860],[293,19260],[295,19380],[308,19480],[310,20300],[319,20440],[324,20780],[333,20980]]},"ch7-014":{"text":"I thought about Jia Wen's question. Earlier had become a word I could trip over even in a new life. With Claire, I would speak before years collected around an assumption. Valentine's Day in 2023 gave me a date to stop postponing it. I chose the words for a question, not a speech about everything I had done.","voiceUrl":"voices/chapter-7/ch7-014.mp3","durationMs":23280,"cues":[[2,240],[10,360],[16,640],[20,960],[26,1200],[36,1560],[44,2920],[48,3660],[55,3840],[57,4180],[62,4300],[64,4900],[70,5020],[75,5280],[80,5580],[85,5940],[88,6400],[90,6540],[94,6660],[100,6860],[105,8220],[113,8400],[115,9300],[121,9380],[127,9640],[134,9960],[140,10420],[150,10820],[157,11320],[160,11760],[172,11880],[184,13580],[188,14260],[191,14560],[196,14900],[201,15760],[204,16000],[206,16120],[211,16280],[214,16800],[219,16960],[230,17320],[234,17940],[236,19200],[242,19300],[246,19620],[252,19760],[256,20260],[258,20380],[268,20520],[272,21320],[274,21500],[281,21660],[287,21960],[298,22200],[300,22640],[304,22700],[309,22880]]},"ch7-before-valentines":{"text":"I still rehearsed. That part had survived every lesson. But this time, when I imagined her answer, I tried to let it be something I hadn't chosen for her. It was easy enough alone in my room. In the morning, seeing a message from her made me hopeful all over again, and I had to start the exercise over.","voiceUrl":"voices/chapter-7/ch7-before-valentines.mp3","durationMs":20544,"cues":[[2,180],[8,300],[19,560],[24,1700],[29,1940],[33,2220],[42,2440],[48,3120],[56,3420],[60,4720],[65,4860],[71,5060],[76,5800],[78,6000],[87,6100],[91,6640],[99,6880],[101,8100],[107,8220],[110,8480],[114,8600],[117,8740],[120,8880],[130,9080],[132,9600],[139,9720],[146,10140],[150,10680],[155,10920],[158,12120],[162,12200],[167,12360],[174,12600],[180,12960],[183,13280],[186,13400],[192,13620],[195,14760],[199,14840],[208,14940],[215,15460],[217,15660],[225,15740],[230,16140],[234,16360],[239,16660],[242,16900],[250,17040],[254,17540],[259,17760],[266,17980],[270,18560],[272,18760],[276,18840],[279,18980],[285,19120],[289,19360],[298,19500],[303,20120]]},"ch7-015":{"text":"On 14 February, I could barely follow our ordinary conversation. By the waterfront, couples kept stopping for photographs while we moved aside to let people pass. The date was suddenly embarrassingly obvious. I had chosen a day that said the thing for me, and still needed to say it myself.","voiceUrl":"voices/chapter-7/ch7-015.mp3","durationMs":19680,"cues":[[3,100],[6,240],[16,720],[18,1580],[24,1660],[31,1860],[38,2240],[42,2540],[51,2820],[65,3260],[68,4680],[72,4800],[84,4900],[92,5920],[97,6300],[106,6520],[110,6820],[122,6940],[128,7700],[131,7880],[137,8039],[143,8280],[146,8680],[150,8780],[157,8960],[163,9240],[167,10660],[172,10800],[176,11380],[185,11540],[200,11960],[209,12900],[211,14280],[215,14340],[222,14480],[224,14800],[228,14920],[233,15160],[238,15360],[242,15840],[248,16040],[252,16680],[256,16840],[260,17640],[266,17880],[273,18220],[276,18540],[280,18680],[283,18820],[290,18960]]},"ch7-016":{"text":"Claire, I like you. More than a friend. I wanted to tell you properly and ask whether you could see us being together.","voiceUrl":"voices/chapter-7/ch7-016.mp3","durationMs":7104,"cues":[[8,180],[10,800],[15,900],[20,1200],[25,1800],[30,2060],[32,2180],[40,2300],[42,3400],[49,3500],[52,3680],[57,3780],[61,3980],[70,4100],[74,4720],[78,4940],[86,5200],[90,5460],[96,5540],[100,5800],[103,5960],[109,6180],[118,6440]]},"ch7-017":{"text":"I'm sorry, Aleem. I care about you, but I can't be with you that way. Our religions are different. Being with someone who shares my religion matters to me.","voiceUrl":"voices/chapter-7/ch7-017.mp3","durationMs":13344,"cues":[[4,120],[11,380],[18,1000],[20,2240],[25,2420],[31,2720],[36,3140],[40,3820],[42,4019],[48,4180],[51,4580],[56,4780],[60,5060],[65,5340],[70,5640],[74,6700],[84,6860],[88,7680],[99,7920],[105,9200],[110,9560],[118,9780],[122,10160],[129,10460],[132,10980],[141,11180],[149,12180],[152,12760],[155,12920]]},"ch7-018":{"text":"I nodded too quickly. Some part of me had prepared for this answer; preparation did very little when it arrived in her voice. I looked out at the water so I could stop managing my expression for a moment. She let the silence stay instead of filling it with a softer possibility.","voiceUrl":"voices/chapter-7/ch7-018.mp3","durationMs":18000,"cues":[[2,200],[9,300],[13,960],[22,1120],[27,2480],[32,2660],[35,2840],[38,2960],[42,3140],[51,3300],[55,3820],[60,3960],[68,4180],[80,5240],[84,5900],[89,6100],[96,6380],[101,6860],[104,7020],[112,7180],[115,7600],[119,7720],[126,7940],[128,9340],[135,9420],[139,9660],[142,9800],[146,9920],[152,10040],[155,10480],[157,10640],[163,10700],[168,10900],[177,11200],[180,11740],[191,11860],[195,12460],[197,12580],[205,12680],[209,13880],[213,14020],[217,14200],[225,14340],[230,15040],[238,15620],[241,16000],[249,16160],[252,16440],[257,16580],[259,16700],[266,16820],[278,17220]]},"ch7-rejection-thanks":{"text":"Thank you for telling me clearly. It hurts, but I'm glad you didn't leave me guessing. I don't have a very graceful response prepared. Just... I heard you. You don't need to explain it over and over to make me feel better.","voiceUrl":"voices/chapter-7/ch7-rejection-thanks.mp3","durationMs":12384,"cues":[[6,60],[10,300],[14,560],[22,700],[25,960],[34,1100],[37,1940],[44,2080],[48,2760],[52,3120],[57,3260],[61,3500],[68,3580],[74,3760],[77,3920],[87,4040],[89,5100],[95,5180],[100,5420],[102,5580],[107,5640],[116,5860],[125,6240],[135,6700],[143,7440],[145,8380],[151,8460],[156,8720],[160,9440],[166,9600],[171,9800],[174,9940],[182,10040],[185,10380],[190,10620],[194,10920],[199,11120],[202,11500],[207,11600],[210,11760],[215,11900],[222,12080]]},"ch7-rejection-minute":{"text":"Okay. I understand. Can we stand here a bit? I need a minute before I can talk normally again. I'm not waiting for you to say something different. My face just hasn't caught up with the part of me that's trying to be sensible.","voiceUrl":"voices/chapter-7/ch7-rejection-minute.mp3","durationMs":12000,"cues":[[6,200],[8,920],[20,980],[24,2160],[27,2280],[33,2460],[38,2720],[40,2860],[45,2920],[47,3580],[52,3660],[54,3800],[61,3900],[68,4160],[70,4400],[74,4460],[79,4580],[88,4820],[95,5160],[99,5880],[103,5960],[111,6140],[115,6420],[119,6520],[122,6600],[126,6720],[136,6920],[147,7260],[150,7940],[155,8119],[160,8600],[167,8840],[174,9180],[177,9380],[182,9600],[186,9700],[191,9820],[194,10020],[197,10140],[204,10380],[211,10640],[214,11020],[217,11120],[226,11260]]},"ch7-rejection-respect":{"text":"I won't ask you to change that for me. I knew religion mattered, but I hoped there might be a way you saw this differently. Now you've told me. I respect it. Give me a little time to get past what I was hoping to hear.","voiceUrl":"voices/chapter-7/ch7-rejection-respect.mp3","durationMs":14640,"cues":[[2,140],[8,220],[12,540],[16,780],[19,1000],[26,1120],[31,1420],[35,1640],[39,1780],[41,3100],[46,3200],[55,3440],[65,3840],[69,4680],[71,4800],[77,4900],[83,5260],[89,5420],[92,5640],[94,5740],[98,5840],[102,6180],[106,6380],[111,6740],[124,7020],[128,8320],[135,8540],[140,8700],[144,8940],[146,9740],[154,9820],[158,10220],[163,11200],[166,11380],[168,11620],[175,11680],[180,11900],[183,12560],[187,12620],[192,12820],[197,13260],[199,13360],[203,13420],[210,13600],[213,14060],[218,14220]]},"ch7-rejection-join":{"text":"There was no negotiation. I accepted her answer, though disappointment followed me home. For once I did not have to reconstruct a hidden message. She had told me something definite about the future she wanted. The difficult part was learning how to remain beside her without treating that future as a challenge.","voiceUrl":"voices/chapter-7/ch7-rejection-join.mp3","durationMs":20640,"cues":[[6,100],[10,260],[13,560],[26,780],[28,2820],[37,2880],[41,3400],[49,3620],[56,4520],[71,4880],[80,5720],[83,6080],[89,6220],[93,7200],[98,7440],[100,7940],[104,8039],[108,8240],[113,8520],[116,8720],[128,8880],[130,9620],[137,9700],[146,10000],[150,11220],[154,11340],[159,11480],[162,11700],[172,11860],[181,12300],[187,13060],[191,13280],[198,13420],[202,13800],[210,14000],[214,15340],[224,15440],[229,15880],[233,16120],[242,16300],[246,16680],[249,16800],[256,16900],[263,17300],[267,17780],[275,18000],[284,18440],[289,18840],[296,19100],[299,19740],[301,19860],[311,20000]]},"ch7-019":{"text":"The next workday, I reached the pantry and found her making a drink. There was a strange little pause before she asked how I was. I could hear the care in the ordinary question, and the uncertainty about whether ordinary questions were still allowed. I was grateful she had asked anyway.","voiceUrl":"voices/chapter-7/ch7-019.mp3","durationMs":18720,"cues":[[4,100],[9,220],[18,540],[20,1440],[28,1560],[32,2020],[39,2160],[43,2600],[49,2780],[53,3020],[60,3200],[62,3540],[69,3660],[75,4820],[79,4940],[81,5080],[89,5220],[96,5660],[102,5940],[109,6440],[113,6840],[119,7060],[123,7360],[125,7620],[130,7740],[132,8860],[138,8920],[143,9100],[147,9300],[152,9480],[155,10160],[159,10260],[168,10480],[178,11000],[182,12040],[186,12400],[198,12540],[204,13240],[212,13500],[221,13980],[231,14540],[236,15120],[242,15340],[251,15620],[253,16960],[257,17040],[266,17200],[270,17620],[274,17720],[280,17900],[287,18200]]},"ch7-020":{"text":"I'm okay enough for coffee. Maybe not okay enough for a long conversation about feelings before lunch.","voiceUrl":"voices/chapter-7/ch7-020.mp3","durationMs":6384,"cues":[[4,260],[9,600],[16,960],[20,1400],[28,1560],[34,2500],[38,2780],[43,3040],[50,3320],[54,3740],[56,3900],[61,4000],[74,4280],[80,4840],[89,5140],[96,5600],[102,5900]]},"ch7-021":{"text":"Coffee I can manage. The blue mug is free.","voiceUrl":"voices/chapter-7/ch7-021.mp3","durationMs":4080,"cues":[[7,140],[9,900],[13,1020],[21,1260],[25,2280],[30,2480],[34,2840],[37,3400],[42,3640]]},"ch7-022":{"text":"We stayed friends. There were careful moments at first, then familiar ones. She still needed somebody to complain to after a frustrating afternoon. I still wanted to tell her things. We found our way back through small exchanges until the confession no longer entered the room ahead of us every time we met.","voiceUrl":"voices/chapter-7/ch7-022.mp3","durationMs":20640,"cues":[[3,160],[10,320],[19,620],[25,2080],[30,2200],[38,2360],[46,2760],[49,3100],[56,3260],[61,4160],[70,4540],[76,5000],[80,6200],[86,6400],[93,6680],[102,7020],[105,7400],[114,7480],[117,8000],[123,8400],[125,8620],[137,8720],[148,9340],[150,10660],[156,10800],[163,11020],[166,11280],[171,11420],[175,11600],[183,11760],[186,13260],[192,13400],[196,13640],[200,13740],[205,13960],[213,14440],[219,14740],[229,15040],[235,16320],[239,16620],[250,16720],[253,17480],[260,17640],[268,18020],[272,18260],[277,18380],[283,18640],[286,18860],[289,18980],[295,19320],[300,19660],[303,19980],[307,20140]]},"ch7-staying-friends":{"text":"When she laughed at something I said, I felt relieved before I felt anything else. We could still do this. I could hand her a mug without making an occasion of it, ask about her weekend, tell her I was having a difficult day. I wanted those things to count as evidence that I was managing the friendship properly.","voiceUrl":"voices/chapter-7/ch7-staying-friends.mp3","durationMs":19440,"cues":[[5,80],[9,240],[17,420],[20,800],[30,940],[32,1320],[38,1460],[40,1780],[45,1880],[54,2100],[61,2920],[63,3280],[68,3400],[77,3680],[83,4080],[86,5360],[92,5520],[98,5780],[101,6040],[107,6240],[109,7440],[115,7500],[120,7700],[124,8000],[126,8160],[130,8320],[138,8680],[145,9120],[148,9480],[157,9600],[160,10140],[164,10260],[168,10920],[174,11140],[178,11320],[187,11480],[192,12320],[196,12500],[198,12880],[202,12940],[209,13060],[211,13320],[221,13400],[226,13800],[228,14940],[235,15040],[241,15340],[248,15620],[251,15920],[257,16079],[260,16420],[269,16660],[274,17160],[276,17340],[280,17420],[289,17620],[293,18100],[304,18240],[313,18760]]},"ch7-023":{"text":"There's a café I want to try. Everybody posts couple photos there, but I just want to know whether the food is actually good. You free this weekend?","voiceUrl":"voices/chapter-7/ch7-023.mp3","durationMs":10224,"cues":[[8,180],[10,440],[15,560],[17,1060],[22,1160],[25,1380],[30,1560],[40,2560],[46,3140],[53,3600],[60,4000],[67,4580],[71,5240],[73,5420],[78,5540],[83,5740],[86,5940],[91,6100],[99,6460],[103,6740],[108,6960],[111,7260],[120,7460],[126,7880],[130,8800],[135,8980],[140,9240],[148,9480]]},"ch7-024":{"text":"As your very objective food research partner, yes.","voiceUrl":"voices/chapter-7/ch7-024.mp3","durationMs":3744,"cues":[[3,140],[8,300],[13,540],[23,900],[28,1520],[37,1760],[46,2140],[50,3000]]},"ch7-025":{"text":"The place had soft lighting, small tables, and prices that encouraged us to make jokes about the rent. Around us, people leaned close for photographs. Claire handed me her phone and asked for a picture before the food arrived. I took several because she always found something wrong with the first one.","voiceUrl":"voices/chapter-7/ch7-025.mp3","durationMs":17184,"cues":[[4,120],[10,220],[14,520],[19,780],[29,1120],[35,1800],[43,2060],[47,2880],[54,3060],[59,3620],[70,3780],[73,4400],[76,4580],[81,4680],[87,4920],[93,5220],[97,5460],[103,5600],[110,6640],[114,7000],[121,7220],[128,7500],[134,7820],[138,8160],[151,8300],[158,9660],[165,9940],[168,10300],[172,10400],[178,10600],[182,10940],[188,11160],[192,11440],[194,11540],[202,11660],[209,11980],[213,12280],[218,12420],[227,12640],[229,13740],[234,13820],[242,14040],[250,14440],[254,15020],[261,15180],[267,15440],[277,15720],[283,16040],[288,16360],[292,16500],[298,16640],[302,16940]]},"ch7-026":{"text":"You made the empty chair the main character. I'm over here, thanks.","voiceUrl":"voices/chapter-7/ch7-026.mp3","durationMs":5112,"cues":[[4,240],[9,440],[13,840],[19,1080],[25,1520],[29,2060],[34,2240],[45,2640],[49,3800],[54,3960],[60,4200],[67,4500]]},"ch7-027":{"text":"We laughed, checked the menu, and spent an unhurried afternoon together. Afterwards, she said she was glad she'd had someone to go with. So was I. That became our explanation for other places too: somewhere we wanted to try, something nicer with company. We were friends. We had already settled that.","voiceUrl":"voices/chapter-7/ch7-027.mp3","durationMs":22944,"cues":[[3,100],[12,220],[20,980],[24,1260],[30,1380],[34,2440],[40,2680],[43,2960],[53,3220],[63,3960],[73,4540],[85,5740],[89,6280],[94,6460],[98,6680],[102,6840],[107,7000],[113,7440],[117,7680],[125,7920],[128,8200],[131,8340],[137,8540],[140,9580],[144,9720],[147,10060],[152,11120],[159,11360],[163,11920],[175,12240],[179,13040],[185,13240],[192,13480],[197,13960],[207,14780],[210,15260],[217,15540],[220,15860],[225,16020],[235,16480],[241,16880],[246,17680],[255,17860],[258,19220],[263,19340],[272,19540],[275,20760],[279,20840],[287,21000],[295,21420],[300,21760]]},"ch7-cafe-photo":{"text":"She took my photograph too, directing me to move my cup because it covered half my face. I complained until she showed me the result. Then we sat shoulder to shoulder over the pictures, choosing which ones to keep. It was a small, lovely thing to do with someone. I carried the feeling home longer than the afternoon lasted.","voiceUrl":"voices/chapter-7/ch7-cafe-photo.mp3","durationMs":21504,"cues":[[4,140],[9,300],[12,520],[23,720],[28,1320],[38,2220],[41,2660],[44,2840],[49,2960],[52,3200],[56,3400],[64,3860],[67,4140],[75,4280],[80,4580],[83,4880],[89,5100],[91,6240],[102,6320],[108,6880],[112,7160],[119,7320],[122,7560],[126,7680],[134,7780],[139,8940],[142,9580],[146,9740],[155,10060],[158,10480],[167,10620],[172,11080],[176,11240],[186,11360],[195,12320],[201,12700],[206,12900],[209,13180],[215,13320],[218,14500],[222,14660],[224,14860],[231,15100],[238,15960],[244,16460],[247,16700],[250,16800],[255,16920],[264,17100],[266,18380],[274,18500],[278,18780],[286,18900],[291,19260],[298,19620],[303,20000],[307,20160],[317,20320],[324,20800]]},"ch7-028":{"text":"There were evenings by the water when the city lights broke into long lines around the boats. We walked at the same pace, stopped when one of us noticed something, and talked until we should have gone home. Anybody passing could have mistaken us for a couple. I knew how little that proved now.","voiceUrl":"voices/chapter-7/ch7-028.mp3","durationMs":18144,"cues":[[6,120],[11,280],[20,520],[23,960],[27,1100],[33,1220],[38,1560],[42,1720],[47,1860],[54,2160],[60,2560],[65,2820],[70,3120],[76,3500],[83,4040],[87,4440],[94,4560],[97,5700],[104,5840],[107,6140],[111,6240],[116,6380],[122,6660],[130,7400],[135,7840],[139,8119],[142,8260],[145,8360],[153,8540],[164,9060],[168,9520],[175,9880],[181,10280],[184,10640],[191,10780],[196,10940],[201,11080],[207,11340],[215,12620],[223,13060],[229,13580],[234,13720],[243,13840],[246,14340],[250,14520],[252,14640],[260,14740],[262,15880],[267,15980],[271,16239],[278,16460],[283,16800],[290,17040],[294,17700]]},"ch7-companionship-company":{"text":"I liked the actual person walking beside me: her terrible photographs, her patient questions, the way she remembered a story I had mentioned once. The friendship wasn't an empty consolation. That was what made it so difficult to notice when enjoying her company slipped back into wanting more.","voiceUrl":"voices/chapter-7/ch7-companionship-company.mp3","durationMs":21912,"cues":[[2,160],[8,260],[12,740],[19,880],[26,1320],[34,1840],[41,2220],[45,2680],[49,3660],[58,3900],[71,4400],[75,5780],[83,5980],[94,6460],[98,7800],[102,7900],[106,8100],[117,8280],[119,8720],[125,8860],[127,9320],[131,9380],[141,9560],[147,10020],[151,10980],[162,11100],[169,11740],[172,12240],[178,12480],[191,12860],[196,14640],[200,15020],[205,15200],[210,15440],[213,15660],[216,15860],[226,16100],[229,16520],[236,16640],[241,17160],[250,18080],[254,18600],[262,18780],[270,20000],[275,20420],[280,20800],[288,21020],[293,21460]]},"ch7-companionship-hope":{"text":"Her answer had not changed. Still, an especially good evening could wake a small, stubborn maybe in me. I didn't say it aloud or ask her to reconsider. I simply let tomorrow remain a little less definite in my head than she had made it in our conversation.","voiceUrl":"voices/chapter-7/ch7-companionship-hope.mp3","durationMs":17832,"cues":[[4,100],[11,320],[15,840],[19,1020],[28,1280],[35,2580],[38,3260],[49,3380],[54,3980],[62,4200],[68,4560],[73,4800],[75,5040],[82,5200],[91,5920],[97,6680],[100,7400],[104,7560],[106,8640],[113,8720],[117,9000],[120,9140],[126,9260],[129,9780],[133,10080],[137,10300],[140,10420],[152,10560],[154,11760],[161,11860],[165,12220],[174,12420],[181,12960],[183,13380],[190,13480],[195,13760],[204,14040],[207,14560],[210,14700],[215,14920],[220,15220],[224,15580],[228,15740],[233,15920],[236,16140],[239,16420],[243,16560],[256,16720]]},"ch7-companionship-alone":{"text":"I knew what waited at home: a quiet room and more time to think than I wanted. Here, somebody was asking whether we should get a drink before leaving. I could accept a small kindness tonight without solving the whole future. It was very easy to keep choosing tonight.","voiceUrl":"voices/chapter-7/ch7-companionship-alone.mp3","durationMs":19104,"cues":[[2,160],[7,280],[12,900],[19,1100],[22,1480],[28,1640],[30,2840],[36,2980],[41,3360],[45,4380],[50,4500],[55,4720],[58,4960],[64,5100],[69,5380],[71,5600],[79,5700],[85,6880],[94,7300],[98,7640],[105,7840],[113,8220],[116,8440],[123,8560],[127,8700],[129,8860],[135,8960],[142,9320],[151,9660],[153,10780],[159,10860],[166,11000],[168,11460],[174,11600],[183,11960],[191,12440],[199,13380],[207,13760],[211,14180],[217,14300],[225,14660],[228,16260],[232,16379],[237,16600],[242,16980],[245,17600],[250,17720],[259,17980],[267,18440]]},"ch7-companionship-join":{"text":"We gave each other company, a reason to go somewhere, someone to send the pictures to afterwards. We said the outings came without feelings attached. I could say it convincingly enough. But I still caught myself smiling at her name on my phone in a way I did not smile at everybody else's.","voiceUrl":"voices/chapter-7/ch7-companionship-join.mp3","durationMs":19200,"cues":[[3,260],[8,420],[13,600],[19,820],[28,1020],[30,2060],[37,2140],[40,2580],[43,2720],[54,2980],[62,3800],[65,4240],[70,4360],[74,4520],[83,4640],[86,5080],[98,5340],[101,6620],[106,6760],[110,6960],[118,7100],[123,7500],[131,7720],[140,8100],[150,8600],[152,9880],[158,9960],[162,10180],[165,10360],[178,10500],[186,11260],[190,12500],[192,12660],[198,12800],[205,13060],[212,13280],[220,13760],[223,14200],[227,14300],[232,14480],[235,14760],[238,14880],[244,15060],[247,15540],[249,15640],[253,15740],[255,16620],[259,16700],[263,16880],[269,17260],[272,17940],[282,18080],[289,18580]]},"ch7-waterfront-goodnight":{"text":"Near the end of an evening, one of us would check the time and groan. We stayed for another few minutes anyway. Then she would wave, turn towards her way home, and leave me with a goodnight that meant exactly what she had said. I tried to keep the evening that simple while I waited for my own journey back.","voiceUrl":"voices/chapter-7/ch7-waterfront-goodnight.mp3","durationMs":19824,"cues":[[5,140],[9,340],[13,460],[16,600],[19,700],[28,840],[32,1520],[35,1700],[38,1840],[44,2040],[50,2220],[54,2420],[59,2560],[63,2960],[70,3240],[73,4540],[80,4760],[84,5100],[92,5220],[96,5560],[104,5720],[112,6040],[117,7220],[121,7560],[127,7740],[133,7940],[138,8620],[146,8920],[150,9280],[154,9480],[160,9700],[164,10560],[170,10720],[173,11000],[178,11300],[180,11460],[190,11580],[195,12380],[201,12620],[209,13000],[214,13720],[218,13920],[222,14060],[228,14260],[230,15560],[236,15660],[239,15860],[244,16000],[248,16200],[256,16379],[261,16800],[268,17100],[274,17640],[276,17900],[283,18020],[287,18400],[290,18540],[294,18800],[302,19060],[307,19420]]},"ch7-029":{"text":"Time passed like that. I could be happy through a whole meal and feel lonely on the journey back. I had learned to ask the question earlier. I had not learned how quickly closeness could become waiting again, even after an answer. Nobody had promised me anything. The waiting happened quietly inside me.","voiceUrl":"voices/chapter-7/ch7-029.mp3","durationMs":21120,"cues":[[5,140],[12,600],[17,980],[23,1240],[25,2380],[31,2440],[34,2600],[40,2780],[48,3140],[50,3340],[56,3460],[61,3820],[65,4620],[70,4760],[77,5040],[80,5440],[84,5560],[92,5680],[98,6000],[100,7180],[104,7240],[112,7440],[115,7880],[119,8060],[123,8340],[132,8460],[141,8960],[143,10080],[147,10140],[151,10280],[159,10580],[163,10980],[171,11240],[181,11720],[187,12280],[194,12420],[202,12880],[209,13260],[214,14220],[220,14500],[223,14760],[231,14920],[238,16160],[242,16580],[251,16760],[254,17240],[264,17420],[268,18440],[276,18580],[285,19060],[293,19500],[300,20340],[303,20860]]},"ch7-030":{"text":"There's someone I've been getting to know. I wanted to tell you myself. We share the same religion. I think this could become something.","voiceUrl":"voices/chapter-7/ch7-030.mp3","durationMs":10320,"cues":[[8,180],[16,540],[21,980],[26,1160],[34,1380],[37,1700],[43,1860],[45,2860],[52,2980],[55,3320],[60,3460],[64,3660],[72,3800],[75,5260],[81,5580],[85,5940],[90,6120],[100,6380],[102,7640],[108,7820],[113,8540],[119,8800],[126,9020],[136,9460]]},"ch7-031":{"text":"This time there was no overheard conversation, no stranger appearing at the edge of a scene I thought I understood. She told me across a table. I watched her choose the words carefully and wished I could make it easy for her without having to feel them first.","voiceUrl":"voices/chapter-7/ch7-031.mp3","durationMs":16464,"cues":[[5,140],[10,360],[16,680],[20,860],[23,1100],[33,1340],[47,1820],[50,3060],[59,3360],[69,4040],[72,4480],[76,4600],[81,4780],[84,4980],[86,5080],[92,5220],[94,5680],[102,5820],[104,6240],[116,6360],[120,7820],[125,8000],[128,8300],[135,8680],[137,9080],[144,9220],[146,10420],[154,10540],[158,10900],[165,11120],[169,11460],[175,11600],[185,11960],[189,12420],[196,12680],[198,13180],[204,13260],[209,13440],[212,13620],[217,13840],[221,14180],[225,14340],[233,14540],[240,14880],[243,15180],[248,15380],[253,15660],[259,15920]]},"ch7-032":{"text":"I'm glad you told me. I hope it goes well. Really.","voiceUrl":"voices/chapter-7/ch7-032.mp3","durationMs":3264,"cues":[[4,220],[9,320],[13,520],[18,620],[22,800],[24,1600],[29,1660],[32,1800],[37,1880],[43,2080],[50,2860]]},"ch7-033":{"text":"I meant it. I also wanted to go somewhere I could stop holding my expression together. Both things sat inside me while she answered. Later, as that relationship found its place in her life, our habits changed. The invitations grew less frequent. Plans that once started with the two of us began somewhere else.","voiceUrl":"voices/chapter-7/ch7-033.mp3","durationMs":20400,"cues":[[2,220],[8,300],[12,600],[14,1680],[19,1760],[26,2040],[29,2280],[32,2380],[42,2580],[44,2940],[50,3000],[55,3180],[63,3500],[66,3840],[77,3960],[87,4500],[92,5580],[99,5940],[103,6480],[110,6780],[113,7300],[119,7600],[123,7820],[133,8020],[140,9120],[143,9720],[148,9900],[161,10080],[167,10740],[171,10960],[177,11180],[180,11480],[184,11580],[190,11760],[194,12440],[201,12580],[210,13040],[214,14100],[226,14200],[231,14980],[236,15500],[246,15760],[252,16820],[257,17260],[262,17440],[270,17660],[275,18060],[279,18200],[283,18320],[286,18500],[289,18660],[295,18880],[305,19640],[310,19980]]},"ch7-changed-plans":{"text":"I could still send her something funny and get a reply. That almost made the change harder to explain to myself. There was no single conversation I could point to and call the ending. I simply stopped assuming she would be free, and began putting the phone down before asking about places we had once said we should visit.","voiceUrl":"voices/chapter-7/ch7-changed-plans.mp3","durationMs":19440,"cues":[[2,180],[8,300],[14,620],[19,900],[23,1180],[33,1320],[39,1780],[43,2260],[47,2440],[49,2600],[56,2680],[61,4280],[68,4460],[73,4860],[77,5020],[84,5160],[91,5460],[94,5760],[102,5880],[105,6260],[113,6360],[119,7740],[123,7860],[126,7980],[133,8240],[146,8580],[148,9360],[154,9440],[160,9640],[163,9960],[167,10180],[172,10440],[176,10800],[184,10980],[186,12000],[193,12120],[201,12480],[210,12780],[214,13300],[220,13460],[223,13640],[229,13820],[233,14600],[239,14760],[247,15160],[251,15420],[257,15540],[262,15820],[269,16120],[276,16520],[282,16900],[289,17200],[292,17760],[296,17860],[301,18060],[306,18320],[309,18560],[316,18720],[322,18940]]},"ch7-034":{"text":"I stayed nearby until there was no longer the same place to stand. There wasn't a second confession or a final argument. Just evenings opening up where her company used to be, and the knowledge that she had found the kind of relationship she had told me she wanted.","voiceUrl":"voices/chapter-7/ch7-034.mp3","durationMs":15600,"cues":[[2,300],[9,460],[16,740],[22,1200],[28,1540],[32,1700],[35,1940],[42,2140],[46,2480],[51,2620],[57,2860],[60,3180],[67,3360],[73,4760],[80,4900],[82,5220],[89,5320],[100,5700],[103,6400],[105,6580],[111,6700],[121,7120],[126,8360],[135,8680],[143,9160],[146,9520],[152,9700],[156,9900],[164,10060],[169,10520],[172,10720],[176,10840],[180,11600],[184,11700],[194,11800],[199,12280],[203,12460],[207,12580],[213,12720],[217,13000],[222,13100],[225,13320],[238,13420],[242,14200],[246,14320],[251,14460],[254,14720],[258,14900],[265,15040]]},"ch7-035":{"text":"At home, I opened a picture from one of our outings. The table, the food, the lighting we had made fun of. I remembered being happy there. Then I locked the phone and sat in the quiet, exhausted by how often happiness had become something I could only visit afterwards.","voiceUrl":"voices/chapter-7/ch7-035.mp3","durationMs":19752,"cues":[[3,100],[9,240],[11,1100],[18,1220],[20,1460],[28,1560],[33,1940],[37,2120],[40,2240],[44,2360],[53,2560],[57,3620],[64,3740],[68,4440],[74,4620],[78,5460],[87,5600],[90,6020],[94,6100],[99,6240],[103,6460],[107,6680],[109,7820],[120,7880],[126,8260],[132,8500],[139,8820],[144,10320],[146,10780],[153,10900],[157,11220],[163,11320],[167,11920],[171,12120],[174,12340],[178,12420],[185,12560],[195,13860],[198,14660],[202,14900],[208,15240],[218,15620],[222,16160],[229,16320],[239,16680],[241,17320],[247,17400],[252,17620],[258,18040],[269,18960]]},"ch7-036":{"text":"I had tried speaking quickly. I had tried waiting. I had finally said what I felt and accepted a clear no. Still, I was here again. The room seemed to hold every earlier disappointment at once, until the life I had imagined felt as if it had come down around me.","voiceUrl":"voices/chapter-7/ch7-036.mp3","durationMs":18864,"cues":[[2,180],[6,220],[12,380],[21,780],[30,1120],[32,1900],[36,1940],[42,2080],[51,2400],[53,3740],[57,3760],[65,3900],[70,4320],[75,4540],[77,4720],[82,4880],[86,5380],[95,5720],[97,6220],[103,6340],[107,7000],[114,8400],[116,8720],[120,8780],[125,8940],[132,9120],[136,10180],[141,10320],[148,10720],[151,11140],[156,11280],[162,11640],[170,12020],[185,12420],[188,13120],[194,13360],[200,14460],[204,14740],[209,14880],[211,15380],[215,15460],[224,15600],[229,16540],[232,16880],[235,17080],[238,17260],[242,17380],[247,17540],[252,17820],[259,18140],[262,18540]]},"ch7-037":{"text":"Maybe that's enough. Maybe I just stop looking for love.","voiceUrl":"voices/chapter-7/ch7-037.mp3","durationMs":4464,"cues":[[6,140],[13,380],[21,560],[27,1660],[29,2100],[34,2240],[39,2860],[47,3400],[51,3940],[56,4080]]},"ch7-038":{"text":"I said it into an empty room. There was no one to challenge me, no new message to interrupt the thought. I wanted to mean it. I wanted the wanting itself to stop, so I could get through a day without feeling that some essential part of my life was missing.","voiceUrl":"voices/chapter-7/ch7-038.mp3","durationMs":17760,"cues":[[2,140],[7,320],[10,520],[15,800],[18,1060],[24,1180],[30,1520],[36,2840],[40,2980],[43,3140],[47,3280],[50,3460],[60,3600],[64,4100],[67,4720],[71,5060],[79,5320],[82,5840],[92,5960],[96,6400],[105,6540],[107,7880],[114,8039],[117,8700],[122,8840],[126,9100],[128,9840],[135,9960],[139,10660],[147,10840],[154,11320],[157,11920],[163,12140],[166,12540],[168,12740],[174,12820],[178,13020],[186,13300],[188,13620],[192,13780],[200,14060],[208,14500],[213,14900],[218,15120],[228,15420],[233,16140],[236,16360],[239,16480],[244,16700],[248,17040],[256,17240]]},"ch8-001":{"text":"Just when I thought I had nothing left to ask for, a different thought settled in my heart: go to the holy land. It came quietly. No sudden certainty that everything would work out, no explanation for the years behind me. Only a pull towards somewhere I had wanted to go, for reasons deeper than this latest hurt.","voiceUrl":"voices/chapter-8/ch8-001.mp3","durationMs":21120,"cues":[[5,160],[10,440],[12,620],[20,700],[22,960],[26,1000],[34,1200],[39,1540],[42,1740],[46,1900],[51,2160],[53,2960],[63,3080],[71,3640],[79,4240],[82,4560],[85,4680],[92,4860],[95,5760],[98,6180],[102,6340],[107,6500],[113,6860],[116,8039],[121,8160],[130,8440],[133,9480],[140,9780],[150,10260],[155,10800],[166,10960],[172,11340],[177,11520],[182,11840],[185,12080],[197,12600],[201,13480],[205,13620],[211,13780],[218,14140],[222,14580],[227,15380],[229,15680],[234,15840],[242,16360],[252,16720],[254,17220],[258,17260],[265,17440],[268,17720],[272,17840],[276,18500],[284,18660],[291,19140],[296,19580],[301,19900],[308,20200],[313,20620]]},"ch8-002":{"text":"By January 2026, I was ready to listen to it. I wanted peace. Blessings. Space for doa, and the chance to bring the things I couldn't explain to God without first arranging them into a story that made me sound stronger than I felt.","voiceUrl":"voices/chapter-8/ch8-002.mp3","durationMs":18624,"cues":[[3,100],[11,340],[17,1060],[19,2700],[23,2800],[29,3040],[32,3420],[39,3540],[42,3860],[46,3980],[48,5280],[55,5380],[62,5900],[73,7340],[79,8760],[83,9220],[88,9460],[92,10680],[96,10800],[103,10940],[106,11280],[112,11380],[116,11600],[123,11740],[125,12120],[134,12260],[142,12560],[145,13100],[149,13260],[157,13680],[163,14120],[173,14420],[178,14920],[183,15120],[185,15340],[191,15500],[196,16040],[201,16320],[204,16600],[210,16880],[219,17360],[224,17840],[226,18060],[231,18200]]},"ch8-003":{"text":"Imran, I'm thinking of going for Umrah. Properly thinking about it. Would you come with me?","voiceUrl":"voices/chapter-8/ch8-003.mp3","durationMs":4152,"cues":[[7,120],[11,700],[20,840],[23,1100],[29,1180],[33,1400],[40,1540],[49,2120],[58,2540],[64,2800],[68,2980],[74,3420],[78,3540],[83,3640],[88,3780],[91,3920]]},"ch8-004":{"text":"He was a good friend, the kind who could hear a serious question without immediately covering it with a joke. He asked about the trip, let me explain what I had looked at, and listened when I ran out of practical details and admitted I just needed to go.","voiceUrl":"voices/chapter-8/ch8-004.mp3","durationMs":16080,"cues":[[3,100],[7,220],[9,360],[14,440],[22,660],[26,1800],[31,1900],[35,2200],[41,2320],[46,2540],[48,2880],[56,3040],[65,3480],[73,3920],[85,4320],[94,4920],[97,5280],[102,5400],[104,5560],[110,5680],[113,6980],[119,7160],[125,7420],[129,7620],[135,7780],[139,8720],[142,8860],[150,9000],[155,9740],[157,10040],[161,10100],[168,10240],[172,10540],[176,11140],[185,11300],[190,11820],[192,12020],[196,12120],[200,12400],[203,12520],[213,12640],[221,13120],[225,13620],[234,13780],[236,14460],[241,14620],[248,15180],[251,15500],[254,15660]]},"ch8-005":{"text":"Let's look at it together. You don't have to figure out everything by yourself.","voiceUrl":"voices/chapter-8/ch8-005.mp3","durationMs":7920,"cues":[[6,160],[11,460],[14,660],[17,780],[27,940],[31,2680],[37,2800],[42,3040],[45,3220],[52,3360],[56,3700],[67,3960],[70,4480],[79,4720]]},"ch8-006":{"text":"That January, we booked the journey. Makkah and Madinah were names I had carried for years; now they were part of a trip I was actually making. I read the confirmation more than once. For the first time in a while, something ahead of me felt possible without depending on whether someone could love me back.","voiceUrl":"voices/chapter-8/ch8-006.mp3","durationMs":19584,"cues":[[5,140],[14,360],[17,1140],[24,1340],[28,1780],[37,1920],[44,3100],[48,3540],[56,3800],[61,4340],[67,4500],[69,4880],[73,4940],[81,5100],[85,5440],[92,5600],[96,6800],[101,7160],[106,7300],[111,7500],[114,7700],[116,7800],[121,7940],[123,8320],[127,8420],[136,8760],[144,9340],[146,10820],[151,10900],[155,11080],[168,11180],[173,11940],[178,12140],[184,12340],[188,13200],[192,13320],[198,13440],[203,13700],[206,13920],[208,14020],[215,14140],[225,14660],[231,15200],[234,15440],[237,15560],[242,15760],[251,16059],[259,16620],[269,16980],[272,17480],[280,17640],[288,18000],[294,18440],[299,18640],[302,18900],[307,19120]]},"ch8-007":{"text":"Packing was ordinary enough to steady me. Clothes folded badly, documents checked, the charger I nearly forgot. I kept moving an item from one side of the bag to the other as if there were a perfect arrangement. The hurt was still there, but now my hands had something useful to do around it.","voiceUrl":"voices/chapter-8/ch8-007.mp3","durationMs":18240,"cues":[[8,120],[12,540],[21,780],[28,1220],[31,1500],[38,1640],[42,1980],[50,2440],[57,3040],[64,3440],[74,4200],[83,4840],[87,5460],[95,5580],[97,6220],[104,6320],[112,6600],[114,7740],[119,7840],[126,8180],[129,8480],[134,8680],[139,8980],[143,9200],[148,9420],[151,9660],[155,9760],[159,9880],[162,10140],[166,10240],[172,10400],[175,10660],[178,10860],[184,11020],[189,11220],[191,11420],[199,11600],[212,12060],[216,13520],[221,13660],[225,14080],[231,14260],[238,14520],[242,15300],[246,15480],[249,15660],[255,15840],[259,16180],[269,16440],[276,16860],[279,17300],[282,17420],[289,17620],[292,17980]]},"ch8-008":{"text":"At the airport, Imran stood beside me while I checked my pockets again. Around us, people counted bags and called to family members. I had imagined leaving would feel momentous. Mostly, I felt tired, slightly nervous, and grateful that somebody knew where I was supposed to be.","voiceUrl":"voices/chapter-8/ch8-008.mp3","durationMs":18072,"cues":[[3,60],[7,180],[16,320],[22,1120],[28,1600],[35,1800],[38,2200],[44,2380],[46,2580],[54,2680],[57,2940],[65,3120],[72,3480],[79,4500],[83,4920],[90,5140],[98,5420],[103,5780],[107,6220],[114,6400],[117,6620],[124,6760],[133,7100],[135,8440],[139,8500],[148,8600],[156,9260],[162,9720],[167,9940],[178,10380],[186,11920],[188,12600],[193,12700],[200,13180],[209,13980],[218,14400],[222,14920],[231,15220],[236,15740],[245,16020],[250,16480],[256,16740],[258,16940],[262,17020],[271,17160],[274,17540],[277,17660]]},"ch8-009":{"text":"Passport still there? Good. Come, let's go. One thing at a time.","voiceUrl":"voices/chapter-8/ch8-009.mp3","durationMs":7512,"cues":[[9,120],[15,800],[22,1120],[28,2300],[34,3420],[40,4160],[44,4460],[48,5420],[54,5880],[57,6460],[59,6640],[64,6820]]},"ch8-010":{"text":"One thing at a time I can do.","voiceUrl":"voices/chapter-8/ch8-010.mp3","durationMs":1992,"cues":[[4,140],[10,320],[13,500],[15,580],[20,700],[22,1300],[26,1400],[29,1620]]},"ch8-011":{"text":"During the journey, I slept unevenly and woke with the old ache still familiar. Then I remembered where we were going. I didn't need to arrive as a repaired version of myself. I could arrive tired, carrying questions, wanting peace without knowing what peace would feel like.","voiceUrl":"voices/chapter-8/ch8-011.mp3","durationMs":19032,"cues":[[7,120],[11,420],[20,580],[22,960],[28,1120],[37,1420],[41,2400],[46,2560],[51,2920],[55,3080],[59,3260],[64,3640],[70,3960],[80,4220],[85,5680],[87,5880],[98,5980],[104,6460],[107,6680],[112,6780],[119,6940],[121,8020],[128,8080],[133,8400],[136,8680],[143,8820],[146,9360],[148,9480],[157,9560],[165,10060],[168,10380],[176,10520],[178,11680],[184,11760],[191,11920],[198,12680],[207,13680],[218,14260],[226,15620],[232,16160],[240,16580],[248,16960],[253,17340],[259,17660],[265,18020],[270,18260],[275,18540]]},"ch8-012":{"text":"When we arrived in the holy land, I paused with my bag in my hand. Imran waited beside me. The air beyond the doors felt unfamiliar against my face. I was here. After all that thinking about leaving, all those small preparations, I had reached the beginning of this different journey.","voiceUrl":"voices/chapter-8/ch8-012.mp3","durationMs":20160,"cues":[[5,160],[8,340],[16,480],[19,940],[23,1040],[28,1120],[34,1380],[36,2260],[43,2400],[48,2880],[51,3060],[55,3220],[58,3480],[61,3560],[67,3740],[73,4820],[80,5220],[87,5500],[91,5900],[95,7040],[99,7200],[106,7380],[110,7600],[116,7740],[121,8160],[132,8720],[140,9400],[143,9760],[149,9960],[151,11280],[155,11360],[161,11640],[167,13000],[171,13320],[176,13500],[185,13720],[191,14060],[200,14340],[204,15300],[210,15400],[216,15660],[230,16000],[232,16780],[236,16820],[244,16960],[248,17460],[258,17580],[261,18320],[266,18460],[276,18940],[284,19600]]},"ch9-001":{"text":"I had come for Umrah with a tired heart and very little idea of how to rest it. Now that we were here, I wanted to stop rehearsing everything that had gone wrong. I wanted to pay attention, make space for worship, and understand what I had been carrying for so long.","voiceUrl":"voices/chapter-9/ch9-001.mp3","durationMs":18240,"cues":[[2,140],[6,180],[11,400],[15,640],[21,880],[26,1240],[28,1400],[34,1540],[40,2000],[44,3060],[49,3280],[56,3620],[61,3920],[64,4200],[68,4340],[71,4480],[76,4600],[80,4920],[84,5860],[89,6100],[92,6280],[97,6400],[103,6640],[105,7640],[112,7740],[115,8020],[120,8180],[131,8480],[142,9160],[147,9700],[151,9820],[156,10000],[163,10260],[165,11620],[172,11700],[175,11940],[179,12060],[190,12200],[195,13260],[201,13560],[205,14020],[214,14220],[218,15340],[229,15560],[234,16200],[236,16400],[240,16440],[245,16580],[254,16800],[258,17300],[261,17520],[266,17740]]},"ch9-002":{"text":"Come, Aleem. We can put our things down first. You're looking at everything at once.","voiceUrl":"voices/chapter-9/ch9-002.mp3","durationMs":5904,"cues":[[6,160],[13,440],[16,1540],[20,1640],[24,1800],[28,1980],[35,2140],[40,2460],[47,2860],[54,3960],[62,4160],[65,4440],[76,4580],[79,4960],[84,5120]]},"ch9-003":{"text":"There were other people to get to know in our tour group. Faces became names, then familiar places to look when somebody called for us. I stood beside Imran and listened, still feeling the strangeness of being so far from my usual days. Then I heard a voice I already knew.","voiceUrl":"voices/chapter-9/ch9-003.mp3","durationMs":18792,"cues":[[6,160],[11,340],[17,540],[24,780],[27,1100],[31,1200],[34,1360],[39,1480],[42,1860],[46,2000],[51,2220],[58,2480],[64,3600],[71,4140],[78,4500],[83,5400],[92,5740],[99,6180],[102,6680],[107,6840],[112,7120],[121,7400],[128,7740],[132,8020],[136,8200],[138,9300],[144,9420],[151,9660],[157,10140],[161,10720],[171,10980],[177,11660],[185,11900],[189,12220],[201,12400],[204,13060],[210,13180],[213,13520],[217,13840],[222,14200],[225,14400],[231,14660],[237,15080],[242,16480],[244,16660],[250,16740],[252,16900],[258,17000],[260,17880],[268,18000],[273,18420]]},"ch9-004":{"text":"Aleem? Eh. You're in this group also?","voiceUrl":"voices/chapter-9/ch9-004.mp3","durationMs":3840,"cues":[[7,100],[11,1500],[18,2240],[21,2480],[26,2620],[32,2800],[37,3100]]},"ch9-005":{"text":"Nadiah. For a moment I could only look at her. The same girl from my National Service years, standing among people I had expected to meet for the first time. I had travelled here with the thought of setting my hurt down. One of the people at the centre of it had arrived too.","voiceUrl":"voices/chapter-9/ch9-005.mp3","durationMs":18240,"cues":[[8,160],[12,1460],[14,1580],[21,1680],[23,2100],[29,2160],[34,2340],[39,2640],[42,2820],[47,2940],[51,3960],[56,4080],[61,4380],[66,4740],[69,4900],[78,5060],[86,5540],[93,5980],[102,6800],[108,7180],[115,7480],[117,8080],[121,8100],[130,8240],[133,8680],[138,8780],[142,8960],[146,9080],[152,9200],[158,9460],[160,10720],[164,10760],[174,10920],[179,11320],[184,11880],[188,12100],[196,12240],[199,12520],[207,12660],[210,12960],[215,13180],[221,13580],[225,14980],[228,15080],[232,15200],[239,15340],[242,15620],[246,15740],[253,15900],[256,16180],[259,16340],[263,16880],[271,17040],[275,17720]]},"ch9-006":{"text":"Nadiah. Yeah. I'm here with my friend. I didn't know you were coming.","voiceUrl":"voices/chapter-9/ch9-006.mp3","durationMs":5352,"cues":[[8,200],[14,1260],[18,1940],[23,2080],[28,2200],[31,2340],[39,2500],[41,3580],[48,3720],[53,4080],[57,4300],[62,4380],[69,4560]]},"ch9-007":{"text":"She wore a hijab, its edge framing the face that had stayed in my memory through years of trying not to think about it. She smiled at my surprise. I remembered that smile before I could decide what expression to offer back. My body had prepared for something painful; her greeting was simply warm.","voiceUrl":"voices/chapter-9/ch9-007.mp3","durationMs":20640,"cues":[[4,140],[9,340],[11,580],[18,660],[22,1520],[27,1740],[35,2020],[39,2420],[44,2580],[49,2980],[53,3100],[60,3340],[63,3620],[66,3760],[73,4000],[81,4420],[87,4800],[90,5240],[97,5420],[101,5780],[104,6040],[110,6180],[116,6420],[120,6680],[124,7580],[131,7760],[134,8100],[137,8200],[147,8400],[149,9800],[160,9880],[165,10700],[171,10960],[178,11680],[180,11980],[186,12060],[193,12220],[198,12640],[209,12800],[212,13340],[218,13480],[224,13760],[227,14900],[232,15100],[236,15420],[245,15600],[249,16040],[259,16200],[268,16660],[272,18080],[281,18240],[285,18720],[292,19680],[297,20100]]},"ch9-008":{"text":"I didn't know either. You look so shocked. Say hello properly first, can?","voiceUrl":"voices/chapter-9/ch9-008.mp3","durationMs":6000,"cues":[[2,220],[9,320],[14,620],[22,880],[26,1980],[31,2120],[34,2340],[43,2600],[47,3840],[53,4059],[62,4400],[69,4960],[73,5440]]},"ch9-009":{"text":"Hello properly. Sorry, my brain needs a bit of time.","voiceUrl":"voices/chapter-9/ch9-009.mp3","durationMs":3360,"cues":[[6,120],[16,580],[23,1900],[26,2180],[32,2340],[38,2560],[40,2720],[44,2780],[47,2880],[52,3000]]},"ch9-010":{"text":"She laughed, and something inside me loosened enough for me to laugh too. There were people moving around us, bags in the way, another conversation waiting to include her. We had only a few ordinary minutes. Afterwards, I kept returning to how ordinary they had felt. I hadn't needed to defend myself from her voice.","voiceUrl":"voices/chapter-9/ch9-010.mp3","durationMs":20160,"cues":[[4,100],[13,320],[17,1060],[27,1220],[34,1540],[37,1980],[46,2180],[53,2600],[57,2920],[60,3080],[63,3240],[69,3380],[74,3700],[80,4880],[85,5020],[92,5200],[99,5540],[106,5860],[110,6220],[115,6660],[118,7040],[122,7160],[127,7300],[135,7860],[148,8200],[156,8920],[159,9320],[167,9460],[172,9880],[175,10860],[179,10940],[184,11120],[186,11380],[190,11500],[199,11860],[208,12360],[220,13180],[222,13940],[227,14000],[237,14280],[240,14780],[244,14880],[253,15220],[258,15980],[262,16079],[268,16239],[270,17360],[277,17440],[284,17780],[287,18140],[294,18260],[301,18760],[306,19260],[310,19460],[316,19660]]},"ch9-reunion-after":{"text":"I sat down with the fact of it once she had moved away. The same Nadiah. I could still picture myself in camp, trying to keep the shock from showing on my face. Yet the person who had just greeted her was older. My own voice had surprised me almost as much as hers: a little awkward, but free of the accusation I had imagined it would carry.","voiceUrl":"voices/chapter-9/ch9-reunion-after.mp3","durationMs":22224,"cues":[[2,260],[6,360],[11,600],[16,880],[20,1000],[25,1140],[28,1380],[31,1480],[36,1800],[40,1980],[44,2080],[50,2220],[56,2480],[60,3900],[65,4040],[73,4360],[75,5540],[81,5600],[87,5800],[95,6100],[102,6400],[105,6800],[111,6960],[118,7680],[121,7900],[126,8020],[130,8200],[136,8320],[141,8600],[149,8820],[152,9120],[155,9240],[161,9420],[165,10840],[169,11000],[176,11140],[180,11520],[184,11600],[189,11760],[197,11980],[201,12360],[205,12540],[212,12820],[215,14240],[219,14400],[225,14620],[229,14940],[239,15080],[242,15540],[249,15740],[252,16140],[257,16280],[260,16480],[266,16620],[268,17980],[275,18060],[284,18400],[288,18880],[293,19700],[296,19940],[300,20040],[311,20180],[313,20820],[317,20880],[326,21020],[329,21480],[335,21600],[341,21780]]},"ch9-011":{"text":"Among the people we began spending time with were Kak Mariam and her husband, Abang Yusuf. Mariam noticed when someone was standing awkwardly at the edge of a conversation. She made space with a small shift of her chair and a wave, as though there had always been a place intended for them.","voiceUrl":"voices/chapter-9/ch9-011.mp3","durationMs":18240,"cues":[[6,120],[10,420],[17,560],[20,900],[26,1020],[35,1420],[40,1820],[45,2080],[50,2800],[54,3000],[61,3280],[65,4040],[69,4200],[78,4360],[84,5240],[91,5580],[98,6840],[106,7240],[111,7760],[119,8039],[123,8360],[132,8540],[142,9000],[145,9680],[149,9800],[154,9940],[157,10120],[159,10220],[173,10300],[177,11800],[182,11940],[188,12220],[193,12680],[195,12840],[201,12940],[207,13220],[210,13480],[214,13560],[220,13740],[224,14220],[226,14380],[232,14480],[235,15320],[242,15460],[248,15880],[252,16040],[259,16300],[264,16760],[266,16880],[272,16980],[281,17260],[285,17780],[290,17960]]},"ch9-012":{"text":"Aleem, sit lah. There's space here. You and your friend have eaten?","voiceUrl":"voices/chapter-9/ch9-012.mp3","durationMs":5040,"cues":[[7,160],[11,820],[16,1100],[24,1780],[30,2080],[36,2420],[40,3700],[44,3820],[49,3960],[56,4140],[61,4400],[67,4600]]},"ch9-013":{"text":"Careful how you answer. If you hesitate, she will decide you haven't.","voiceUrl":"voices/chapter-9/ch9-013.mp3","durationMs":5520,"cues":[[8,200],[12,660],[16,880],[24,1100],[27,1900],[31,2060],[41,2200],[45,3060],[50,3260],[57,3460],[61,4340],[69,4500]]},"ch9-014":{"text":"Mariam gave him a look that seemed to have a whole marriage behind it. He smiled and moved something off the spare seat. I liked being near them. Their kindness asked for very little in return: an answer, a bit of conversation, the chance to make sure we were all right. I stopped feeling like a stranger so quickly.","voiceUrl":"voices/chapter-9/ch9-014.mp3","durationMs":21840,"cues":[[7,140],[12,600],[16,800],[18,940],[23,1040],[28,1300],[35,1500],[38,1720],[43,1820],[45,2000],[51,2100],[60,2520],[67,3040],[71,3400],[74,4220],[81,4420],[85,4900],[91,5200],[101,5540],[105,5940],[109,6100],[115,6260],[121,6580],[123,7740],[129,7840],[135,8160],[140,8420],[146,8620],[152,9400],[161,9600],[167,10480],[171,10840],[176,11060],[183,11420],[186,11680],[194,11840],[197,13140],[205,13280],[207,14300],[211,14380],[214,14520],[228,14640],[232,16120],[239,16239],[242,16580],[247,16680],[252,16920],[255,17400],[260,17600],[264,17820],[271,18000],[273,19320],[281,19440],[289,19820],[294,20200],[296,20380],[305,20500],[308,21060],[316,21280]]},"ch9-015":{"text":"In Makkah, I tried to let the purpose of the trip settle around me. There was room in a day for things I usually pushed aside. Sometimes I noticed how quickly I reached for my phone whenever a quiet moment opened. I began leaving it in my pocket a little longer, allowing myself to remain where I was.","voiceUrl":"voices/chapter-9/ch9-015.mp3","durationMs":19752,"cues":[[3,160],[11,340],[13,1280],[19,1400],[22,1700],[26,1820],[30,2020],[38,2160],[41,2540],[45,2660],[50,2800],[57,3120],[64,3400],[68,3820],[74,4620],[78,4740],[83,4980],[86,5440],[88,5580],[92,5680],[96,5960],[103,6120],[105,6500],[113,6660],[120,7120],[127,7400],[137,8600],[139,9100],[147,9200],[151,9580],[159,9800],[161,10200],[169,10320],[173,10680],[176,10820],[182,11040],[191,11480],[193,11840],[199,11960],[206,12320],[214,12720],[216,13900],[222,13980],[230,14360],[233,14700],[236,14820],[239,14940],[246,15160],[248,15840],[255,15920],[263,16180],[272,17160],[279,17580],[282,18020],[289,18160],[295,18960],[297,19200],[301,19320]]},"ch9-016":{"text":"Nadiah was there too, woven into the ordinary rhythm of the group. We greeted each other. We ended up within the same conversations. Each encounter was small, but the accumulated fear I had attached to seeing her again did not match what happened. I could look up, find her nearby, and feel pleased before I felt anything else.","voiceUrl":"voices/chapter-9/ch9-016.mp3","durationMs":24000,"cues":[[7,160],[11,580],[17,780],[22,1020],[28,1940],[33,2520],[37,2760],[46,2980],[53,3560],[56,3900],[60,4040],[67,4160],[70,5380],[78,5520],[83,5920],[90,6160],[93,7080],[99,7220],[102,7540],[109,7700],[113,7980],[118,8119],[133,8380],[138,10060],[148,10260],[152,10840],[159,11340],[163,11940],[167,12220],[179,12360],[184,13180],[186,13540],[190,13600],[199,13760],[202,14420],[209,14580],[213,14840],[219,15000],[223,15880],[227,16079],[233,16379],[238,16780],[248,16940],[250,18400],[256,18460],[261,18620],[265,18880],[270,19520],[274,19800],[282,20020],[286,21080],[291,21280],[299,21580],[306,22380],[308,22740],[313,22880],[322,23180],[327,23580]]},"ch9-017":{"text":"It was the way she listened that I recognised most. She turned towards the person speaking and waited for the rest of the sentence. When she teased me, her eyes gave the joke away before her mouth did. I began to feel that she had returned to the person I once knew, the person I had loved.","voiceUrl":"voices/chapter-9/ch9-017.mp3","durationMs":17520,"cues":[[3,100],[7,240],[11,420],[15,520],[19,720],[28,940],[33,1740],[35,1900],[46,2000],[52,2640],[56,3820],[63,4000],[71,4300],[75,4700],[82,4800],[91,5200],[95,5580],[102,5740],[106,6080],[110,6200],[115,6280],[118,6540],[122,6640],[132,6760],[137,8060],[141,8200],[148,8400],[152,8780],[156,9340],[161,9540],[166,9840],[170,10060],[175,10160],[180,10380],[187,10620],[191,10920],[197,11080],[202,11420],[204,12520],[210,12600],[213,12860],[218,12980],[223,13220],[227,13380],[231,13500],[240,13600],[243,14080],[247,14180],[254,14280],[256,14660],[261,14780],[267,15020],[271,16040],[278,16160],[280,16780],[284,16840],[290,17020]]},"ch9-018":{"text":"That was how it felt to me. I couldn't measure all the years between us by the sight of her hijab or a few warm conversations. Still, seeing her this way brought back a gentleness I had almost stopped allowing myself to remember. The old hurt no longer arrived every time the memory did.","voiceUrl":"voices/chapter-9/ch9-018.mp3","durationMs":19752,"cues":[[5,180],[9,380],[13,540],[16,660],[21,820],[24,1080],[28,1220],[30,2600],[39,2680],[47,3000],[51,3420],[55,3560],[61,3680],[69,3940],[72,4340],[75,4500],[79,4620],[85,4760],[88,4960],[92,5060],[98,5200],[101,5880],[103,6480],[107,6560],[112,6840],[127,7180],[134,9360],[141,9780],[145,10060],[150,10260],[154,10520],[162,11400],[167,11660],[169,12000],[180,12180],[182,13080],[186,13120],[193,13260],[201,13760],[210,14040],[217,14400],[220,14840],[230,14940],[234,16560],[238,16700],[243,16960],[246,17400],[253,17560],[261,17920],[267,18420],[272,18660],[276,18900],[283,19000],[287,19380]]},"ch9-019":{"text":"When we climbed Jabal Nur, there were five of us together at the beginning. I remember the company more clearly than any precise arrangement: voices close enough to answer, people checking their footing, the small negotiations of finding a pace. Nadiah was among us. At first, speaking to her was part of speaking to everyone.","voiceUrl":"voices/chapter-9/ch9-019.mp3","durationMs":21600,"cues":[[5,120],[8,300],[16,480],[22,960],[27,1320],[33,2100],[38,2220],[43,2400],[46,2660],[49,2780],[58,2980],[61,3320],[65,3420],[76,3520],[78,5080],[87,5160],[91,5520],[99,5640],[104,6040],[112,6260],[117,6640],[121,6940],[129,7140],[142,7580],[149,8860],[155,9480],[162,9760],[165,9960],[173,10120],[180,11080],[189,11560],[195,11880],[204,12080],[208,13080],[214,13240],[227,13520],[230,14520],[238,14720],[240,15040],[246,15160],[253,16560],[257,16960],[263,17120],[267,17420],[270,18460],[277,18620],[286,19160],[289,19540],[293,19660],[297,19900],[302,20100],[305,20300],[314,20460],[317,20820],[326,20980]]},"ch9-020":{"text":"The climb gave our conversation a different rhythm. A few words, then breath. A glance towards the next stretch before looking back at the person beside me. I couldn't fill every silence with something clever even if I wanted to. We kept moving, and the little group gradually stopped moving as one.","voiceUrl":"voices/chapter-9/ch9-020.mp3","durationMs":18720,"cues":[[4,120],[10,240],[15,620],[19,800],[32,980],[34,1640],[44,1740],[52,2080],[54,3260],[58,3360],[65,3580],[70,4340],[78,4560],[80,5640],[87,5720],[95,6120],[99,6560],[104,6660],[112,6940],[119,7380],[127,7680],[132,7960],[135,8140],[139,8220],[146,8340],[153,8660],[157,9060],[159,10220],[168,10300],[173,10580],[179,10940],[187,11280],[192,11700],[202,11880],[209,12260],[214,12880],[217,13080],[219,13220],[226,13320],[230,13700],[233,14960],[238,15100],[246,15360],[250,16239],[254,16340],[261,16440],[267,16680],[277,16980],[285,17500],[292,17860],[295,18140],[299,18360]]},"ch9-climb-rhythm":{"text":"I watched the ground more than her face at first. It gave me something practical to concentrate on while the surprise of having her nearby settled. Then she said something I hadn't caught. I turned, asked her to repeat it, and found myself smiling at how easily we could do that. I didn't have to pretend I had heard everything perfectly.","voiceUrl":"voices/chapter-9/ch9-climb-rhythm.mp3","durationMs":20160,"cues":[[2,140],[10,200],[14,520],[21,660],[26,1160],[31,1320],[35,1480],[40,1660],[43,1880],[50,2060],[53,3140],[58,3260],[61,3480],[71,3640],[81,4080],[84,4640],[96,4740],[99,5320],[105,5620],[109,5820],[118,5940],[121,6380],[128,6500],[132,6780],[139,6980],[148,7540],[153,8620],[157,8960],[162,9100],[172,9300],[174,9660],[181,9740],[189,10060],[191,11340],[199,11460],[205,12380],[209,12660],[212,12860],[219,12960],[223,13300],[227,14140],[233,14280],[240,14480],[248,14900],[251,15260],[255,15380],[262,15700],[265,16079],[271,16200],[274,16360],[280,16560],[282,17480],[289,17540],[294,17760],[297,17920],[305,18020],[307,18560],[311,18640],[317,18760],[328,19020],[338,19440]]},"ch9-021":{"text":"Five became fewer. Somewhere in the ordinary changes of pace and pauses, the others were no longer beside us. When I looked around, it was just Nadiah and me. Nobody had announced that we should be together. I hadn't manoeuvred to make it happen. Yet there she was, close enough to hear me speak without raising my voice.","voiceUrl":"voices/chapter-9/ch9-021.mp3","durationMs":22632,"cues":[[5,100],[12,460],[19,840],[29,2120],[32,2580],[36,2680],[45,2860],[53,3380],[56,3820],[61,4000],[65,4400],[73,4680],[77,5680],[84,5860],[89,6240],[92,6400],[99,6560],[106,6840],[110,7260],[115,8240],[117,8420],[124,8500],[132,8720],[135,9200],[139,9300],[144,9520],[151,10020],[155,10740],[159,11000],[166,12320],[170,12680],[180,12840],[185,13520],[188,13680],[195,13820],[198,14000],[208,14160],[210,15260],[217,15340],[228,15760],[231,16440],[236,16580],[239,16740],[247,16860],[251,17300],[257,18260],[261,18460],[266,18660],[272,19720],[279,20020],[282,20280],[287,20420],[290,20620],[296,20860],[304,21160],[312,21560],[315,21920],[321,22120]]},"ch9-022":{"text":"How did we end up just the two of us?","voiceUrl":"voices/chapter-9/ch9-022.mp3","durationMs":3120,"cues":[[4,200],[8,520],[11,700],[15,920],[18,1300],[23,1580],[27,1900],[31,2120],[34,2380],[37,2580]]},"ch9-023":{"text":"I was going to ask you. Started with five, right? My counting still okay?","voiceUrl":"voices/chapter-9/ch9-023.mp3","durationMs":4152,"cues":[[2,260],[6,340],[12,440],[15,640],[19,780],[24,1000],[32,1640],[37,1900],[43,2180],[50,2520],[53,3080],[62,3340],[68,3640],[73,3800]]},"ch9-024":{"text":"She laughed and caught her breath. We paused where there was room to stand comfortably. For a little while we looked out instead of at each other. I could feel the effort in my legs and hear my own breathing settle. When she asked how I had been, the question had enough space around it for an honest answer.","voiceUrl":"voices/chapter-9/ch9-024.mp3","durationMs":18960,"cues":[[4,120],[12,340],[16,720],[23,900],[27,1080],[35,1240],[38,2300],[45,2480],[51,2980],[57,3120],[61,3280],[66,3460],[69,3680],[75,3840],[88,4280],[92,5420],[94,5520],[101,5600],[107,5840],[110,6240],[117,6420],[121,6740],[129,7180],[132,7560],[135,7680],[140,7800],[147,8039],[149,8880],[155,8940],[160,9140],[164,9360],[171,9580],[174,9920],[177,10040],[182,10260],[186,10800],[191,11100],[194,11300],[198,11480],[208,11700],[216,12200],[221,13520],[225,13680],[231,13920],[235,14360],[237,14600],[241,14660],[247,14840],[251,15680],[260,15820],[264,16460],[271,16600],[277,16920],[284,17220],[287,17560],[291,17740],[294,17860],[301,18060],[308,18460]]},"ch9-025":{"text":"So, how are you now? Work, life... everything? It's been so long.","voiceUrl":"voices/chapter-9/ch9-025.mp3","durationMs":9024,"cues":[[4,140],[8,1120],[12,1340],[16,1520],[21,1680],[27,2940],[35,4059],[47,5520],[52,7620],[57,7840],[60,8119],[65,8420]]},"ch9-sharing-tired":{"text":"I've been tired, honestly. I can do the normal things, go to work, laugh with people. But underneath that, a lot has been sitting there. I wanted some time to breathe properly.","voiceUrl":"voices/chapter-9/ch9-sharing-tired.mp3","durationMs":10464,"cues":[[5,200],[10,320],[17,480],[27,1040],[29,2140],[33,2220],[36,2380],[40,2540],[47,2640],[55,2900],[58,3620],[61,3720],[67,3820],[73,4380],[78,4600],[86,4740],[90,5620],[101,5840],[107,6300],[109,6740],[113,6860],[117,7120],[122,7280],[130,7480],[137,7760],[139,8760],[146,8840],[151,9080],[156,9220],[159,9480],[167,9620],[176,9960]]},"ch9-sharing-ordinary":{"text":"Working already. Some days I think I've got the routine sorted, then I get home and realise I forgot something simple again. Life is okay in many ways. I'm still figuring out the rest.","voiceUrl":"voices/chapter-9/ch9-sharing-ordinary.mp3","durationMs":12240,"cues":[[8,120],[17,480],[22,1620],[27,1780],[29,2260],[35,2340],[40,2520],[44,2620],[48,2760],[56,2840],[64,3240],[69,4059],[71,4200],[75,4260],[80,4420],[84,4820],[92,4960],[94,5480],[101,5500],[111,5820],[118,6200],[125,7160],[130,8520],[133,8720],[138,8840],[141,9140],[146,9240],[152,9440],[156,10300],[162,10560],[171,10860],[175,11240],[179,11540],[184,11640]]},"ch9-sharing-peace":{"text":"I wanted peace. That's the simplest way to say it. I had things I kept going over in my head, and I wanted to come here with them. See what I could understand, or finally let go.","voiceUrl":"voices/chapter-9/ch9-sharing-peace.mp3","durationMs":10464,"cues":[[2,220],[9,260],[16,600],[23,1400],[27,1720],[36,1840],[40,2180],[43,2300],[47,2380],[51,2520],[53,3180],[57,3220],[64,3400],[66,3760],[71,3820],[77,4059],[82,4400],[85,4620],[88,4720],[94,4860],[98,5160],[100,5340],[107,5380],[110,5580],[115,5700],[120,6000],[125,6520],[131,6740],[135,7540],[140,7800],[142,7980],[148,8000],[160,8140],[163,8800],[171,9320],[175,9900],[178,10100]]},"ch9-sharing-join":{"text":"She listened without turning the answer into something I needed to defend. Then I asked about her. We exchanged the ordinary outlines of our present lives, pausing to clarify something, smiling when the years between updates became obvious. I found myself listening for what she was saying instead of rehearsing what I would say next.","voiceUrl":"voices/chapter-9/ch9-sharing-join.mp3","durationMs":21504,"cues":[[4,180],[13,400],[21,1080],[29,1480],[33,1760],[40,1920],[45,2220],[55,2440],[57,2820],[64,2940],[67,3280],[75,3380],[80,4760],[82,4980],[88,5100],[94,5420],[99,5700],[102,7020],[112,7120],[116,7920],[125,8080],[134,8660],[137,9220],[141,9340],[149,9560],[156,9960],[164,10640],[167,11080],[175,11200],[186,11740],[194,12420],[199,12940],[203,13100],[209,13240],[217,13580],[225,14000],[232,14480],[241,14880],[243,16320],[249,16420],[256,16680],[266,17120],[270,17580],[275,17740],[279,17980],[283,18200],[290,18420],[298,18980],[301,19360],[312,19480],[317,20080],[319,20380],[325,20460],[329,20680],[334,20920]]},"ch9-present-lives":{"text":"There were things each of us needed to explain from the beginning. We no longer knew all the people in the other's daily life, or what an ordinary afternoon looked like. That gap could have made me sad. Instead I liked hearing her fill a little of it. The girl I remembered was here, with years of living I hadn't been there to see.","voiceUrl":"voices/chapter-9/ch9-present-lives.mp3","durationMs":23352,"cues":[[6,120],[11,260],[18,420],[23,960],[26,1120],[29,1240],[36,1460],[39,1740],[47,1860],[52,2420],[56,2660],[67,2760],[70,4080],[73,4200],[80,4400],[85,4720],[89,5200],[93,5360],[100,5500],[103,5820],[107,5920],[115,6040],[121,6360],[127,6700],[130,7580],[135,7780],[138,7960],[147,8220],[157,8780],[164,9360],[170,9640],[175,10980],[179,11300],[185,12180],[190,12320],[195,12480],[198,12680],[203,12860],[211,14120],[213,15020],[219,15160],[227,15480],[231,15840],[236,16100],[238,16540],[245,16640],[248,16900],[252,17040],[256,18120],[261,18260],[263,18680],[274,18780],[278,19300],[284,19500],[289,20360],[295,20640],[298,21120],[305,21280],[307,21980],[314,22040],[319,22320],[325,22500],[328,22700],[332,22860]]},"ch9-026":{"text":"Last time you knew me, so much of my conversation was about camp. You must have been very patient.","voiceUrl":"voices/chapter-9/ch9-026.mp3","durationMs":6864,"cues":[[5,100],[10,380],[14,660],[19,760],[23,940],[26,1620],[31,2000],[34,2260],[37,2380],[50,2540],[54,3180],[60,3320],[66,3640],[70,4620],[75,4740],[80,4920],[85,5040],[90,5580],[98,5920]]},"ch9-027":{"text":"You always said civilian conversation was too fast for you. Now working already. Can keep up or not?","voiceUrl":"voices/chapter-9/ch9-027.mp3","durationMs":7680,"cues":[[4,160],[11,340],[16,720],[25,1020],[38,1520],[42,2260],[46,2480],[51,2720],[55,3080],[60,3300],[64,4120],[72,4400],[81,4840],[85,5880],[90,6120],[93,6400],[96,6920],[100,7080]]},"ch9-028":{"text":"Depends. If there are too many questions, I still need advance notice.","voiceUrl":"voices/chapter-9/ch9-028.mp3","durationMs":4632,"cues":[[9,160],[12,980],[18,1100],[22,1180],[26,1420],[31,1720],[42,1940],[44,2780],[50,2880],[55,3140],[63,3280],[70,3660]]},"ch9-029":{"text":"We remembered book-ins, the strange way a short weekend used to hold so much, how much conversation we had fitted into the edges of a day. I had kept those memories shut away with the ending for years. Now one of them came back and made me smile. She remembered it too. I hadn't imagined every good thing.","voiceUrl":"voices/chapter-9/ch9-029.mp3","durationMs":20712,"cues":[[3,100],[14,280],[24,880],[28,1980],[36,2160],[40,2580],[42,2760],[48,2900],[56,3220],[61,3800],[64,4000],[69,4120],[72,4520],[78,4740],[82,5640],[87,5760],[100,5980],[103,6720],[107,6820],[114,6960],[119,7280],[123,7480],[129,7620],[132,8060],[134,8140],[139,8260],[141,9620],[145,9660],[150,9820],[156,10100],[165,10340],[170,10900],[175,11100],[180,11400],[184,11540],[191,11660],[195,12020],[202,12260],[206,13560],[210,13820],[213,13940],[218,14040],[223,14260],[228,14480],[232,14720],[237,14840],[240,15040],[247,15260],[251,16480],[262,16720],[265,17120],[270,17320],[272,18700],[279,18760],[288,19040],[294,19680],[299,20060],[305,20280]]},"ch9-030":{"text":"There was no long account of who had hurt whom. We didn't settle the past on that mountain. We talked around familiar details and allowed some of them to be tender again. The air moved against my face while she spoke. I noticed that my shoulders had dropped, and that I was no longer choosing each word to keep myself protected.","voiceUrl":"voices/chapter-9/ch9-030.mp3","durationMs":20400,"cues":[[6,140],[10,320],[13,500],[18,700],[26,940],[29,1340],[33,1520],[37,1860],[42,2080],[48,2400],[51,3660],[58,3780],[65,4100],[69,4420],[74,4560],[77,4980],[82,5100],[92,5300],[95,6500],[102,6620],[109,6880],[118,7240],[126,7700],[130,8540],[138,8700],[143,9060],[146,9240],[151,9360],[154,9580],[157,9660],[164,9840],[171,10160],[175,11380],[179,11560],[185,11780],[193,12040],[196,12440],[201,12660],[207,12980],[211,13180],[218,13380],[220,14400],[228,14500],[233,15080],[236,15260],[246,15480],[250,15980],[259,16160],[263,16900],[268,17040],[270,17200],[274,17280],[277,17440],[284,17600],[293,17980],[298,18440],[303,18700],[306,18960],[311,19100],[318,19300],[328,19720]]},"ch9-memory-ease":{"text":"Once, we began remembering the same thing at the same time and both stopped to let the other finish. She waved for me to continue. It was such a small gesture, but I felt a sudden affection for the ease of it. For years I had remembered our ending more often than I remembered what it was like simply to talk to her.","voiceUrl":"voices/chapter-9/ch9-memory-ease.mp3","durationMs":22224,"cues":[[6,220],[9,900],[15,1060],[27,1460],[31,2060],[36,2220],[42,2540],[45,2940],[49,3060],[54,3260],[59,3600],[63,4640],[68,4800],[76,5140],[79,5660],[83,5780],[87,5960],[93,6060],[101,6280],[105,7420],[111,7600],[115,7960],[118,8080],[121,8240],[131,8340],[134,9220],[138,9340],[143,10260],[145,10460],[151,10640],[160,10980],[164,12060],[166,12220],[171,12340],[173,13200],[180,13340],[190,13700],[194,14500],[198,14640],[203,14860],[206,15180],[210,15300],[214,16219],[220,16440],[222,16960],[226,17020],[237,17180],[241,17760],[248,18060],[253,18540],[259,18800],[264,19100],[266,19300],[277,19400],[282,20080],[285,20220],[289,20300],[294,20460],[301,20800],[304,21200],[309,21400],[312,21820],[316,21960]]},"ch9-031":{"text":"When a silence came, I let it stay. I had once been frightened that a conversation ending meant I was becoming less important. Beside her here, I could take a breath without immediately finding a question. After a while she said something small about the climb, and we continued from there. Nothing had been lost in the pause.","voiceUrl":"voices/chapter-9/ch9-031.mp3","durationMs":22464,"cues":[[5,100],[7,240],[15,340],[21,840],[23,1660],[27,1740],[30,1900],[36,2140],[38,3680],[42,3680],[47,3840],[52,4059],[63,4260],[68,4920],[70,5040],[83,5120],[90,5920],[96,6460],[98,6760],[102,6840],[111,7000],[116,7480],[127,7860],[134,9540],[138,9980],[144,10360],[146,11460],[152,11520],[157,11640],[159,11800],[166,11900],[174,12340],[186,12660],[194,13280],[196,13660],[206,13760],[212,15420],[214,15660],[220,15760],[224,16200],[229,16420],[239,16680],[245,17080],[251,17440],[255,17660],[262,17780],[266,18440],[269,18640],[279,18780],[284,19260],[291,19420],[299,20580],[303,20860],[308,20960],[313,21160],[316,21780],[320,21880],[326,22000]]},"ch9-032":{"text":"Later, I kept thinking about that change from five people to two. Out of everyone in the group, out of all the possible ways a day could unfold, we had been given that stretch of time. I knew how ordinary the explanation might be. It still felt extraordinary to be the person walking beside her again.","voiceUrl":"voices/chapter-9/ch9-032.mp3","durationMs":22152,"cues":[[7,140],[9,940],[14,1040],[23,1320],[29,1780],[34,2040],[41,2280],[46,2740],[51,3080],[58,3480],[61,3880],[66,4080],[70,5280],[73,5440],[82,5680],[85,6120],[89,6220],[96,6340],[100,6940],[103,7060],[107,7300],[111,7480],[120,7700],[125,8260],[127,8600],[131,8700],[137,8920],[145,9080],[148,10360],[152,10860],[157,11020],[163,11240],[168,11640],[176,12020],[179,12280],[185,12440],[187,13920],[192,14020],[196,14360],[205,14700],[209,15300],[221,15460],[227,16219],[231,16480],[234,17600],[240,17800],[245,18140],[259,18620],[262,19640],[265,19760],[269,19900],[276,20060],[284,20680],[291,21080],[295,21520],[301,21680]]},"ch9-033":{"text":"Then it happened again at Jabal Rahmah. We were there with the group, and once more I found that the conversation nearest me belonged to Nadiah. We climbed, paused, looked around. The people who had been beside us were elsewhere. I turned towards her with a half-formed question, and saw that she had noticed too.","voiceUrl":"voices/chapter-9/ch9-033.mp3","durationMs":20640,"cues":[[5,140],[8,340],[17,480],[23,780],[26,1460],[32,1600],[40,2000],[43,3160],[48,3280],[54,3500],[59,3800],[63,3980],[70,4080],[74,4740],[79,4940],[84,5200],[86,5440],[92,5540],[97,5760],[101,5880],[114,5980],[122,6700],[125,7140],[134,7300],[137,7820],[145,7940],[148,9240],[157,9360],[165,10300],[172,11060],[180,11300],[184,12600],[191,12720],[195,13040],[199,13140],[204,13260],[211,13440],[214,13860],[219,14080],[230,14320],[232,15460],[239,15580],[247,16100],[251,16460],[256,16840],[258,17000],[270,17080],[280,17720],[284,18820],[288,19000],[293,19200],[297,19420],[301,19580],[309,19740],[313,20240]]},"ch9-034":{"text":"Again ah?","voiceUrl":"voices/chapter-9/ch9-034.mp3","durationMs":1680,"cues":[[6,160],[9,840]]},"ch9-035":{"text":"Apparently we keep choosing the same pace.","voiceUrl":"voices/chapter-9/ch9-035.mp3","durationMs":3360,"cues":[[11,120],[14,980],[19,1100],[28,1320],[32,1900],[37,2140],[42,2760]]},"ch9-rahmah-pause":{"text":"I looked back towards where I had last noticed the others, then turned to find her doing much the same thing. We both smiled. It felt like the start of a private joke, something that would need very little explanation if one of us mentioned it later. I caught myself wanting there to be a later in which we could mention it.","voiceUrl":"voices/chapter-9/ch9-rahmah-pause.mp3","durationMs":20472,"cues":[[2,100],[9,200],[14,460],[22,700],[28,1040],[30,1260],[34,1300],[39,1440],[47,1700],[51,2060],[59,2200],[64,3180],[71,3400],[74,3840],[79,3960],[83,4200],[89,4420],[94,4660],[98,4920],[103,5040],[110,5320],[113,6640],[118,6780],[126,7060],[129,8500],[134,8620],[139,8840],[143,9020],[149,9160],[152,9380],[154,9480],[162,9580],[168,10020],[178,11200],[183,11500],[189,11640],[194,11800],[199,12040],[206,12340],[218,12660],[221,13680],[225,13900],[228,14020],[231,14120],[241,14300],[244,14660],[251,14800],[253,16360],[260,16460],[267,16700],[275,17260],[281,17540],[284,17700],[287,17840],[289,18020],[295,18120],[298,18860],[304,19000],[307,19220],[313,19420],[321,19860],[324,20200]]},"ch9-036":{"text":"I knew the tradition associated with Jabal Rahmah: that Adam and Hawa, Adam and Eve, had met again here after coming down to earth. It was a story I carried about the place. Standing there beside someone I had loved and lost, I felt its meaning come suddenly close to my own life.","voiceUrl":"voices/chapter-9/ch9-036.mp3","durationMs":19584,"cues":[[2,320],[7,420],[11,680],[21,840],[32,1360],[37,2100],[43,2360],[51,2720],[56,3820],[61,4120],[65,4700],[71,4940],[76,5980],[80,6280],[85,6540],[89,7160],[93,7320],[99,7520],[104,8000],[110,8520],[117,8740],[122,9020],[125,9260],[132,9420],[135,10340],[139,10520],[141,10720],[147,10840],[149,11260],[157,11400],[163,11720],[167,11940],[174,12060],[183,13260],[189,13680],[196,13900],[204,14280],[206,14600],[210,14660],[216,14860],[220,15440],[226,15660],[228,16900],[233,16980],[237,17200],[245,17400],[250,17780],[259,18020],[265,18420],[268,18740],[271,18820],[275,19000],[280,19180]]},"ch9-037":{"text":"Once could be chance. Twice, my hopeful heart whispered, surely meant something. I looked at the space around us, then at her, and wondered whether this was a sign. The thought came with such warmth that I wanted to stay inside it. I had arrived believing love might be finished for me. Now I was wondering about another beginning.","voiceUrl":"voices/chapter-9/ch9-037.mp3","durationMs":24624,"cues":[[5,220],[11,900],[14,1080],[22,1260],[29,2600],[32,3620],[40,3760],[46,4180],[57,4480],[64,5420],[70,5900],[81,6240],[83,7800],[90,7880],[93,8080],[97,8180],[103,8360],[110,8700],[114,9100],[119,9800],[122,9960],[127,10120],[131,10940],[140,11160],[148,11680],[153,11940],[157,12280],[159,12460],[165,12580],[169,13600],[177,13720],[182,14140],[187,14400],[192,14640],[199,15060],[204,15700],[206,15860],[213,15940],[216,16239],[221,16400],[228,16600],[232,17080],[234,18220],[238,18280],[246,18440],[256,18940],[261,19440],[267,19780],[270,20040],[279,20220],[283,20660],[287,20820],[291,21740],[293,22560],[297,22640],[307,22820],[313,23280],[321,23620],[331,23960]]},"ch9-sign-reunion":{"text":"I allowed myself to picture another beginning with her. We were older now. We could speak differently, understand more. The possibility felt lovely before any difficult questions reached it, and for that moment I let myself want it.","voiceUrl":"voices/chapter-9/ch9-sign-reunion.mp3","durationMs":16152,"cues":[[2,140],[10,220],[17,520],[20,880],[28,1000],[36,1300],[46,1640],[51,2040],[56,2200],[59,3320],[64,3420],[70,3620],[75,3900],[78,4840],[84,4920],[90,5120],[103,5400],[114,6180],[120,6840],[124,8160],[136,8300],[141,8980],[148,9320],[155,10020],[159,10420],[169,10680],[179,11140],[187,11640],[191,11980],[195,13020],[199,13120],[204,13240],[211,13440],[213,14840],[217,14920],[224,15060],[229,15500],[232,15800]]},"ch9-sign-forgiveness":{"text":"Perhaps this was what I needed: her face without the old shock arriving behind it. I wanted to keep the ease of this conversation when we left the mountain, to remember her and still feel able to breathe.","voiceUrl":"voices/chapter-9/ch9-sign-forgiveness.mp3","durationMs":13344,"cues":[[8,80],[13,560],[17,800],[22,980],[24,1220],[32,1340],[36,2420],[41,2580],[49,2920],[53,3220],[57,3400],[63,3680],[72,4240],[79,4740],[83,5160],[85,6180],[92,6320],[95,6740],[100,6860],[104,7100],[109,7300],[112,7560],[117,7680],[130,7880],[135,8580],[138,8760],[143,8940],[147,9260],[157,9380],[160,10260],[169,10380],[173,10880],[177,11400],[183,11640],[188,11960],[193,12380],[196,12680],[204,12800]]},"ch9-sign-open":{"text":"I had been so tired of hoping that I scarcely recognised how good it felt. Perhaps my life still held room for something I hadn't planned. I wanted to remain open to that feeling a little longer.","voiceUrl":"voices/chapter-9/ch9-sign-open.mp3","durationMs":13272,"cues":[[2,160],[6,200],[11,380],[14,720],[20,1080],[23,1520],[30,1640],[35,2060],[37,2220],[46,2400],[57,2900],[61,3500],[66,3740],[69,3900],[75,4080],[83,5240],[86,5640],[91,5840],[97,6220],[102,6560],[107,6900],[111,7180],[121,7380],[123,7840],[130,7960],[139,8320],[141,9740],[148,9840],[151,10100],[158,10220],[163,10700],[166,11100],[171,11240],[179,11540],[181,12300],[188,12440],[195,12720]]},"ch9-sign-join":{"text":"I kept the thought to myself. Nadiah had made no promise by standing beside me. Around us, other people were having their own conversations, taking their own pauses. I turned back to ours. Whatever the coincidence meant, I wanted to hear the person who was actually here, rather than disappear entirely into the future I could imagine.","voiceUrl":"voices/chapter-9/ch9-sign-join.mp3","durationMs":22080,"cues":[[2,120],[7,220],[11,420],[19,520],[22,740],[30,840],[37,2300],[41,2740],[46,2940],[49,3180],[57,3400],[60,3900],[69,4140],[76,4520],[80,4940],[87,5960],[91,6340],[97,6840],[104,7080],[109,7420],[116,7580],[122,7860],[126,8060],[141,8280],[148,9400],[154,9720],[158,9940],[166,10200],[168,11500],[175,11600],[180,11980],[183,12220],[189,12420],[198,13520],[202,13820],[214,13940],[221,14640],[223,15600],[230,15700],[233,15960],[238,16079],[242,16260],[249,16420],[253,16860],[257,17000],[266,17560],[272,18240],[279,18840],[284,19160],[294,19400],[303,19900],[308,20480],[312,20680],[319,20820],[321,21240],[327,21320],[335,21460]]},"ch9-038":{"text":"You're very quiet suddenly. Tired?","voiceUrl":"voices/chapter-9/ch9-038.mp3","durationMs":4080,"cues":[[7,180],[12,420],[18,900],[28,1500],[34,3300]]},"ch9-039":{"text":"A bit. Also just taking it in. I'm glad we got to talk like this.","voiceUrl":"voices/chapter-9/ch9-039.mp3","durationMs":4800,"cues":[[2,160],[7,240],[12,1120],[17,1360],[24,1860],[27,2140],[31,2280],[35,3380],[40,3520],[43,3740],[47,3840],[50,3960],[55,4040],[60,4240],[65,4420]]},"ch9-040":{"text":"She smiled, and we let the conversation find its own pace again. I felt peaceful in her company. That was the part I had never thought to hope for: sitting with the very person I associated with being broken, and finding that I could be at ease. I didn't have to erase her from my life to survive remembering her.","voiceUrl":"voices/chapter-9/ch9-040.mp3","durationMs":21600,"cues":[[4,140],[12,360],[16,1460],[19,1600],[23,1740],[27,1900],[40,2020],[45,2720],[49,2960],[53,3120],[58,3320],[65,3580],[67,5040],[72,5140],[81,5440],[84,6160],[88,6280],[97,6440],[102,7760],[106,7960],[110,8119],[115,8240],[117,8520],[121,8580],[127,8740],[135,9040],[138,9340],[143,9460],[148,9740],[156,10720],[161,11080],[165,11240],[170,11380],[177,11780],[179,12380],[190,12480],[195,13260],[201,13440],[209,13880],[213,15020],[221,15220],[226,15700],[228,16100],[234,16200],[237,16420],[240,16560],[246,16740],[248,18020],[255,18100],[260,18360],[263,18540],[269,18700],[273,19140],[278,19400],[281,19600],[286,19820],[289,20180],[297,20320],[309,20800],[313,21340]]},"ch9-rahmah-after":{"text":"Afterwards, those minutes returned while I was doing other things. I would remember a phrase, the look she gave me, the way neither of us had hurried to fill the quiet. I could feel myself making room for her again. This time, at least, I recognised the movement in my own heart. I knew how much I wanted our closeness to mean something.","voiceUrl":"voices/chapter-9/ch9-rahmah-after.mp3","durationMs":22392,"cues":[[12,200],[18,920],[26,1200],[35,1540],[41,2020],[43,2200],[47,2260],[53,2420],[59,2680],[67,2900],[69,4040],[75,4080],[84,4280],[86,4680],[94,4780],[98,5860],[103,5980],[107,6320],[112,6520],[116,6840],[120,7740],[124,7820],[132,8060],[135,8460],[138,8600],[142,8780],[150,8940],[153,9220],[158,9360],[162,9580],[169,9700],[171,11320],[177,11380],[182,11620],[189,11940],[196,12400],[201,12800],[205,13160],[209,13320],[216,13500],[221,14900],[227,15100],[230,15300],[237,15420],[239,15820],[250,15920],[254,16520],[263,16640],[266,17060],[269,17160],[273,17320],[280,17500],[282,18900],[287,19020],[291,19580],[296,19820],[298,20200],[305,20300],[309,20620],[319,20800],[322,21320],[327,21460],[337,21840]]},"ch9-041":{"text":"As we spoke more during the trip, I began noticing smaller things too. Sometimes an answer would arrive after a hesitation, her expression changing before she found the words. Sometimes a conversation that had been easy would become quieter for a moment. She remained kind. Still, I could feel myself reaching towards something that didn't quite meet me.","voiceUrl":"voices/chapter-9/ch9-041.mp3","durationMs":23592,"cues":[[3,140],[6,300],[12,500],[17,780],[24,1100],[28,1480],[34,1660],[36,2040],[42,2140],[51,2480],[59,3060],[66,3440],[71,3800],[81,5020],[84,5540],[91,5740],[97,6080],[104,6240],[110,6740],[112,6980],[124,7060],[128,8100],[139,8220],[148,8860],[155,9360],[159,9660],[165,9860],[169,10180],[176,10300],[186,11800],[188,12280],[201,12360],[206,13040],[210,13160],[215,13300],[220,13620],[226,14080],[233,14280],[241,14840],[245,15520],[247,15640],[255,15760],[259,17280],[268,17460],[274,18180],[281,19620],[283,19920],[289,19980],[294,20180],[301,20400],[310,20860],[318,21300],[328,21600],[333,21980],[340,22220],[346,22600],[351,23040],[354,23260]]},"ch9-042":{"text":"I thought I saw longing in those pauses, an attention held somewhere beyond the conversation we were having. The more we interacted, the harder it was to ignore. I could not name what she was thinking about. I only knew the feeling it stirred in me: there might be someone else her heart was still turned towards.","voiceUrl":"voices/chapter-9/ch9-042.mp3","durationMs":19680,"cues":[[2,200],[10,280],[12,560],[16,680],[24,980],[27,1740],[33,1860],[41,2140],[44,3060],[54,3200],[59,3860],[69,4260],[76,4660],[80,4980],[93,5100],[96,5780],[101,5880],[109,6020],[113,6820],[118,6980],[121,7320],[133,7480],[137,8520],[144,8680],[147,8980],[151,9120],[154,9340],[162,9440],[164,10860],[170,10940],[174,11100],[179,11400],[184,11780],[188,12000],[192,12140],[201,12300],[208,12640],[210,13440],[215,13540],[220,13780],[224,13980],[232,14160],[235,14500],[243,14700],[246,15040],[250,15200],[256,15960],[262,16140],[265,16460],[273,16780],[278,17240],[282,17600],[288,17840],[292,18220],[298,18420],[305,18740],[313,19160]]},"ch9-043":{"text":"That was my reading of her, unfinished and uncertain. She hadn't offered me a story about another man, and I had no hidden piece of information to examine. I had her warmth, her hesitation, and my own memories. For once I tried to leave those things separate while I worked out what they meant for me.","voiceUrl":"voices/chapter-9/ch9-043.mp3","durationMs":20712,"cues":[[5,120],[9,320],[12,540],[20,760],[23,1100],[28,1240],[39,1820],[43,2520],[54,2860],[58,4000],[65,4160],[73,4560],[76,4880],[78,5000],[84,5120],[90,5520],[98,5880],[103,6240],[107,7080],[109,7380],[113,7480],[116,7660],[123,7800],[129,8080],[132,8320],[144,8440],[147,9000],[156,9120],[158,10500],[162,10580],[166,10760],[174,11020],[178,11880],[190,12200],[194,13720],[197,14340],[201,14540],[211,14740],[215,16239],[220,16460],[222,16960],[228,17060],[231,17280],[237,17380],[243,17620],[250,17900],[259,18280],[265,18920],[267,19120],[274,19220],[278,19520],[283,19680],[288,19820],[294,19980],[298,20260],[301,20400]]},"ch9-uncertain-warmth":{"text":"Sometimes she would come back from one of those quiet moments and ask me to continue what I had been saying. I would, grateful that she wanted to hear it, aware of how quickly gratitude could become hope. I didn't want to punish her for a thought she hadn't shared. I also didn't want to ignore the small uncertainty I felt beside the warmth.","voiceUrl":"voices/chapter-9/ch9-uncertain-warmth.mp3","durationMs":21672,"cues":[[10,140],[14,820],[20,960],[25,1120],[30,1320],[35,1600],[39,1800],[42,1920],[48,2020],[54,2280],[62,2660],[66,3200],[70,3400],[73,3640],[76,3780],[85,3900],[90,4500],[92,4680],[96,4740],[101,4860],[109,5100],[111,6400],[118,6500],[127,7240],[132,7820],[136,8000],[143,8200],[146,8480],[151,8600],[155,8800],[161,9560],[164,9920],[168,10060],[176,10360],[186,10800],[192,11480],[199,11660],[205,12160],[207,13400],[214,13480],[219,13740],[222,13900],[229,14080],[233,14420],[237,14680],[239,14800],[247,14940],[251,15240],[258,15380],[266,15680],[268,16880],[273,16980],[280,17300],[285,17540],[288,17740],[295,17880],[299,18300],[305,18560],[317,19020],[319,19780],[324,19940],[331,20420],[335,20920],[342,21080]]},"ch9-044":{"text":"The hope did not disappear simply because I noticed the uncertainty. I could still remember our conversation on Jabal Nur and feel grateful for every minute. I could still think of Jabal Rahmah and wonder. But beneath that wondering, another question had begun to make itself heard: could I keep this peace even if we never became us again?","voiceUrl":"voices/chapter-9/ch9-044.mp3","durationMs":25104,"cues":[[4,240],[9,360],[13,660],[17,840],[27,1080],[34,1700],[42,2040],[44,2400],[52,2500],[56,3100],[69,3240],[71,5000],[77,5060],[83,5300],[92,5620],[96,6100],[109,6340],[112,7020],[118,7200],[122,7560],[126,8540],[131,8680],[140,8960],[144,9400],[150,9700],[158,10120],[160,11320],[166,11380],[172,11600],[178,11860],[181,12060],[187,12200],[194,12540],[198,13120],[206,13320],[210,14640],[218,14800],[223,15280],[234,15580],[242,16780],[251,17140],[255,17560],[261,17720],[264,17980],[269,18080],[276,18260],[283,18620],[289,20060],[291,20300],[296,20500],[301,21060],[307,21340],[312,22600],[315,22840],[318,22980],[324,23200],[331,23480],[334,24040],[340,24580]]},"ch10-001":{"text":"Madinah came after Makkah. I carried the two climbs with me, the sound of Nadiah laughing, the little hesitations I couldn't explain. I also carried the reason I had made this journey in the first place. Beneath every new possibility was the same tired part of me that had wanted somewhere to put everything down.","voiceUrl":"voices/chapter-10/ch10-001.mp3","durationMs":20784,"cues":[[8,140],[13,760],[19,1040],[27,1380],[29,2680],[37,2820],[41,3140],[45,3300],[52,3500],[57,3940],[61,4140],[65,4640],[71,4780],[74,5160],[81,5360],[91,5800],[95,6580],[102,6700],[114,6920],[116,7680],[125,7780],[134,8020],[136,9620],[141,9740],[149,10120],[153,10440],[160,10580],[162,10980],[166,11040],[171,11200],[176,11460],[184,11680],[187,11940],[191,12040],[197,12160],[204,12520],[212,13780],[218,14220],[222,14740],[234,15060],[238,15860],[242,16059],[247,16239],[253,16700],[258,17200],[261,17420],[264,17580],[269,17860],[273,17980],[280,18200],[290,18700],[293,19160],[297,19320],[308,19700],[313,20300]]},"ch10-002":{"text":"Imran stayed easy company. We could walk together without giving each other a report on every thought. Sometimes he pointed something out and I realised I had stopped noticing what was around me. I would look where he was looking, answer him, and come back to the place we had travelled so far to reach.","voiceUrl":"voices/chapter-10/ch10-002.mp3","durationMs":17112,"cues":[[6,100],[13,540],[18,920],[27,1220],[30,2240],[36,2340],[41,2520],[50,2760],[58,3200],[65,3500],[70,3720],[76,3920],[78,4180],[85,4260],[88,4760],[94,5020],[103,5320],[113,6120],[116,6620],[124,6760],[134,7100],[138,7460],[142,7640],[144,7840],[153,7960],[155,8700],[159,8760],[167,8960],[176,9400],[181,9940],[185,10100],[192,10240],[196,10680],[198,11560],[204,11620],[209,11800],[215,12060],[218,12240],[222,12380],[231,12560],[238,13160],[243,13460],[247,14060],[252,14220],[257,14420],[260,14640],[264,14760],[270,14880],[273,15240],[277,15320],[287,15460],[290,15960],[294,16219],[297,16460],[303,16600]]},"ch10-003":{"text":"In Masjidil Nabawi, I found a moment alone. There were other people around, but no one was waiting for me to speak or watching for the right expression on my face. I sat and allowed myself to become still. The quiet did not arrive all at once. My mind kept trying to continue conversations that weren't happening anymore.","voiceUrl":"voices/chapter-10/ch10-003.mp3","durationMs":23520,"cues":[[3,160],[12,320],[20,960],[22,1840],[28,1940],[30,2180],[37,2300],[44,2680],[50,3920],[55,4120],[61,4380],[68,4680],[76,4960],[80,5380],[83,5580],[87,5780],[91,5960],[99,6160],[103,6560],[106,6700],[109,6900],[115,7140],[118,7720],[127,8039],[131,8580],[135,8700],[141,8820],[152,9040],[155,9620],[158,9760],[164,9980],[166,11480],[170,11620],[174,12460],[182,12640],[189,12960],[192,13380],[199,13500],[206,14000],[210,15720],[216,15860],[220,16540],[224,16760],[231,17000],[235,17640],[238,17760],[244,18000],[247,19020],[252,19220],[257,19700],[264,19940],[267,20320],[276,20420],[290,20940],[295,21800],[303,22120],[313,22460],[321,22920]]},"ch10-004":{"text":"I noticed my hands first. They had settled in my lap, yet I was still holding myself as if I needed to be ready for something. My shoulders were tight. I let them lower a little. Around me were small sounds of people shifting, footsteps passing and fading, the life of the mosque continuing while I sat within it.","voiceUrl":"voices/chapter-10/ch10-004.mp3","durationMs":21912,"cues":[[2,140],[10,220],[13,680],[19,860],[26,1300],[31,2720],[35,2840],[43,3020],[46,3320],[49,3440],[54,3620],[58,4420],[60,4820],[64,4920],[70,5040],[78,5340],[85,5700],[88,6340],[91,6460],[93,6620],[100,6720],[103,7000],[106,7100],[112,7300],[116,7580],[127,7740],[130,8800],[140,8980],[145,9440],[152,9680],[154,11080],[158,11160],[163,11320],[169,11500],[171,12000],[179,12080],[186,13320],[189,13760],[194,14080],[200,14360],[207,14700],[210,15060],[217,15200],[227,15540],[237,16360],[245,17000],[249,17420],[257,17580],[261,18640],[266,18760],[269,19220],[273,19340],[280,19460],[291,19960],[297,20580],[299,20900],[303,21020],[310,21300],[313,21580]]},"ch10-005":{"text":"For so long, whenever I thought about my love life, I began explaining. What I had tried. What I had given. Why the hurt had lasted. I could tell the story in a way that made every disappointment lead neatly to the next. Sitting there, I found I had very little desire to make the account convincing.","voiceUrl":"voices/chapter-10/ch10-005.mp3","durationMs":21672,"cues":[[4,120],[7,340],[13,600],[22,1320],[24,1780],[32,1880],[38,2120],[41,2360],[46,2580],[52,2820],[54,3800],[60,3880],[72,4280],[77,5900],[79,6080],[83,6140],[90,6340],[95,7200],[97,7440],[101,7520],[108,7700],[112,8780],[116,9100],[121,9240],[125,9720],[133,9900],[135,11180],[141,11240],[146,11400],[150,11580],[156,11740],[159,12160],[161,12300],[165,12380],[170,12600],[175,12760],[181,13140],[196,13500],[201,14260],[208,14560],[211,15060],[215,15200],[221,15320],[229,16760],[236,17080],[238,18000],[244,18120],[246,18520],[250,18580],[255,18800],[262,19140],[269,19440],[272,19940],[277,20060],[281,20240],[289,20380],[300,20900]]},"ch10-prayer-honesty":{"text":"I looked down for a while. There was something difficult about admitting how much I still wanted to be loved, after all the times I had said I was done with it. Here I could admit it without somebody telling me to be patient or asking what had happened. I could begin with the wanting itself, and the fact that I didn't know what to do with it anymore.","voiceUrl":"voices/chapter-10/ch10-prayer-honesty.mp3","durationMs":22800,"cues":[[2,140],[9,200],[14,540],[18,880],[20,1020],[27,1120],[33,2380],[37,2520],[47,2700],[57,3060],[63,3800],[73,4059],[77,4540],[82,4700],[84,4980],[90,5160],[97,5580],[100,5960],[103,6060],[110,6280],[116,7180],[120,7440],[124,7620],[130,7760],[132,8200],[136,8260],[141,8440],[143,8720],[147,8820],[152,9020],[157,9280],[161,9460],[166,10760],[168,11220],[174,11300],[180,11460],[183,11780],[191,12400],[200,12740],[208,13140],[211,13440],[214,13580],[217,13680],[225,13860],[228,14440],[235,14780],[240,15220],[244,15340],[254,15500],[256,16900],[262,17000],[268,17160],[273,17660],[277,17820],[285,18000],[293,18460],[297,19440],[301,19540],[306,19700],[311,20000],[313,20340],[320,20440],[325,20740],[330,21020],[333,21200],[336,21400],[341,21560],[344,21780],[352,22160]]},"ch10-006":{"text":"I made a small doa about love. I cannot give its exact words back to you. What I remember is wanting God to help me with this part of my life: guide me towards what was good, ease what I was carrying, help me find peace with what I could not make happen. It was simple enough to come from somewhere beneath the explanations.","voiceUrl":"voices/chapter-10/ch10-006.mp3","durationMs":23664,"cues":[[2,160],[7,240],[9,480],[15,640],[19,980],[25,1800],[31,2160],[33,3460],[40,3580],[45,4019],[49,4300],[55,4460],[61,4940],[66,5380],[69,5660],[74,5780],[79,6640],[81,6880],[90,7000],[93,7700],[101,7880],[105,8360],[108,8780],[113,8960],[116,9240],[121,9440],[126,9620],[131,9860],[134,10140],[137,10260],[143,10440],[149,11540],[152,11920],[160,12160],[165,12520],[169,12760],[175,12980],[180,13800],[185,14480],[187,14660],[191,14740],[201,14920],[206,16079],[209,16300],[214,16500],[220,16960],[225,17460],[230,17660],[232,18020],[238,18140],[242,18400],[247,18720],[255,18940],[258,20240],[262,20320],[269,20460],[276,20740],[279,21120],[284,21260],[289,21540],[299,21840],[307,22300],[311,22620],[324,22760]]},"ch10-007":{"text":"The familiar faces came to mind without lining up into an argument. People I had loved. People I had hoped would love me. The younger versions of myself who had waited beside a phone or travelled home with things they couldn't say. I felt how tired they all were. I was tired of carrying them as if none of those days had ended.","voiceUrl":"voices/chapter-10/ch10-007.mp3","durationMs":22560,"cues":[[4,100],[13,220],[19,700],[24,1120],[27,1320],[32,1440],[40,1820],[47,2280],[50,2680],[55,2860],[58,3100],[68,3260],[75,4300],[77,4620],[81,4680],[88,4860],[95,5880],[97,6240],[101,6300],[107,6520],[113,6980],[118,7220],[122,7520],[126,8580],[134,8680],[143,9020],[146,9420],[153,9540],[157,10040],[161,10160],[168,10300],[175,10620],[177,10940],[183,11040],[186,11700],[196,12260],[201,12700],[206,13020],[213,13200],[218,13540],[227,13720],[232,14060],[234,15340],[239,15460],[243,15740],[249,15980],[254,16760],[258,16960],[264,17140],[266,18380],[270,18460],[276,18660],[279,19020],[288,19200],[293,19660],[296,20280],[299,20460],[304,20860],[307,21040],[313,21180],[318,21460],[322,21820],[328,22020]]},"ch10-008":{"text":"I didn't know what the next part of my life should look like. Even here, with Nadiah close again, I couldn't turn possibility into certainty. I let that be part of what I brought to God. The wanting, the disappointment, the fear that being alone meant something had gone wrong with me. There was no need to tidy it first.","voiceUrl":"voices/chapter-10/ch10-008.mp3","durationMs":21744,"cues":[[2,200],[9,300],[14,660],[19,1040],[23,1220],[28,1320],[33,1600],[36,1780],[39,1900],[44,2100],[51,2360],[56,2560],[62,2760],[67,3960],[73,4260],[78,4740],[85,4980],[91,5400],[98,5700],[100,6360],[109,6440],[114,6760],[126,7160],[131,8240],[142,8560],[144,10100],[148,10180],[153,10400],[156,10740],[161,10920],[164,11120],[169,11200],[171,11400],[179,11500],[182,11760],[187,11900],[191,13000],[200,13120],[204,14140],[220,14240],[224,15560],[229,15720],[234,16020],[240,16219],[246,16480],[252,16920],[262,17340],[266,17620],[271,17800],[277,18080],[282,18400],[286,18620],[292,19780],[296,19880],[299,20040],[304,20240],[307,20520],[312,20700],[315,21000],[321,21160]]},"ch10-009":{"text":"Then a breath left me. A long, unplanned sigh, deeper than the ordinary breaths before it. It felt as if something had come out with it, something I had been keeping pressed inside my chest without knowing how firmly I held it. I remained still, surprised by the space it seemed to leave behind.","voiceUrl":"voices/chapter-10/ch10-009.mp3","durationMs":20304,"cues":[[5,100],[7,260],[14,360],[19,760],[23,1100],[25,2020],[31,2140],[41,3100],[47,3860],[54,4440],[59,4820],[63,4980],[72,5160],[80,5720],[87,6080],[91,6460],[94,7360],[99,7520],[102,7820],[105,7960],[115,8140],[119,8520],[124,8680],[128,8880],[133,9120],[137,9340],[147,10160],[149,10600],[153,10660],[158,10780],[166,11020],[174,11380],[181,11820],[184,12220],[190,12440],[198,12780],[206,13120],[210,13420],[217,13680],[219,14180],[224,14260],[228,14540],[230,15760],[239,15840],[246,16379],[256,17180],[259,17800],[263,17960],[269,18140],[272,18520],[279,18700],[282,19180],[288,19320],[295,19600]]},"ch10-010":{"text":"I breathed in again. There was room. I could feel the air arrive without the familiar tightness gathering around it. My hands rested where they were. Nothing dramatic happened in the space around me; people continued with their own moments. Inside, I felt an enormous relief, so quiet that I wanted to sit carefully and let it reach the rest of me.","voiceUrl":"voices/chapter-10/ch10-010.mp3","durationMs":24240,"cues":[[2,120],[11,220],[14,620],[21,760],[27,2080],[31,2240],[37,2440],[39,3660],[45,3720],[50,3880],[54,4120],[58,4360],[65,4740],[73,5200],[77,5480],[86,5620],[96,6140],[106,6660],[113,7080],[117,7420],[120,8220],[126,8360],[133,8900],[139,9340],[144,9520],[150,9700],[158,10860],[167,11160],[176,11660],[179,12080],[183,12180],[189,12320],[196,12640],[200,13060],[207,13820],[217,14200],[222,14800],[228,14980],[232,15200],[241,15440],[249,16980],[251,17460],[256,17580],[259,17920],[268,18060],[276,18980],[279,20200],[285,20380],[290,20800],[292,20980],[299,21080],[302,21360],[306,21560],[316,21840],[320,22400],[324,22800],[327,22940],[333,23100],[337,23420],[342,23540],[345,23820],[348,23960]]},"ch10-release-stillness":{"text":"I waited for the ache to gather itself again out of habit. It had accompanied so many quiet moments that its absence felt unfamiliar. A thought of the past crossed my mind and passed through. I didn't need to follow it all the way back. I could remain seated here, aware of where I was, feeling the next breath come as easily as the last.","voiceUrl":"voices/chapter-10/ch10-release-stillness.mp3","durationMs":22392,"cues":[[2,200],[9,280],[13,780],[17,960],[22,1160],[25,1540],[32,1660],[39,1980],[45,2400],[49,2780],[52,2920],[59,3060],[62,4240],[66,4320],[78,4440],[81,5100],[86,5280],[92,5560],[100,5960],[105,6480],[109,6620],[117,6920],[122,7400],[134,7700],[136,9320],[144,9400],[147,9640],[151,9760],[156,9900],[164,10460],[167,10880],[172,11080],[176,11520],[183,11780],[192,12220],[194,13340],[201,13400],[206,13620],[209,13780],[216,13940],[219,14240],[223,14400],[227,14520],[231,14600],[237,14800],[239,15900],[245,15980],[252,16160],[259,16640],[265,17060],[271,17660],[274,18020],[280,18200],[282,18480],[287,18620],[295,19280],[299,19720],[304,19840],[311,20220],[316,20580],[319,20800],[326,21020],[329,21440],[333,21640],[338,21780]]},"ch10-011":{"text":"The memories were still there. I could bring one close and recognise it. But the weight that usually came with it had loosened. I no longer felt caught inside the worst part of each story, bracing for it to happen again. I sat in Masjidil Nabawi and felt free in a way I had almost forgotten was possible.","voiceUrl":"voices/chapter-10/ch10-011.mp3","durationMs":21984,"cues":[[4,100],[13,220],[18,940],[24,1140],[31,1380],[33,2440],[39,2500],[45,2680],[49,3000],[55,3220],[59,3660],[69,3860],[73,4420],[77,5420],[81,5540],[88,5720],[93,6340],[101,6560],[106,6980],[111,7240],[114,7420],[118,8500],[128,8660],[130,10060],[133,10140],[140,10300],[145,10640],[152,10940],[159,11320],[163,11740],[169,11900],[174,12320],[177,12580],[182,12720],[189,13000],[197,13660],[201,14140],[204,14260],[207,14400],[214,14540],[221,14880],[223,16120],[227,16260],[230,16620],[239,16780],[246,17400],[250,18140],[255,18440],[260,18800],[263,19120],[265,19240],[269,19340],[271,19720],[275,19780],[282,20000],[292,20400],[296,21200],[305,21400]]},"ch10-release-resentment":{"text":"I had kept the hurt close because loosening my hold on it felt like letting somebody dismiss what happened. Now I could remember it without holding it against every new day. I wanted to live in this one.","voiceUrl":"voices/chapter-10/ch10-release-resentment.mp3","durationMs":14304,"cues":[[2,240],[6,280],[11,480],[15,720],[20,820],[26,1100],[34,1840],[44,2280],[47,2760],[52,2960],[55,3260],[58,3440],[63,3620],[68,3820],[76,4080],[85,4420],[93,4880],[98,5740],[108,5920],[112,7340],[114,8060],[120,8180],[129,8460],[132,8900],[140,9080],[148,9420],[151,9760],[159,9860],[165,10400],[169,10880],[174,11160],[176,12460],[183,12560],[186,12840],[191,12980],[194,13520],[199,13700],[203,13960]]},"ch10-release-proof":{"text":"So much effort had gone into making myself impossible to overlook. I felt tired just thinking of it. Sitting here, I could stop presenting reasons someone should love me. I could let my hands be empty for a while.","voiceUrl":"voices/chapter-10/ch10-release-proof.mp3","durationMs":14232,"cues":[[3,140],[8,380],[15,740],[19,1080],[24,1280],[29,1540],[36,1800],[43,2120],[54,2520],[57,3180],[67,3340],[69,4860],[74,4940],[80,5220],[85,5660],[94,5900],[97,6280],[101,6400],[109,7560],[115,7880],[117,8560],[123,8640],[128,8840],[139,9100],[147,9600],[155,10220],[162,10540],[167,10720],[171,10960],[173,11840],[179,11900],[183,12040],[186,12220],[192,12420],[195,12900],[201,13120],[205,13520],[207,13660],[213,13760]]},"ch10-release-fear":{"text":"I didn't want to reach every new person already expecting the familiar ending. For once that expectation felt like something I could set beside me. I could meet the next part of my life when it actually arrived.","voiceUrl":"voices/chapter-10/ch10-release-fear.mp3","durationMs":14232,"cues":[[2,140],[9,200],[14,440],[17,660],[23,800],[29,1160],[33,1460],[40,1660],[48,2120],[58,2520],[62,3100],[71,3240],[79,3800],[83,5060],[88,5280],[93,6160],[105,6340],[110,7140],[115,7340],[125,7560],[127,8140],[133,8220],[137,8500],[144,8900],[148,9340],[150,10580],[156,10640],[161,10880],[165,11320],[170,11440],[175,11780],[178,11960],[181,12080],[186,12280],[191,12580],[194,12720],[203,12960],[211,13560]]},"ch10-release-join":{"text":"I stayed a little longer. There was no answer naming who I would marry, no instruction to go back to Nadiah. There was this relief, and it was enough to hold my attention. I had asked for help with love. I began to feel how much of that help could be the freedom to stop being afraid of it.","voiceUrl":"voices/chapter-10/ch10-release-join.mp3","durationMs":20472,"cues":[[2,140],[9,280],[11,720],[18,800],[26,1060],[32,2240],[36,2340],[39,2500],[46,2760],[53,3360],[57,3760],[59,4000],[65,4059],[72,4240],[75,5080],[87,5240],[90,5940],[93,6020],[98,6180],[101,6400],[109,6540],[115,7820],[119,7960],[124,8140],[132,9080],[136,10340],[139,10460],[143,10560],[150,10700],[153,10980],[158,11080],[161,11320],[172,11480],[174,13160],[178,13220],[184,13480],[188,13940],[193,14120],[198,14600],[204,14840],[206,16079],[212,16140],[215,16440],[220,16600],[224,16900],[229,17140],[232,17360],[237,17480],[242,17720],[248,18020],[251,18180],[255,18320],[263,18480],[266,18900],[271,19060],[277,19360],[284,19600],[287,20080],[290,20220]]},"ch10-012":{"text":"The old rule about Malay women seemed especially tired now. I had carried it from one disappointment into another life, avoiding people before I knew them. Here, I could feel the resentment beneath that habit letting go. I didn't want it choosing whom I allowed near me anymore. Someone new could be herself when I met her.","voiceUrl":"voices/chapter-10/ch10-012.mp3","durationMs":22560,"cues":[[4,100],[8,220],[13,500],[19,820],[25,1140],[31,1540],[38,1980],[49,2280],[55,2940],[60,3340],[62,4280],[66,4340],[74,4560],[77,4940],[82,5100],[86,5400],[101,5620],[106,6560],[114,6820],[120,7220],[129,7940],[136,8480],[143,8800],[145,9200],[150,9320],[156,9520],[162,10800],[164,11380],[170,11460],[175,11680],[179,11960],[190,12100],[198,12820],[203,13220],[209,13480],[217,13880],[221,14200],[223,15460],[230,15520],[235,15840],[238,16020],[247,16239],[252,16680],[254,17020],[262,17140],[267,17540],[270,17780],[279,17940],[287,19700],[291,20080],[297,20620],[300,20820],[308,20940],[313,21800],[315,22000],[319,22100],[323,22280]]},"ch10-room-ahead":{"text":"I imagined an ordinary introduction, the kind I used to step away from before it went anywhere. I could listen. I could ask a question because I wanted to know the answer. I would not have to begin by placing a stranger beside the people who had hurt me. The thought was small, but I felt how much space it opened in my life.","voiceUrl":"voices/chapter-10/ch10-room-ahead.mp3","durationMs":21504,"cues":[[2,160],[11,180],[14,700],[23,1000],[37,1520],[41,2660],[46,2760],[48,3060],[53,3220],[56,3460],[61,3600],[66,3820],[71,4100],[78,4340],[81,4600],[86,4740],[96,5000],[98,6300],[104,6360],[112,6540],[114,7680],[120,7740],[124,7980],[126,8240],[135,8340],[143,8820],[145,9460],[152,9580],[155,10200],[160,10300],[164,10440],[172,10580],[174,11860],[180,11920],[184,12100],[189,12400],[192,12580],[198,12680],[201,13040],[209,13220],[211,13580],[220,13740],[227,14140],[231,14480],[238,14640],[242,15040],[246,15160],[251,15400],[255,15760],[259,16980],[267,17100],[271,17460],[278,17680],[282,18700],[284,18860],[289,18940],[293,19200],[298,19380],[304,19740],[307,20320],[314,20460],[317,20780],[320,20880],[325,21060]]},"ch10-013":{"text":"When I was with Imran again, he looked at me for a moment before speaking. I wondered whether something about the way I stood had changed. I certainly felt it: less effort in my chest, less urgency to resolve every thought before the day could continue. I could hear him without another conversation running underneath.","voiceUrl":"voices/chapter-10/ch10-013.mp3","durationMs":20304,"cues":[[5,100],[7,280],[11,360],[16,540],[22,760],[29,1120],[32,2100],[39,2240],[42,2420],[45,2540],[49,2720],[51,2840],[58,2920],[65,3260],[75,3620],[77,4940],[86,5020],[94,5360],[104,5660],[110,5980],[114,6180],[118,6280],[120,6520],[126,6700],[130,7060],[139,7280],[141,8440],[151,8560],[156,8980],[160,9260],[165,9940],[172,10320],[175,10700],[178,10840],[185,11040],[190,11680],[198,12160],[201,12800],[209,12920],[215,13520],[223,14020],[230,14380],[234,14700],[238,14840],[244,15080],[254,15280],[256,16800],[262,16860],[267,17100],[271,17340],[279,17940],[287,18280],[300,18620],[308,19440],[319,19720]]},"ch10-014":{"text":"You okay?","voiceUrl":"voices/chapter-10/ch10-014.mp3","durationMs":2640,"cues":[[4,280],[9,440]]},"ch10-015":{"text":"Yeah. I feel lighter. I don't really know how to explain it yet.","voiceUrl":"voices/chapter-10/ch10-015.mp3","durationMs":3744,"cues":[[6,180],[8,620],[13,760],[22,1400],[24,2120],[30,2180],[37,2400],[42,2600],[46,2800],[49,2900],[57,2980],[60,3340],[64,3440]]},"ch10-016":{"text":"No need to explain now. Come. We can walk a bit.","voiceUrl":"voices/chapter-10/ch10-016.mp3","durationMs":4320,"cues":[[3,320],[8,540],[11,760],[19,880],[24,1460],[30,2580],[33,3220],[37,3360],[42,3540],[44,3800],[48,3900]]},"ch10-017":{"text":"That lightness stayed with me when I saw Nadiah. I still liked the warmth in her greeting. I still knew how quickly one of her smiles could find the affectionate part of me. Forgiving her had not made her a stranger. It had made it possible to see her without needing every encounter to repair the past.","voiceUrl":"voices/chapter-10/ch10-017.mp3","durationMs":18240,"cues":[[5,120],[15,340],[22,820],[27,1140],[30,1320],[35,1460],[37,1640],[41,1760],[49,1960],[51,3140],[57,3300],[63,3560],[67,3940],[74,4100],[77,4560],[81,4660],[91,4820],[93,6100],[99,6240],[104,6520],[108,6780],[116,7000],[120,7380],[123,7520],[127,7600],[134,7780],[140,8220],[145,8400],[149,8800],[162,8900],[167,9540],[170,9760],[174,9900],[184,10860],[188,11340],[192,11800],[196,11940],[201,12140],[205,12360],[207,12540],[217,12700],[220,14160],[224,14240],[229,14380],[232,14560],[241,14700],[244,15100],[248,15240],[252,15420],[260,15560],[268,15880],[274,16180],[284,16400],[287,16880],[294,16980],[298,17380],[303,17540]]},"ch10-018":{"text":"As we continued talking, I recognised the hesitation and longing I had noticed before. A pause, a thought she seemed to follow inward, the feeling that some part of her attention was elsewhere. I took those moments as a sign that her feelings for another man might still be there. It was an impression I formed, never a confession she gave me.","voiceUrl":"voices/chapter-10/ch10-018.mp3","durationMs":22224,"cues":[[3,300],[6,460],[16,580],[25,1140],[27,1760],[38,1860],[42,2460],[53,2560],[57,3140],[65,3340],[67,3760],[71,3820],[79,3940],[87,4360],[89,5960],[96,6080],[98,7280],[106,7400],[110,7900],[117,8080],[120,8440],[127,8560],[135,8960],[139,10000],[147,10120],[152,10460],[157,10620],[162,10880],[165,11120],[169,11200],[179,11340],[183,11820],[194,12080],[196,13860],[201,13940],[207,14120],[215,14360],[218,14720],[220,14840],[225,14960],[230,15260],[234,15380],[243,15540],[247,15940],[255,16040],[259,16340],[265,16660],[271,16920],[274,17180],[281,17360],[284,18640],[288,18780],[291,19080],[302,19180],[304,19660],[312,19800],[318,20600],[320,20840],[331,20920],[335,21480],[340,21660],[343,21960]]},"ch10-019":{"text":"I couldn't know the whole of her heart. I could know that I was starting to lean towards a reunion while sensing she might be leaning elsewhere. That was enough to make me pause. I had lived inside that waiting before. This time I could recognise where my own hope was taking me before I built a life around it.","voiceUrl":"voices/chapter-10/ch10-019.mp3","durationMs":19920,"cues":[[2,200],[11,280],[16,640],[20,900],[26,1020],[29,1240],[33,1380],[40,1580],[42,2800],[48,2900],[53,3160],[58,3520],[60,3700],[64,3760],[73,3900],[76,4280],[81,4400],[89,4680],[91,5080],[99,5160],[105,6380],[113,6660],[117,7160],[123,7380],[126,7600],[134,7740],[145,8080],[150,9440],[154,9680],[161,9820],[164,10100],[169,10200],[172,10400],[179,10600],[181,11980],[185,12040],[191,12200],[198,12460],[203,12900],[211,13100],[219,13420],[224,14640],[229,14860],[231,15220],[237,15280],[247,15460],[253,16100],[256,16320],[260,16580],[265,16820],[269,17080],[276,17240],[279,17580],[286,18260],[288,18560],[294,18640],[296,18860],[301,18960],[308,19260],[311,19600]]},"ch10-020":{"text":"I wanted us to have another chance; I could admit that quietly to myself. Yet I began to understand that we weren't meant to begin again together. I did not need to press her for a place she hadn't offered. Whatever remained unresolved for her was hers to understand. I could care about her while taking my own next step.","voiceUrl":"voices/chapter-10/ch10-020.mp3","durationMs":21672,"cues":[[2,220],[9,340],[12,780],[15,1000],[20,1100],[28,1240],[36,1620],[38,2880],[44,2940],[50,3100],[55,3440],[63,3700],[66,4120],[74,4220],[78,5180],[80,5400],[86,5480],[89,5800],[100,5920],[105,6420],[108,6600],[116,6760],[122,7080],[125,7520],[131,7640],[137,7960],[147,8300],[149,9600],[153,9680],[157,9880],[162,10140],[165,10380],[171,10500],[175,10780],[179,11020],[181,11160],[187,11280],[191,11860],[198,12020],[207,12360],[216,13620],[225,14020],[236,14580],[240,15340],[244,15500],[248,15820],[253,16239],[256,16640],[268,16780],[270,18320],[276,18380],[281,18580],[287,18820],[291,19080],[297,19340],[304,19620],[307,19960],[311,20220],[316,20740],[321,21260]]},"ch10-boundary-kindness":{"text":"I could answer her warmly, enjoy a conversation, and let it end where it ended. Affection didn't have to become pursuit. I wanted the gentleness we had found again to survive without asking it to promise me more.","voiceUrl":"voices/chapter-10/ch10-boundary-kindness.mp3","durationMs":13344,"cues":[[2,200],[8,220],[15,400],[19,680],[27,880],[33,1760],[35,2120],[49,2220],[53,3000],[57,3200],[60,3400],[64,3660],[70,4120],[73,4320],[80,4520],[90,5540],[97,6160],[102,6460],[105,6700],[112,6780],[121,7120],[123,8500],[130,8640],[134,9040],[145,9180],[148,9720],[152,9800],[158,9960],[164,10220],[167,10540],[175,10660],[183,11220],[190,11780],[193,12140],[196,12260],[204,12400],[207,12760],[212,12920]]},"ch10-boundary-peace":{"text":"I thought of the breath that had left me in the mosque. That relief belonged to this journey even if Nadiah and I never became a couple again. I could carry it forward without carrying another expectation for her.","voiceUrl":"voices/chapter-10/ch10-boundary-peace.mp3","durationMs":13344,"cues":[[2,140],[10,220],[13,500],[17,640],[24,740],[29,1220],[33,1360],[38,1540],[41,1840],[44,1960],[48,2040],[56,2140],[61,3340],[68,3520],[77,4059],[80,4800],[85,4940],[93,5180],[98,5740],[101,6020],[108,6200],[112,6660],[114,6960],[120,7080],[127,7340],[129,7640],[136,7740],[143,8020],[145,9140],[151,9220],[157,9440],[160,9700],[168,9880],[176,10540],[185,10940],[193,11360],[205,12040],[209,12900],[213,13080]]},"ch10-boundary-waiting":{"text":"I knew how to make waiting look like an ordinary friendship. I had done it for years. This time I wanted to let my future stay open, instead of quietly keeping it empty until somebody else was ready.","voiceUrl":"voices/chapter-10/ch10-boundary-waiting.mp3","durationMs":13512,"cues":[[2,240],[7,320],[11,580],[14,720],[19,820],[27,1040],[32,1540],[37,1780],[40,1960],[49,2160],[61,2660],[63,3660],[67,3700],[72,3860],[75,4040],[79,4200],[86,4380],[91,5720],[96,5980],[98,6840],[105,6920],[108,7200],[112,7320],[115,7500],[122,7700],[127,8140],[133,8540],[141,9520],[144,9920],[152,10120],[160,10640],[163,10940],[169,11120],[175,11440],[184,11800],[189,12300],[193,12900],[199,13100]]},"ch10-boundary-join":{"text":"I made no announcement. There was no farewell conversation for her to answer. The decision belonged in the small things I would do next: stop seeking another moment alone, stop returning to each pause for a possible promise, remain kind when we met. I could step away from pursuing her without making the warmth between us something to regret.","voiceUrl":"voices/chapter-10/ch10-boundary-join.mp3","durationMs":23520,"cues":[[2,160],[7,260],[10,540],[24,700],[30,1980],[34,2100],[37,2240],[46,2440],[59,2900],[63,3540],[67,3660],[70,3820],[78,3980],[82,5040],[91,5140],[100,5660],[103,6360],[107,6460],[113,6680],[120,7000],[122,7560],[128,7640],[131,7820],[137,8000],[142,9060],[150,9400],[158,9820],[165,10260],[172,10680],[177,11720],[187,11960],[190,12460],[195,12620],[201,12920],[205,13460],[207,13600],[216,13740],[225,14240],[232,15500],[237,15920],[242,16860],[245,17080],[250,17240],[252,18540],[258,18620],[263,18840],[268,19100],[273,19400],[282,19600],[286,20180],[294,20400],[301,20800],[305,21160],[312,21340],[320,21780],[323,22180],[333,22400],[336,22800],[343,22920]]},"ch10-boundary-practice":{"text":"When a conversation finished, I let myself turn back towards the rest of the group. For a moment the old impulse remained: find one more thing to say, keep the opening there a little longer. I noticed it, then allowed the moment to finish. There were other people to speak to and a whole journey around me that I wanted to be present for.","voiceUrl":"voices/chapter-10/ch10-boundary-practice.mp3","durationMs":21264,"cues":[[5,100],[7,200],[20,280],[30,1040],[32,1780],[36,1840],[43,2020],[48,2420],[53,2640],[61,2900],[65,3340],[70,3420],[73,3680],[77,3760],[84,3860],[88,5100],[90,5220],[97,5340],[101,6000],[105,6160],[113,6440],[123,6860],[128,7900],[132,8260],[137,8500],[143,8780],[146,9020],[151,9160],[156,9700],[160,9880],[168,10100],[174,10460],[176,10640],[183,10720],[191,11020],[193,12620],[201,12700],[205,13100],[210,14020],[218,14260],[222,14520],[229,14620],[232,14900],[240,15040],[246,16320],[251,16460],[257,16720],[264,16940],[267,17260],[273,17400],[276,17680],[280,18260],[282,18400],[288,18480],[296,18780],[303,19120],[306,19520],[311,19700],[313,19880],[320,19980],[323,20260],[326,20340],[334,20500],[338,20880]]},"ch10-021":{"text":"The group still had its familiar places for me. Kak Mariam would catch my eye and ask how I was. Abang Yusuf could turn a small observation into a conversation that wandered pleasantly for a while. I joined them and found I had more attention to give. I wasn't spending every spare moment trying to interpret someone else.","voiceUrl":"voices/chapter-10/ch10-021.mp3","durationMs":19512,"cues":[[4,100],[10,180],[16,580],[20,860],[24,1060],[33,1260],[40,1680],[44,2160],[48,2340],[52,3080],[59,3320],[65,3700],[71,3880],[74,4140],[78,4360],[82,4580],[86,4760],[90,4960],[92,5140],[97,5240],[103,6140],[109,6440],[115,6860],[120,7040],[122,7220],[128,7360],[140,7680],[145,8260],[147,8460],[160,8560],[165,9220],[174,9440],[185,9860],[189,10420],[191,10560],[198,10640],[200,12040],[207,12160],[212,12500],[216,13000],[222,13180],[224,13520],[228,13580],[233,13780],[243,13960],[246,14420],[252,14560],[254,16020],[261,16120],[270,16420],[276,16840],[282,17220],[289,17480],[296,17880],[299,18120],[309,18200],[317,18800],[322,19080]]},"ch10-022":{"text":"Aleem, come sit with us. Every time I see you standing, I feel like I'm taking your chair.","voiceUrl":"voices/chapter-10/ch10-022.mp3","durationMs":7680,"cues":[[7,120],[12,1240],[16,1540],[21,1820],[25,2060],[31,3080],[36,3420],[38,3780],[42,3940],[46,4160],[56,4440],[58,5560],[63,5760],[68,6000],[72,6260],[79,6460],[84,6880],[90,7100]]},"ch10-023":{"text":"Kak, you already offered me a seat before I even saw the chair.","voiceUrl":"voices/chapter-10/ch10-023.mp3","durationMs":3504,"cues":[[5,180],[9,580],[17,760],[25,1080],[28,1340],[30,1460],[35,1600],[42,1760],[44,2120],[49,2160],[53,2420],[57,2600],[63,2760]]},"ch10-024":{"text":"Then you had better take it. Very difficult to win this argument.","voiceUrl":"voices/chapter-10/ch10-024.mp3","durationMs":4320,"cues":[[5,140],[9,480],[13,600],[20,820],[25,1160],[29,1440],[34,1940],[44,2260],[47,2800],[51,3020],[56,3360],[65,3620]]},"ch10-025":{"text":"I sat, smiling before I had found something to say. Their company had become one of the quiet comforts of the trip. There was no particular performance needed from me. I could contribute to the conversation or listen, and remain welcome either way. I liked seeing how often they made room for other people within their ease with each other.","voiceUrl":"voices/chapter-10/ch10-025.mp3","durationMs":21024,"cues":[[2,240],[7,340],[15,660],[22,1140],[24,1440],[28,1520],[34,1660],[44,1900],[47,2260],[52,2400],[58,3660],[66,3860],[70,4300],[77,4460],[81,4780],[84,4900],[88,5020],[94,5160],[103,5540],[106,6060],[110,6180],[116,6300],[122,7300],[126,7420],[129,7560],[140,7700],[152,8240],[159,9000],[164,9400],[168,9600],[170,10540],[176,10640],[187,10840],[190,11360],[194,11460],[207,11560],[210,12340],[218,12560],[222,13080],[229,13260],[237,13660],[244,14180],[249,14460],[251,15820],[257,15940],[264,16360],[268,16720],[274,16960],[279,17280],[284,17500],[289,17820],[293,18140],[299,18320],[306,18620],[313,19040],[319,19440],[324,19800],[329,20260],[334,20440],[340,20660]]},"ch10-couple-ease":{"text":"Yusuf would pause to let Mariam add something, then pick up the thread without needing to start again. Sometimes they disagreed about a small detail and laughed when neither would give way. I watched them with a feeling I couldn't have managed at home: pleasure in somebody else's companionship, without immediately measuring the empty space beside me.","voiceUrl":"voices/chapter-10/ch10-couple-ease.mp3","durationMs":21360,"cues":[[6,160],[12,580],[18,820],[21,1300],[25,1420],[32,1640],[36,2180],[47,2400],[52,3220],[57,3460],[60,3640],[64,3780],[71,3880],[79,4220],[87,4600],[90,4940],[96,5100],[103,5320],[113,6620],[118,7120],[128,7300],[134,7920],[136,8140],[142,8280],[149,8560],[153,9180],[161,9360],[166,9800],[174,10040],[180,10400],[185,10580],[190,10800],[192,12040],[200,12140],[205,12560],[210,12760],[212,12900],[220,13020],[222,13460],[231,13600],[236,13900],[244,14080],[247,14560],[253,14700],[262,15560],[265,16239],[274,16420],[281,16780],[296,17080],[304,18320],[316,18600],[326,19280],[330,19740],[336,19860],[342,20260],[349,20660],[352,21100]]},"ch10-026":{"text":"I thought about how I had felt before leaving home, alone in my room and almost ready to stop wanting love entirely. Here I was, sitting with people whose kindness had become familiar, feeling able to imagine a future again. I hadn't planned this version of the journey. I was grateful to be inside it.","voiceUrl":"voices/chapter-10/ch10-026.mp3","durationMs":19752,"cues":[[2,140],[10,200],[16,440],[20,700],[22,860],[26,900],[31,1060],[38,1340],[46,1640],[52,1960],[58,2840],[61,3160],[64,3280],[69,3480],[73,3800],[80,4180],[86,4560],[89,4800],[94,4920],[102,5140],[107,5460],[117,5620],[122,7120],[124,7340],[129,7480],[137,8540],[142,8820],[149,9000],[155,9260],[164,9500],[168,10000],[175,10140],[185,10440],[193,11600],[198,11960],[201,12220],[209,12320],[211,12680],[218,12800],[225,13180],[227,14480],[234,14520],[242,14780],[247,15540],[255,15740],[258,16040],[262,16160],[271,16300],[273,17840],[277,17880],[286,18040],[289,18820],[292,18920],[299,19020],[302,19480]]},"ch10-027":{"text":"Mariam turned towards me as our conversation found a pause. There was something she wanted to tell me; I could see it in the way she waited until she had my attention. I settled back in the chair and listened.","voiceUrl":"voices/chapter-10/ch10-027.mp3","durationMs":12072,"cues":[[7,100],[14,560],[22,900],[25,1320],[28,1440],[32,1560],[45,1720],[51,2320],[53,2520],[60,2640],[66,3920],[70,4019],[80,4180],[84,4660],[91,4800],[94,5060],[99,5200],[103,5440],[105,6420],[111,6460],[115,6640],[118,6800],[121,6940],[125,7040],[129,7120],[133,7300],[140,7480],[146,7840],[150,8140],[154,8260],[157,8420],[168,8540],[170,10200],[178,10280],[183,10600],[186,10800],[190,10880],[196,11000],[200,11360],[209,11520]]},"ch11-001":{"text":"Aleem, there's someone I work with. A girl I know. I'd like to introduce you to her.","voiceUrl":"voices/chapter-11/ch11-001.mp3","durationMs":7344,"cues":[[7,180],[15,1280],[23,1860],[25,2280],[30,2380],[36,2720],[38,3760],[43,3920],[45,4300],[51,4420],[55,5280],[60,5500],[63,5760],[73,5860],[77,6580],[80,6760],[84,6920]]},"ch11-002":{"text":"Her name is Nurulain.","voiceUrl":"voices/chapter-11/ch11-002.mp3","durationMs":3120,"cues":[[4,160],[9,400],[12,1000],[21,1240]]},"ch11-003":{"text":"Nurulain. A name I had never attached to a memory, a disappointment, or something I wished I had said differently. I listened to Kak Mariam and felt a small, unfamiliar willingness. I could get to know someone. That was all an introduction needed to mean for now.","voiceUrl":"voices/chapter-11/ch11-003.mp3","durationMs":19680,"cues":[[10,180],[12,1820],[17,1940],[19,2460],[23,2520],[29,2680],[38,2940],[41,3560],[43,3680],[51,3780],[53,4740],[69,4820],[72,5780],[82,6200],[84,6540],[91,6640],[93,6980],[97,7020],[102,7180],[115,7420],[117,9320],[126,9400],[129,9920],[133,10060],[140,10340],[144,11060],[149,11240],[151,11440],[158,11600],[169,12080],[182,12780],[184,14400],[190,14500],[194,14860],[197,15080],[202,15240],[211,15520],[216,16800],[220,16960],[224,17260],[227,17580],[240,17760],[247,18340],[250,18680],[255,18820],[259,19160],[263,19320]]},"ch11-004":{"text":"When it was time to message her, I made the first move. Moving on had given me room to try again; it hadn't removed every doubt. I still paused over the screen. Then I thought of the trust I had carried home from Umrah. I couldn't know His plans by waiting until I felt completely certain.","voiceUrl":"voices/chapter-11/ch11-004.mp3","durationMs":19440,"cues":[[5,60],[8,220],[12,380],[17,600],[20,860],[28,1000],[33,1360],[35,2240],[40,2340],[44,2520],[50,2640],[56,3020],[63,4160],[66,4520],[70,4700],[76,4860],[79,5140],[84,5380],[87,5700],[91,5840],[98,6100],[101,6980],[108,7260],[116,7560],[122,8060],[129,8340],[131,9440],[137,9540],[144,9800],[149,10320],[153,10500],[161,10640],[166,11840],[168,12020],[176,12120],[179,12320],[183,12440],[189,12620],[191,13060],[195,13120],[203,13280],[208,13620],[213,14000],[220,14300],[222,15140],[231,15260],[236,15620],[240,15940],[246,16160],[249,16640],[257,16880],[263,17240],[265,17620],[270,17740],[281,18060],[289,18900]]},"ch11-005":{"text":"Assalamualaikum, Nurul. I'm Aleem. Kak Mariam introduced us. How are you?","voiceUrl":"voices/chapter-11/ch11-005.mp3","durationMs":4704,"cues":[[17,100],[24,860],[28,1600],[35,1740],[39,2560],[46,2700],[57,3020],[61,3400],[65,3980],[69,4100],[73,4240]]},"ch11-006":{"text":"She answered, and we began talking. Nothing went dramatically wrong. There were greetings, questions, little exchanges about our days. If you had asked me then, I would have said things were okay. Looking back at how little I gave her to work with, I think she deserved a more generous conversation than okay.","voiceUrl":"voices/chapter-11/ch11-006.mp3","durationMs":22320,"cues":[[4,140],[14,320],[18,820],[21,1140],[27,1280],[36,1640],[44,2940],[49,3320],[62,3560],[69,4220],[75,5240],[80,5380],[91,5560],[102,6420],[109,7220],[119,7460],[125,8260],[129,8540],[135,8780],[138,10120],[142,10260],[146,10340],[152,10540],[155,10860],[161,11060],[163,12200],[169,12300],[174,12440],[179,12600],[186,12860],[191,13160],[197,13380],[205,14980],[210,15300],[213,15580],[217,15680],[224,15940],[226,16340],[231,16460],[235,16660],[238,16840],[243,16980],[249,17260],[251,18400],[257,18500],[261,18740],[270,18900],[272,19320],[277,19380],[286,19620],[299,20020],[304,20740],[309,21640]]},"ch11-007":{"text":"What do you usually do when you're free? Meet your friends?","voiceUrl":"voices/chapter-11/ch11-007.mp3","durationMs":3744,"cues":[[5,200],[8,380],[12,560],[20,780],[23,1240],[28,1540],[35,1720],[41,1900],[46,2660],[51,2860],[59,3000]]},"ch11-008":{"text":"Sometimes. Depends if everyone's free.","voiceUrl":"voices/chapter-11/ch11-008.mp3","durationMs":2304,"cues":[[11,140],[19,900],[22,1240],[33,1360],[38,1720]]},"ch11-009":{"text":"That was the sort of answer I sent. Accurate. Finished. No question travelling back with it. Nurul would find another opening: something about me, something about the people I mentioned. I would answer that too. From my side of the phone, I thought I was allowing things to happen naturally. She was doing most of the happening.","voiceUrl":"voices/chapter-11/ch11-009.mp3","durationMs":22224,"cues":[[5,120],[9,360],[13,600],[18,820],[21,1020],[28,1180],[30,1520],[36,1660],[46,2560],[56,3640],[59,4840],[68,5080],[79,5620],[84,6060],[89,6300],[93,6460],[99,7420],[105,7880],[110,8080],[118,8360],[127,8720],[137,9540],[143,9860],[147,10200],[157,10940],[163,11260],[167,11700],[174,11840],[176,12200],[187,12300],[189,13320],[195,13380],[202,13540],[207,13840],[212,14280],[217,15380],[220,15600],[225,15880],[228,16120],[232,16239],[239,16340],[241,17020],[249,17100],[251,17400],[255,17480],[264,17640],[271,18060],[274,18360],[281,18460],[292,19040],[296,20340],[300,20640],[306,20820],[311,21100],[314,21400],[318,21500],[328,21620]]},"ch11-010":{"text":"My excuse was familiar to me. If a girl wasn't interested, I didn't want to pour my effort and energy into persuading her. I had done enough waiting beside one-sided conversations. But I had brought that caution into a conversation with someone who kept showing up. I was watching for her interest while doing very little to show my own.","voiceUrl":"voices/chapter-11/ch11-010.mp3","durationMs":21744,"cues":[[3,180],[10,300],[14,880],[23,1080],[26,1540],[30,1660],[33,2560],[35,2660],[40,2760],[47,3060],[59,3460],[61,4120],[68,4200],[73,4440],[76,4640],[81,4820],[84,5100],[91,5400],[95,5780],[102,6080],[107,6560],[118,6760],[123,7280],[125,8460],[129,8520],[134,8680],[141,8880],[149,9260],[156,9620],[166,10080],[181,10800],[185,12480],[187,12720],[191,12800],[199,12960],[204,13260],[212,13540],[217,14160],[219,14380],[232,14480],[237,15200],[245,15360],[249,15660],[254,15880],[262,16540],[266,16980],[268,18000],[272,18080],[281,18220],[285,18620],[289,18740],[298,18960],[304,19500],[310,19820],[315,20140],[322,20460],[325,20820],[330,20960],[333,21180],[337,21400]]},"ch11-011":{"text":"Much later, Nurul told me what she had thought of those early messages. She had wondered whether I was a narcissist. I winced when I heard it. She was describing her first impression of a man who answered questions about himself and scarcely asked about her. I understood how I had given her that impression.","voiceUrl":"voices/chapter-11/ch11-011.mp3","durationMs":20640,"cues":[[5,320],[12,620],[18,1380],[23,1880],[26,2200],[31,2400],[35,2620],[39,2720],[47,2860],[50,3080],[56,3200],[62,3440],[72,3700],[76,5240],[80,5360],[89,5500],[97,6000],[99,6440],[103,6540],[105,6700],[117,6880],[119,8480],[126,8640],[131,9180],[133,9360],[139,9440],[143,9680],[147,10760],[151,10900],[162,11060],[166,11680],[172,11860],[183,12160],[186,12620],[188,12740],[192,12820],[196,13080],[205,13260],[215,13600],[221,14080],[229,14280],[233,15260],[242,15440],[248,15980],[254,16280],[259,16520],[261,17860],[272,17960],[276,18640],[278,19140],[282,19160],[288,19340],[292,19560],[297,19760],[308,19940]]},"ch11-012":{"text":"Would you like to meet? We can eat and talk properly.","voiceUrl":"voices/chapter-11/ch11-012.mp3","durationMs":3912,"cues":[[6,100],[10,260],[15,400],[18,640],[24,780],[27,1880],[31,2020],[35,2200],[39,2540],[44,2820],[53,3140]]},"ch11-013":{"text":"She initiated our first meeting. Even that small suggestion reached me more deeply than she could have known. Someone wanted to spend time with me enough to ask. I accepted, pleased and still a little careful, and we arranged to eat at Yakiniku. At least there, my replies would have a face and a voice attached to them.","voiceUrl":"voices/chapter-11/ch11-013.mp3","durationMs":23592,"cues":[[4,200],[14,360],[18,1080],[24,1340],[33,1700],[38,2920],[43,3220],[49,3600],[60,3960],[68,4580],[71,4980],[76,5180],[83,5540],[88,6020],[92,6260],[98,6440],[103,6580],[110,6760],[118,8100],[125,8600],[128,8960],[134,9140],[139,9440],[144,9700],[147,9900],[154,10040],[157,10580],[162,10880],[164,12360],[174,12480],[182,13460],[186,14220],[192,14500],[194,14900],[201,15000],[210,15320],[214,16140],[217,16280],[226,16420],[229,16820],[233,17000],[236,17180],[246,17380],[249,18800],[255,18940],[262,19460],[265,19880],[273,20120],[279,20720],[284,20900],[286,21060],[291,21200],[295,21840],[297,22100],[303,22220],[312,22720],[315,23160],[320,23260]]},"ch11-014":{"text":"Across the grill, Nurul became more than the person keeping my phone conversation alive. Her smile was bright. I could see when a thought amused her before she said it, and hear the small changes in her voice that a message couldn't carry. We settled opposite each other with beef to grill and plenty we still didn't know.","voiceUrl":"voices/chapter-11/ch11-014.mp3","durationMs":18864,"cues":[[7,120],[11,540],[18,700],[24,1400],[31,1840],[36,2180],[41,2420],[45,2560],[52,2700],[60,3100],[63,3380],[69,3560],[82,3840],[89,4460],[93,5600],[99,5820],[103,6380],[111,6620],[113,7760],[119,7820],[123,8020],[128,8240],[130,8400],[138,8480],[145,8700],[149,9140],[156,9320],[160,9660],[165,9840],[169,10040],[173,10640],[178,10760],[182,10900],[188,11060],[196,11400],[199,11840],[203,11940],[209,12080],[214,12440],[216,12560],[224,12660],[233,13080],[240,13400],[243,14780],[251,14940],[260,15300],[265,15660],[271,15860],[276,16040],[281,16239],[284,16500],[290,16620],[294,17180],[301,17320],[304,17700],[310,17900],[317,18140],[322,18400]]},"ch11-015":{"text":"So. Are you always this quiet, or only when you're texting?","voiceUrl":"voices/chapter-11/ch11-015.mp3","durationMs":4632,"cues":[[4,200],[8,1000],[12,1200],[19,1580],[24,2000],[31,2240],[34,2820],[39,3240],[44,3500],[51,3660],[59,3820]]},"ch11-016":{"text":"Is my texting that bad?","voiceUrl":"voices/chapter-11/ch11-016.mp3","durationMs":2232,"cues":[[3,140],[6,320],[14,560],[19,1100],[23,1480]]},"ch11-017":{"text":"You answer the question very efficiently.","voiceUrl":"voices/chapter-11/ch11-017.mp3","durationMs":3120,"cues":[[4,200],[11,460],[15,820],[24,940],[29,1600],[41,2100]]},"ch11-018":{"text":"I laughed, partly because I could hear the space she had politely left after that sentence. The beef sizzled between us. I turned a piece and found it easier to admit my awkwardness with something ordinary to do with my hands. She waited, smiling, and I managed more than the few words I would have sent from home.","voiceUrl":"voices/chapter-11/ch11-018.mp3","durationMs":20064,"cues":[[2,220],[11,320],[18,1140],[26,1500],[28,1820],[34,1880],[39,2020],[43,2200],[49,2400],[53,2940],[57,3060],[66,3200],[71,3700],[77,4040],[82,4300],[92,4540],[96,5760],[101,5940],[109,6520],[117,6880],[121,7260],[123,8280],[130,8380],[132,8620],[138,8720],[142,9000],[148,9180],[151,9420],[158,9600],[161,10000],[167,10140],[170,10460],[182,10700],[187,11380],[197,11600],[206,12080],[209,12660],[212,12780],[217,12900],[220,13060],[227,13240],[231,14480],[239,14640],[248,15500],[252,16660],[254,16960],[262,17080],[267,17720],[272,17980],[276,18140],[280,18280],[286,18500],[288,18920],[294,19000],[299,19120],[304,19280],[309,19520],[314,19700]]},"ch11-019":{"text":"I think I hold back at first. I don't want to keep bothering someone if she's not interested. But I can see how that looks from your side.","voiceUrl":"voices/chapter-11/ch11-019.mp3","durationMs":6240,"cues":[[2,180],[8,200],[10,420],[15,480],[20,700],[23,920],[30,1080],[32,1880],[38,1940],[43,2080],[46,2140],[51,2240],[61,2460],[69,2860],[72,3260],[78,3360],[82,3540],[94,3760],[98,4620],[100,4740],[104,4780],[108,4960],[112,5100],[117,5220],[123,5360],[128,5540],[133,5700],[138,5860]]},"ch11-020":{"text":"If I ask you something, you can ask me also. I don't mind answering.","voiceUrl":"voices/chapter-11/ch11-020.mp3","durationMs":5112,"cues":[[3,140],[5,340],[9,580],[13,860],[24,1120],[28,1960],[32,2120],[36,2300],[39,2540],[45,2740],[47,3800],[53,3880],[58,4120],[68,4400]]},"ch11-021":{"text":"There was nothing difficult about her request. Still, hearing it aloud made me notice how often I had treated a reply as the end of my part. I asked something back. She answered. A detail led to another question, and for a while neither of us needed to search for the next subject. We only had to remember the food.","voiceUrl":"voices/chapter-11/ch11-021.mp3","durationMs":20472,"cues":[[6,140],[10,260],[18,440],[28,780],[34,1180],[38,1480],[47,1620],[54,2940],[62,3700],[65,4000],[71,4140],[76,4620],[79,4840],[86,4980],[90,5320],[96,5520],[98,5900],[102,5960],[110,6140],[112,6540],[118,6620],[121,7340],[125,7540],[129,7720],[132,7980],[135,8140],[141,8380],[143,9600],[149,9760],[159,10160],[165,10560],[169,11220],[179,11440],[181,12380],[188,12480],[192,13020],[195,13280],[203,13400],[213,13760],[217,14620],[221,14780],[223,14920],[229,15020],[237,15380],[240,15700],[243,15840],[250,16020],[253,16360],[260,16520],[264,16860],[268,16980],[273,17100],[282,17520],[285,18720],[290,18880],[294,19140],[297,19300],[306,19420],[310,19880],[315,20040]]},"ch11-yakiniku-pause":{"text":"Once, I stopped halfway through an answer to turn the beef. By the time I looked up, I had lost the rest of the sentence. She reminded me where I had been. I liked that: we could interrupt a conversation to deal with dinner, laugh about it, and find our way back together.","voiceUrl":"voices/chapter-11/ch11-yakiniku-pause.mp3","durationMs":17352,"cues":[[6,180],[8,780],[16,920],[24,1160],[32,1500],[35,1700],[42,1860],[45,2260],[50,2380],[54,2580],[60,2720],[63,3800],[67,3940],[72,4059],[74,4340],[81,4420],[85,4740],[87,5180],[91,5220],[96,5380],[100,5840],[105,5940],[108,6220],[112,6360],[122,6480],[126,8000],[135,8160],[138,8660],[144,8880],[146,9120],[150,9180],[156,9360],[158,10560],[164,10640],[170,10960],[173,11940],[179,12060],[189,12240],[191,12660],[204,12740],[207,13440],[212,13560],[217,13780],[225,14000],[231,14700],[237,15020],[241,15300],[245,15480],[250,15800],[254,16059],[258,16340],[263,16540],[272,16780]]},"ch11-022":{"text":"The grill gave us pauses without making them feel empty. We could stop to eat, look down to see what was ready, then return to a sentence. Nurul seemed more at ease as we talked. She would tell me that meeting face to face was much better. I was glad she had given the person behind those dry messages a chance.","voiceUrl":"voices/chapter-11/ch11-022.mp3","durationMs":20544,"cues":[[4,120],[10,260],[15,720],[18,960],[25,1240],[33,1880],[40,2240],[45,2520],[50,2740],[57,3040],[60,4500],[66,4600],[71,4820],[74,5060],[79,5220],[84,5800],[89,6000],[92,6260],[96,6380],[101,6560],[105,6760],[112,6940],[117,7620],[124,7840],[127,8260],[129,8360],[139,8440],[145,10260],[152,10780],[157,11100],[160,11260],[165,11460],[168,11860],[171,12000],[179,12160],[183,13280],[189,13380],[194,13540],[197,13760],[202,13940],[210,14180],[215,14580],[218,14820],[223,14940],[227,15280],[232,15480],[240,15680],[242,16900],[246,16980],[251,17140],[255,17460],[259,17560],[265,17680],[269,17880],[276,18000],[283,18340],[289,18760],[293,19060],[302,19380],[304,19900],[311,20020]]},"ch11-023":{"text":"I want to say something. When you greet me, or start a conversation... I really appreciate it. It may seem small to you, but it means a lot to me.","voiceUrl":"voices/chapter-11/ch11-023.mp3","durationMs":9024,"cues":[[2,120],[7,140],[10,240],[14,360],[25,540],[30,1500],[34,1620],[40,1760],[44,2000],[47,2440],[53,2580],[55,2720],[71,2800],[73,4040],[80,4180],[91,4400],[95,4860],[98,5700],[102,5800],[107,6020],[113,6300],[116,6560],[121,6680],[125,7200],[128,7300],[134,7440],[136,7840],[140,7940],[143,8340],[146,8460]]},"ch11-024":{"text":"I didn't give her my whole history across that table. I simply wanted her to know I noticed. I had grown used to being the one reaching, keeping a thread alive, finding a reason to speak. With Nurul, a conversation could arrive because she had thought of me. It felt like a breath of fresh air.","voiceUrl":"voices/chapter-11/ch11-024.mp3","durationMs":18864,"cues":[[2,280],[9,300],[14,600],[18,820],[21,980],[27,1200],[35,1440],[42,1840],[47,2240],[54,2440],[56,3400],[63,3560],[70,3960],[74,4280],[77,4440],[82,4580],[84,5040],[93,5200],[95,6480],[99,6540],[105,6680],[110,7020],[113,7220],[119,7320],[123,7540],[127,7700],[137,7940],[145,8620],[147,9040],[154,9140],[161,9440],[169,9880],[171,10320],[178,10420],[181,10760],[188,10960],[193,12060],[200,12300],[202,13340],[215,13420],[221,14080],[228,14220],[236,14720],[240,15160],[244,15340],[252,15580],[255,15840],[259,16079],[262,16900],[267,17040],[272,17260],[274,17440],[281,17560],[284,17880],[290,18020],[294,18360]]},"ch11-025":{"text":"That was when I first wondered whether she could be the one. The thought arrived quietly while she was still right there, talking to me. I didn't need to turn it into an announcement. I wanted another meal, another conversation, more chances to know the woman who had made this one possible.","voiceUrl":"voices/chapter-11/ch11-025.mp3","durationMs":17040,"cues":[[5,100],[9,300],[14,460],[16,640],[22,760],[31,1100],[39,1480],[43,1800],[49,2120],[52,2280],[56,2420],[61,2600],[65,3660],[73,3800],[81,4059],[89,4480],[95,5140],[99,5320],[103,5440],[109,5600],[115,5880],[122,6140],[130,6460],[133,6860],[137,6940],[139,7860],[146,7920],[151,8200],[154,8420],[159,8560],[162,8740],[167,8900],[170,9080],[184,9220],[186,10520],[193,10600],[201,10960],[207,11340],[215,11920],[229,12240],[234,13520],[242,13740],[245,14320],[250,14480],[254,14700],[260,14820],[264,15140],[268,15220],[273,15380],[278,15700],[282,16040],[291,16340]]},"ch11-reciprocity-greeting":{"text":"Her hello had already changed the shape of an ordinary day. I wanted to remember that feeling when it was my turn to reach for the phone: how good it was to know someone had made a little room for me.","voiceUrl":"voices/chapter-11/ch11-reciprocity-greeting.mp3","durationMs":12624,"cues":[[4,120],[10,340],[14,820],[22,1000],[30,1500],[34,2000],[40,2120],[43,2400],[46,2520],[55,2660],[60,3200],[62,4360],[69,4460],[72,4760],[81,4860],[86,5340],[94,5560],[99,6200],[102,6320],[106,6420],[109,6660],[114,6920],[117,7160],[123,7240],[127,7480],[131,7600],[138,7700],[142,8680],[147,8920],[150,9060],[154,9220],[157,9500],[162,9600],[170,9800],[174,10060],[179,10240],[181,10960],[188,11040],[193,11360],[197,11940],[200,12120]]},"ch11-reciprocity-return":{"text":"She had given me so many chances to speak. I wanted to know what she would say if I gave her the same room. There was a person across from me, with a whole life I had barely begun to ask about.","voiceUrl":"voices/chapter-11/ch11-reciprocity-return.mp3","durationMs":12864,"cues":[[4,100],[8,200],[14,340],[17,580],[20,780],[25,920],[33,1180],[36,1700],[43,1880],[45,3140],[52,3240],[55,3580],[60,3720],[65,3960],[69,4220],[75,4460],[79,4720],[82,4960],[84,5160],[89,5280],[93,5480],[97,5620],[102,5780],[108,6100],[114,7520],[118,7640],[120,7780],[127,7900],[134,8320],[139,8740],[143,8940],[148,9720],[150,9880],[156,10040],[161,10440],[163,10880],[167,10940],[174,11120],[180,11520],[183,11920],[187,12120],[193,12380]]},"ch11-reciprocity-ease":{"text":"I had spent so long trying to become someone another person might choose. Here I could eat, laugh at myself, and finish a thought. I wanted to stay present enough to enjoy that ease with her.","voiceUrl":"voices/chapter-11/ch11-reciprocity-ease.mp3","durationMs":12072,"cues":[[2,280],[6,320],[12,560],[15,920],[20,1160],[27,1480],[30,1760],[37,1840],[45,2180],[53,2600],[60,3040],[66,3420],[74,3680],[79,4900],[81,5300],[87,5360],[92,5660],[98,6460],[101,6740],[109,6900],[113,7480],[120,7720],[122,8039],[131,8160],[133,9100],[140,9180],[143,9500],[148,9640],[156,9860],[163,10220],[166,10500],[172,10600],[177,11060],[182,11360],[187,11640],[191,11780]]},"ch11-reciprocity-join":{"text":"We met again. Then again. The first meeting became something we could refer back to, instead of the only thing we knew about being together. A familiar smile greeted me. Conversation picked up from something we had mentioned before. I began looking forward to her company in the middle of otherwise ordinary days.","voiceUrl":"voices/chapter-11/ch11-reciprocity-join.mp3","durationMs":19344,"cues":[[3,120],[7,280],[14,480],[19,1900],[26,2060],[30,3260],[36,3400],[44,3740],[51,4080],[61,4420],[64,4800],[70,4940],[76,5100],[81,5440],[85,5740],[93,6160],[96,6540],[100,6660],[105,6800],[111,7060],[114,7260],[119,7420],[125,7660],[131,7920],[141,8140],[143,9560],[152,9640],[158,10140],[166,10540],[170,10900],[183,11820],[190,12520],[193,12780],[198,12920],[208,13160],[211,13520],[215,13580],[225,13720],[233,14060],[235,15280],[241,15360],[249,15680],[257,16020],[260,16360],[264,16520],[272,16680],[275,17060],[279,17140],[286,17240],[289,17480],[299,17720],[308,18320],[313,18860]]},"ch11-026":{"text":"Getting to know her didn't happen in one long, revealing conversation. It came in smaller pieces: an answer she expanded because I had asked, a joke I understood more quickly now, a pause I could leave alone. I was still learning to be curious. Sometimes I noticed a question only after I had already started talking about myself again.","voiceUrl":"voices/chapter-11/ch11-026.mp3","durationMs":24144,"cues":[[8,140],[11,460],[16,620],[20,920],[27,1180],[34,1520],[37,1920],[41,2200],[47,2560],[57,3100],[71,3720],[74,5280],[79,5400],[82,5600],[90,5780],[98,6140],[101,7360],[108,7500],[112,7920],[121,8060],[129,8740],[131,9180],[135,9240],[142,9480],[144,10360],[149,10480],[151,11000],[162,11080],[167,11520],[175,11740],[180,12100],[182,13300],[188,13440],[190,14280],[196,14360],[202,14500],[209,14720],[211,16059],[215,16140],[221,16320],[230,16580],[233,17000],[236,17120],[245,17380],[255,18740],[257,19380],[265,19480],[267,19860],[276,19960],[281,20500],[287,20980],[289,21340],[293,21400],[301,21660],[309,22140],[317,22560],[323,22920],[330,23160],[336,23640]]},"ch11-meetings-listening":{"text":"I could catch myself and return to what she had been saying. It was a little awkward sometimes. I would ask her to go on, then wait while she found the thread again. But I wanted her to finish. I was beginning to understand how much of a person I could miss while preparing my own next sentence.","voiceUrl":"voices/chapter-11/ch11-meetings-listening.mp3","durationMs":20472,"cues":[[2,160],[8,240],[14,460],[21,760],[25,1260],[32,1500],[35,1900],[40,2000],[44,2220],[48,2340],[53,2460],[61,2700],[64,4240],[68,4380],[70,4800],[77,4900],[85,5340],[96,6040],[98,7340],[104,7400],[108,7600],[112,7780],[115,7900],[118,8020],[122,8260],[127,8860],[132,9340],[138,9860],[142,10100],[148,10300],[152,10740],[159,10880],[166,11180],[170,12460],[172,12640],[179,12800],[183,13280],[186,13420],[194,13560],[196,14720],[200,14800],[210,14940],[213,15340],[224,15460],[228,16040],[233,16260],[236,16460],[238,16580],[245,16700],[247,17140],[253,17220],[258,17460],[264,17860],[274,18100],[277,18620],[281,18880],[286,19340],[295,19880]]},"ch11-027":{"text":"And I could still feel a distance between us. We could have a good time together and reach a point where she held something back. I pictured a wall in front of her, though I knew that was my way of describing what I felt. Nurul had her own reasons for being careful. I didn't yet know all of them.","voiceUrl":"voices/chapter-11/ch11-027.mp3","durationMs":19992,"cues":[[4,120],[6,340],[12,460],[18,740],[23,1080],[25,1340],[34,1460],[42,2120],[46,2520],[49,3460],[55,3560],[60,3720],[62,3880],[67,3960],[72,4160],[81,4460],[85,5100],[91,5280],[93,5480],[99,5580],[105,5880],[109,6220],[114,6420],[124,6720],[130,7100],[132,8360],[141,8480],[143,8840],[148,8980],[151,9620],[157,9780],[160,9980],[165,10080],[172,10800],[174,11220],[179,11340],[184,11760],[188,12040],[191,12240],[195,12460],[198,12600],[209,12700],[214,13380],[216,13700],[222,13820],[228,15100],[232,15800],[236,15980],[240,16180],[248,16360],[252,16720],[258,16880],[267,17120],[269,18220],[276,18320],[280,18660],[285,19040],[289,19420],[292,19540],[297,19680]]},"ch11-028":{"text":"I wanted her to feel safe with me. Wanting it didn't make it happen immediately. I couldn't count our meetings and decide she had been given enough time. So I kept showing up, and tried to leave space around what she wasn't ready to share. The person who had been patient with my dry replies deserved patience from me too.","voiceUrl":"voices/chapter-11/ch11-028.mp3","durationMs":21120,"cues":[[2,240],[9,340],[13,660],[16,820],[21,960],[26,1220],[31,1480],[35,1660],[43,2660],[46,3080],[53,3380],[58,3620],[61,3780],[68,3900],[81,4240],[83,5560],[92,5640],[98,5940],[102,6280],[111,6500],[115,7020],[122,7180],[126,7800],[130,7920],[135,8039],[141,8260],[148,8560],[154,8880],[157,10100],[159,10260],[164,10380],[172,10740],[176,11140],[180,11840],[186,11960],[189,12200],[195,12300],[201,12580],[208,12940],[213,13320],[217,13580],[224,13760],[230,14120],[233,14420],[240,14560],[244,15880],[251,16020],[255,16480],[259,16600],[264,16720],[272,16940],[277,17420],[280,17620],[284,17920],[292,18300],[301,19240],[310,19820],[315,20300],[318,20480],[322,20740]]},"ch11-029":{"text":"Then, in our messages, she asked a question that made me sit with the phone for a moment. We had been seeing each other, becoming part of each other's time. She wanted to know where we were going with it.","voiceUrl":"voices/chapter-11/ch11-029.mp3","durationMs":13512,"cues":[[6,140],[9,740],[13,940],[23,1220],[27,2220],[33,2480],[35,2780],[44,2900],[49,3380],[54,3600],[57,3800],[61,4059],[66,4360],[70,4520],[76,4640],[80,5040],[82,5200],[90,5300],[93,6620],[97,6740],[102,6900],[109,7160],[114,7460],[121,7700],[130,8260],[135,8840],[138,9080],[143,9180],[151,9380],[157,9680],[161,10920],[168,11100],[171,11400],[176,11540],[182,12060],[185,12360],[190,12500],[196,12700],[201,13060],[204,13240]]},"ch11-030":{"text":"What's next?","voiceUrl":"voices/chapter-11/ch11-030.mp3","durationMs":1200,"cues":[[7,280],[12,600]]},"ch11-031":{"text":"I thought about giving her another reassuring sentence. Instead, I found myself considering something I had never done before. I wanted to meet her parents. I wanted to sit with the people who knew and loved her, let them know who I was, and show her that my interest had a sincere direction.","voiceUrl":"voices/chapter-11/ch11-031.mp3","durationMs":19344,"cues":[[2,260],[10,360],[16,660],[23,960],[27,1220],[35,1380],[46,1760],[56,2360],[65,3640],[67,4120],[73,4220],[80,4440],[92,4840],[102,5440],[104,6040],[108,6060],[114,6260],[119,6540],[127,6760],[129,8560],[136,8640],[139,8960],[144,9060],[148,9240],[157,9420],[159,11040],[166,11120],[169,11420],[173,11620],[178,11900],[182,12020],[189,12160],[193,12520],[198,12740],[202,13160],[208,13380],[213,13640],[217,14120],[222,14320],[227,14540],[231,14840],[233,15220],[238,15360],[242,16100],[247,16340],[251,16620],[256,16820],[259,17000],[268,17260],[272,17740],[274,17900],[282,18040],[292,18660]]},"ch11-032":{"text":"I'd like to meet your parents, if you're comfortable with that. I'm serious about getting to know you. I would like to know them too.","voiceUrl":"voices/chapter-11/ch11-032.mp3","durationMs":6552,"cues":[[4,180],[9,300],[12,460],[17,560],[22,700],[31,840],[34,1780],[41,1880],[53,2020],[58,2400],[64,2520],[68,3360],[76,3620],[82,3920],[90,4080],[93,4280],[98,4380],[103,4560],[105,5220],[111,5240],[116,5360],[119,5540],[124,5640],[129,5800],[133,6040]]},"ch11-033":{"text":"At the time, I thought I had made my intention clearer. I didn't know that my answer had made her feel even more intimidated. She told me later that it had felt as though I might force my way into her life. I had heard her question as an opening; she still needed to feel that she had room to choose.","voiceUrl":"voices/chapter-11/ch11-033.mp3","durationMs":20064,"cues":[[3,120],[7,240],[13,360],[15,800],[23,900],[25,1200],[29,1260],[34,1400],[37,1600],[47,1720],[56,2280],[58,3840],[65,3920],[70,4200],[75,4480],[78,4660],[85,4880],[89,5240],[94,5420],[98,5620],[103,5800],[108,6120],[113,6420],[126,6840],[130,8540],[135,8700],[138,8920],[144,9100],[149,9540],[152,9820],[156,9920],[161,10120],[164,10400],[171,10540],[173,10800],[179,10880],[185,11220],[188,11560],[192,11780],[197,12060],[201,12300],[207,12480],[209,13860],[213,13900],[219,14100],[223,14380],[232,14560],[235,15320],[238,15460],[247,15660],[251,16840],[257,17040],[264,17300],[267,17600],[272,17760],[277,18100],[281,18280],[285,18420],[290,18680],[293,19240],[300,19440]]},"ch11-034":{"text":"Remembering that now, I can understand both sides of the message. I was trying to offer something solid. From where she stood, it was a large step arriving while she was still learning to trust me. Sincerity needed to be felt in the way I treated her, including how I made room for her uncertainty.","voiceUrl":"voices/chapter-11/ch11-034.mp3","durationMs":18864,"cues":[[12,100],[17,620],[22,860],[24,1600],[28,1660],[39,1800],[44,2340],[50,2660],[53,2940],[57,3020],[66,3120],[68,4620],[72,4700],[79,4880],[82,5160],[88,5320],[98,5600],[105,6020],[110,6960],[116,7140],[120,7360],[127,7620],[130,8160],[134,8300],[136,8460],[142,8560],[147,8900],[156,9460],[162,9960],[166,10140],[170,10260],[176,10400],[185,10660],[188,11000],[194,11120],[198,11440],[208,12600],[215,13360],[218,13660],[221,13760],[226,14000],[229,14420],[233,14500],[237,14600],[239,14840],[247,14980],[252,15340],[262,16140],[266,16900],[268,17080],[273,17160],[278,17400],[282,17680],[286,17820],[298,18020]]},"ch11-035":{"text":"We arranged the meeting for after my trip to Kazakhstan. The plan gave us something ahead of us, and some time before it arrived. I wanted the evening to go well. More than that, I wanted us to keep getting to know each other in the days before it. Meeting her parents couldn't do that work for us.","voiceUrl":"voices/chapter-11/ch11-035.mp3","durationMs":18072,"cues":[[3,100],[12,220],[16,720],[24,860],[28,1260],[34,1420],[37,1640],[42,1840],[45,2060],[57,2180],[61,3340],[66,3440],[71,3820],[74,4000],[84,4140],[90,4460],[93,4680],[97,4820],[101,5320],[106,5780],[111,6000],[118,6320],[121,6640],[130,6820],[132,8200],[139,8320],[143,8680],[151,8860],[154,9260],[157,9380],[163,9620],[168,10440],[173,10660],[179,10860],[181,11480],[188,11600],[191,11940],[194,12120],[199,12260],[207,12480],[210,12760],[215,12980],[220,13180],[226,13440],[229,13660],[233,13760],[238,13880],[245,14160],[249,14520],[257,15500],[261,15760],[269,15940],[278,16520],[281,16840],[286,17020],[291,17240],[295,17540],[298,17760]]},"ch11-patience-pace":{"text":"My readiness couldn't decide hers. I could tell her what I hoped for, then leave enough room for an honest answer. I wanted whatever grew between us to be something she could step towards willingly.","voiceUrl":"voices/chapter-11/ch11-patience-pace.mp3","durationMs":12000,"cues":[[3,160],[13,420],[22,980],[29,1220],[35,1640],[37,2880],[43,2980],[48,3180],[52,3400],[57,3580],[59,3840],[65,3880],[70,4180],[75,4900],[81,5120],[88,5300],[93,5580],[97,5860],[100,5960],[107,6140],[115,6520],[117,8020],[124,8119],[133,8500],[138,8880],[146,9100],[149,9500],[152,9660],[155,9760],[165,9920],[169,10320],[175,10460],[180,10660],[188,10900],[198,11420]]},"ch11-patience-listen":{"text":"I knew how easily a careful reply could make me anxious. I wanted to hear her properly even then. If something felt too much, she should be able to tell me without having to manage my disappointment first.","voiceUrl":"voices/chapter-11/ch11-patience-listen.mp3","durationMs":12072,"cues":[[2,280],[7,380],[11,600],[18,900],[20,1300],[28,1420],[34,1840],[40,2280],[45,2440],[48,2620],[57,2800],[59,4100],[66,4180],[69,4500],[74,4620],[78,4820],[87,5000],[92,5480],[98,5720],[101,6600],[111,6700],[116,7080],[120,7340],[126,7540],[130,8140],[137,8300],[140,8500],[145,8640],[148,8800],[153,8940],[156,9140],[164,9300],[171,9620],[174,9860],[181,10020],[184,10480],[199,10700],[205,11520]]},"ch11-patience-consistent":{"text":"One serious proposal wasn't the whole of sincerity. There would be another greeting, another question, another chance to remember something she had said. Those were things I could give my attention to now.","voiceUrl":"voices/chapter-11/ch11-patience-consistent.mp3","durationMs":12792,"cues":[[4,140],[12,600],[21,1120],[28,1720],[32,2000],[38,2160],[41,2480],[52,2640],[58,4220],[64,4360],[67,4500],[75,4620],[85,4980],[93,5640],[103,5980],[111,6820],[118,7200],[121,7580],[130,7700],[140,8200],[144,8620],[148,8760],[154,8960],[160,10160],[165,10480],[172,10640],[174,11180],[180,11200],[185,11380],[188,11560],[198,11720],[201,12220],[205,12440]]},"ch11-patience-join":{"text":"I left for Kazakhstan with our conversation still open. Travel made the days different, but she remained someone I wanted to speak to within them. When a quiet moment came, I found myself wondering what her day had been like. This time the thought became a question I actually sent.","voiceUrl":"voices/chapter-11/ch11-patience-join.mp3","durationMs":16320,"cues":[[2,200],[7,280],[11,520],[22,660],[27,1340],[31,1460],[44,1620],[50,2440],[56,2680],[63,3620],[68,4040],[72,4220],[77,4320],[88,4620],[92,5300],[96,5560],[105,5720],[113,6120],[115,6460],[122,6540],[125,6820],[131,7020],[134,7260],[141,7400],[147,7720],[152,8580],[154,8680],[160,8780],[167,9120],[173,9500],[175,10140],[181,10240],[188,10500],[198,10880],[203,11260],[207,11420],[211,11600],[215,11820],[220,11960],[226,12160],[231,13240],[236,13440],[240,13740],[248,13860],[255,14160],[257,14400],[266,14520],[268,15120],[277,15380],[282,15840]]},"ch11-036":{"text":"How was your day? You mentioned something earlier. How did that go?","voiceUrl":"voices/chapter-11/ch11-036.mp3","durationMs":3192,"cues":[[4,180],[8,320],[13,440],[18,540],[22,1220],[32,1300],[42,1680],[51,1980],[55,2560],[59,2660],[64,2760],[67,2920]]},"ch11-037":{"text":"It was a small change on the screen. Inside me, it felt larger. I wanted the answer for its own sake. When she replied, I read what she said instead of only feeling relieved that she had replied. There was something to follow up on, something to remember when we next spoke.","voiceUrl":"voices/chapter-11/ch11-037.mp3","durationMs":19200,"cues":[[3,120],[7,220],[9,420],[15,580],[22,960],[25,1380],[29,1500],[37,1680],[44,2780],[48,3280],[51,3440],[56,3600],[64,3940],[66,5200],[73,5320],[77,5640],[84,5860],[88,6300],[92,6420],[96,6700],[102,7040],[107,8300],[111,8480],[120,8660],[122,9740],[127,9860],[132,10160],[136,10380],[141,10600],[149,10920],[152,11280],[157,11400],[165,11740],[174,12140],[179,12840],[183,13020],[187,13160],[196,13280],[202,14580],[206,14700],[216,14840],[219,15160],[226,15280],[229,15640],[233,15840],[243,16660],[246,17040],[255,17160],[260,17900],[263,18100],[268,18260],[274,18740]]},"ch11-038":{"text":"I could picture her beyond the conversation with me now: having her own day, dealing with things I wasn't there to see, deciding what she wanted to share. I asked about those things. Sometimes I told her something from the trip, and she asked more. Our messages began to feel like a place we both brought our lives to.","voiceUrl":"voices/chapter-11/ch11-038.mp3","durationMs":20304,"cues":[[2,160],[8,240],[16,420],[20,780],[27,1200],[31,1600],[44,1700],[49,2340],[52,2500],[57,2660],[64,3320],[68,3620],[72,3840],[77,4140],[85,5080],[90,5380],[97,5540],[99,6120],[106,6200],[112,6500],[115,6660],[120,6840],[129,7580],[134,8280],[138,8500],[145,8640],[148,8920],[155,9060],[157,10560],[163,10680],[169,10940],[175,11180],[183,11400],[193,12500],[195,12980],[200,13080],[204,13300],[214,13480],[219,13840],[223,14020],[229,14120],[233,14600],[237,14780],[243,14960],[249,15300],[253,16720],[262,16880],[268,17400],[271,17660],[276,17800],[281,18020],[283,18180],[289,18260],[292,18560],[297,18720],[305,19060],[309,19320],[315,19540],[318,19960]]},"ch11-kazakhstan-answer":{"text":"Back at the accommodation, I would sit with a reply a little longer. If I hadn't understood something, I could ask what she meant. I didn't have to offer an immediate solution or turn it into my own similar story. Sometimes she only needed someone to follow what had happened and care enough to hear the rest.","voiceUrl":"voices/chapter-11/ch11-kazakhstan-answer.mp3","durationMs":18960,"cues":[[5,80],[8,260],[12,380],[27,500],[29,1720],[35,1800],[39,2000],[44,2220],[46,2380],[52,2480],[54,2980],[61,3080],[69,3360],[72,4580],[74,4740],[81,4820],[92,5120],[103,5640],[105,6260],[111,6340],[115,6640],[120,6920],[124,7080],[131,7240],[133,8180],[140,8260],[145,8540],[148,8800],[154,9000],[157,9320],[167,9440],[176,9980],[179,10520],[184,10760],[187,11000],[192,11180],[195,11400],[199,11680],[207,12060],[214,12500],[224,13900],[228,14640],[233,14820],[240,15140],[248,15480],[251,15760],[258,15940],[263,16320],[267,16440],[276,16580],[280,17320],[285,17500],[292,17700],[295,18000],[300,18100],[304,18260],[309,18380]]},"ch11-039":{"text":"You remembered?","voiceUrl":"voices/chapter-11/ch11-039.mp3","durationMs":2064,"cues":[[4,360],[15,560]]},"ch11-040":{"text":"Yes. I wanted to know how it turned out.","voiceUrl":"voices/chapter-11/ch11-040.mp3","durationMs":2544,"cues":[[5,240],[7,840],[14,960],[17,1240],[22,1380],[26,1760],[29,1920],[36,2020],[40,2260]]},"ch11-041":{"text":"Curiosity became the key. I had been so occupied with whether someone would choose me that I could forget to learn who she was. Wanting to know Nurul gave my attention somewhere better to go. I could be interested without demanding a promise in return. I liked discovering how much more there was to talk about.","voiceUrl":"voices/chapter-11/ch11-041.mp3","durationMs":22320,"cues":[[10,120],[17,1040],[21,1400],[26,1540],[28,2780],[32,2840],[37,2980],[40,3320],[49,3700],[54,4280],[62,4460],[70,4800],[76,5140],[83,5360],[86,5820],[91,6420],[93,6640],[99,6780],[106,7020],[109,7380],[115,7560],[119,7940],[123,8119],[128,8320],[136,9680],[139,10080],[144,10180],[150,10480],[155,11180],[158,11420],[168,11600],[178,12200],[185,12680],[188,13000],[192,13140],[194,14400],[200,14480],[203,14620],[214,14800],[222,15640],[232,15980],[234,16420],[242,16540],[245,17140],[253,17260],[255,18820],[261,18920],[273,19400],[277,20040],[282,20220],[287,20520],[293,20840],[297,21060],[300,21420],[305,21560],[311,21840]]},"ch11-042":{"text":"I told the friends travelling with me that I was seeing someone. Saying it aloud made me smile before I had finished. They were happy for me and wished us all the best. I let myself receive that warmth without immediately adding a warning about everything that might go wrong.","voiceUrl":"voices/chapter-11/ch11-042.mp3","durationMs":16944,"cues":[[2,260],[7,380],[11,640],[19,740],[30,1160],[35,1580],[38,1780],[43,2000],[45,2680],[49,2740],[56,2920],[65,3240],[72,4600],[75,4820],[81,4980],[86,5340],[89,5540],[95,5760],[102,6120],[104,6440],[108,6500],[118,6660],[123,7600],[128,7740],[134,7920],[138,8280],[141,8480],[145,8960],[152,9180],[155,9460],[159,9780],[163,10000],[169,10120],[171,11320],[175,11380],[182,11560],[190,11940],[195,12360],[202,12580],[210,13080],[222,13600],[229,14240],[231,14480],[239,14640],[245,15060],[256,15460],[261,15880],[267,16040],[270,16280],[276,16460]]},"ch11-043":{"text":"There were still stretches when we were each occupied with our own days. I could leave a message and return to the people around me. Then there would be something from her to read later. I liked that she was becoming part of my life while the rest of it continued around our conversation.","voiceUrl":"voices/chapter-11/ch11-043.mp3","durationMs":16800,"cues":[[6,100],[11,220],[17,400],[27,680],[32,1280],[35,1520],[40,1660],[45,1860],[54,2120],[59,2740],[63,2920],[67,3100],[73,3300],[75,4280],[81,4340],[87,4500],[89,4680],[97,4780],[101,5300],[108,5480],[111,5840],[115,5940],[122,6060],[129,6360],[133,6740],[138,7740],[144,8020],[150,8200],[153,8400],[163,8620],[168,9000],[172,9220],[175,9460],[180,9600],[187,9840],[189,11220],[195,11320],[200,11940],[204,12180],[208,12360],[217,12540],[222,13040],[225,13220],[228,13360],[233,13580],[239,13960],[243,14140],[248,14260],[251,14540],[254,14640],[264,14780],[271,15400],[275,15740],[288,15880]]},"ch11-044":{"text":"As the trip came to a close, the meeting we had arranged became the next real thing on the calendar. Soon I would be sitting opposite her parents. I thought about what I wanted them to understand. There was no impressive version of myself I needed to invent. I wanted to be clear, respectful, and present.","voiceUrl":"voices/chapter-11/ch11-044.mp3","durationMs":20232,"cues":[[3,140],[7,340],[12,460],[17,700],[20,900],[22,1000],[29,1100],[33,1840],[41,1980],[44,2420],[48,2520],[57,2680],[64,3220],[68,3640],[73,3740],[78,4180],[84,4520],[87,4800],[91,4900],[101,5020],[106,6380],[108,7060],[114,7140],[117,7300],[125,7440],[134,7740],[138,8100],[147,8260],[149,9620],[157,9700],[163,9900],[168,10160],[170,10340],[177,10460],[182,10800],[185,11140],[197,11280],[203,12740],[207,12860],[210,12960],[221,13140],[229,13760],[232,14120],[239,14260],[241,14840],[248,14960],[251,15280],[259,15400],[261,16620],[268,16720],[271,16980],[274,17100],[281,17320],[293,18200],[297,19500],[305,19720]]},"ch11-045":{"text":"We met at a restaurant. Her mother had a warm, rounded face; her father was a slim Malay uncle with an easy presence. They were two people curious about the man their daughter was seeing. Standing there before we settled at the table, I felt the importance of it without feeling that I had to hide behind it.","voiceUrl":"voices/chapter-11/ch11-045.mp3","durationMs":20544,"cues":[[3,280],[7,460],[10,880],[12,1000],[24,1080],[28,2740],[35,2880],[39,3300],[41,3440],[47,3600],[55,4280],[61,4780],[65,5820],[72,5960],[76,6340],[78,6500],[83,6660],[89,7000],[95,7440],[100,7820],[103,7980],[108,8200],[118,8540],[123,9900],[128,10020],[132,10200],[139,10460],[147,10940],[153,11420],[157,11620],[161,11740],[167,12000],[176,12220],[180,12540],[188,12720],[197,14020],[203,14400],[210,14800],[213,15120],[221,15300],[224,15680],[228,15800],[235,15920],[237,16940],[242,17020],[246,17220],[257,17320],[260,17940],[263,18060],[271,18340],[279,18680],[284,19020],[286,19200],[290,19260],[293,19440],[298,19560],[305,19840],[308,20240]]},"ch11-046":{"text":"Come, Aleem. Sit. Have you been waiting long?","voiceUrl":"voices/chapter-11/ch11-046.mp3","durationMs":3600,"cues":[[6,200],[13,480],[18,1240],[23,2440],[27,2580],[32,2680],[40,2840],[45,3180]]},"ch11-047":{"text":"No, not long. Thank you for meeting me.","voiceUrl":"voices/chapter-11/ch11-047.mp3","durationMs":3264,"cues":[[4,120],[8,580],[14,760],[20,1640],[24,1820],[28,1900],[36,2020],[39,2260]]},"ch11-048":{"text":"So, you've just come back from your trip?","voiceUrl":"voices/chapter-11/ch11-048.mp3","durationMs":4320,"cues":[[4,260],[11,1460],[16,1840],[21,2180],[26,2500],[31,2940],[36,3260],[41,3600]]},"ch11-049":{"text":"We began there, with something straightforward. I told them about having been away with friends. They asked about me, about work and the shape of my ordinary life. I answered without looking to Nurul to finish every sentence for me. When I needed a moment to think, I took one and continued.","voiceUrl":"voices/chapter-11/ch11-049.mp3","durationMs":18720,"cues":[[3,80],[9,220],[16,600],[21,1300],[31,1540],[48,1900],[50,3320],[55,3400],[60,3600],[66,3780],[73,4019],[78,4280],[83,4440],[88,4700],[97,4880],[102,6000],[108,6180],[114,6520],[118,6780],[124,7540],[129,7840],[133,8220],[137,8320],[143,8420],[146,8660],[149,8780],[158,9060],[164,9560],[166,10920],[175,11020],[183,11340],[191,11680],[194,11980],[200,12140],[203,12520],[210,12660],[216,13060],[225,13380],[229,13820],[233,14020],[238,15020],[240,15180],[247,15260],[249,15560],[256,15620],[259,15880],[266,16059],[268,16980],[273,17060],[277,17340],[281,17820],[291,17960]]},"ch11-parents-listening":{"text":"I asked them questions too. As they spoke, I could see Nurul listening to familiar voices from a place that was new to me. I liked being allowed into that little circle. There was more to knowing her than the time we spent alone together. Here were people for whom she had never been a recent introduction.","voiceUrl":"voices/chapter-11/ch11-parents-listening.mp3","durationMs":18960,"cues":[[2,300],[8,400],[13,660],[23,900],[28,1480],[31,2580],[36,2740],[43,2960],[45,3720],[51,3760],[55,3920],[61,4120],[71,4500],[74,4900],[83,5040],[90,5480],[95,5980],[97,6140],[103,6240],[108,6520],[112,6680],[116,6880],[119,7080],[123,7200],[125,8440],[131,8540],[137,8820],[145,9000],[150,9380],[155,9600],[162,9780],[170,10120],[176,11280],[180,11400],[185,11600],[188,11820],[196,11980],[200,12300],[205,12520],[209,12700],[214,12840],[217,13100],[223,13280],[229,13500],[239,13820],[244,15120],[249,15380],[256,15580],[260,15940],[265,16100],[269,16340],[273,16460],[279,16620],[284,16900],[286,17300],[293,17460],[306,18120]]},"ch11-050":{"text":"And how has it been, getting to know Nurul?","voiceUrl":"voices/chapter-11/ch11-050.mp3","durationMs":2712,"cues":[[4,140],[8,440],[12,600],[15,780],[21,900],[29,1560],[32,1860],[37,1980],[43,2160]]},"ch11-051":{"text":"Good. I'm happy I met her. She's made a lot of effort to know me. At the beginning my messages were very short, so I think she had quite a difficult job.","voiceUrl":"voices/chapter-11/ch11-051.mp3","durationMs":9120,"cues":[[6,100],[10,780],[16,920],[18,1200],[22,1280],[27,1440],[33,2080],[38,2280],[40,2520],[44,2640],[47,2840],[54,3000],[57,3280],[62,3400],[66,3580],[69,4500],[73,4600],[83,4680],[86,5200],[95,5320],[100,5760],[105,5940],[112,6220],[115,6800],[117,7320],[123,7380],[127,7560],[131,7680],[137,7880],[139,8160],[149,8220],[153,8620]]},"ch11-052":{"text":"At least you know now.","voiceUrl":"voices/chapter-11/ch11-052.mp3","durationMs":2232,"cues":[[3,220],[9,420],[13,780],[18,920],[22,1300]]},"ch11-053":{"text":"I looked towards her and smiled. A little laughter travelled around the table, and the conversation felt easier afterwards. I could admit something imperfect about myself and remain there. Her parents listened with the ordinary curiosity of people trying to place a new face within the life of someone they loved.","voiceUrl":"voices/chapter-11/ch11-053.mp3","durationMs":18384,"cues":[[2,200],[9,260],[17,560],[21,920],[25,1020],[33,1220],[35,2460],[42,2520],[51,2760],[61,3180],[68,3500],[72,3760],[79,3860],[83,4560],[87,4640],[100,4740],[105,5360],[112,5740],[124,6380],[126,7860],[132,7920],[138,8080],[148,8600],[158,8940],[164,9500],[171,9760],[175,10340],[182,10460],[189,10840],[193,12000],[201,12160],[210,12540],[215,13340],[219,13460],[228,13640],[238,14100],[241,14700],[248,14820],[255,15160],[258,15400],[264,15480],[266,15740],[270,15860],[275,16120],[282,16700],[286,16920],[291,17040],[294,17320],[302,17460],[307,17720],[313,17880]]},"ch11-054":{"text":"And what are you hoping for, with the two of you?","voiceUrl":"voices/chapter-11/ch11-054.mp3","durationMs":3744,"cues":[[4,160],[9,780],[13,960],[17,1140],[24,1300],[29,1840],[34,2580],[38,2800],[42,2960],[45,3160],[49,3360]]},"ch11-055":{"text":"I'm serious about knowing her. I wanted to meet you because you're part of her life. I hope we can build towards a future together, at a pace we're both comfortable with.","voiceUrl":"voices/chapter-11/ch11-055.mp3","durationMs":9024,"cues":[[4,140],[12,400],[18,900],[26,1100],[31,1400],[33,2360],[40,2460],[43,2680],[48,2780],[52,2980],[60,3340],[67,3720],[72,3900],[75,4059],[79,4140],[85,4300],[87,5440],[92,5480],[95,5640],[99,5740],[105,5880],[113,6100],[115,6300],[122,6400],[132,6640],[135,7380],[137,7480],[142,7580],[148,7880],[153,8039],[165,8280],[170,8660]]},"ch11-056":{"text":"I meant it, and I could hear that in my own voice. I didn't have every future detail ready. I could tell them why I was here. Around that answer, we went on having dinner: listening, eating, asking another question when there was room. The evening had space for everyone at the table.","voiceUrl":"voices/chapter-11/ch11-056.mp3","durationMs":19512,"cues":[[2,280],[8,400],[12,720],[16,1380],[18,1520],[24,1580],[29,1800],[34,2040],[37,2240],[40,2360],[44,2520],[51,2720],[53,4000],[60,4059],[65,4360],[71,4760],[78,5120],[85,5500],[92,5940],[94,6820],[100,6920],[105,7080],[110,7280],[114,7480],[116,7780],[120,7880],[126,8039],[133,9060],[138,9400],[146,9660],[149,10240],[154,10400],[157,10620],[164,10800],[172,11100],[183,11760],[191,12640],[198,13540],[206,13940],[215,14320],[220,14880],[226,15060],[230,15240],[236,15440],[240,16780],[248,16940],[252,17340],[258,17640],[262,18000],[271,18240],[274,18840],[278,18960],[284,19080]]},"ch11-057":{"text":"Nurul would later tell me that seeing me there changed something for her. She saw my confidence, and finally felt the affection behind what I was doing. What had first seemed intimidating began to make sense as sincerity. I was serious about getting to know her and being with her. That was what reached her during the conversation.","voiceUrl":"voices/chapter-11/ch11-057.mp3","durationMs":22464,"cues":[[6,120],[12,640],[18,840],[23,1180],[26,1380],[31,1620],[38,1900],[41,2200],[47,2340],[55,2720],[65,3480],[69,3920],[74,4140],[78,5160],[82,5380],[85,5680],[97,5880],[101,6880],[109,7100],[114,7600],[118,7880],[128,8000],[135,8620],[140,9080],[142,9300],[146,9400],[153,9580],[158,10480],[162,10860],[168,11460],[175,11740],[188,12060],[194,12760],[197,13060],[202,13160],[208,13400],[211,13940],[222,14400],[224,15880],[228,15960],[236,16140],[242,16580],[250,16840],[253,17140],[258,17280],[262,17520],[266,17800],[272,18140],[277,18560],[282,18720],[287,19860],[291,20260],[296,20460],[304,20680],[308,21000],[315,21220],[319,21440],[332,21560]]},"ch11-058":{"text":"I treasure that part of her account because I hadn't been able to see it happening inside her. I had simply tried to speak honestly to two kind people. Later, knowing what the evening had meant to her, I felt grateful that she had let me come, and that we had given each other the time to understand it.","voiceUrl":"voices/chapter-11/ch11-058.mp3","durationMs":16944,"cues":[[2,200],[11,220],[16,620],[21,860],[24,1080],[28,1180],[36,1340],[44,1840],[46,2160],[53,2200],[58,2440],[63,2620],[66,2840],[70,3000],[73,3140],[83,3260],[90,3640],[95,4100],[97,5100],[101,5160],[108,5320],[114,5640],[117,5900],[123,6060],[132,6380],[135,7000],[139,7140],[144,7420],[152,7820],[159,9100],[167,9740],[172,10040],[176,10180],[184,10320],[188,10580],[194,10740],[197,10940],[202,11080],[204,12020],[209,12080],[218,12320],[223,12980],[227,13100],[231,13200],[235,13320],[238,13520],[244,13680],[248,14400],[253,14500],[256,14660],[260,14740],[266,14880],[271,15120],[277,15320],[281,15560],[286,15720],[289,16040],[300,16160],[303,16700]]},"ch11-059":{"text":"The following weekend, we met again. We sat by the pier near the Kallang River and watched the sunset. Light stretched across the water, shifting as the surface moved. For a while, admiring it together was enough. I was glad to be beside her with no table between us and nowhere our conversation had to arrive.","voiceUrl":"voices/chapter-11/ch11-059.mp3","durationMs":19440,"cues":[[4,100],[14,220],[23,640],[26,1040],[30,1180],[37,1340],[40,2500],[44,2620],[47,2820],[51,2940],[56,3080],[61,3320],[65,3460],[73,3580],[79,3940],[83,4400],[91,4560],[95,4900],[103,5040],[109,6600],[119,6880],[126,7260],[130,7600],[137,7740],[146,8560],[149,8980],[153,9140],[161,9280],[168,9700],[172,11140],[174,11260],[181,11360],[190,11800],[193,12300],[202,12400],[206,12720],[214,12880],[216,14220],[220,14280],[225,14440],[228,14740],[231,14840],[238,14960],[242,15380],[247,15520],[250,15720],[256,15980],[264,16320],[267,16740],[271,16920],[279,17100],[283,17580],[296,17760],[300,18440],[303,18580],[310,18740]]},"ch11-060":{"text":"It's nice here.","voiceUrl":"voices/chapter-11/ch11-060.mp3","durationMs":2400,"cues":[[5,960],[10,1180],[15,1520]]},"ch11-061":{"text":"Yeah. I'm glad we came.","voiceUrl":"voices/chapter-11/ch11-061.mp3","durationMs":2304,"cues":[[6,160],[10,800],[15,920],[18,1100],[23,1200]]},"ch11-062":{"text":"I began telling her about my past. One part led to another: the times I had hoped too quickly, the times I had stayed too long, the hurt I had carried into the next beginning. She was learning where I had been. I was hearing myself describe it without feeling that I had fallen back into it.","voiceUrl":"voices/chapter-11/ch11-062.mp3","durationMs":17832,"cues":[[2,140],[8,200],[16,580],[20,860],[26,1020],[29,1280],[35,1480],[39,2700],[44,2920],[48,3320],[51,3520],[60,3620],[64,4540],[70,4660],[72,5140],[76,5140],[82,5260],[86,5620],[95,5780],[99,6640],[105,6760],[107,7100],[111,7140],[118,7300],[122,7580],[128,7760],[132,8840],[137,8980],[139,9560],[143,9600],[151,9760],[156,10100],[160,10280],[165,10400],[176,10700],[180,11840],[184,11960],[193,12120],[199,12480],[201,12800],[205,12860],[211,13040],[213,14300],[217,14360],[225,14500],[232,14780],[241,15140],[244,15580],[252,15720],[260,16040],[265,16379],[267,16540],[271,16560],[278,16720],[283,17060],[288,17280],[291,17560]]},"ch11-pier-past":{"text":"Sometimes I kept hoping even when the answer was already there. I thought if I did enough, or waited long enough, things might change. By the end I was tired of being hurt, but I was also tired of the way I kept living inside that hope.","voiceUrl":"voices/chapter-11/ch11-pier-past.mp3","durationMs":13272,"cues":[[10,160],[12,820],[17,940],[24,1160],[29,2040],[34,2280],[38,2400],[45,2520],[49,2800],[57,2960],[64,3180],[66,4100],[74,4180],[77,4480],[79,4680],[83,4720],[91,4840],[94,5480],[101,5660],[106,5960],[114,6140],[121,6760],[127,7180],[135,7440],[138,8460],[142,8580],[146,8680],[148,9020],[152,9060],[158,9240],[161,9560],[167,9680],[173,9880],[177,10540],[179,10640],[183,10680],[188,10860],[194,11120],[197,11320],[201,11400],[205,11480],[207,11740],[212,11800],[219,12060],[226,12280],[231,12620],[236,12800]]},"ch11-063":{"text":"I told her about being so tired of love that I had almost stopped wanting to try. About going for Umrah, and the relief I found in Masjidil Nabawi. I could still remember the breath leaving me. Sitting beside the river, I paused, surprised that I had brought her all the way into that memory.","voiceUrl":"voices/chapter-11/ch11-063.mp3","durationMs":19032,"cues":[[2,140],[7,240],[11,480],[17,600],[23,840],[26,1060],[32,1260],[35,1600],[40,1760],[45,2140],[47,2320],[51,2360],[58,2540],[66,2860],[74,3220],[77,3580],[82,3740],[88,5020],[94,5280],[98,5560],[105,5740],[109,6500],[113,6660],[120,6780],[122,7240],[128,7380],[131,7700],[140,7840],[148,8400],[150,9920],[156,9980],[162,10220],[171,10500],[175,10960],[182,11100],[190,11540],[194,11920],[202,13300],[209,13560],[213,13880],[220,14000],[222,14500],[230,14640],[240,15440],[245,16260],[247,16460],[251,16520],[259,16700],[263,16960],[267,17260],[271,17480],[275,17620],[280,18000],[285,18280],[292,18500]]},"ch11-pier-surprise":{"text":"Sorry. I didn't realise how much I was going to say.","voiceUrl":"voices/chapter-11/ch11-pier-surprise.mp3","durationMs":2952,"cues":[[7,220],[9,820],[16,1200],[24,1380],[28,1660],[33,1760],[35,1900],[39,1960],[45,2060],[48,2200],[52,2300]]},"ch11-064":{"text":"You can take your time. I'm listening.","voiceUrl":"voices/chapter-11/ch11-064.mp3","durationMs":2952,"cues":[[4,260],[8,420],[13,620],[18,840],[24,1040],[28,2040],[38,2200]]},"ch11-065":{"text":"I looked at her. There was no need to hurry through the difficult part so we could return to something pleasant. She let me find the next sentence. I had imagined openness as a difficult thing I would one day prepare myself to do. Here I was, already doing it, with someone who wanted to hear me.","voiceUrl":"voices/chapter-11/ch11-065.mp3","durationMs":21504,"cues":[[2,140],[9,220],[12,440],[17,540],[23,1780],[27,1920],[30,2060],[35,2280],[38,2520],[44,2660],[52,3020],[56,3280],[66,3380],[71,3840],[74,4240],[77,4420],[83,4540],[90,4720],[93,5140],[103,5280],[113,5740],[117,7220],[121,7380],[124,7540],[129,7740],[133,8240],[138,8360],[148,8860],[150,10780],[154,10840],[163,10960],[172,11580],[175,12180],[177,12320],[187,12460],[193,13020],[195,13500],[201,13620],[205,13900],[209,14100],[217,14360],[224,14780],[227,15240],[231,15380],[236,16620],[238,16840],[243,16940],[251,18000],[257,18440],[261,18740],[266,19580],[274,19800],[278,20140],[285,20380],[288,20760],[293,20940],[296,21180]]},"ch11-pier-quiet":{"text":"For a moment I watched the light on the water instead. I could feel how much I had said, and how calm it was between us afterwards. The stories hadn't made her look at me as though I belonged somewhere else. When I turned back towards her, I still felt welcome beside her.","voiceUrl":"voices/chapter-11/ch11-pier-quiet.mp3","durationMs":18960,"cues":[[4,140],[6,280],[13,380],[15,1100],[23,1200],[27,1680],[33,1840],[36,2160],[40,2280],[46,2420],[55,2780],[57,4320],[63,4380],[68,4580],[72,4880],[77,5100],[79,5580],[83,5620],[89,5860],[93,6540],[97,6780],[102,7040],[105,7400],[109,7520],[117,7780],[120,8140],[132,8340],[136,10040],[144,10180],[151,10640],[156,10960],[160,11200],[165,11420],[168,11600],[171,11780],[174,11980],[181,12160],[183,12420],[192,12520],[202,13160],[208,13560],[213,14820],[215,14980],[222,15100],[227,15420],[235,15680],[240,16020],[242,17000],[248,17120],[253,17440],[261,17780],[268,18300],[272,18700]]},"ch11-openness-surprise":{"text":"I'm surprised I'm telling you all this. I didn't come here with a speech prepared. I just started talking, and it felt okay to keep going. That means a lot to me.","voiceUrl":"voices/chapter-11/ch11-openness-surprise.mp3","durationMs":8304,"cues":[[4,180],[14,300],[18,700],[26,840],[30,1080],[34,1200],[40,1340],[42,2240],[49,2300],[54,2500],[59,2700],[64,2840],[66,2940],[73,3100],[83,3300],[85,4180],[90,4280],[98,4400],[107,4680],[111,5160],[114,5240],[119,5360],[124,5580],[127,5820],[132,5940],[139,6140],[144,7140],[150,7260],[152,7460],[156,7520],[159,7720],[162,7820]]},"ch11-openness-grateful":{"text":"Thank you for listening like this. I know some of it is difficult to hear. I'm really grateful I can sit here with you and say it in my own time.","voiceUrl":"voices/chapter-11/ch11-openness-grateful.mp3","durationMs":7920,"cues":[[6,140],[10,400],[14,660],[24,800],[29,1160],[35,1360],[37,2300],[42,2360],[47,2560],[50,2700],[53,2800],[56,2960],[66,3180],[69,3500],[75,3620],[79,4480],[86,4660],[95,4880],[97,5360],[101,5440],[105,5640],[110,5800],[115,5940],[119,6160],[123,6420],[127,6640],[130,6800],[133,6920],[136,7020],[140,7160],[145,7340]]},"ch11-openness-ready":{"text":"For a long time I kept bringing the same hurt into everything. I feel ready to have something new in my life now. And I'm happy that getting to know you is part of that.","voiceUrl":"voices/chapter-11/ch11-openness-ready.mp3","durationMs":10392,"cues":[[4,160],[6,280],[11,380],[16,720],[18,1440],[23,1480],[32,1700],[36,2000],[41,2180],[46,2500],[51,3000],[63,3400],[65,4620],[70,4740],[76,4980],[79,5400],[84,5500],[94,5680],[98,6080],[101,6480],[104,6560],[109,6700],[114,6960],[118,7740],[122,7860],[128,8039],[133,8320],[141,8440],[144,8640],[149,8740],[153,9000],[156,9400],[161,9600],[164,9860],[169,9980]]},"ch11-openness-join":{"text":"The water kept moving below us. I thought about the timing of her arrival: after I had found some peace, after I had stopped trying to reopen an old ending. I had decided to begin a new book. Then Mariam had turned towards me, and a name I didn't know had entered my life.","voiceUrl":"voices/chapter-11/ch11-openness-join.mp3","durationMs":19752,"cues":[[4,160],[10,280],[15,740],[22,1080],[28,1580],[32,1960],[34,3180],[42,3260],[48,3480],[52,3680],[59,3840],[62,4240],[66,4340],[75,4540],[81,5760],[83,6380],[87,6440],[93,6600],[98,6880],[105,7080],[111,8060],[113,8400],[117,8460],[125,8640],[132,9040],[135,9300],[142,9460],[145,10000],[149,10260],[157,10600],[159,12120],[163,12180],[171,12280],[174,12740],[180,12860],[182,13440],[186,13580],[192,13840],[197,15180],[204,15440],[208,15920],[215,16120],[223,16440],[227,16800],[231,17120],[233,17280],[238,17420],[240,17800],[247,17900],[252,18200],[256,18520],[264,18740],[267,19100],[272,19300]]},"ch11-066":{"text":"I'm really happy you came into my life when you did. After Umrah, I felt like I could begin again. Then I met you. It feels like the pieces have been clicking together.","voiceUrl":"voices/chapter-11/ch11-066.mp3","durationMs":9744,"cues":[[4,160],[11,280],[17,540],[21,980],[26,1100],[31,1280],[34,1460],[39,1580],[44,1820],[48,1940],[53,2060],[59,3100],[66,3360],[68,3980],[73,4059],[78,4200],[80,4380],[86,4420],[92,4580],[99,4840],[104,5700],[106,5840],[110,5900],[115,6140],[118,6960],[124,7100],[129,7340],[133,7460],[140,7580],[145,8220],[150,8360],[159,8560],[168,9140]]},"ch11-067":{"text":"That was how it felt, sitting there with her. I couldn't explain every part of His plans. I could feel my gratitude for the path that had brought me to this evening: the release, the introduction, her persistence, and our growing willingness to meet each other honestly. I wanted her to know how happy I was that she was here.","voiceUrl":"voices/chapter-11/ch11-067.mp3","durationMs":23040,"cues":[[5,160],[9,420],[13,560],[16,720],[22,860],[30,1740],[36,2020],[41,2220],[46,2340],[48,3620],[57,3700],[65,3960],[71,4560],[76,4980],[79,5260],[83,5380],[90,5600],[92,6620],[98,6680],[103,7000],[106,7520],[116,7700],[120,8340],[124,8480],[129,8640],[134,9240],[138,9380],[146,9560],[149,9840],[152,10020],[157,10160],[166,10400],[170,11500],[179,11620],[183,12780],[197,12900],[201,14240],[214,14460],[218,15820],[222,16180],[230,16420],[242,16820],[245,17340],[250,17460],[255,17660],[261,17880],[271,18120],[273,19740],[280,19840],[284,20140],[287,20300],[292,20460],[296,20900],[302,21220],[304,21700],[308,21800],[313,22180],[317,22360],[321,22540],[326,22720]]},"ch11-pier-gratitude":{"text":"I remembered her asking whether we could meet, the questions she had kept finding, the way she had stayed in our first conversation when I barely knew how to help it along. Now I knew more of her, and I wanted to keep knowing her. The words I needed were simple enough to say without rehearsing them.","voiceUrl":"voices/chapter-11/ch11-pier-gratitude.mp3","durationMs":18552,"cues":[[2,120],[13,200],[17,640],[24,860],[32,1240],[35,1460],[41,1580],[47,1760],[51,2740],[61,2840],[65,3600],[69,3700],[74,3820],[83,4080],[87,5100],[91,5220],[95,5520],[99,5620],[106,5840],[109,6160],[113,6280],[119,6540],[132,6880],[137,7860],[139,8020],[146,8119],[151,8420],[155,8620],[158,8780],[163,8880],[166,9060],[173,9220],[177,10980],[179,11240],[184,11340],[189,11540],[192,11760],[197,11880],[201,12760],[203,12900],[210,13000],[213,13520],[218,13660],[226,13920],[231,14220],[235,15600],[241,15720],[243,16079],[250,16160],[255,16480],[262,16640],[269,16900],[272,17140],[276,17280],[284,17480],[295,17800],[300,18240]]},"ch11-068":{"text":"Nurul, I love you.","voiceUrl":"voices/chapter-11/ch11-068.mp3","durationMs":2472,"cues":[[7,260],[9,1420],[14,1500],[18,1700]]},"ch11-069":{"text":"I love you too, Aleem.","voiceUrl":"voices/chapter-11/ch11-069.mp3","durationMs":2304,"cues":[[2,280],[7,480],[11,780],[16,1000],[22,1540]]},"ch11-070":{"text":"We confessed our love to each other that evening by the river. I could hear her words without searching them for a smaller meaning, without needing to persuade myself they had happened. The sunset continued around us. Beside me was someone I loved, telling me that she loved me too.","voiceUrl":"voices/chapter-11/ch11-070.mp3","durationMs":18000,"cues":[[3,80],[13,180],[17,620],[22,800],[25,1040],[30,1120],[36,1300],[41,1500],[49,1720],[52,2040],[56,2200],[63,2320],[65,3560],[71,3620],[76,3780],[80,4000],[86,4200],[94,4860],[104,5200],[109,5560],[113,5760],[115,5880],[123,6020],[132,6360],[140,7380],[148,7660],[151,7920],[160,8020],[167,8440],[172,8840],[176,8940],[186,9100],[190,10360],[197,10500],[207,11040],[214,11780],[218,12220],[225,13480],[228,13960],[232,14260],[240,14440],[242,14900],[249,15080],[257,16079],[260,16360],[265,16540],[269,16740],[275,17000],[278,17320],[282,17540]]},"epilogue-001":{"text":"We got engaged. Now we are preparing for our wedding, with things to arrange, decisions to make, and a future that keeps appearing inside ordinary conversations. I used to wonder whether anyone would want to plan a life with me. These days, I find myself discussing the next thing we need to do with Nurul.","voiceUrl":"voices/epilogue/epilogue-001.mp3","durationMs":19344,"cues":[[3,160],[7,360],[16,620],[20,2040],[23,2240],[27,2340],[37,2460],[41,2960],[45,3080],[54,3240],[59,3940],[66,4120],[69,4480],[78,4600],[88,5240],[91,5780],[97,5900],[101,6640],[103,6780],[110,6880],[115,7240],[121,7440],[131,7720],[138,8240],[147,8740],[162,9140],[164,10980],[169,11100],[172,11300],[179,11460],[187,11880],[194,12220],[200,12600],[205,12760],[208,12920],[213,13060],[215,13360],[220,13460],[225,13700],[229,13900],[235,14920],[241,15220],[243,15900],[248,16000],[255,16260],[266,16680],[270,17240],[275,17360],[281,17680],[284,17940],[289,18060],[292,18220],[295,18360],[300,18580],[306,18820]]},"epilogue-002":{"text":"The wedding is still ahead of us. So is the marriage we hope to build. There are things we are still learning about each other, and moments when we have to slow down and explain ourselves better. I can be quiet when I need to speak. She can need time when I am ready with an answer.","voiceUrl":"voices/epilogue/epilogue-002.mp3","durationMs":16944,"cues":[[4,160],[12,320],[15,940],[21,1100],[27,1320],[30,1540],[34,1680],[37,2400],[40,2540],[44,2720],[53,2880],[56,3400],[61,3500],[64,3700],[71,3800],[77,4580],[81,4780],[88,5020],[91,5440],[95,5520],[101,5700],[110,6000],[116,6380],[121,6620],[128,6820],[132,7700],[140,7920],[145,8440],[148,8600],[153,8700],[156,8840],[161,8980],[166,9240],[170,9700],[178,9820],[188,10280],[196,10860],[198,12020],[202,12120],[205,12260],[211,12400],[216,12800],[218,12980],[223,13060],[226,13220],[233,13380],[237,14460],[241,14680],[246,14800],[251,15020],[256,15300],[258,15660],[261,15720],[267,15860],[272,16100],[275,16239],[282,16379]]},"epilogue-003":{"text":"But we can return to the conversation. I can ask about her day and stay curious about the answer. She can tell me when something feels too much. There is still that bright smile, and the warmth of a greeting I have learned to appreciate. I hope I never let those small things become invisible through familiarity.","voiceUrl":"voices/epilogue/epilogue-003.mp3","durationMs":20400,"cues":[[4,80],[7,240],[11,360],[18,520],[21,900],[25,1000],[39,1100],[41,2540],[45,2620],[49,2860],[55,3160],[59,3400],[63,3580],[67,4320],[72,4460],[80,4740],[86,5360],[90,5580],[98,5740],[102,6880],[106,7020],[111,7180],[114,7360],[119,7520],[129,7700],[135,8080],[139,8700],[145,8920],[151,10320],[154,10460],[160,10620],[165,10960],[172,11220],[179,11620],[183,12660],[187,12760],[194,12920],[197,13320],[199,13420],[208,13540],[210,14080],[215,14120],[223,14260],[226,14600],[238,14720],[240,16400],[245,16480],[247,16720],[253,16800],[257,17000],[263,17180],[269,17460],[276,17780],[283,18180],[293,18440],[301,19240],[313,19480]]},"epilogue-004":{"text":"When I think of the boy at the beginning of this story, I feel tenderness for him. He wanted love so badly and had so much to learn about giving it. I am still learning. I wish I could let him sit with this ordinary happiness for a moment: being included in someone's plans, and making room for hers.","voiceUrl":"voices/epilogue/epilogue-004.mp3","durationMs":21360,"cues":[[5,180],[7,400],[13,500],[16,700],[20,800],[24,940],[27,1140],[31,1240],[41,1360],[44,1700],[49,1820],[56,2020],[58,3080],[63,3160],[74,3440],[78,4180],[83,4340],[86,5580],[93,5780],[98,6220],[101,6660],[107,6960],[111,7860],[115,7980],[118,8240],[123,8520],[126,8840],[132,8960],[138,9220],[145,9500],[149,9800],[151,10840],[154,10920],[160,11140],[170,11480],[172,12900],[177,13020],[179,13540],[185,13620],[189,13780],[193,13920],[197,14140],[202,14360],[207,14500],[216,14860],[226,15320],[230,15800],[232,15920],[240,16000],[246,17180],[255,17420],[258,18000],[268,18140],[275,18520],[279,19680],[286,19800],[291,20160],[295,20500],[300,20680]]},"epilogue-005":{"text":"This is where I will leave the telling, while we are engaged and getting ready for what comes next. Nurul and I have more life ahead than I can put on these pages. I am grateful we get to step towards it together, trusting Him with what we cannot see. And inshallah, it will be a happily ever after.","voiceUrl":"voices/epilogue/epilogue-005.mp3","durationMs":18552,"cues":[[5,260],[8,440],[14,600],[16,940],[21,1000],[27,1160],[31,1440],[40,1580],[46,2340],[49,2520],[53,2640],[61,2760],[65,3340],[73,3500],[79,3780],[83,4019],[88,4160],[94,4340],[100,4620],[106,5880],[110,6200],[112,6440],[117,6520],[122,6720],[127,6920],[133,7180],[138,7460],[140,7620],[144,7700],[148,7860],[151,8020],[157,8119],[164,8380],[166,9520],[169,9560],[178,9720],[181,10140],[185,10280],[188,10420],[193,10560],[201,10780],[204,11120],[214,11240],[223,12340],[227,12780],[232,13180],[237,13320],[240,13500],[247,13640],[252,14020],[256,15260],[267,15540],[270,16840],[275,16960],[278,17100],[280,17260],[288,17380],[293,17800],[299,18080]]}};
